window.COURSE={"version":"1.1.0","units":[{"id":1,"title":"Ciao!","titleDe":"Hallo und Tschüss","goal":"Du kannst Leute begrüßen, dich vorstellen und dich verabschieden.","intro":"Willkommen bei deinem Italienischkurs! Diese Woche lernst du die Wörter, die du bei jeder Begegnung brauchst: grüßen, dich vorstellen und dich verabschieden. Damit kommst du schon erstaunlich weit.","culture":"Freunde begrüßt man in Italien oft mit zwei Küsschen auf die Wangen, Fremden gibt man die Hand. 'Ciao' sagst du nur zu Freunden und Familie. Im Laden, im Hotel oder im Restaurant passt 'Buongiorno' oder 'Salve', ab dem Nachmittag 'Buonasera'.","vocab":[{"it":"ciao","de":"hallo; tschüss (zu Freunden)","alt":[],"note":"Informell. Nur zu Freunden, Familie und Kindern.","ex":"Ciao, Giulia!","exDe":"Hallo, Giulia!"},{"it":"buongiorno","de":"guten Morgen; guten Tag","alt":["buon giorno"],"note":"Sagt man ungefähr bis zum frühen Nachmittag.","ex":"Buongiorno, signora!","exDe":"Guten Tag!"},{"it":"buonasera","de":"guten Abend","alt":["buona sera"],"note":"Schon ab dem späten Nachmittag.","ex":"Buonasera, signor Rossi.","exDe":"Guten Abend, Herr Rossi."},{"it":"arrivederci","de":"auf Wiedersehen","alt":[],"note":"","ex":"Grazie, arrivederci!","exDe":"Danke, auf Wiedersehen!"},{"it":"grazie","de":"danke","alt":[],"note":"Aussprache: gra tsie. Das e am Ende hört man.","ex":"Grazie, Giulia!","exDe":"Danke, Giulia!"},{"it":"prego","de":"bitte (gern geschehen)","alt":[],"note":"Die Antwort auf grazie. Auch: 'Bitte schön, was darf es sein?'","ex":"Grazie! Prego.","exDe":"Danke! Gern geschehen."},{"it":"per favore","de":"bitte (wenn du um etwas bittest)","alt":["per piacere"],"note":"","ex":"Un momento, per favore.","exDe":"Einen Moment, bitte."},{"it":"sì","de":"ja","alt":["si"],"note":"Mit Akzent auf dem i.","ex":"Sì, grazie.","exDe":"Ja, danke."},{"it":"no","de":"nein","alt":[],"note":"","ex":"No, grazie.","exDe":"Nein, danke."},{"it":"Come ti chiami?","de":"Wie heißt du?","alt":[],"note":"ch klingt wie k: kia mi.","ex":"Ciao! Come ti chiami?","exDe":"Hallo! Wie heißt du?"},{"it":"mi chiamo","de":"ich heiße","alt":[],"note":"Wörtlich: ich nenne mich.","ex":"Mi chiamo Lukas.","exDe":"Ich heiße Lukas."},{"it":"piacere","de":"freut mich (beim Kennenlernen)","alt":[],"note":"Aussprache: pia tsche re.","ex":"Piacere, Giulia!","exDe":"Freut mich, Giulia!"},{"it":"Come stai?","de":"Wie geht's dir?","alt":[],"note":"Zu Freunden (tu).","ex":"Ciao, Giulia! Come stai?","exDe":"Hallo, Giulia! Wie geht's dir?"},{"it":"Come sta?","de":"Wie geht es Ihnen?","alt":[],"note":"Höflich, zu Fremden (Lei).","ex":"Buongiorno, signora! Come sta?","exDe":"Guten Tag! Wie geht es Ihnen?"},{"it":"bene","de":"gut","alt":[],"note":"","ex":"Sto bene, grazie.","exDe":"Mir geht's gut, danke."},{"it":"molto bene","de":"sehr gut","alt":[],"note":"","ex":"Molto bene, e tu?","exDe":"Sehr gut. Und du?"},{"it":"così così","de":"so lala","alt":["cosi cosi"],"note":"","ex":"Così così. E tu?","exDe":"So lala. Und du?"},{"it":"male","de":"schlecht","alt":[],"note":"Non c'è male = nicht schlecht.","ex":"Oggi sto male.","exDe":"Heute geht's mir schlecht."},{"it":"e tu?","de":"und du?","alt":[],"note":"","ex":"Bene, grazie. E tu?","exDe":"Gut, danke. Und du?"},{"it":"e Lei?","de":"und Sie?","alt":[],"note":"Lei mit großem L ist die Höflichkeitsform.","ex":"Molto bene, grazie. E Lei?","exDe":"Sehr gut, danke. Und Ihnen?"},{"it":"anche","de":"auch","alt":[],"note":"Anche io = ich auch.","ex":"Bene anche io, grazie!","exDe":"Mir geht's auch gut, danke!"},{"it":"scusa","de":"Entschuldigung (zu Freunden)","alt":[],"note":"","ex":"Scusa, come ti chiami?","exDe":"Entschuldigung, wie heißt du?"},{"it":"scusi","de":"Entschuldigung (höflich)","alt":[],"note":"Aussprache: sku si. Vor u bleibt sc hart.","ex":"Scusi, come si chiama?","exDe":"Entschuldigung, wie heißen Sie?"},{"it":"Come si chiama?","de":"Wie heißen Sie?","alt":["Lei come si chiama?"],"note":"Höflich (Lei).","ex":"Buongiorno! Come si chiama?","exDe":"Guten Tag! Wie heißen Sie?"},{"it":"salve","de":"hallo (neutral, auch zu Fremden)","alt":[],"note":"Passt fast immer: nicht zu locker und nicht zu förmlich.","ex":"Salve, come sta?","exDe":"Hallo, wie geht es Ihnen?"},{"it":"buonanotte","de":"gute Nacht","alt":["buona notte"],"note":"","ex":"Buonanotte, Giulia!","exDe":"Gute Nacht, Giulia!"},{"it":"a presto","de":"bis bald","alt":[],"note":"","ex":"Ciao, a presto!","exDe":"Tschüss, bis bald!"},{"it":"a domani","de":"bis morgen","alt":[],"note":"","ex":"Ciao Giulia, a domani!","exDe":"Tschüss Giulia, bis morgen!"},{"it":"ci vediamo","de":"wir sehen uns","alt":[],"note":"Sehr häufig zum Abschied.","ex":"Ci vediamo, ciao!","exDe":"Wir sehen uns, tschüss!"},{"it":"grazie mille","de":"vielen Dank","alt":[],"note":"Wörtlich: tausend Dank.","ex":"Grazie mille, Lukas!","exDe":"Vielen Dank, Lukas!"},{"it":"il signore","de":"der Herr","alt":[],"note":"Vor einem Namen fällt das e weg: signor Rossi.","ex":"Buongiorno, signore!","exDe":"Guten Tag, mein Herr!"},{"it":"la signora","de":"die Frau (Anrede); die Dame","alt":[],"note":"gn klingt wie nj: si nio ra.","ex":"Buonasera, signora Bianchi.","exDe":"Guten Abend, Frau Bianchi."},{"it":"l'amico","de":"der Freund (befreundet)","alt":["amico"],"note":"Maskulin. Plural: gli amici.","ex":"Ciao, amico mio!","exDe":"Hallo, mein Freund!"},{"it":"l'amica","de":"die Freundin (befreundet)","alt":["amica"],"note":"Feminin. Plural: le amiche.","ex":"Ciao, amica mia!","exDe":"Hallo, meine Liebe!"},{"it":"il ragazzo","de":"der Junge; junger Mann","alt":[],"note":"Auch: der feste Freund.","ex":"Il ragazzo si chiama Marco.","exDe":"Der Junge heißt Marco."},{"it":"la ragazza","de":"das Mädchen; junge Frau","alt":[],"note":"Auch: die feste Freundin.","ex":"La ragazza si chiama Giulia.","exDe":"Das Mädchen heißt Giulia."}],"grammar":{"title":"Aussprache und tu oder Lei","points":["Italienisch spricht man fast so, wie man es schreibt. Jeder Vokal wird klar ausgesprochen, auch am Wortende: <b>grazie</b> klingt wie gra tsie, das e am Ende hört man deutlich.","<b>c</b> und <b>g</b> werden vor e und i weich: <b>ciao</b> klingt wie tschao, <b>Giulia</b> wie Dschulia. Ein <b>h</b> macht sie wieder hart: <b>che</b> = ke, <b>spaghetti</b> = spagetti.","<b>gn</b> klingt wie nj (signora), <b>gli</b> wie lj (famiglia), <b>sc</b> vor e oder i wie sch (pesce). Doppelte Konsonanten spricht man hörbar länger: <b>nonna</b>, <b>mille</b>.","<b>tu</b> sagst du zu Freunden, Familie und Kindern. <b>Lei</b> ist die Höflichkeitsform für Fremde. Mit Lei nimmst du eine andere Verbform: <b>Come sta?</b> statt <b>Come stai?</b>"],"table":{"head":["Schreibung","klingt wie","Beispiel"],"rows":[["ci / ce","tschi / tsche","ciao, piacere"],["chi / che","ki / ke","chiamo, che"],["gi / ge","dschi / dsche","Giulia, gelato"],["ghi / ghe","gi / ge","spaghetti"],["gn","nj","signora, bagno"],["gli","lj","famiglia, figlio"],["sci / sce","schi / sche","piscina, pesce"],["h","stumm","hotel, ho"]]},"examples":[{"it":"Ciao, come stai?","de":"Hallo, wie geht's dir?"},{"it":"Buongiorno, come sta?","de":"Guten Tag, wie geht es Ihnen?"},{"it":"Piacere, mi chiamo Giulia.","de":"Freut mich, ich heiße Giulia."},{"it":"Scusi, signora!","de":"Entschuldigung!"},{"it":"Grazie mille, ciao!","de":"Vielen Dank, tschüss!"}],"drills":[{"type":"choice","q":"Wie klingt das c in 'ciao'?","de":"","options":["k","tsch","s"],"answer":1,"why":"c vor i oder e klingt wie tsch."},{"type":"choice","q":"Wie klingt 'che'?","de":"","options":["tsche","sche","ke"],"answer":2,"why":"Das h macht das c hart: che = ke."},{"type":"choice","q":"Welches Wort beginnt mit dsch?","de":"","options":["Giulia","grazie","ghiaccio"],"answer":0,"why":"g vor i oder e klingt wie dsch."},{"type":"choice","q":"Zur Kellnerin sagst du: Buongiorno, come ___?","de":"Guten Tag, wie geht es Ihnen?","options":["stai","sta","ti chiami"],"answer":1,"why":"Fremde siezt man (Lei): come sta?"},{"type":"choice","q":"Ciao Giulia! Come ___?","de":"Hallo Giulia! Wie geht's dir?","options":["sta","si chiama","stai"],"answer":2,"why":"Giulia ist eine Freundin, also tu: come stai?"},{"type":"type","q":"Buongiorno! Come si ___?","de":"Guten Tag! Wie heißen Sie?","answer":"chiama","alt":[],"why":"Höflich: come si chiama?"},{"type":"type","q":"Ciao! Come ti ___?","de":"Hallo! Wie heißt du?","answer":"chiami","alt":[],"why":"Zu Freunden: come ti chiami?"},{"type":"type","q":"Mi ___ Lukas.","de":"Ich heiße Lukas.","answer":"chiamo","alt":[],"why":"mi chiamo = ich heiße."}]},"dialog":{"title":"Una serata tandem","setting":"Abend zum Sprachaustausch in einer Bar in Bologna. Lukas spricht eine junge Frau an.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Giulia","gender":"f"}},"lines":[{"s":"A","it":"Ciao! Scusa, come ti chiami?","de":"Hallo! Entschuldige, wie heißt du?"},{"s":"B","it":"Ciao! Giulia. E tu?","de":"Hallo! Giulia. Und du?"},{"s":"A","it":"Lukas. Piacere!","de":"Lukas. Freut mich!"},{"s":"B","it":"Piacere mio! Benvenuto a Bologna!","de":"Mich auch! Willkommen in Bologna!"},{"s":"A","it":"Grazie mille! Allora, come va?","de":"Vielen Dank! Und, wie läuft's?"},{"s":"B","it":"Benissimo, grazie! E tu?","de":"Sehr gut, danke! Und bei dir?"},{"s":"A","it":"Bene! Ma l'italiano, eh... così così.","de":"Gut! Aber mein Italienisch, na ja ... so lala."},{"s":"B","it":"Ma no, dai! Va benissimo!","de":"Ach was! Das klappt doch super!"},{"s":"A","it":"Grazie! Ci vediamo domani?","de":"Danke! Sehen wir uns morgen?"},{"s":"B","it":"Sì, sì! A domani. Buonanotte, Lukas!","de":"Ja, klar! Bis morgen. Gute Nacht, Lukas!"},{"s":"A","it":"Buonanotte, Giulia! Ciao ciao!","de":"Gute Nacht, Giulia! Tschüssi!"}],"questions":[{"q":"Wo lernen sich Lukas und Giulia kennen?","options":["In München","In Bologna","In Rom"],"answer":1},{"q":"Wie geht es Giulia?","options":["Sehr gut","So lala","Schlecht"],"answer":0},{"q":"Wann sehen sich die beiden wieder?","options":["Heute Abend","Nächste Woche","Morgen"],"answer":2}]},"sentences":[{"it":"Ciao, mi chiamo Lukas.","de":"Hallo, ich heiße Lukas."},{"it":"Buongiorno signora, come sta?","de":"Guten Tag, wie geht es Ihnen?"},{"it":"Molto bene, grazie. E tu?","de":"Sehr gut, danke. Und dir?"},{"it":"Scusi, come si chiama?","de":"Entschuldigung, wie heißen Sie?"},{"it":"Grazie mille e buona giornata!","de":"Vielen Dank und schönen Tag noch!"},{"it":"Ciao Giulia, a domani!","de":"Tschüss Giulia, bis morgen!"},{"it":"Anch'io sto bene, grazie.","de":"Mir geht's auch gut, danke."},{"it":"Ciao Lukas, ci vediamo presto!","de":"Tschüss Lukas, wir sehen uns bald!"}],"spoken":[{"it":"Come va?","book":"Come stai?","de":"Wie läuft's?","note":"Passt fast immer, zu Freunden und auch zu Bekannten, die du siezt, denn es braucht weder tu noch Lei. Typische Antwort: Bene! oder Tutto bene!","ex":"Ciao Giulia! Come va?","exDe":"Hi Giulia! Wie läuft's?","alt":[]},{"it":"Tutto bene?","book":"Stai bene?","de":"Alles gut?","note":"Sehr häufig als Begrüßung unter Freunden. Man antwortet einfach: Sì, tutto bene!","ex":"Ciao Lukas, tutto bene? Sì, tutto bene!","exDe":"Hallo Lukas, alles gut? Ja, alles gut!","alt":["Tutto a posto?"]},{"it":"Non c'è male.","book":"Sto abbastanza bene.","de":"Nicht schlecht. (auf Wie geht's?)","note":"Entspannte Antwort auf Come va? oder Come stai? Passt zu Freunden und Fremden.","ex":"Come va? Non c'è male. E tu?","exDe":"Wie läuft's? Nicht schlecht. Und bei dir?","alt":[]},{"it":"Piacere mio!","book":"Anche per me è un piacere.","de":"Ganz meinerseits!","note":"Die Antwort, wenn jemand zuerst Piacere! sagt. Klingt freundlich und passt überall.","ex":"Piacere, Lukas! Piacere mio!","exDe":"Freut mich, Lukas! Ganz meinerseits!","alt":[]},{"it":"Di niente!","book":"Prego.","de":"Keine Ursache!","note":"Lockere Antwort auf grazie, überall üblich. Genauso oft hörst du Di nulla!","ex":"Grazie mille! Di niente!","exDe":"Vielen Dank! Keine Ursache!","alt":["Di nulla!"]},{"it":"Ciao ciao!","book":"Arrivederci.","de":"Tschüssi!","note":"Doppelt gesagt klingt ciao besonders herzlich, typisch am Ende eines Telefonats. Nur zu Leuten, die du duzt.","ex":"A domani, Giulia! Ciao ciao!","exDe":"Bis morgen, Giulia! Tschüssi!","alt":[]},{"it":"Ci sentiamo!","book":"A presto.","de":"Wir hören uns!","note":"Zum Abschied, wenn ihr später telefoniert oder schreibt. Unter Freunden und auch im Job sehr häufig.","ex":"Ci sentiamo domani, ciao!","exDe":"Wir hören uns morgen, tschüss!","alt":[]},{"it":"Buona giornata!","book":"","de":"Schönen Tag noch!","note":"Zum Abschied im Laden, in der Bar oder unter Freunden. Ab dem späten Nachmittag sagt man Buona serata!","ex":"Grazie e buona giornata!","exDe":"Danke und schönen Tag noch!","alt":[]}],"speak":[{"sit":"Du triffst Giulia morgens auf der Straße. Begrüße sie und frag, wie es läuft.","answers":["Ciao Giulia! Come va?","Ciao! Tutto bene?","Ciao Giulia, come stai?"],"tip":"Come va? ist unter Freunden die lockerste Frage."},{"sit":"Auf einer Party stehst du neben einer jungen Frau. Sprich sie an und frag, wie sie heißt.","answers":["Ciao! Come ti chiami?","Scusa, come ti chiami?"],"tip":"Unter jungen Leuten duzt man sich sofort."},{"sit":"Ein Freund von Giulia sagt zu dir: 'Ciao, mi chiamo Marco. Piacere!' Antworte ihm.","answers":["Piacere mio!","Ciao Marco, piacere!"],"tip":""},{"sit":"Eine ältere Nachbarin fragt dich: 'Buongiorno! Come sta?' Antworte und frag höflich zurück.","answers":["Bene, grazie. E Lei?","Non c'è male, grazie. E Lei?","Molto bene, grazie! E Lei?"],"tip":"Zu Fremden fragst du mit E Lei? zurück."},{"sit":"Du beendest ein Telefonat mit Giulia. Ihr telefoniert morgen wieder.","answers":["Ci sentiamo domani! Ciao ciao!","Ciao, ci sentiamo domani!","A domani, ciao ciao!"],"tip":"Am Telefon sagen Italiener oft mehrmals hintereinander ciao."},{"sit":"Du hast in einer Bar einen Kaffee getrunken und gehst. Bedank dich und verabschiede dich freundlich.","answers":["Grazie, buona giornata!","Grazie mille, arrivederci!"],"tip":""}]},{"id":2,"title":"Di dove sei?","titleDe":"Woher kommst du?","goal":"Du kannst sagen, woher du kommst, wo du wohnst und welche Sprachen du sprichst.","intro":"Woher kommst du? Diese Frage hörst du in Italien ständig. Diese Woche lernst du Länder, Nationalitäten und Sprachen und dazu das wichtigste Verb überhaupt: essere (sein).","culture":"Viele Italiener fühlen sich zuerst mit ihrer Stadt verbunden und erst dann mit Italien. Auf 'Di dove sei?' antwortet man deshalb meist mit der Stadt: 'Sono di Bologna.' Bologna hat übrigens drei Spitznamen: la dotta (die Gelehrte, wegen der ältesten Universität Europas), la grassa (die Fette, wegen des guten Essens) und la rossa (die Rote, wegen der roten Dächer).","vocab":[{"it":"Di dove sei?","de":"Woher kommst du?","alt":[],"note":"Zu Freunden (tu). Antwort: Sono di ...","ex":"Ciao! Di dove sei?","exDe":"Hallo! Woher kommst du?"},{"it":"Di dov'è?","de":"Woher kommen Sie?","alt":["Di dov'e?","Lei di dov'è?"],"note":"Höflich (Lei). dov'è ist kurz für dove è.","ex":"Scusi, signora, di dov'è?","exDe":"Entschuldigung, woher kommen Sie?"},{"it":"sono di","de":"ich bin aus (Stadt)","alt":[],"note":"Mit Stadt: Sono di Monaco. Mit Land sagt man die Nationalität: Sono tedesco.","ex":"Sono di Bologna.","exDe":"Ich bin aus Bologna."},{"it":"essere","de":"sein","alt":[],"note":"Unregelmäßig: io sono, tu sei, lui/lei è.","ex":"Lukas è di Monaco.","exDe":"Lukas ist aus München."},{"it":"l'Italia","de":"Italien","alt":["Italia"],"note":"Feminin. Länder haben im Italienischen einen Artikel.","ex":"Benvenuto in Italia!","exDe":"Willkommen in Italien!"},{"it":"la Germania","de":"Deutschland","alt":[],"note":"","ex":"Lukas abita in Germania.","exDe":"Lukas wohnt in Deutschland."},{"it":"italiano","de":"italienisch; Italienisch (Sprache)","alt":[],"note":"feminin: italiana. Nationalitäten schreibt man klein.","ex":"Giulia è italiana.","exDe":"Giulia ist Italienerin."},{"it":"tedesco","de":"deutsch; Deutsch (Sprache)","alt":[],"note":"feminin: tedesca. Plural: tedeschi.","ex":"Sono tedesco, di Monaco.","exDe":"Ich bin Deutscher, aus München."},{"it":"parlare","de":"sprechen","alt":[],"note":"io parlo, tu parli, lui/lei parla.","ex":"Giulia parla tedesco.","exDe":"Giulia spricht Deutsch."},{"it":"Parli italiano?","de":"Sprichst du Italienisch?","alt":[],"note":"Höflich (Lei): Parla italiano?","ex":"Scusa, parli italiano?","exDe":"Entschuldigung, sprichst du Italienisch?"},{"it":"un po'","de":"ein bisschen","alt":["un po","un poco"],"note":"Mit Apostroph, nicht mit Akzent. Kurz für un poco.","ex":"Parlo un po' di italiano.","exDe":"Ich spreche ein bisschen Italienisch."},{"it":"la lingua","de":"die Sprache","alt":[],"note":"Auch: die Zunge.","ex":"L'italiano è la lingua di Dante.","exDe":"Italienisch ist die Sprache Dantes."},{"it":"abitare","de":"wohnen","alt":[],"note":"io abito, tu abiti. Bei abito liegt die Betonung vorne: A bi to.","ex":"Abito a Monaco di Baviera.","exDe":"Ich wohne in München."},{"it":"Dove abiti?","de":"Wo wohnst du?","alt":[],"note":"Höflich (Lei): Dove abita?","ex":"Giulia, dove abiti?","exDe":"Giulia, wo wohnst du?"},{"it":"la città","de":"die Stadt","alt":["la citta"],"note":"Feminin. Im Plural unverändert: le città.","ex":"Di che città sei?","exDe":"Aus welcher Stadt kommst du?"},{"it":"l'Austria","de":"Österreich","alt":["Austria"],"note":"Feminin.","ex":"Vienna è in Austria.","exDe":"Wien liegt in Österreich."},{"it":"austriaco","de":"österreichisch; Österreicher","alt":[],"note":"feminin: austriaca","ex":"Anna è austriaca, di Vienna.","exDe":"Anna ist Österreicherin, aus Wien."},{"it":"la Svizzera","de":"die Schweiz","alt":[],"note":"","ex":"Abito in Svizzera.","exDe":"Ich wohne in der Schweiz."},{"it":"svizzero","de":"schweizerisch; Schweizer","alt":[],"note":"feminin: svizzera","ex":"Il signor Keller è svizzero.","exDe":"Herr Keller ist Schweizer."},{"it":"bavarese","de":"bayerisch; Bayer","alt":[],"note":"Gleich für m und f.","ex":"Lukas è bavarese.","exDe":"Lukas ist Bayer."},{"it":"inglese","de":"englisch; Englisch (Sprache)","alt":[],"note":"Gleich für m und f.","ex":"Giulia parla inglese.","exDe":"Giulia spricht Englisch."},{"it":"francese","de":"französisch; Französisch (Sprache)","alt":[],"note":"Gleich für m und f.","ex":"Marie è francese.","exDe":"Marie ist Französin."},{"it":"la Francia","de":"Frankreich","alt":[],"note":"","ex":"Marie abita in Francia.","exDe":"Marie wohnt in Frankreich."},{"it":"la Spagna","de":"Spanien","alt":[],"note":"gn klingt wie nj: spa nja.","ex":"Madrid è in Spagna.","exDe":"Madrid liegt in Spanien."},{"it":"spagnolo","de":"spanisch; Spanisch (Sprache)","alt":[],"note":"feminin: spagnola","ex":"Parlo spagnolo e inglese.","exDe":"Ich spreche Spanisch und Englisch."},{"it":"facile","de":"leicht (einfach)","alt":[],"note":"Gleich für m und f.","ex":"L'italiano è facile!","exDe":"Italienisch ist leicht!"},{"it":"difficile","de":"schwer (schwierig)","alt":[],"note":"Gleich für m und f.","ex":"Il tedesco è difficile.","exDe":"Deutsch ist schwer."},{"it":"Monaco di Baviera","de":"München","alt":["Monaco"],"note":"Oft nur Monaco. Wörtlich: Monaco in Bayern.","ex":"Monaco di Baviera è in Germania.","exDe":"München liegt in Deutschland."},{"it":"Firenze","de":"Florenz","alt":[],"note":"","ex":"Firenze è in Toscana.","exDe":"Florenz liegt in der Toskana."},{"it":"Napoli","de":"Neapel","alt":[],"note":"","ex":"Davide è di Napoli.","exDe":"Davide ist aus Neapel."},{"it":"Milano","de":"Mailand","alt":[],"note":"","ex":"Matteo abita a Milano.","exDe":"Matteo wohnt in Mailand."},{"it":"Come si dice in italiano?","de":"Wie sagt man das auf Italienisch?","alt":[],"note":"Sehr nützlich, wenn dir ein Wort fehlt.","ex":"Scusa, come si dice in italiano?","exDe":"Entschuldigung, wie sagt man das auf Italienisch?"},{"it":"Non capisco.","de":"Ich verstehe nicht.","alt":[],"note":"Von capire (verstehen).","ex":"Scusi, non capisco.","exDe":"Entschuldigung, ich verstehe nicht."},{"it":"più piano","de":"langsamer (beim Sprechen)","alt":["piu piano"],"note":"Piano piano heißt: langsam, Schritt für Schritt.","ex":"Più piano, per favore!","exDe":"Langsamer, bitte!"},{"it":"vero?","de":"oder? (nicht wahr?)","alt":[],"note":"Am Satzende, wenn du eine Bestätigung willst.","ex":"Sei di Bologna, vero?","exDe":"Du bist aus Bologna, oder?"},{"it":"Davvero?","de":"Wirklich?","alt":[],"note":"","ex":"Davvero? Sei di Napoli?","exDe":"Wirklich? Du bist aus Neapel?"}],"grammar":{"title":"Das Verb essere und die Pronomen","points":["<b>essere</b> heißt sein. Es ist unregelmäßig, deshalb lernst du die sechs Formen am besten auswendig: <b>sono, sei, è, siamo, siete, sono</b>. Achtung: <b>è</b> mit Akzent heißt ist, <b>e</b> ohne Akzent heißt und.","Die Pronomen <b>io, tu, lui, lei</b> und so weiter lässt man meist weg, denn die Verbform zeigt schon, wer gemeint ist: <b>Sono Lukas.</b> Für die Verneinung stellst du <b>non</b> vor das Verb: <b>Non sono italiano.</b>","Die Höflichkeitsform <b>Lei</b> (Sie) hat dieselbe Verbform wie lei (sie): <b>Lei è di Roma?</b> bedeutet: Sind Sie aus Rom?","Nationalitäten schreibt man klein. Adjektive mit der Endung <b>o/a</b> passen sich an: Lukas è tedesc<b>o</b>, Giulia è italian<b>a</b>. Adjektive mit der Endung <b>e</b> bleiben gleich: Marc è frances<b>e</b>, Marie è frances<b>e</b>."],"table":{"head":["Person","essere","Beispiel"],"rows":[["io","sono","Sono tedesco."],["tu","sei","Sei di Bologna?"],["lui / lei / Lei","è","Giulia è italiana."],["noi","siamo","Siamo amici."],["voi","siete","Di dove siete?"],["loro","sono","Sono di Napoli."]]},"examples":[{"it":"Sono Lukas e sono tedesco.","de":"Ich bin Lukas und ich bin Deutscher."},{"it":"Giulia è italiana, di Bologna.","de":"Giulia ist Italienerin, aus Bologna."},{"it":"Di dove siete? Siamo di Napoli.","de":"Woher seid ihr? Wir sind aus Neapel."},{"it":"Scusi, Lei è svizzera?","de":"Entschuldigung, sind Sie Schweizerin?"},{"it":"Non sono di Roma, sono di Milano.","de":"Ich bin nicht aus Rom, ich bin aus Mailand."}],"drills":[{"type":"choice","q":"Io ___ di Monaco.","de":"Ich bin aus München.","options":["è","sono","sei"],"answer":1,"why":"Zu io gehört sono."},{"type":"type","q":"Tu ___ di Bologna?","de":"Bist du aus Bologna?","answer":"sei","alt":[],"why":"Zu tu gehört sei."},{"type":"choice","q":"Scusi, Lei ___ italiana?","de":"Entschuldigung, sind Sie Italienerin?","options":["è","sei","e"],"answer":0,"why":"Lei hat dieselbe Form wie lui und lei: è mit Akzent."},{"type":"choice","q":"Noi ___ di Napoli.","de":"Wir sind aus Neapel.","options":["siete","sono","siamo"],"answer":2,"why":"Zu noi gehört siamo."},{"type":"type","q":"Voi di dove ___?","de":"Woher seid ihr?","answer":"siete","alt":[],"why":"Zu voi gehört siete."},{"type":"type","q":"Matteo e Giulia ___ di Bologna.","de":"Matteo und Giulia sind aus Bologna.","answer":"sono","alt":[],"why":"Zu loro (Matteo und Giulia) gehört sono, genau wie bei io."},{"type":"choice","q":"Giulia è ___.","de":"Giulia ist Italienerin.","options":["italiana","italiano","italiane"],"answer":0,"why":"Giulia ist eine Frau, also Endung a: italiana."},{"type":"choice","q":"Anna è ___, di Londra.","de":"Anna ist Engländerin, aus London.","options":["inglesi","inglesa","inglese"],"answer":2,"why":"Adjektive auf e bleiben für Mann und Frau gleich: inglese."}]},"dialog":{"title":"Di dove sei?","setting":"Lukas und Giulia trinken einen Kaffee in Bologna und sprechen über Herkunft und Sprachen.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Giulia","gender":"f"}},"lines":[{"s":"B","it":"Allora Lukas, sei tedesco, vero?","de":"Also Lukas, du bist Deutscher, oder?"},{"s":"A","it":"Sì, di Monaco di Baviera.","de":"Ja, aus München."},{"s":"B","it":"E abiti a Monaco?","de":"Und wohnst du auch in München?"},{"s":"A","it":"Sì, sì. E tu, sei di qui?","de":"Ja, klar. Und du, bist du von hier?"},{"s":"B","it":"Sì, di Bologna. Senti, parli inglese?","de":"Ja, aus Bologna. Sag mal, sprichst du Englisch?"},{"s":"A","it":"Sì, e anche un pochino di spagnolo. Tu?","de":"Ja, außerdem ein kleines bisschen Spanisch. Und du?"},{"s":"B","it":"Inglese, francese e un po' di tedesco!","de":"Englisch, Französisch und ein bisschen Deutsch!"},{"s":"A","it":"Ma dai! Il tedesco è difficile, no?","de":"Echt jetzt? Deutsch ist doch schwer, oder?"},{"s":"B","it":"Eh, sì, molto! Ma tu parli bene italiano!","de":"Oh ja, total! Aber du sprichst gut Italienisch!"},{"s":"A","it":"Grazie! Ma l'italiano non è facile, eh.","de":"Danke! Aber Italienisch ist echt nicht leicht."},{"s":"B","it":"Piano piano, Lukas! Piano piano.","de":"Immer mit der Ruhe, Lukas! Schritt für Schritt."}],"questions":[{"q":"Woher kommt Lukas?","options":["Aus Bologna","Aus München","Aus Neapel"],"answer":1},{"q":"Welche Sprachen spricht Giulia?","options":["Englisch und ein bisschen Spanisch","Nur Englisch","Englisch, Französisch und ein bisschen Deutsch"],"answer":2},{"q":"Wie findet Lukas Italienisch?","options":["Nicht leicht","Sehr leicht","Schwerer als Deutsch"],"answer":0}]},"sentences":[{"it":"Sono tedesco, di Monaco di Baviera.","de":"Ich bin Deutscher, aus München."},{"it":"Giulia è italiana e abita a Bologna.","de":"Giulia ist Italienerin und wohnt in Bologna."},{"it":"Di dove sei? Sei svizzera?","de":"Woher kommst du? Bist du Schweizerin?"},{"it":"Parlo inglese e un po' di francese.","de":"Ich spreche Englisch und ein bisschen Französisch."},{"it":"Scusi, Lei è di Milano?","de":"Entschuldigung, sind Sie aus Mailand?"},{"it":"Siamo di Monaco. E voi, di dove siete?","de":"Wir sind aus München. Und ihr, woher kommt ihr?"},{"it":"Non capisco. Più piano, per favore.","de":"Ich verstehe nicht. Langsamer, bitte."},{"it":"Davide non è di Bologna, è di Napoli.","de":"Davide ist nicht aus Bologna, er ist aus Neapel."}],"spoken":[{"it":"Ma dai!","book":"Non è possibile!","de":"Echt jetzt? (überrascht)","note":"Typische Reaktion auf etwas Überraschendes, unter Freunden ständig zu hören. Je nach Ton heißt es auch: Ach komm!","ex":"Giulia parla tedesco? Ma dai!","exDe":"Giulia spricht Deutsch? Echt jetzt?","alt":[]},{"it":"Come, scusa?","book":"Può ripetere, per favore?","de":"Wie bitte?","note":"So fragst du nach, wenn du etwas nicht verstanden hast. Zu Fremden: Come, scusi?","ex":"Sono di Bolzano. Come, scusa?","exDe":"Ich bin aus Bozen. Wie bitte?","alt":["Scusa, come?","Come, scusi?"]},{"it":"Anch'io!","book":"Anche io.","de":"Ich auch!","note":"Im Gespräch zieht man anche io fast immer zusammen. Verneint heißt es neanch'io (ich auch nicht).","ex":"Parlo inglese. Anch'io!","exDe":"Ich spreche Englisch. Ich auch!","alt":[]},{"it":"Un pochino.","book":"Un po'.","de":"ein kleines bisschen","note":"Klingt bescheiden und sympathisch. Perfekt als Antwort auf Parli italiano?","ex":"Parli italiano? Sì, un pochino!","exDe":"Sprichst du Italienisch? Ja, ein kleines bisschen!","alt":[]},{"it":"Mica male!","book":"Non è male.","de":"Gar nicht übel!","note":"Lockere Anerkennung unter Freunden und Bekannten. mica verstärkt die Verneinung, ungefähr wie gar.","ex":"Parli francese e spagnolo? Mica male!","exDe":"Du sprichst Französisch und Spanisch? Gar nicht übel!","alt":[]},{"it":"Piano piano.","book":"Lentamente.","de":"Schritt für Schritt","note":"Zum Mutmachen, wenn etwas schwer ist, oder wenn es jemand zu eilig hat. Bekanntes Sprichwort: Piano piano si va lontano.","ex":"L'italiano è difficile! Piano piano, dai.","exDe":"Italienisch ist schwer! Na komm, Schritt für Schritt.","alt":[]},{"it":"Sei di qui?","book":"Sei di questa città?","de":"Bist du von hier?","note":"Die typische Frage beim Kennenlernen. Zu Fremden: È di qui?","ex":"Scusa, sei di qui? No, sono di Milano.","exDe":"Entschuldige, bist du von hier? Nein, aus Mailand.","alt":[]},{"it":"Ah, ecco!","book":"Adesso capisco.","de":"Ach so! (jetzt ist alles klar)","note":"Wenn dir plötzlich etwas klar wird. Sehr häufig, überall in Italien.","ex":"Parli tedesco? Sì, sono austriaca. Ah, ecco!","exDe":"Du sprichst Deutsch? Ja, ich bin Österreicherin. Ach so!","alt":[]}],"speak":[{"sit":"Auf einer Party fragt dich jemand: 'Di dove sei?' Sag, dass du aus München bist.","answers":["Sono di Monaco.","Sono tedesco, di Monaco.","Di Monaco di Baviera."],"tip":"Italiener antworten meist mit der Stadt, nicht mit dem Land."},{"sit":"Eine Italienerin fragt dich: 'Parli italiano?' Sag, dass du ein kleines bisschen sprichst.","answers":["Un pochino!","Sì, un po'.","Sì, parlo un pochino di italiano."],"tip":""},{"sit":"Jemand sagt dir etwas, aber du hast es nicht verstanden. Frag locker nach.","answers":["Come, scusa?","Scusa, non capisco.","Scusa, più piano, per favore!"],"tip":"Zu Fremden sagst du scusi statt scusa."},{"sit":"Im Zug sitzt ein älterer Herr neben dir. Frag ihn höflich, woher er kommt.","answers":["Scusi, di dov'è?","Scusi, Lei è di qui?"],"tip":"Bei Fremden nimmst du die Höflichkeitsform: di dov'è? statt di dove sei?"},{"sit":"Giulia sagt: 'Parlo inglese.' Du sprichst auch Englisch. Reagiere ganz kurz.","answers":["Anch'io!","Anch'io parlo inglese!"],"tip":""},{"sit":"Ein neuer Bekannter erzählt, dass er Deutsch, Englisch und Spanisch spricht. Reagiere überrascht und anerkennend.","answers":["Ma dai! Mica male!","Davvero? Mica male!","Ma dai! Parli anche tedesco?"],"tip":""}]},{"id":3,"title":"I numeri","titleDe":"Die Zahlen","goal":"Du kannst bis 100 zählen, dein Alter sagen und Telefonnummern austauschen.","intro":"Zahlen brauchst du überall: beim Bezahlen, für Telefonnummern und wenn jemand fragt, wie alt du bist. Diese Woche lernst du die Zahlen bis 100 und das zweite wichtige Verb: avere (haben).","culture":"In Italien gratuliert man nie vor dem Geburtstag, denn Glückwünsche im Voraus bringen Unglück. Die Unglückszahl ist nicht die 13, sondern die 17: Als römische Zahl XVII ergibt sie umgestellt VIXI, lateinisch für 'ich habe gelebt', also: ich bin tot. Die 13 gilt dagegen oft als Glückszahl.","vocab":[{"it":"zero","de":"0 (null)","alt":[],"note":"","ex":"Ho zero euro!","exDe":"Ich habe null Euro!"},{"it":"uno","de":"1 (eins)","alt":[],"note":"Vor einem Nomen wird es zu un oder una.","ex":"Uno, due, tre... via!","exDe":"Eins, zwei, drei ... los!"},{"it":"due","de":"2 (zwei)","alt":[],"note":"","ex":"Due caffè, per favore.","exDe":"Zwei Kaffee, bitte."},{"it":"tre","de":"3 (drei)","alt":[],"note":"Allein ohne Akzent, in längeren Zahlen mit: ventitré.","ex":"Sono tre euro.","exDe":"Das macht drei Euro."},{"it":"quattro","de":"4 (vier)","alt":[],"note":"Aussprache: kuat tro. Das tt hört man lang.","ex":"Siamo in quattro.","exDe":"Wir sind zu viert."},{"it":"cinque","de":"5 (fünf)","alt":[],"note":"Aussprache: tschin kue.","ex":"Cinque minuti, per favore!","exDe":"Fünf Minuten, bitte!"},{"it":"sei","de":"6 (sechs)","alt":[],"note":"Klingt genau wie tu sei (du bist).","ex":"Ciao! Hai sei anni?","exDe":"Hallo! Bist du sechs Jahre alt?"},{"it":"sette","de":"7 (sieben)","alt":[],"note":"","ex":"Sette euro, grazie.","exDe":"Sieben Euro, danke."},{"it":"otto","de":"8 (acht)","alt":[],"note":"","ex":"Il bambino ha otto anni.","exDe":"Das Kind ist acht Jahre alt."},{"it":"nove","de":"9 (neun)","alt":[],"note":"","ex":"Sono nove euro, signora.","exDe":"Das macht neun Euro."},{"it":"dieci","de":"10 (zehn)","alt":[],"note":"Aussprache: die tschi.","ex":"Dieci caffè? Siamo in dieci!","exDe":"Zehn Kaffee? Wir sind zu zehnt!"},{"it":"Quanti anni hai?","de":"Wie alt bist du?","alt":[],"note":"Wörtlich: Wie viele Jahre hast du? Höflich (Lei): Quanti anni ha?","ex":"Lukas, quanti anni hai?","exDe":"Lukas, wie alt bist du?"},{"it":"undici","de":"11 (elf)","alt":[],"note":"Von 11 bis 16 liegt die Betonung auf der drittletzten Silbe: UN di tschi.","ex":"Sono undici euro.","exDe":"Das macht elf Euro."},{"it":"dodici","de":"12 (zwölf)","alt":[],"note":"Betonung vorne: DO di tschi.","ex":"La ragazza ha dodici anni.","exDe":"Das Mädchen ist zwölf Jahre alt."},{"it":"tredici","de":"13 (dreizehn)","alt":[],"note":"Betonung vorne: TRE di tschi.","ex":"Siamo in tredici!","exDe":"Wir sind zu dreizehnt!"},{"it":"quattordici","de":"14 (vierzehn)","alt":[],"note":"Betonung auf tor: kuat TOR di tschi.","ex":"Ho quattordici euro.","exDe":"Ich habe vierzehn Euro."},{"it":"quindici","de":"15 (fünfzehn)","alt":[],"note":"Betonung vorne: KUIN di tschi.","ex":"Hai quindici anni?","exDe":"Bist du fünfzehn?"},{"it":"sedici","de":"16 (sechzehn)","alt":[],"note":"Betonung vorne: SE di tschi.","ex":"Sono sedici euro.","exDe":"Das macht sechzehn Euro."},{"it":"diciassette","de":"17 (siebzehn)","alt":[],"note":"Ab 17 steht die Zehn vorne: dieci und sette.","ex":"Il numero diciassette porta sfortuna.","exDe":"Die Zahl Siebzehn bringt Unglück."},{"it":"diciotto","de":"18 (achtzehn)","alt":[],"note":"dieci und otto in einem Wort.","ex":"Domani ho diciotto anni!","exDe":"Morgen werde ich achtzehn!"},{"it":"diciannove","de":"19 (neunzehn)","alt":[],"note":"dieci und nove in einem Wort.","ex":"La ragazza ha diciannove anni.","exDe":"Die junge Frau ist neunzehn."},{"it":"venti","de":"20 (zwanzig)","alt":[],"note":"Bei 21 und 28 fällt das i weg: ventuno, ventotto.","ex":"Sono venti euro, grazie.","exDe":"Das macht zwanzig Euro, danke."},{"it":"avere","de":"haben","alt":[],"note":"Unregelmäßig: io ho, tu hai, lui/lei ha. Das h ist stumm.","ex":"Hai un minuto?","exDe":"Hast du eine Minute?"},{"it":"il numero di telefono","de":"die Telefonnummer","alt":[],"note":"Kurz: il numero.","ex":"Hai il numero di telefono di Giulia?","exDe":"Hast du Giulias Telefonnummer?"},{"it":"trenta","de":"30 (dreißig)","alt":[],"note":"Vor anni oft mit Apostroph: trent'anni.","ex":"Quanti anni hai? Trenta.","exDe":"Wie alt bist du? Dreißig."},{"it":"quaranta","de":"40 (vierzig)","alt":[],"note":"","ex":"Siamo in quaranta!","exDe":"Wir sind zu vierzig!"},{"it":"cinquanta","de":"50 (fünfzig)","alt":[],"note":"","ex":"Sono cinquanta euro.","exDe":"Das macht fünfzig Euro."},{"it":"sessanta","de":"60 (sechzig)","alt":[],"note":"","ex":"Quanti anni ha Franco? Sessanta.","exDe":"Wie alt ist Franco? Sechzig."},{"it":"settanta","de":"70 (siebzig)","alt":[],"note":"","ex":"Settanta euro? No, grazie!","exDe":"Siebzig Euro? Nein, danke!"},{"it":"ottanta","de":"80 (achtzig)","alt":[],"note":"","ex":"Ottanta? No, ottantadue!","exDe":"Achtzig? Nein, zweiundachtzig!"},{"it":"novanta","de":"90 (neunzig)","alt":[],"note":"","ex":"Novanta minuti di calcio!","exDe":"Neunzig Minuten Fußball!"},{"it":"cento","de":"100 (hundert)","alt":[],"note":"Ohne uno davor: cento heißt hundert.","ex":"Cento euro? Grazie mille!","exDe":"Hundert Euro? Vielen Dank!"},{"it":"il compleanno","de":"der Geburtstag","alt":[],"note":"","ex":"Domani è il compleanno di Giulia.","exDe":"Morgen hat Giulia Geburtstag."},{"it":"Buon compleanno!","de":"Alles Gute zum Geburtstag!","alt":["Tanti auguri!"],"note":"Oft auch: Tanti auguri! Aber nie vor dem Geburtstag.","ex":"Buon compleanno, Giulia!","exDe":"Alles Gute zum Geburtstag, Giulia!"},{"it":"avere fame","de":"Hunger haben","alt":[],"note":"Ho fame heißt: Ich habe Hunger.","ex":"Ho fame! E tu?","exDe":"Ich habe Hunger! Und du?"},{"it":"avere sete","de":"Durst haben","alt":[],"note":"Ho sete heißt: Ich habe Durst.","ex":"Hai sete, Lukas?","exDe":"Hast du Durst, Lukas?"}],"grammar":{"title":"Das Verb avere und Ausdrücke mit avere","points":["<b>avere</b> (haben) ist neben essere das zweite wichtige Verb. Auch avere ist unregelmäßig. Das <b>h</b> schreibt man, spricht es aber nie: <b>ho</b> klingt wie o, <b>hanno</b> (sie haben) genau wie anno (Jahr).","Dein Alter sagst du mit avere: <b>Ho trent'anni.</b> Wörtlich: Ich habe dreißig Jahre. Die Frage dazu lautet <b>Quanti anni hai?</b>","Auch Hunger und Durst 'hat' man: <b>ho fame</b> (ich habe Hunger), <b>ho sete</b> (ich habe Durst), <b>ho freddo</b> (mir ist kalt), <b>ho caldo</b> (mir ist warm), <b>ho sonno</b> (ich bin müde).","Ab 21 hängst du die Einer einfach an: <b>ventidue, trentacinque</b>. Bei <b>uno</b> und <b>otto</b> fällt der letzte Vokal der Zehnerzahl weg: <b>ventuno, trentotto</b>. Mit <b>tre</b> am Ende bekommt die Zahl einen Akzent: <b>ventitré</b>."],"table":{"head":["Person","avere","Beispiel"],"rows":[["io","ho","Ho fame."],["tu","hai","Hai sete?"],["lui / lei / Lei","ha","Ha trent'anni."],["noi","abbiamo","Abbiamo freddo."],["voi","avete","Avete caldo?"],["loro","hanno","Hanno sonno."]]},"examples":[{"it":"Quanti anni hai? Ho ventotto anni.","de":"Wie alt bist du? Ich bin achtundzwanzig."},{"it":"Lukas ha fame e anche sete.","de":"Lukas hat Hunger und auch Durst."},{"it":"Abbiamo freddo!","de":"Uns ist kalt!"},{"it":"Nonna Lucia ha ottantadue anni.","de":"Oma Lucia ist zweiundachtzig."},{"it":"Matteo e Giulia hanno sonno.","de":"Matteo und Giulia sind müde."}],"drills":[{"type":"choice","q":"Io ___ trent'anni.","de":"Ich bin dreißig Jahre alt.","options":["sono","ho","hai"],"answer":1,"why":"Das Alter sagt man mit avere: io ho."},{"type":"type","q":"Giulia, quanti anni ___?","de":"Giulia, wie alt bist du?","answer":"hai","alt":[],"why":"Zu tu gehört hai."},{"type":"choice","q":"Lukas ___ fame.","de":"Lukas hat Hunger.","options":["ha","hai","è"],"answer":0,"why":"Zu lui (Lukas) gehört ha."},{"type":"type","q":"Noi ___ sete.","de":"Wir haben Durst.","answer":"abbiamo","alt":[],"why":"Zu noi gehört abbiamo."},{"type":"choice","q":"Voi ___ freddo?","de":"Ist euch kalt?","options":["hanno","abbiamo","avete"],"answer":2,"why":"Zu voi gehört avete."},{"type":"type","q":"Rosa e Franco ___ sonno.","de":"Rosa und Franco sind müde.","answer":"hanno","alt":[],"why":"Zu loro (Rosa und Franco) gehört hanno."},{"type":"choice","q":"Ho ___! Acqua, per favore!","de":"Ich habe Durst! Wasser, bitte!","options":["fame","sete","sonno"],"answer":1,"why":"Wer Wasser will, hat Durst: ho sete."},{"type":"type","q":"Domani Giulia ha ___ anni. (28)","de":"Morgen wird Giulia achtundzwanzig.","answer":"ventotto","alt":[],"why":"Bei otto fällt das i von venti weg: ventotto."}]},"dialog":{"title":"Il numero di Giulia","setting":"Am Ende des Abends tauschen Lukas und Giulia ihre Telefonnummern.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Giulia","gender":"f"}},"lines":[{"s":"A","it":"Giulia, mi dai il tuo numero?","de":"Giulia, gibst du mir deine Nummer?"},{"s":"B","it":"Certo! Tre quattro sette, sei due nove, quindici, ottanta.","de":"Klar! Drei vier sieben, sechs zwei neun, fünfzehn, achtzig."},{"s":"A","it":"Un attimo! Tre quattro sette, sei due nove...","de":"Sekunde! Drei vier sieben, sechs zwei neun ..."},{"s":"B","it":"... quindici, ottanta. Ce l'hai?","de":"... fünfzehn, achtzig. Hast du sie?"},{"s":"A","it":"Sì, ce l'ho! Ti faccio uno squillo, ok?","de":"Ja, hab ich! Ich klingel kurz bei dir an, okay?"},{"s":"B","it":"Perfetto! Senti, ma quanti anni hai?","de":"Super! Sag mal, wie alt bist du eigentlich?"},{"s":"A","it":"Trenta. E tu?","de":"Dreißig. Und du?"},{"s":"B","it":"Ventisette, ma domani è il mio compleanno!","de":"Siebenundzwanzig, aber morgen hab ich Geburtstag!"},{"s":"A","it":"Ma dai! Allora tanti auguri!","de":"Echt jetzt? Dann alles Gute!"},{"s":"B","it":"No, no, oggi no! Porta sfortuna!","de":"Nein, nein, nicht heute! Das bringt Unglück!"},{"s":"A","it":"Ah, scusa! Allora a domani, con una torta!","de":"Oh, Entschuldigung! Dann bis morgen, mit Torte!"},{"s":"B","it":"Sì, dai! Ho già fame!","de":"Oh ja! Ich hab jetzt schon Hunger!"}],"questions":[{"q":"Wie alt ist Giulia heute?","options":["27 Jahre","28 Jahre","30 Jahre"],"answer":0},{"q":"Was ist morgen?","options":["Lukas hat Geburtstag","Lukas fliegt nach München","Giulia hat Geburtstag"],"answer":2},{"q":"Warum will Giulia heute keine Glückwünsche?","options":["Sie hat Hunger","Das bringt Unglück","Sie ist müde"],"answer":1}]},"sentences":[{"it":"Quanti anni hai? Ho trent'anni.","de":"Wie alt bist du? Ich bin dreißig."},{"it":"Domani Giulia ha ventotto anni.","de":"Morgen wird Giulia achtundzwanzig."},{"it":"Ho fame e anche un po' di sete.","de":"Ich habe Hunger und auch ein bisschen Durst."},{"it":"Qual è il tuo numero di telefono?","de":"Wie ist deine Telefonnummer?"},{"it":"Domani è il compleanno di Giulia.","de":"Morgen hat Giulia Geburtstag."},{"it":"Abbiamo sonno, ma non abbiamo fame.","de":"Wir sind müde, aber wir haben keinen Hunger."},{"it":"Avete caldo o freddo, ragazzi?","de":"Ist euch warm oder kalt, Leute?"},{"it":"Sono di Monaco e ho trent'anni.","de":"Ich bin aus München und bin dreißig Jahre alt."}],"spoken":[{"it":"Più o meno.","book":"Circa.","de":"ungefähr; so um die","note":"Sehr praktisch bei Alter, Preisen und Zahlen. Passt überall.","ex":"Quanti anni ha Franco? Sessanta, più o meno.","exDe":"Wie alt ist Franco? So um die sechzig.","alt":[]},{"it":"Ce l'hai?","book":"Lo hai?","de":"Hast du's?","note":"Im Alltag sagt man bei haben mit einer Sache fast immer ce l'ho, ce l'hai. Antwort: Sì, ce l'ho oder No, non ce l'ho.","ex":"Ce l'hai il numero di Giulia?","exDe":"Hast du Giulias Nummer?","alt":[]},{"it":"Che fame!","book":"Ho fame.","de":"Hab ich einen Hunger!","note":"Mit che klingt alles stärker: Che sete! Che sonno! Che freddo! Hört man ständig, überall.","ex":"Che fame! Hai fame anche tu?","exDe":"Hab ich einen Hunger! Hast du auch Hunger?","alt":[]},{"it":"Pronto?","book":"","de":"Hallo? (am Telefon)","note":"So meldet man sich am Telefon, privat und im Büro. Wörtlich heißt pronto: bereit.","ex":"Pronto? Ciao Giulia, sono Lukas!","exDe":"Hallo? Hi Giulia, hier ist Lukas!","alt":[]},{"it":"Ti faccio uno squillo.","book":"Ti telefono.","de":"Ich klingel kurz bei dir an.","note":"Typisch beim Nummerntausch: kurz anrufen, gleich wieder auflegen, schon hat der andere deine Nummer. Unter Freunden.","ex":"Ti faccio uno squillo, ok?","exDe":"Ich klingel kurz bei dir an, okay?","alt":[]},{"it":"Cento di questi giorni!","book":"Buon compleanno!","de":"Auf viele weitere Jahre!","note":"Klassischer Geburtstagswunsch, wörtlich: hundert solcher Tage. Bei Älteren besonders beliebt.","ex":"Buon compleanno, nonna! Cento di questi giorni!","exDe":"Alles Gute, Oma! Auf viele weitere Jahre!","alt":[]},{"it":"Non li dimostri!","book":"Sembri più giovane.","de":"Das sieht man dir nicht an! (beim Alter)","note":"Nettes Kompliment, wenn jemand sein Alter verrät. li steht für die Jahre. Zu Fremden: Non li dimostra!","ex":"Ho quarant'anni. Davvero? Non li dimostri!","exDe":"Ich bin vierzig. Echt? Sieht man dir nicht an!","alt":["Non li dimostra!"]},{"it":"Quanti anni mi dai?","book":"Quanti anni ho, secondo te?","de":"Was schätzt du, wie alt ich bin?","note":"Beliebtes Spiel beim Kennenlernen, immer mit einem Augenzwinkern. Unter Freunden und Bekannten.","ex":"Quanti anni mi dai? Mah... trenta?","exDe":"Was schätzt du, wie alt ich bin? Hm ... dreißig?","alt":[]}],"speak":[{"sit":"Eine neue Bekannte fragt dich: 'Quanti anni hai?' Du bist dreißig. Antworte und frag zurück.","answers":["Ho trent'anni. E tu?","Trenta. E tu?","Trenta! Tu quanti anni hai?"],"tip":"Oft sagt man nur die Zahl, ohne anni."},{"sit":"Du möchtest Giulias Telefonnummer haben. Frag sie danach.","answers":["Qual è il tuo numero?","Mi dai il tuo numero?"],"tip":"Mi dai ...? heißt: Gibst du mir ...?"},{"sit":"Du hast seit dem Frühstück nichts gegessen. Sag deinen Freunden, dass du riesigen Hunger hast.","answers":["Che fame!","Ho fame!","Ho una fame!"],"tip":""},{"sit":"Dein älterer Nachbar hat heute Geburtstag. Gratuliere ihm herzlich.","answers":["Buon compleanno!","Tanti auguri!","Cento di questi giorni!"],"tip":"Gratuliere in Italien nie vor dem Geburtstag."},{"sit":"Jemand diktiert dir eine Telefonnummer viel zu schnell. Bitte um einen Moment und dass er langsamer spricht.","answers":["Un attimo! Più piano, per favore.","Scusa, un attimo! Più piano!"],"tip":""},{"sit":"Ein Bekannter erzählt, dass er fünfzig ist. Er sieht viel jünger aus. Mach ihm ein Kompliment.","answers":["Non li dimostri!","Cinquanta? Ma dai! Non li dimostri!"],"tip":""}]},{"id":4,"title":"Al bar","titleDe":"In der Bar","goal":"Du kannst in einer italienischen Bar bestellen und bezahlen.","intro":"Die Bar ist das zweite Wohnzimmer der Italiener: morgens Cappuccino und Cornetto, mittags ein schneller Espresso, abends ein Aperitivo. Diese Woche lernst du, wie du bestellst und bezahlst. Dazu kommen die Artikel: der, die, ein, eine.","culture":"Cappuccino trinkt man in Italien nur morgens, nach dem Mittagessen bestellt man einen caffè. An der Theke (al banco) trinkt man schnell im Stehen, am Tisch (al tavolo) kostet derselbe Kaffee oft mehr. In vielen Bars zahlst du zuerst an der Kasse und gibst dann den scontrino an der Theke ab.","vocab":[{"it":"il caffè","de":"der Kaffee (Espresso)","alt":["il caffe"],"note":"In Italien ist un caffè immer ein Espresso.","ex":"Un caffè, per favore.","exDe":"Einen Kaffee, bitte."},{"it":"il cappuccino","de":"der Cappuccino","alt":[],"note":"Trinkt man nur morgens zum Frühstück.","ex":"Un cappuccino e un cornetto!","exDe":"Einen Cappuccino und ein Hörnchen!"},{"it":"il cornetto","de":"das Hörnchen (Croissant)","alt":[],"note":"Oft gefüllt: alla crema, alla marmellata. In Norditalien sagt man auch brioche.","ex":"Vorrei un cornetto alla crema.","exDe":"Ich hätte gern ein Hörnchen mit Creme."},{"it":"vorrei","de":"ich hätte gern; ich möchte","alt":[],"note":"Die höfliche Form zum Bestellen.","ex":"Vorrei un tè, per favore.","exDe":"Ich hätte gern einen Tee, bitte."},{"it":"per me","de":"für mich","alt":[],"note":"Beim Bestellen: Per me un caffè.","ex":"Per me un cappuccino, grazie.","exDe":"Für mich einen Cappuccino, danke."},{"it":"Cosa prende?","de":"Was nehmen Sie?","alt":["Che cosa prende?"],"note":"Das fragt der Barista. Zu Freunden: Cosa prendi?","ex":"Buongiorno! Cosa prende?","exDe":"Guten Morgen! Was nehmen Sie?"},{"it":"l'acqua","de":"das Wasser","alt":["acqua"],"note":"Feminin. Naturale heißt still, frizzante heißt mit Kohlensäure.","ex":"Un'acqua frizzante, per favore.","exDe":"Ein Wasser mit Kohlensäure, bitte."},{"it":"il tè","de":"der Tee","alt":["il te"],"note":"Mit Akzent auf dem e.","ex":"Il tè è per Giulia.","exDe":"Der Tee ist für Giulia."},{"it":"il latte","de":"die Milch","alt":[],"note":"Achtung: Wer in Italien un latte bestellt, bekommt nur Milch!","ex":"Un bicchiere di latte, per favore.","exDe":"Ein Glas Milch, bitte."},{"it":"lo zucchero","de":"der Zucker","alt":[],"note":"Vor z steht lo.","ex":"Senza zucchero, grazie.","exDe":"Ohne Zucker, danke."},{"it":"Quanto costa?","de":"Wie viel kostet das?","alt":[],"note":"","ex":"Scusi, quanto costa un cornetto?","exDe":"Entschuldigung, wie viel kostet ein Hörnchen?"},{"it":"il conto","de":"die Rechnung","alt":[],"note":"","ex":"Il conto, per favore.","exDe":"Die Rechnung, bitte."},{"it":"il bar","de":"die Bar; das Café","alt":[],"note":"Ein Café für Kaffee, Frühstück und kleine Snacks. Plural: i bar.","ex":"Ci vediamo al bar!","exDe":"Wir sehen uns in der Bar!"},{"it":"il banco","de":"die Theke (in der Bar)","alt":[],"note":"Al banco heißt: im Stehen an der Theke.","ex":"Al banco o al tavolo?","exDe":"An der Theke oder am Tisch?"},{"it":"la cassa","de":"die Kasse","alt":[],"note":"","ex":"Scusi, dov'è la cassa?","exDe":"Entschuldigung, wo ist die Kasse?"},{"it":"lo scontrino","de":"der Kassenbon","alt":[],"note":"Vor s plus Konsonant steht lo.","ex":"Ecco lo scontrino.","exDe":"Hier ist der Kassenbon."},{"it":"pagare","de":"bezahlen","alt":[],"note":"io pago, tu paghi. Das h hält das g hart.","ex":"Scusi, dove pago?","exDe":"Entschuldigung, wo zahle ich?"},{"it":"Quant'è?","de":"Was macht das? (beim Zahlen)","alt":["Quant'e?","Quanto è?"],"note":"Kurz für quanto è.","ex":"Grazie. Quant'è?","exDe":"Danke. Was macht das?"},{"it":"ecco","de":"hier ist; bitte schön (beim Geben)","alt":[],"note":"Ecco il caffè! heißt: Hier ist der Kaffee!","ex":"Ecco il cappuccino!","exDe":"Hier ist der Cappuccino!"},{"it":"il resto","de":"das Wechselgeld","alt":[],"note":"Wörtlich: der Rest.","ex":"Ecco il resto, signore.","exDe":"Hier ist Ihr Wechselgeld."},{"it":"senza","de":"ohne","alt":[],"note":"","ex":"Un caffè senza zucchero.","exDe":"Einen Kaffee ohne Zucker."},{"it":"con","de":"mit","alt":[],"note":"","ex":"Per me un tè con zucchero.","exDe":"Für mich einen Tee mit Zucker."},{"it":"il bicchiere","de":"das Glas (zum Trinken)","alt":[],"note":"Un bicchiere d'acqua heißt: ein Glas Wasser.","ex":"Un bicchiere d'acqua, per favore.","exDe":"Ein Glas Wasser, bitte."},{"it":"la tazza","de":"die Tasse","alt":[],"note":"","ex":"Una tazza di tè, per favore.","exDe":"Eine Tasse Tee, bitte."},{"it":"la spremuta","de":"der frisch gepresste Saft","alt":[],"note":"Spremuta d'arancia heißt: frisch gepresster Orangensaft.","ex":"Vorrei una spremuta d'arancia.","exDe":"Ich hätte gern einen frisch gepressten Orangensaft."},{"it":"il succo di frutta","de":"der Fruchtsaft","alt":[],"note":"Aus der Flasche, nicht frisch gepresst.","ex":"Per me un succo di frutta.","exDe":"Für mich einen Fruchtsaft."},{"it":"la cioccolata calda","de":"die heiße Schokolade","alt":[],"note":"In Italien sehr dick, fast wie Pudding.","ex":"Una cioccolata calda, grazie!","exDe":"Eine heiße Schokolade, danke!"},{"it":"il caffè macchiato","de":"der Espresso mit etwas Milch","alt":["il macchiato","il caffe macchiato"],"note":"Macchiato heißt befleckt: Espresso mit einem Klecks Milchschaum.","ex":"Per me un caffè macchiato.","exDe":"Für mich einen Espresso mit etwas Milch."},{"it":"il caffellatte","de":"der Milchkaffee","alt":["il caffelatte"],"note":"Viel Milch, wenig Kaffee. Meist zu Hause zum Frühstück.","ex":"Un caffellatte, per favore.","exDe":"Einen Milchkaffee, bitte."},{"it":"il panino","de":"das belegte Brötchen","alt":[],"note":"","ex":"Un panino e una birra!","exDe":"Ein belegtes Brötchen und ein Bier!"},{"it":"il tramezzino","de":"das dreieckige Sandwich","alt":[],"note":"Weiches Toastbrot ohne Rinde, typisch für die Bar.","ex":"Vorrei un tramezzino, per favore.","exDe":"Ich hätte gern ein Sandwich, bitte."},{"it":"l'aranciata","de":"die Orangenlimonade","alt":["aranciata"],"note":"Feminin.","ex":"Un'aranciata, per favore.","exDe":"Eine Orangenlimonade, bitte."},{"it":"la birra","de":"das Bier","alt":[],"note":"","ex":"Una birra? Sì, grazie!","exDe":"Ein Bier? Ja, danke!"},{"it":"il vino","de":"der Wein","alt":[],"note":"Rosso oder bianco: rot oder weiß.","ex":"Un bicchiere di vino?","exDe":"Ein Glas Wein?"},{"it":"l'aperitivo","de":"der Aperitif","alt":["aperitivo"],"note":"Maskulin. Am frühen Abend, mit kleinen Snacks.","ex":"Un aperitivo, Giulia?","exDe":"Einen Aperitif, Giulia?"},{"it":"lo spritz","de":"der Spritz","alt":[],"note":"Vor s plus Konsonant steht lo: uno spritz.","ex":"Uno spritz, per favore!","exDe":"Einen Spritz, bitte!"}],"grammar":{"title":"Der Artikel: il, lo, la, l' und un, uno, una","points":["Jedes Nomen ist maskulin oder feminin. Faustregel: Endung <b>o</b> ist meist maskulin (il cornetto), Endung <b>a</b> meist feminin (la tazza). Bei Endung <b>e</b> lernst du das Geschlecht mit: il latte, la notte.","Der bestimmte Artikel (der, die, das): maskulin <b>il</b>, vor s plus Konsonant und vor z <b>lo</b> (lo scontrino, lo zucchero), vor Vokal <b>l'</b> (l'aperitivo). Feminin <b>la</b>, vor Vokal <b>l'</b> (l'acqua).","Der unbestimmte Artikel (ein, eine): <b>un</b> caffè, <b>uno</b> spritz, <b>una</b> birra. Vor Vokal steht maskulin <b>un</b> ohne Apostroph (un aperitivo), feminin <b>un'</b> mit Apostroph (un'aranciata).","Lerne jedes Nomen immer mit Artikel, also nicht nur caffè, sondern <b>il caffè</b>. Wörter aus anderen Sprachen sind meist maskulin: il bar, lo spritz."],"table":{"head":["","maskulin","feminin"],"rows":[["vor Konsonant","il caffè / un caffè","la tazza / una tazza"],["vor s plus Konsonant, z","lo spritz / uno spritz","la spremuta / una spremuta"],["vor Vokal","l'aperitivo / un aperitivo","l'acqua / un'acqua"]]},"examples":[{"it":"Un caffè e un cornetto, per favore.","de":"Einen Kaffee und ein Hörnchen, bitte."},{"it":"Vorrei uno spritz e un'aranciata.","de":"Ich hätte gern einen Spritz und eine Orangenlimonade."},{"it":"Il cappuccino è per Lukas.","de":"Der Cappuccino ist für Lukas."},{"it":"Lo zucchero, per favore.","de":"Den Zucker, bitte."},{"it":"L'acqua è per me.","de":"Das Wasser ist für mich."},{"it":"Un aperitivo? Sì, grazie!","de":"Einen Aperitif? Ja, danke!"}],"drills":[{"type":"choice","q":"___ cappuccino, per favore.","de":"Einen Cappuccino, bitte.","options":["Uno","Un","Una"],"answer":1,"why":"cappuccino ist maskulin und beginnt mit c: un."},{"type":"choice","q":"Vorrei ___ spritz.","de":"Ich hätte gern einen Spritz.","options":["un","una","uno"],"answer":2,"why":"Vor s plus Konsonant steht uno."},{"type":"type","q":"Vorrei ___ spremuta.","de":"Ich hätte gern einen frisch gepressten Saft.","answer":"una","alt":[],"why":"spremuta ist feminin und beginnt mit Konsonant: una."},{"type":"choice","q":"Per me ___ aranciata.","de":"Für mich eine Orangenlimonade.","options":["un'","un","uno"],"answer":0,"why":"aranciata ist feminin und beginnt mit Vokal: un'."},{"type":"type","q":"Dov'è ___ zucchero?","de":"Wo ist der Zucker?","answer":"lo","alt":[],"why":"Vor z steht lo."},{"type":"choice","q":"___ acqua è per Lukas.","de":"Das Wasser ist für Lukas.","options":["La","L'","Lo"],"answer":1,"why":"acqua ist feminin und beginnt mit Vokal: l'."},{"type":"type","q":"Scusi, ___ conto, per favore.","de":"Entschuldigung, die Rechnung, bitte.","answer":"il","alt":[],"why":"conto ist maskulin und beginnt mit c: il."},{"type":"choice","q":"Un caffè e ___ aperitivo.","de":"Einen Kaffee und einen Aperitif.","options":["un","un'","uno"],"answer":0,"why":"aperitivo ist maskulin: un ohne Apostroph, auch vor Vokal."}]},"dialog":{"title":"Un cappuccino, per favore","setting":"Morgens in einer kleinen Bar in Bologna. Lukas frühstückt an der Theke.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Barista","gender":"f"}},"lines":[{"s":"B","it":"Buongiorno! Mi dica!","de":"Guten Morgen! Was darf's sein?"},{"s":"A","it":"Buongiorno! Mi fa un cappuccino e un cornetto?","de":"Morgen! Kriege ich einen Cappuccino und ein Hörnchen?"},{"s":"B","it":"Certo! Il cornetto alla crema o alla marmellata?","de":"Klar! Das Hörnchen mit Creme oder mit Marmelade?"},{"s":"A","it":"Alla crema. E un bicchiere d'acqua, per favore.","de":"Mit Creme. Und ein Glas Wasser, bitte."},{"s":"B","it":"Ecco a Lei! Zucchero?","de":"Bitte sehr! Zucker?"},{"s":"A","it":"No, senza zucchero, grazie.","de":"Nein, ohne Zucker, danke."},{"s":"B","it":"Perfetto. Altro?","de":"Perfekt. Sonst noch was?"},{"s":"A","it":"No, nient'altro, grazie. Quant'è?","de":"Nein, sonst nichts, danke. Was macht das?"},{"s":"B","it":"Tre e cinquanta. Alla cassa, per favore.","de":"Drei fünfzig. An der Kasse, bitte."},{"s":"A","it":"Ok. Ecco cinque euro.","de":"Okay. Hier sind fünf Euro."},{"s":"B","it":"Grazie! Ecco il resto e lo scontrino.","de":"Danke! Hier, Ihr Wechselgeld und der Bon."},{"s":"A","it":"Grazie, buona giornata!","de":"Danke, schönen Tag noch!"}],"questions":[{"q":"Was isst Lukas zum Frühstück?","options":["Ein Hörnchen mit Creme","Ein Hörnchen mit Marmelade","Ein belegtes Brötchen"],"answer":0},{"q":"Wie trinkt Lukas seinen Cappuccino?","options":["Mit viel Zucker","Ohne Zucker","Mit Milch und Zucker"],"answer":1},{"q":"Wo bezahlt Lukas?","options":["Am Tisch","An der Theke","An der Kasse"],"answer":2}]},"sentences":[{"it":"Vorrei un caffè e un cornetto.","de":"Ich hätte gern einen Kaffee und ein Hörnchen."},{"it":"Per me un cappuccino senza zucchero.","de":"Für mich einen Cappuccino ohne Zucker."},{"it":"Scusi, quanto costa una spremuta?","de":"Entschuldigung, wie viel kostet ein frisch gepresster Saft?"},{"it":"Il conto, per favore. Quant'è?","de":"Die Rechnung, bitte. Was macht das?"},{"it":"Un bicchiere d'acqua, per favore.","de":"Ein Glas Wasser, bitte."},{"it":"Uno spritz e un'aranciata, per favore.","de":"Einen Spritz und eine Orangenlimonade, bitte."},{"it":"Ecco lo scontrino, grazie mille.","de":"Hier ist der Kassenbon, vielen Dank."},{"it":"Un tè con latte e zucchero.","de":"Einen Tee mit Milch und Zucker."}],"spoken":[{"it":"Mi dica!","book":"Cosa desidera?","de":"Was darf's sein?","note":"So begrüßt dich der Barista oder Verkäufer. Wörtlich: Sagen Sie mir! Das ist ganz normal und höflich.","ex":"Buongiorno, mi dica! Un caffè, per favore.","exDe":"Guten Morgen, was darf's sein? Einen Kaffee, bitte.","alt":["Prego, dica!","Dica!"]},{"it":"Mi fa un caffè?","book":"Vorrei un caffè, per favore.","de":"Machen Sie mir einen Kaffee?","note":"So bestellen viele Italiener an der Bar, locker und trotzdem höflich. Geht mit allem: Mi fa un cappuccino?","ex":"Scusi, mi fa un caffè macchiato?","exDe":"Entschuldigung, machen Sie mir einen Macchiato?","alt":[]},{"it":"Un caffè al volo","book":"Un caffè veloce","de":"schnell einen Kaffee im Stehen","note":"Al volo heißt im Flug: an der Theke kurz trinken und weiter. Typisch italienisch, vor allem morgens.","ex":"Un caffè al volo? Sì, dai!","exDe":"Schnell einen Kaffee? Ja, komm!","alt":[]},{"it":"Il solito?","book":"Come sempre?","de":"Wie immer?","note":"Fragt der Barista seine Stammgäste. Wer jeden Morgen in dieselbe Bar geht, hört das schnell.","ex":"Ciao Lukas! Il solito? Sì, grazie!","exDe":"Hi Lukas! Wie immer? Ja, danke!","alt":[]},{"it":"Ecco a Lei.","book":"Ecco il Suo caffè.","de":"Bitte sehr! (höflich beim Überreichen)","note":"Sagen Barista, Kellner und Verkäufer, wenn sie dir etwas geben. Unter Freunden: Ecco a te!","ex":"Un cappuccino e un cornetto. Ecco a Lei!","exDe":"Ein Cappuccino und ein Hörnchen. Bitte sehr!","alt":[]},{"it":"Nient'altro, grazie.","book":"No, non desidero altro.","de":"Sonst nichts, danke.","note":"Die Antwort, wenn jemand Altro? fragt. Noch kürzer: Niente, grazie.","ex":"Altro? No, nient'altro, grazie.","exDe":"Sonst noch was? Nein, sonst nichts, danke.","alt":["Niente, grazie."]},{"it":"Offro io!","book":"Pago io per te.","de":"Ich lade dich ein!","note":"Unter Freunden streitet man in der Bar gern ums Bezahlen. Wer zuerst Offro io! sagt, zahlt. Genauso üblich: Pago io!","ex":"Due spritz? Dai, offro io!","exDe":"Zwei Spritz? Komm, ich lade dich ein!","alt":["Pago io!"]},{"it":"Cin cin!","book":"Salute!","de":"Prost!","note":"Beim Anstoßen, vor allem beim Aperitivo. Dabei schaut man sich in die Augen!","ex":"Allora... cin cin!","exDe":"Also dann ... Prost!","alt":[]}],"speak":[{"sit":"Du stehst morgens an der Bar und möchtest einen Cappuccino und ein Hörnchen.","answers":["Un cappuccino e un cornetto, per favore.","Mi fa un cappuccino e un cornetto?","Vorrei un cappuccino e un cornetto."],"tip":"'Mi fa ...?' hörst du an jeder Bar."},{"sit":"Am Abend bestellst du für dich und Giulia zwei Spritz.","answers":["Due spritz, per favore.","Mi fa due spritz?","Per noi due spritz, per favore."],"tip":"spritz bleibt im Plural gleich."},{"sit":"Die Barista fragt: 'Altro?' Du möchtest nichts mehr.","answers":["Nient'altro, grazie.","No, grazie. Quant'è?"],"tip":""},{"sit":"Du bist unsicher, ob du zuerst an der Kasse zahlen musst. Frag die Barista.","answers":["Scusi, pago alla cassa?","Scusi, dove pago?"],"tip":"In vielen Bars zahlst du zuerst an der Kasse und gibst den scontrino an der Theke ab."},{"sit":"Du bist mit Giulia beim Aperitivo und willst für beide bezahlen.","answers":["Offro io!","Pago io!","Dai, offro io!"],"tip":""},{"sit":"Die Getränke sind da. Stoß mit Giulia an.","answers":["Cin cin!","Cin cin, Giulia!","Salute!"],"tip":""}]},{"id":5,"title":"La mia famiglia","titleDe":"Meine Familie","goal":"Du kannst deine Familie vorstellen und Menschen beschreiben.","intro":"Familie ist in Italien ein großes Thema. Diese Woche lernst du, wie du über deine Familie sprichst und Menschen beschreibst: groß oder klein, lustig oder schüchtern. Dazu lernst du mein, dein und sein auf Italienisch.","culture":"Die Familie hat in Italien einen sehr hohen Stellenwert. Viele junge Leute wohnen bis etwa 30 bei den Eltern. Sonntags trifft sich oft die ganze Familie zum langen Mittagessen bei der nonna. Wer sehr an der Mama hängt, wird scherzhaft 'mammone' genannt.","vocab":[{"it":"la famiglia","de":"die Familie","alt":[],"note":"gli klingt wie lj: fa mi lja.","ex":"Ecco la mia famiglia!","exDe":"Hier ist meine Familie!"},{"it":"la madre","de":"die Mutter","alt":[],"note":"","ex":"Mia madre si chiama Rosa.","exDe":"Meine Mutter heißt Rosa."},{"it":"il padre","de":"der Vater","alt":[],"note":"","ex":"Il padre di Giulia si chiama Franco.","exDe":"Giulias Vater heißt Franco."},{"it":"i genitori","de":"die Eltern","alt":[],"note":"Maskulin Plural. Ein Elternteil: il genitore.","ex":"I miei genitori sono simpatici.","exDe":"Meine Eltern sind nett."},{"it":"il fratello","de":"der Bruder","alt":[],"note":"","ex":"Giulia ha un fratello, Matteo.","exDe":"Giulia hat einen Bruder, Matteo."},{"it":"la sorella","de":"die Schwester","alt":[],"note":"","ex":"Hai una sorella?","exDe":"Hast du eine Schwester?"},{"it":"il nonno","de":"der Opa; der Großvater","alt":[],"note":"Plural: i nonni, die Großeltern.","ex":"Mio nonno ha novant'anni.","exDe":"Mein Opa ist neunzig."},{"it":"la nonna","de":"die Oma; die Großmutter","alt":[],"note":"","ex":"Nonna Lucia ha ottantadue anni.","exDe":"Oma Lucia ist zweiundachtzig."},{"it":"la mamma","de":"die Mama","alt":[],"note":"","ex":"Ciao, mamma!","exDe":"Hallo, Mama!"},{"it":"il papà","de":"der Papa","alt":[],"note":"Mit Akzent! Ohne Akzent heißt il papa der Papst.","ex":"Papà, dove sei?","exDe":"Papa, wo bist du?"},{"it":"Hai fratelli?","de":"Hast du Geschwister?","alt":[],"note":"fratelli heißt Brüder oder Geschwister.","ex":"Lukas, hai fratelli?","exDe":"Lukas, hast du Geschwister?"},{"it":"Sono figlio unico.","de":"Ich bin Einzelkind.","alt":["Sono figlia unica."],"note":"Als Frau: Sono figlia unica.","ex":"No, sono figlio unico.","exDe":"Nein, ich bin Einzelkind."},{"it":"il figlio","de":"der Sohn","alt":[],"note":"gli klingt wie lj: fi ljo.","ex":"Matteo è il figlio di Rosa.","exDe":"Matteo ist Rosas Sohn."},{"it":"la figlia","de":"die Tochter","alt":[],"note":"","ex":"Giulia è la figlia di Franco.","exDe":"Giulia ist Francos Tochter."},{"it":"lo zio","de":"der Onkel","alt":[],"note":"Vor z steht lo.","ex":"Mio zio abita a Roma.","exDe":"Mein Onkel wohnt in Rom."},{"it":"la zia","de":"die Tante","alt":[],"note":"","ex":"Mia zia è molto simpatica.","exDe":"Meine Tante ist sehr nett."},{"it":"il cugino","de":"der Cousin","alt":[],"note":"","ex":"Mio cugino è di Milano.","exDe":"Mein Cousin ist aus Mailand."},{"it":"la cugina","de":"die Cousine","alt":[],"note":"","ex":"Tua cugina è bionda?","exDe":"Ist deine Cousine blond?"},{"it":"il marito","de":"der Ehemann","alt":[],"note":"","ex":"Franco è il marito di Rosa.","exDe":"Franco ist Rosas Mann."},{"it":"la moglie","de":"die Ehefrau","alt":[],"note":"gli klingt wie lj. Plural: le mogli.","ex":"Rosa è la moglie di Franco.","exDe":"Rosa ist Francos Frau."},{"it":"sposato","de":"verheiratet","alt":[],"note":"feminin: sposata","ex":"Sei sposato, Lukas?","exDe":"Bist du verheiratet, Lukas?"},{"it":"il nipote","de":"der Enkel; der Neffe","alt":[],"note":"Feminin: la nipote, die Enkelin oder die Nichte.","ex":"Matteo è il nipote di nonna Lucia.","exDe":"Matteo ist Oma Lucias Enkel."},{"it":"la foto","de":"das Foto","alt":[],"note":"Feminin, kurz für la fotografia. Plural: le foto.","ex":"Ecco una foto di Matteo.","exDe":"Hier ist ein Foto von Matteo."},{"it":"Com'è?","de":"Wie ist er oder sie?","alt":["Com'e?","Come è?"],"note":"Kurz für come è. Fragt nach Aussehen oder Charakter.","ex":"Tuo fratello? Com'è?","exDe":"Dein Bruder? Wie ist er?"},{"it":"alto","de":"groß (Körpergröße)","alt":[],"note":"feminin: alta","ex":"Matteo è molto alto.","exDe":"Matteo ist sehr groß."},{"it":"basso","de":"klein (Körpergröße)","alt":[],"note":"feminin: bassa","ex":"Mia nonna è bassa.","exDe":"Meine Oma ist klein."},{"it":"bello","de":"schön; gutaussehend","alt":[],"note":"feminin: bella","ex":"Che bella famiglia!","exDe":"Was für eine schöne Familie!"},{"it":"giovane","de":"jung","alt":[],"note":"Gleich für m und f.","ex":"Tua zia è giovane!","exDe":"Deine Tante ist jung!"},{"it":"anziano","de":"älter; alt (bei Personen)","alt":[],"note":"feminin: anziana. Höflicher als vecchio.","ex":"Il signore anziano? È mio nonno.","exDe":"Der ältere Herr? Das ist mein Opa."},{"it":"simpatico","de":"sympathisch; nett","alt":[],"note":"feminin: simpatica. Plural: simpatici, simpatiche.","ex":"Davide è molto simpatico.","exDe":"Davide ist sehr sympathisch."},{"it":"gentile","de":"freundlich; höflich","alt":[],"note":"Gleich für m und f.","ex":"Tua madre è molto gentile.","exDe":"Deine Mutter ist sehr freundlich."},{"it":"divertente","de":"lustig; unterhaltsam","alt":[],"note":"Gleich für m und f.","ex":"Matteo è divertente e simpatico.","exDe":"Matteo ist lustig und sympathisch."},{"it":"timido","de":"schüchtern","alt":[],"note":"feminin: timida","ex":"Mia sorella è un po' timida.","exDe":"Meine Schwester ist ein bisschen schüchtern."},{"it":"carino","de":"hübsch; süß","alt":[],"note":"feminin: carina. Auch für nette Gesten: Che carino!","ex":"Tuo cugino è carino!","exDe":"Dein Cousin ist süß!"},{"it":"bravo","de":"tüchtig; gut (in etwas)","alt":[],"note":"feminin: brava. Bravo! heißt auch: Gut gemacht!","ex":"Nonna Lucia è brava in cucina.","exDe":"Oma Lucia ist eine gute Köchin."},{"it":"biondo","de":"blond","alt":[],"note":"feminin: bionda","ex":"Matteo è biondo?","exDe":"Ist Matteo blond?"}],"grammar":{"title":"Mein, dein, sein und die Angleichung der Adjektive","points":["Mein, dein, sein richten sich im Italienischen nach dem Nomen, nicht nach dem Besitzer: <b>il mio</b> caffè, <b>la mia</b> tazza, <b>i miei</b> amici, <b>le mie</b> amiche. Meist steht der Artikel davor.","<b>Ausnahme Familie:</b> Bei einem einzelnen Familienmitglied fällt der Artikel weg: <b>mia madre, tuo fratello, sua nonna</b>. Im Plural kommt er zurück: <b>i miei genitori</b>. Bei <b>loro</b> bleibt er immer: <b>la loro madre</b>. Bei mamma und papà geht beides.","<b>suo</b> heißt sein, ihr und auch Ihr (Lei). Es richtet sich nur nach dem Nomen: <b>sua madre</b> kann seine Mutter oder ihre Mutter sein.","Adjektive passen sich dem Nomen an und stehen meist dahinter. Endung <b>o</b>: alt<b>o</b>, alt<b>a</b>, im Plural alt<b>i</b>, alt<b>e</b>. Endung <b>e</b>: gentil<b>e</b> für m und f, im Plural gentil<b>i</b>."],"table":{"head":["","maskulin (Einzahl / Plural)","feminin (Einzahl / Plural)"],"rows":[["mein","il mio / i miei","la mia / le mie"],["dein","il tuo / i tuoi","la tua / le tue"],["sein, ihr, Ihr","il suo / i suoi","la sua / le sue"],["unser","il nostro / i nostri","la nostra / le nostre"],["euer","il vostro / i vostri","la vostra / le vostre"],["ihr (Plural)","il loro / i loro","la loro / le loro"]]},"examples":[{"it":"Mia madre si chiama Rosa.","de":"Meine Mutter heißt Rosa."},{"it":"I miei nonni sono di Bologna.","de":"Meine Großeltern sind aus Bologna."},{"it":"Tuo fratello è alto e simpatico.","de":"Dein Bruder ist groß und sympathisch."},{"it":"Le mie cugine sono bionde.","de":"Meine Cousinen sind blond."},{"it":"Sua sorella è gentile e divertente.","de":"Seine Schwester ist freundlich und lustig."}],"drills":[{"type":"choice","q":"___ madre si chiama Rosa.","de":"Meine Mutter heißt Rosa.","options":["La mia","Mia","Mio"],"answer":1,"why":"Einzelnes Familienmitglied: ohne Artikel. madre ist feminin, also mia."},{"type":"choice","q":"___ genitori sono di Bologna.","de":"Meine Eltern sind aus Bologna.","options":["I miei","Miei","Le mie"],"answer":0,"why":"Im Plural kommt der Artikel zurück. genitori ist maskulin: i miei."},{"type":"type","q":"Matteo è ___ fratello.","de":"Matteo ist mein Bruder.","answer":"mio","alt":[],"why":"fratello ist maskulin Einzahl: mio, ohne Artikel."},{"type":"choice","q":"Giulia, come si chiama ___ padre?","de":"Giulia, wie heißt dein Vater?","options":["il tuo","tua","tuo"],"answer":2,"why":"padre ist maskulin und ein einzelnes Familienmitglied: tuo ohne Artikel."},{"type":"type","q":"Le ___ sorelle sono bionde.","de":"Meine Schwestern sind blond.","answer":"mie","alt":[],"why":"sorelle ist feminin Plural: le mie."},{"type":"choice","q":"Mia sorella è molto ___.","de":"Meine Schwester ist sehr groß.","options":["alto","alta","alte"],"answer":1,"why":"sorella ist feminin Einzahl: alta."},{"type":"type","q":"Giulia è molto ___. (simpatico)","de":"Giulia ist sehr sympathisch.","answer":"simpatica","alt":[],"why":"Giulia ist eine Frau: simpatica."},{"type":"choice","q":"Giulia? La ___ famiglia è di Bologna.","de":"Giulia? Ihre Familie ist aus Bologna.","options":["sua","suo","sue"],"answer":0,"why":"famiglia ist feminin Einzahl und kein einzelnes Familienmitglied: la sua."}]},"dialog":{"title":"Le foto di famiglia","setting":"Giulia zeigt Lukas auf dem Handy Fotos von ihrer Familie.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Giulia","gender":"f"}},"lines":[{"s":"B","it":"Guarda, Lukas, ecco la mia famiglia!","de":"Schau mal, Lukas, das ist meine Familie!"},{"s":"A","it":"Che bello! E il signore alto chi è?","de":"Wie schön! Und wer ist der große Mann?"},{"s":"B","it":"È mio padre, Franco. Simpaticissimo!","de":"Das ist mein Vater, Franco. Total nett!"},{"s":"A","it":"E la signora bionda è tua madre?","de":"Und die blonde Frau ist deine Mutter?"},{"s":"B","it":"Sì, Rosa. Gentile, ma un po' timida.","de":"Ja, Rosa. Freundlich, aber ein bisschen schüchtern."},{"s":"A","it":"E il ragazzo? Tuo fratello?","de":"Und der junge Mann? Dein Bruder?"},{"s":"B","it":"Sì, Matteo. Ha ventitré anni e abita a Milano.","de":"Ja, Matteo. Er ist dreiundzwanzig und wohnt in Mailand."},{"s":"A","it":"Alto e simpatico... è tutto tuo padre!","de":"Groß und nett ... ganz der Vater!"},{"s":"B","it":"Eh, sì! E lei è nonna Lucia: ottantadue anni, bravissima in cucina.","de":"Oh ja! Und das ist Oma Lucia: zweiundachtzig und eine super Köchin."},{"s":"A","it":"Mamma mia, che bella famiglia! Io sono figlio unico.","de":"Meine Güte, was für eine schöne Familie! Ich bin Einzelkind."},{"s":"B","it":"Allora la mia famiglia è anche la tua!","de":"Dann ist meine Familie jetzt auch deine!"}],"questions":[{"q":"Wie ist Giulias Vater?","options":["Schüchtern","Blond","Sehr nett"],"answer":2},{"q":"Wo wohnt Matteo?","options":["In Mailand","In Bologna","In Neapel"],"answer":0},{"q":"Wie alt ist nonna Lucia?","options":["72 Jahre","82 Jahre","28 Jahre"],"answer":1}]},"sentences":[{"it":"Mia madre si chiama Rosa.","de":"Meine Mutter heißt Rosa."},{"it":"Mio fratello abita a Milano.","de":"Mein Bruder wohnt in Mailand."},{"it":"I miei nonni sono molto simpatici.","de":"Meine Großeltern sind sehr nett."},{"it":"Hai fratelli o sorelle?","de":"Hast du Brüder oder Schwestern?"},{"it":"Mia sorella è alta e bionda.","de":"Meine Schwester ist groß und blond."},{"it":"Tuo padre è gentile e divertente.","de":"Dein Vater ist freundlich und lustig."},{"it":"Sono figlio unico. E tu?","de":"Ich bin Einzelkind. Und du?"},{"it":"La mia famiglia è di Bologna.","de":"Meine Familie ist aus Bologna."}],"spoken":[{"it":"I miei","book":"I miei genitori","de":"meine Eltern (kurz)","note":"Im Alltag sagt man oft nur i miei. Alle wissen dann, dass die Eltern gemeint sind. Genauso: i tuoi, i suoi.","ex":"I miei sono di Napoli.","exDe":"Meine Eltern sind aus Neapel.","alt":[]},{"it":"Sei tutto tuo padre!","book":"Sei uguale a tuo padre.","de":"Du bist ganz der Vater!","note":"Sagen Verwandte gern, wenn jemand den Eltern ähnlich sieht oder ähnlich tickt. Zu einer Frau: Sei tutta tua madre!","ex":"Ecco Matteo. È tutto suo padre!","exDe":"Das ist Matteo. Ganz der Vater!","alt":[]},{"it":"Si vede!","book":"È evidente.","de":"Das sieht man!","note":"Kurze, lockere Bestätigung, überall üblich. Oft mit einem Lächeln als Kompliment.","ex":"Siamo fratelli. Si vede!","exDe":"Wir sind Geschwister. Das sieht man!","alt":[]},{"it":"Mamma mia!","book":"","de":"Meine Güte!","note":"Der Klassiker bei Überraschung, Freude oder Schreck. Überall in Italien, bei Jung und Alt.","ex":"Dieci nipoti? Mamma mia!","exDe":"Zehn Enkel? Meine Güte!","alt":[]},{"it":"Che carino!","book":"È molto carino.","de":"Wie süß!","note":"Für Kinder, Fotos und nette Gesten. Bei einer Frau oder einem femininen Wort: Che carina!","ex":"Ecco mio nipote. Che carino!","exDe":"Das ist mein Neffe. Wie süß!","alt":["Che carina!"]},{"it":"È alla mano.","book":"È una persona semplice.","de":"Er (sie) ist total unkompliziert.","note":"Großes Lob für Menschen, die locker und natürlich sind, ganz ohne Allüren. Passt überall.","ex":"Tuo padre è molto alla mano.","exDe":"Dein Vater ist total unkompliziert.","alt":[]},{"it":"È un pezzo di pane.","book":"È una persona molto buona.","de":"Er (sie) ist herzensgut.","note":"Wörtlich: ein Stück Brot. So beschreibt man liebe, gutmütige Menschen, gerade in der Familie.","ex":"Mio zio? È un pezzo di pane!","exDe":"Mein Onkel? Der ist herzensgut!","alt":[]},{"it":"Salutami tua madre!","book":"Saluta tua madre da parte mia.","de":"Grüß deine Mutter von mir!","note":"Sehr häufig zum Abschied. Geht mit allen: Salutami i tuoi! Salutami Matteo!","ex":"Ciao Giulia! Salutami tua madre!","exDe":"Tschüss Giulia! Grüß deine Mutter von mir!","alt":["Salutami tua mamma!"]}],"speak":[{"sit":"Giulia fragt dich: 'Hai fratelli?' Du bist Einzelkind.","answers":["No, sono figlio unico.","No, sono figlio unico. E tu?"],"tip":"Als Frau sagst du: figlia unica."},{"sit":"Giulia zeigt dir ein Foto von ihrem kleinen Neffen. Reagiere.","answers":["Che carino!","Che carino! Quanti anni ha?","Mamma mia, che carino!"],"tip":""},{"sit":"Beschreibe deine Mutter: Sie ist klein, blond und sehr nett.","answers":["Mia madre è bassa, bionda e molto simpatica.","Mia mamma è bassa, bionda e simpaticissima."],"tip":"Bei madre ohne Artikel, bei mamma geht beides: mia mamma oder la mia mamma."},{"sit":"Jemand fragt nach deinen Eltern. Sag, dass sie aus München sind.","answers":["I miei sono di Monaco.","I miei genitori sono di Monaco."],"tip":""},{"sit":"Matteo ist genau wie sein Vater Franco. Sag es ihm im Spaß.","answers":["Sei tutto tuo padre!","Sei tutto tuo papà!"],"tip":""},{"sit":"Du verabschiedest dich von Giulia. Sie soll ihre Mutter von dir grüßen.","answers":["Salutami tua madre!","Ciao! Salutami tua mamma!"],"tip":""}]},{"id":6,"title":"Al mercato","titleDe":"Auf dem Markt","goal":"Du kannst auf dem Markt einkaufen, nach Preisen fragen und Mengen angeben.","intro":"Diese Woche gehst du mit Giulia auf den Markt. Du lernst Obst, Gemüse und andere Lebensmittel, dazu Mengen, Preise und die Zahlen bis 1000. Außerdem kommt der Plural: Aus einer Tomate werden ganz schnell viele.","culture":"Auf italienischen Märkten fasst du Obst und Gemüse besser nicht selbst an. Das übernimmt der Verkäufer: Du sagst einfach, was und wie viel du möchtest, gern in etti (100 Gramm). In Bologna lohnt sich das Quadrilatero direkt neben der Piazza Maggiore mit seinen alten Lebensmittelläden. Am besten kaufst du, was gerade Saison hat.","vocab":[{"it":"il mercato","de":"der Markt","alt":[],"note":"Plural: i mercati.","ex":"Domani c'è il mercato!","exDe":"Morgen ist Markt!"},{"it":"la frutta","de":"das Obst","alt":[],"note":"Immer Singular: la frutta.","ex":"La frutta qui è freschissima!","exDe":"Das Obst hier ist superfrisch!"},{"it":"la verdura","de":"das Gemüse","alt":[],"note":"Oft auch im Plural: le verdure.","ex":"C'è anche la verdura?","exDe":"Gibt es auch Gemüse?"},{"it":"la mela","de":"der Apfel","alt":[],"note":"Plural: le mele.","ex":"Vorrei tre mele.","exDe":"Ich hätte gern drei Äpfel."},{"it":"il pomodoro","de":"die Tomate","alt":[],"note":"Wörtlich: goldener Apfel. Plural: i pomodori.","ex":"I pomodori sono molto buoni.","exDe":"Die Tomaten sind sehr gut."},{"it":"la patata","de":"die Kartoffel","alt":[],"note":"Plural: le patate.","ex":"Le patate sono italiane?","exDe":"Sind die Kartoffeln aus Italien?"},{"it":"il pane","de":"das Brot","alt":[],"note":"","ex":"Il pane è caldo!","exDe":"Das Brot ist warm!"},{"it":"il formaggio","de":"der Käse","alt":[],"note":"gg klingt wie dsch: for MAD dscho. Plural: i formaggi.","ex":"Il formaggio è caro?","exDe":"Ist der Käse teuer?"},{"it":"il chilo","de":"das Kilo","alt":["il kilo"],"note":"Mit di: un chilo di mele. Plural: i chili.","ex":"Due chili di patate, per favore.","exDe":"Zwei Kilo Kartoffeln, bitte."},{"it":"l'etto","de":"100 Gramm","alt":["etto"],"note":"Maskulin. Typisch beim Einkaufen: due etti = 200 Gramm.","ex":"Un etto di prosciutto, per favore.","exDe":"100 Gramm Schinken, bitte."},{"it":"Quanto costano?","de":"Wie viel kosten sie?","alt":[],"note":"Für mehrere Dinge. Für eine Sache: Quanto costa?","ex":"Le fragole? Quanto costano?","exDe":"Die Erdbeeren? Wie viel kosten sie?"},{"it":"l'euro","de":"der Euro","alt":["euro"],"note":"Maskulin. Im Plural unverändert: due euro.","ex":"Sono tre euro, grazie.","exDe":"Das macht drei Euro, danke."},{"it":"il prezzo","de":"der Preis","alt":[],"note":"zz klingt wie ts. Plural: i prezzi.","ex":"I prezzi qui sono buoni.","exDe":"Die Preise hier sind gut."},{"it":"caro","de":"teuer","alt":[],"note":"feminin: cara. Auch: lieb (Caro Lukas = Lieber Lukas).","ex":"Le fragole sono care.","exDe":"Die Erdbeeren sind teuer."},{"it":"fresco","de":"frisch","alt":[],"note":"feminin: fresca. Plural: freschi, fresche.","ex":"Il pane è fresco?","exDe":"Ist das Brot frisch?"},{"it":"c'è","de":"es gibt (eine Sache)","alt":["c'e"],"note":"Auch: ist da (C'è Giulia? = Ist Giulia da?). Verneint: non c'è.","ex":"C'è un mercato qui?","exDe":"Gibt es hier einen Markt?"},{"it":"ci sono","de":"es gibt (mehrere Sachen)","alt":[],"note":"Verneint: non ci sono.","ex":"Oggi ci sono le fragole!","exDe":"Heute gibt es Erdbeeren!"},{"it":"prendo","de":"ich nehme","alt":[],"note":"Feste Wendung beim Einkaufen. Das ganze Verb prendere kommt in Lektion 8.","ex":"Prendo mezzo chilo di mele.","exDe":"Ich nehme ein halbes Kilo Äpfel."},{"it":"l'arancia","de":"die Orange","alt":["arancia"],"note":"Feminin. Plural: le arance (ohne i).","ex":"Le arance sono siciliane.","exDe":"Die Orangen sind aus Sizilien."},{"it":"la fragola","de":"die Erdbeere","alt":[],"note":"Betonung vorne: FRA go la.","ex":"Le fragole sono molto dolci.","exDe":"Die Erdbeeren sind sehr süß."},{"it":"il limone","de":"die Zitrone","alt":[],"note":"Plural: i limoni.","ex":"Due limoni, per favore.","exDe":"Zwei Zitronen, bitte."},{"it":"la cipolla","de":"die Zwiebel","alt":[],"note":"Das ll spricht man lang: tschi POL la.","ex":"Una cipolla e due pomodori.","exDe":"Eine Zwiebel und zwei Tomaten."},{"it":"l'uovo","de":"das Ei","alt":["uovo"],"note":"Maskulin. Unregelmäßiger Plural: le uova.","ex":"Le uova sono fresche.","exDe":"Die Eier sind frisch."},{"it":"il prosciutto","de":"der Schinken","alt":[],"note":"crudo = luftgetrocknet, cotto = gekocht.","ex":"Il prosciutto di Parma è famoso.","exDe":"Der Parmaschinken ist berühmt."},{"it":"il pesce","de":"der Fisch","alt":[],"note":"sce klingt wie sche: PE sche. Plural: i pesci.","ex":"Oggi non c'è pesce.","exDe":"Heute gibt es keinen Fisch."},{"it":"l'uva","de":"die Weintrauben","alt":["uva"],"note":"Feminin und immer Singular: l'uva.","ex":"L'uva è buonissima!","exDe":"Die Trauben sind superlecker!"},{"it":"la carne","de":"das Fleisch","alt":[],"note":"Meist Singular, wie la frutta.","ex":"La carne qui è molto buona.","exDe":"Das Fleisch hier ist sehr gut."},{"it":"l'olio","de":"das Öl","alt":["olio"],"note":"Maskulin. L'olio d'oliva = das Olivenöl.","ex":"L'olio d'oliva è italiano.","exDe":"Das Olivenöl ist italienisch."},{"it":"il pezzo","de":"das Stück","alt":[],"note":"zz klingt wie ts: PET tso.","ex":"Un pezzo di parmigiano, per favore.","exDe":"Ein Stück Parmesan, bitte."},{"it":"mezzo chilo","de":"ein halbes Kilo","alt":["mezzo kilo"],"note":"Ohne un: mezzo chilo di pomodori.","ex":"Mezzo chilo di pomodori, per favore.","exDe":"Ein halbes Kilo Tomaten, bitte."},{"it":"duecento","de":"zweihundert","alt":[],"note":"Weiter geht es genauso: trecento, quattrocento, seicento ... novecento.","ex":"Duecento grammi di formaggio, per favore.","exDe":"Zweihundert Gramm Käse, bitte."},{"it":"cinquecento","de":"fünfhundert","alt":[],"note":"Wie das Auto: la Cinquecento. Zahlen schreibt man zusammen: 550 = cinquecentocinquanta.","ex":"Cinquecento grammi di fragole, per favore.","exDe":"Fünfhundert Gramm Erdbeeren, bitte."},{"it":"mille","de":"tausend","alt":[],"note":"Ab 2000 heißt es mila: duemila, tremila.","ex":"Mille grammi sono un chilo.","exDe":"Tausend Gramm sind ein Kilo."},{"it":"economico","de":"günstig; billig","alt":[],"note":"feminin: economica. Plural: economici.","ex":"Il mercato è economico.","exDe":"Der Markt ist günstig."},{"it":"Altro?","de":"Sonst noch etwas?","alt":["altro"],"note":"Fragt der Verkäufer fast immer.","ex":"Ecco le mele. Altro?","exDe":"Hier sind die Äpfel. Sonst noch etwas?"},{"it":"Basta così.","de":"Das ist alles; das reicht.","alt":["basta così","basta cosi"],"note":"Die höfliche Antwort auf Altro?","ex":"Basta così, grazie mille.","exDe":"Das ist alles, vielen Dank."}],"grammar":{"title":"Plural der Nomen und c'è / ci sono","points":["Im Plural ändert sich die Endung. Aus <b>o</b> wird <b>i</b>: il pomodoro, i pomodori. Aus <b>a</b> wird <b>e</b>: la mela, le mele. Aus <b>e</b> wird <b>i</b>, egal ob maskulin oder feminin: il limone, i limoni.","Auch der Artikel geht in den Plural: Aus <b>il</b> wird <b>i</b>, aus <b>lo</b> und maskulinem <b>l'</b> wird <b>gli</b>, aus <b>la</b> und femininem <b>l'</b> wird <b>le</b>. Also: gli etti, le arance.","Manche Wörter bleiben gleich: Wörter mit Akzent am Ende (il caffè, i caffè; la città, le città), Wörter auf Konsonant (il bar, i bar) und l'euro (due euro). Eine wichtige Ausnahme: l'uovo, <b>le uova</b>.","<b>c'è</b> heißt es gibt oder ist da, wenn es um eine Sache geht: Oggi c'è il mercato. Bei mehreren Sachen sagst du <b>ci sono</b>: Ci sono le fragole. Verneint: <b>non c'è</b>, <b>non ci sono</b>."],"table":{"head":["Regel","Singular","Plural"],"rows":[["o → i","il pomodoro","i pomodori"],["a → e","la mela","le mele"],["e → i (m)","il limone","i limoni"],["e → i (f)","la notte","le notti"],["lo → gli","lo studente","gli studenti"],["l' → gli (m)","l'etto","gli etti"],["l' → le (f)","l'arancia","le arance"],["bleibt gleich","il caffè, la città","i caffè, le città"]]},"examples":[{"it":"Le mele sono buone.","de":"Die Äpfel sind gut."},{"it":"I pomodori sono freschi.","de":"Die Tomaten sind frisch."},{"it":"Oggi c'è il mercato.","de":"Heute ist Markt."},{"it":"Ci sono le fragole?","de":"Gibt es Erdbeeren?"},{"it":"Non ci sono pomodori oggi?","de":"Gibt es heute keine Tomaten?"},{"it":"Sei uova e due limoni, per favore.","de":"Sechs Eier und zwei Zitronen, bitte."}],"drills":[{"type":"choice","q":"Due ___, per favore.","de":"Zwei Äpfel, bitte.","options":["mela","meli","mele"],"answer":2,"why":"la mela endet auf a, im Plural wird daraus e: le mele."},{"type":"type","q":"Un chilo di ___, per favore. (pomodoro)","de":"Ein Kilo Tomaten, bitte.","answer":"pomodori","alt":[],"why":"il pomodoro endet auf o, im Plural wird daraus i."},{"type":"choice","q":"___ arance sono molto buone.","de":"Die Orangen sind sehr gut.","options":["Le","Gli","I"],"answer":0,"why":"arancia ist feminin, im Plural also le arance."},{"type":"choice","q":"Oggi ___ il mercato.","de":"Heute ist Markt.","options":["ci sono","c'è","sono"],"answer":1,"why":"il mercato ist eine Sache, also c'è."},{"type":"type","q":"Oggi ___ le fragole?","de":"Gibt es heute Erdbeeren?","answer":"ci sono","alt":[],"why":"fragole ist Plural, also ci sono."},{"type":"type","q":"Due ___, per favore. (limone)","de":"Zwei Zitronen, bitte.","answer":"limoni","alt":[],"why":"il limone endet auf e, im Plural wird daraus i."},{"type":"choice","q":"Sei ___, per favore.","de":"Sechs Eier, bitte.","options":["uovi","uove","uova"],"answer":2,"why":"l'uovo ist eine Ausnahme: le uova."},{"type":"choice","q":"Le ___ italiane sono belle.","de":"Die italienischen Städte sind schön.","options":["città","citti","citte"],"answer":0,"why":"Wörter mit Akzent am Ende bleiben im Plural gleich."}]},"dialog":{"title":"Al mercato","setting":"Lukas und Giulia kaufen in Bologna an einem Marktstand mit Obst und Gemüse ein.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Giulia","gender":"f"},"C":{"name":"Verkäufer","gender":"m"}},"lines":[{"s":"C","it":"Buongiorno, ragazzi! Ditemi!","de":"Guten Tag, ihr zwei! Was darf's sein?"},{"s":"B","it":"Buongiorno! Oggi ci sono le fragole?","de":"Guten Tag! Gibt's heute Erdbeeren?"},{"s":"C","it":"Certo! Fresche e dolcissime!","de":"Klar! Frisch und supersüß!"},{"s":"A","it":"E quanto vengono?","de":"Und was kosten die?"},{"s":"C","it":"Quattro euro al chilo.","de":"Vier Euro das Kilo."},{"s":"B","it":"Allora mezzo chilo. E mi dà un chilo di pomodori?","de":"Dann ein halbes Kilo. Und kriege ich noch ein Kilo Tomaten?"},{"s":"A","it":"Scusi, c'è anche il basilico?","de":"Entschuldigung, gibt's auch Basilikum?"},{"s":"C","it":"Eh, oggi no, mi dispiace. Altro?","de":"Nee, heute nicht, tut mir leid. Sonst noch was?"},{"s":"B","it":"Sì, due limoni. E basta così, grazie.","de":"Ja, zwei Zitronen. Und das war's, danke."},{"s":"C","it":"Ecco fatto! Allora... quattro e ottanta.","de":"So, fertig! Also ... vier achtzig."},{"s":"A","it":"Ecco cinque euro.","de":"Hier sind fünf Euro."},{"s":"C","it":"Grazie! Venti centesimi di resto. Arrivederci, ragazzi!","de":"Danke! Zwanzig Cent zurück. Wiedersehen, ihr zwei!"}],"questions":[{"q":"Was kostet ein Kilo Erdbeeren?","options":["Vier Euro","Zwei Euro","Fünf Euro"],"answer":0},{"q":"Was gibt es heute nicht?","options":["Zitronen","Tomaten","Basilikum"],"answer":2},{"q":"Wie viel Wechselgeld bekommt Lukas?","options":["Achtzig Cent","Zwanzig Cent","Einen Euro"],"answer":1}]},"sentences":[{"it":"Un chilo di pomodori, per favore.","de":"Ein Kilo Tomaten, bitte."},{"it":"Scusi, quanto costano le fragole?","de":"Entschuldigung, wie viel kosten die Erdbeeren?"},{"it":"Le mele sono fresche e buone.","de":"Die Äpfel sind frisch und gut."},{"it":"Due etti di prosciutto, per favore.","de":"Zweihundert Gramm Schinken, bitte."},{"it":"Scusi, c'è pane fresco?","de":"Entschuldigung, gibt es frisches Brot?"},{"it":"Qui ci sono arance siciliane.","de":"Hier gibt es Orangen aus Sizilien."},{"it":"Prendo mezzo chilo di arance.","de":"Ich nehme ein halbes Kilo Orangen."},{"it":"No, grazie, basta così.","de":"Nein danke, das ist alles."}],"spoken":[{"it":"Quanto viene?","book":"Quanto costa?","de":"Was kostet's? (locker)","note":"Auf dem Markt und im Laden sehr häufig. Für mehrere Sachen: Quanto vengono?","ex":"Il formaggio, quanto viene?","exDe":"Der Käse, was kostet der?","alt":["Quanto vengono?"]},{"it":"A chi tocca?","book":"Chi è il prossimo?","de":"Wer ist dran?","note":"Fragt der Verkäufer am Stand oder an der Theke. Wenn du dran bist, sagst du: Tocca a me!","ex":"A chi tocca? Tocca a me!","exDe":"Wer ist dran? Ich bin dran!","alt":[]},{"it":"Lascio?","book":"Va bene se è un po' di più?","de":"Darf's ein bisschen mehr sein?","note":"Hörst du an der Theke, wenn es etwas mehr geworden ist. Wörtlich: Lass ich es so? Antwort: Sì, va bene!","ex":"Sono due etti e mezzo. Lascio?","exDe":"Das sind 250 Gramm. Darf's ein bisschen mehr sein?","alt":[]},{"it":"Ha spiccioli?","book":"Ha delle monete?","de":"Haben Sie Kleingeld?","note":"Auf dem Markt sehr häufig, denn große Scheine mag niemand. Unter Freunden: Hai spiccioli?","ex":"Cinque euro e venti. Ha spiccioli?","exDe":"Fünf Euro zwanzig. Haben Sie Kleingeld?","alt":["Hai spiccioli?"]},{"it":"Chi è l'ultimo?","book":"Chi è l'ultima persona in fila?","de":"Wer ist der Letzte? (in der Schlange)","note":"Fragst du am Marktstand oder an der Theke, wenn es keine Nummern gibt. Dann weißt du, nach wem du dran bist.","ex":"Scusi, chi è l'ultimo? Sono io.","exDe":"Entschuldigung, wer ist der Letzte? Ich.","alt":["Chi è l'ultima?"]},{"it":"Quanto ne vuole?","book":"Quanto vuole?","de":"Wie viel möchten Sie davon?","note":"Fragt der Verkäufer ständig. ne heißt davon. Bei Äpfeln und anderen Stücken heißt es quanti oder quante.","ex":"Prosciutto? Quanto ne vuole? Un etto.","exDe":"Schinken? Wie viel möchten Sie? 100 Gramm.","alt":[]},{"it":"Faccia Lei!","book":"Scelga Lei, per favore.","de":"Wie Sie meinen! (Sie entscheiden)","note":"Typisch auf dem Markt, wenn der Verkäufer das Obst für dich aussucht. Unter Freunden: Fai tu!","ex":"Scelgo io? Sì, faccia Lei!","exDe":"Soll ich aussuchen? Ja, wie Sie meinen!","alt":[]},{"it":"Va bene così.","book":"Tenga il resto.","de":"Passt so. (beim Bezahlen)","note":"So sagst du, dass jemand das Wechselgeld behalten kann. Sonst heißt es auch einfach: So ist es gut.","ex":"Ecco dieci euro, va bene così.","exDe":"Hier sind zehn Euro, passt so.","alt":[]}],"speak":[{"sit":"Am Obststand möchtest du ein Kilo Äpfel.","answers":["Un chilo di mele, per favore.","Mi dà un chilo di mele?","Vorrei un chilo di mele."],"tip":"'Mi dà ...?' heißt: Geben Sie mir ...?"},{"sit":"Du siehst schöne Erdbeeren, aber kein Preisschild. Frag nach dem Preis.","answers":["Quanto costano le fragole?","Le fragole, quanto vengono?"],"tip":""},{"sit":"An der Käsetheke möchtest du 200 Gramm Parmesan.","answers":["Due etti di parmigiano, per favore.","Mi dà due etti di parmigiano?"],"tip":"In Italien rechnet man in etti: Ein etto sind 100 Gramm."},{"sit":"Vor dem Käsestand warten mehrere Leute, Nummern gibt es nicht. Frag, wer der Letzte ist.","answers":["Scusi, chi è l'ultimo?","Chi è l'ultimo?"],"tip":"Die Antwort lautet meist Sono io! Dann bist du nach dieser Person dran."},{"sit":"Du möchtest wissen, ob es heute frischen Fisch gibt.","answers":["C'è pesce fresco oggi?","Scusi, oggi c'è il pesce fresco?"],"tip":""},{"sit":"Ein Kilo Erdbeeren kostet neun Euro. Sag Giulia, dass sie viel zu teuer sind.","answers":["Sono molto care!","Mamma mia, sono carissime!"],"tip":""}]},{"id":7,"title":"La mia giornata","titleDe":"Mein Tag","goal":"Du kannst über deinen Alltag und deine Arbeit sprechen und sagen, wie oft du etwas machst.","intro":"Jetzt wird es lebendig: Diese Woche lernst du viele neue Verben. Damit erzählst du, wann du arbeitest, isst und lernst und wie oft du etwas machst. Das Beste: Die meisten Verben funktionieren nach genau einem Muster.","culture":"Der italienische Tag hat einen eigenen Rhythmus. Das Frühstück ist klein und süß, oft nur ein Cappuccino mit Cornetto. Mittags machen viele eine echte Pause und in kleineren Städten schließen manche Geschäfte etwa von 13 bis 16 Uhr. Zu Abend isst man spät, oft erst ab 20 Uhr.","vocab":[{"it":"lavorare","de":"arbeiten","alt":[],"note":"","ex":"Dove lavori?","exDe":"Wo arbeitest du?"},{"it":"mangiare","de":"essen","alt":[],"note":"tu mangi, noi mangiamo (nur ein i).","ex":"Mangi carne?","exDe":"Isst du Fleisch?"},{"it":"la mattina","de":"der Morgen; der Vormittag","alt":[],"note":"Ohne Präposition: la mattina = morgens.","ex":"La mattina studio italiano.","exDe":"Morgens lerne ich Italienisch."},{"it":"il pomeriggio","de":"der Nachmittag","alt":[],"note":"gg klingt wie dsch: po me RID dscho.","ex":"Il pomeriggio lavoro a casa.","exDe":"Nachmittags arbeite ich zu Hause."},{"it":"la sera","de":"der Abend","alt":[],"note":"la sera = abends.","ex":"La sera telefono a Giulia.","exDe":"Abends rufe ich Giulia an."},{"it":"la colazione","de":"das Frühstück","alt":[],"note":"Aussprache: ko la TSIO ne.","ex":"La colazione italiana è dolce.","exDe":"Das italienische Frühstück ist süß."},{"it":"il pranzo","de":"das Mittagessen","alt":[],"note":"a pranzo = zum Mittagessen; mittags.","ex":"A pranzo mangio poco.","exDe":"Mittags esse ich wenig."},{"it":"la cena","de":"das Abendessen","alt":[],"note":"a cena = zum Abendessen.","ex":"A cena mangiamo la pasta.","exDe":"Zum Abendessen essen wir Pasta."},{"it":"sempre","de":"immer","alt":[],"note":"Steht meist direkt nach dem Verb.","ex":"Lavoro sempre la mattina.","exDe":"Ich arbeite immer vormittags."},{"it":"spesso","de":"oft","alt":[],"note":"","ex":"Mangiamo spesso la pizza.","exDe":"Wir essen oft Pizza."},{"it":"mai","de":"nie","alt":[],"note":"Mit non vor dem Verb: non ... mai.","ex":"Non cucino mai.","exDe":"Ich koche nie."},{"it":"il lavoro","de":"die Arbeit; der Job","alt":[],"note":"Plural: i lavori.","ex":"Il mio lavoro è interessante.","exDe":"Meine Arbeit ist interessant."},{"it":"Che lavoro fai?","de":"Was machst du beruflich?","alt":[],"note":"Höflich (Lei): Che lavoro fa?","ex":"Ciao Davide, che lavoro fai?","exDe":"Hallo Davide, was machst du beruflich?"},{"it":"l'ufficio","de":"das Büro","alt":["ufficio"],"note":"Maskulin. in ufficio = im Büro; ins Büro.","ex":"Oggi lavoro in ufficio.","exDe":"Heute arbeite ich im Büro."},{"it":"studiare","de":"studieren; lernen (für Schule, Uni)","alt":[],"note":"tu studi, noi studiamo (nur ein i).","ex":"Studi o lavori?","exDe":"Studierst du oder arbeitest du?"},{"it":"imparare","de":"lernen (etwas Neues)","alt":[],"note":"","ex":"Impariamo l'italiano insieme!","exDe":"Wir lernen zusammen Italienisch!"},{"it":"cucinare","de":"kochen","alt":[],"note":"","ex":"Nonna Lucia cucina molto bene.","exDe":"Oma Lucia kocht sehr gut."},{"it":"comprare","de":"kaufen","alt":[],"note":"","ex":"Compro il pane la mattina.","exDe":"Ich kaufe morgens Brot."},{"it":"giocare","de":"spielen","alt":[],"note":"tu giochi, noi giochiamo (mit h). giocare a calcio = Fußball spielen.","ex":"Davide gioca a calcio.","exDe":"Davide spielt Fußball."},{"it":"cominciare","de":"anfangen; beginnen","alt":[],"note":"tu cominci, noi cominciamo (nur ein i).","ex":"Il lavoro comincia presto.","exDe":"Die Arbeit fängt früh an."},{"it":"a volte","de":"manchmal","alt":["qualche volta"],"note":"Steht gern am Satzanfang.","ex":"A volte cucino io.","exDe":"Manchmal koche ich."},{"it":"di solito","de":"normalerweise","alt":[],"note":"","ex":"Di solito mangio a casa.","exDe":"Normalerweise esse ich zu Hause."},{"it":"ogni giorno","de":"jeden Tag","alt":["tutti i giorni"],"note":"ogni bleibt immer gleich.","ex":"Studio italiano ogni giorno.","exDe":"Ich lerne jeden Tag Italienisch."},{"it":"presto","de":"früh","alt":[],"note":"Kennst du schon aus a presto = bis bald.","ex":"Domani comincio presto.","exDe":"Morgen fange ich früh an."},{"it":"tardi","de":"spät","alt":[],"note":"","ex":"Mangiamo sempre tardi.","exDe":"Wir essen immer spät."},{"it":"il collega","de":"der Kollege","alt":[],"note":"feminin: la collega. Plural: i colleghi, le colleghe.","ex":"I miei colleghi sono simpatici.","exDe":"Meine Kollegen sind nett."},{"it":"il capo","de":"der Chef","alt":[],"note":"Auch für eine Chefin sagt man oft il capo.","ex":"Il mio capo è tedesco.","exDe":"Mein Chef ist Deutscher."},{"it":"l'azienda","de":"die Firma","alt":["azienda"],"note":"Feminin. Plural: le aziende.","ex":"Lavoro per un'azienda tedesca.","exDe":"Ich arbeite für eine deutsche Firma."},{"it":"a casa","de":"zu Hause; nach Hause","alt":[],"note":"Ohne Artikel: a casa.","ex":"Matteo è a casa?","exDe":"Ist Matteo zu Hause?"},{"it":"aspettare","de":"warten; erwarten","alt":[],"note":"Ohne Präposition: aspetto Giulia = ich warte auf Giulia.","ex":"Aspetto Giulia qui.","exDe":"Ich warte hier auf Giulia."},{"it":"cercare","de":"suchen","alt":[],"note":"tu cerchi, noi cerchiamo (mit h).","ex":"Cerco lavoro a Bologna.","exDe":"Ich suche Arbeit in Bologna."},{"it":"telefonare","de":"anrufen; telefonieren","alt":[],"note":"Mit a: telefono a Giulia.","ex":"Telefono spesso a mia madre.","exDe":"Ich rufe oft meine Mutter an."},{"it":"insegnare","de":"unterrichten; beibringen","alt":[],"note":"gn klingt wie nj: in se NIA re.","ex":"Insegno tedesco a Giulia.","exDe":"Ich bringe Giulia Deutsch bei."},{"it":"l'insegnante","de":"der Lehrer; die Lehrerin","alt":["insegnante"],"note":"Maskulin und feminin gleich: l'insegnante.","ex":"Davide è insegnante di musica.","exDe":"Davide ist Musiklehrer."},{"it":"l'ingegnere","de":"der Ingenieur","alt":["ingegnere"],"note":"Maskulin. Beim Beruf ohne Artikel: sono ingegnere.","ex":"Lukas è ingegnere.","exDe":"Lukas ist Ingenieur."},{"it":"insieme","de":"zusammen","alt":[],"note":"","ex":"Cuciniamo insieme?","exDe":"Kochen wir zusammen?"}],"grammar":{"title":"Präsens: Verben auf are","points":["Die meisten Verben enden auf <b>are</b>. Für das Präsens streichst du <b>are</b> und hängst diese Endungen an: <b>o, i, a, iamo, ate, ano</b>. Aus lavorare wird also: io lavoro, tu lavori, lei lavora.","Die Pronomen lässt du meistens weg, denn die Endung zeigt schon, wer gemeint ist: <b>Lavoro</b> a Monaco. Für die Höflichkeitsform <b>Lei</b> nimmst du die Form von lui und lei: Lei lavora qui?","Bei Verben auf <b>care</b> und <b>gare</b> kommt vor i ein <b>h</b> dazu, damit es hart klingt: tu giochi, noi paghiamo. Bei Verben auf <b>iare</b> schreibst du nur ein i: tu mangi, noi studiamo.","<b>sempre</b> und <b>spesso</b> stehen meist direkt nach dem Verb: Lavoro sempre. Bei <b>mai</b> kommt zusätzlich <b>non</b> vor das Verb: Non cucino mai. <b>a volte</b> und <b>di solito</b> stehen gern am Satzanfang."],"table":{"head":["","lavorare","mangiare","giocare"],"rows":[["io","lavoro","mangio","gioco"],["tu","lavori","mangi","giochi"],["lui, lei, Lei","lavora","mangia","gioca"],["noi","lavoriamo","mangiamo","giochiamo"],["voi","lavorate","mangiate","giocate"],["loro","lavorano","mangiano","giocano"]]},"examples":[{"it":"Lukas lavora la mattina.","de":"Lukas arbeitet vormittags."},{"it":"Matteo studia a Milano.","de":"Matteo studiert in Mailand."},{"it":"Nonna Lucia cucina ogni giorno.","de":"Oma Lucia kocht jeden Tag."},{"it":"Mangiamo spesso insieme.","de":"Wir essen oft zusammen."},{"it":"Giochi a calcio, Davide?","de":"Spielst du Fußball, Davide?"},{"it":"Rosa e Franco non mangiano mai tardi.","de":"Rosa und Franco essen nie spät."}],"drills":[{"type":"choice","q":"Io ___ in un ufficio.","de":"Ich arbeite in einem Büro.","options":["lavora","lavoro","lavori"],"answer":1,"why":"io bekommt die Endung o: lavoro."},{"type":"type","q":"Davide, ___ a calcio? (giocare)","de":"Davide, spielst du Fußball?","answer":"giochi","alt":[],"why":"giocare: vor i kommt ein h dazu, also giochi."},{"type":"choice","q":"Noi ___ sempre insieme.","de":"Wir essen immer zusammen.","options":["mangiamo","mangiano","mangiate"],"answer":0,"why":"noi bekommt die Endung iamo, bei mangiare mit nur einem i."},{"type":"type","q":"Matteo ___ a Milano. (studiare)","de":"Matteo studiert in Mailand.","answer":"studia","alt":[],"why":"lui und lei bekommen die Endung a: studia."},{"type":"choice","q":"Rosa e Franco ___ spesso a casa.","de":"Rosa und Franco kochen oft zu Hause.","options":["cucina","cucinate","cucinano"],"answer":2,"why":"loro bekommt die Endung ano: cucinano."},{"type":"type","q":"Voi ___ l'italiano? (imparare)","de":"Lernt ihr Italienisch?","answer":"imparate","alt":[],"why":"voi bekommt die Endung ate: imparate."},{"type":"choice","q":"Lukas non lavora ___ la sera.","de":"Lukas arbeitet abends nie.","options":["sempre","mai","spesso"],"answer":1,"why":"nie heißt non ... mai."},{"type":"type","q":"Noi ___ il conto. (pagare)","de":"Wir bezahlen die Rechnung.","answer":"paghiamo","alt":[],"why":"pagare: vor i kommt ein h dazu, also paghiamo."}]},"dialog":{"title":"Che lavoro fai?","setting":"Lukas und Davide sitzen in einer Bar in Bologna und erzählen von ihrem Alltag.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Davide","gender":"m"}},"lines":[{"s":"B","it":"Senti, Lukas, ma tu che lavoro fai?","de":"Sag mal, Lukas, was machst du eigentlich beruflich?"},{"s":"A","it":"Sono ingegnere. Lavoro per un'azienda di Monaco.","de":"Ich bin Ingenieur. Ich arbeite für eine Firma aus München."},{"s":"B","it":"Ah! E qui a Bologna lavori?","de":"Ah! Und hier in Bologna, arbeitest du da?"},{"s":"A","it":"Sì, la mattina in smart working. Il pomeriggio studio italiano.","de":"Ja, vormittags im Homeoffice. Nachmittags lerne ich Italienisch."},{"s":"B","it":"Bravo! Io insegno musica in una scuola.","de":"Stark! Ich unterrichte Musik an einer Schule."},{"s":"A","it":"Che bello! E la sera che fai?","de":"Wie schön! Und was machst du abends?"},{"s":"B","it":"Gioco spesso a calcio con gli amici. E tu?","de":"Ich spiele oft Fußball mit Freunden. Und du?"},{"s":"A","it":"Io a calcio non gioco mai, ma cucino un sacco!","de":"Fußball spiele ich nie, aber ich koche total viel!"},{"s":"B","it":"Davvero? Allora domani cucini tu per noi!","de":"Echt? Dann kochst du morgen für uns!"},{"s":"A","it":"Va bene, ma voi comprate il vino, eh!","de":"Okay, aber ihr kauft den Wein, ja?"},{"s":"B","it":"Perfetto! E Giulia porta il dolce.","de":"Perfekt! Und Giulia bringt den Nachtisch mit."}],"questions":[{"q":"Was ist Lukas von Beruf?","options":["Lehrer","Ingenieur","Koch"],"answer":1},{"q":"Was macht Davide abends oft?","options":["Er spielt Fußball","Er kocht","Er lernt Deutsch"],"answer":0},{"q":"Wer kocht morgen?","options":["Davide","Giulia","Lukas"],"answer":2}]},"sentences":[{"it":"La mattina lavoro in ufficio.","de":"Vormittags arbeite ich im Büro."},{"it":"Di solito mangiamo a casa.","de":"Normalerweise essen wir zu Hause."},{"it":"Che lavoro fai, Davide?","de":"Was machst du beruflich, Davide?"},{"it":"Non cucino mai la sera.","de":"Abends koche ich nie."},{"it":"Matteo studia spesso il pomeriggio.","de":"Matteo lernt oft nachmittags."},{"it":"A volte comincio a lavorare presto.","de":"Manchmal fange ich früh an zu arbeiten."},{"it":"Il mio capo è molto simpatico.","de":"Mein Chef ist sehr nett."},{"it":"Mangiamo insieme a pranzo?","de":"Essen wir mittags zusammen?"}],"spoken":[{"it":"Che fai?","book":"Che cosa fai?","de":"Was machst du gerade?","note":"Typischer Einstieg unter Freunden, am Telefon oder per Nachricht. Gern auch: Che fai di bello?","ex":"Ehi Davide, che fai? Cucino!","exDe":"Hey Davide, was machst du? Ich koche!","alt":["Cosa fai?"]},{"it":"Niente di che","book":"Niente di speciale.","de":"nichts Besonderes","note":"Die typische Antwort auf Che fai? Locker und überall üblich.","ex":"Che fai oggi? Niente di che.","exDe":"Was machst du heute? Nichts Besonderes.","alt":[]},{"it":"Un sacco","book":"Molto.","de":"total viel; jede Menge","note":"Steht nach dem Verb (lavoro un sacco) oder mit di vor einem Nomen (un sacco di lavoro). Locker, aber überall üblich.","ex":"Oggi ho un sacco di lavoro.","exDe":"Heute hab ich jede Menge Arbeit.","alt":[]},{"it":"Ogni tanto","book":"A volte.","de":"ab und zu","note":"Im Gespräch noch häufiger als a volte. Steht gern am Satzende: Sì, ogni tanto.","ex":"Cucini? Sì, ogni tanto.","exDe":"Kochst du? Ja, ab und zu.","alt":[]},{"it":"Mi tocca","book":"Devo.","de":"ich muss leider","note":"Mit der Grundform: mi tocca lavorare. Für Pflichten, die keinen Spaß machen. Sehr häufig.","ex":"Domani mi tocca lavorare.","exDe":"Morgen muss ich leider arbeiten.","alt":[]},{"it":"Sono di corsa!","book":"Ho fretta.","de":"Ich hab's eilig!","note":"Hörst du ständig, wenn jemand keine Zeit hat. Genauso üblich: Vado di corsa!","ex":"Scusa, sono di corsa! Ciao!","exDe":"Sorry, ich hab's eilig! Tschüss!","alt":["Vado di corsa!"]},{"it":"Che giornata!","book":"È una giornata difficile.","de":"Was für ein Tag!","note":"Ein Seufzer nach einem langen Tag. Mit strahlendem Gesicht gesagt heißt es: Was für ein toller Tag!","ex":"Che giornata! In ufficio c'è un sacco di lavoro.","exDe":"Was für ein Tag! Im Büro gibt's jede Menge Arbeit.","alt":[]},{"it":"in smart working","book":"da casa","de":"im Homeoffice","note":"So sagen Italiener zum Homeoffice, obwohl es englisch klingt. Ganz kurz auch: sono in smart.","ex":"Oggi lavoro in smart working.","exDe":"Heute arbeite ich im Homeoffice.","alt":[]}],"speak":[{"sit":"Ein Freund schreibt dir: 'Che fai?' Du machst gerade nichts Besonderes.","answers":["Niente di che. E tu?","Niente di che, studio italiano."],"tip":"Mit 'E tu?' gibst du die Frage locker zurück."},{"sit":"Auf einer Party fragt dich jemand, was du beruflich machst. Du arbeitest im Büro für eine deutsche Firma.","answers":["Lavoro per un'azienda tedesca.","Lavoro in ufficio, per un'azienda tedesca."],"tip":""},{"sit":"Davide fragt, ob ihr heute zusammen esst. Du musst aber leider arbeiten.","answers":["Oggi no, mi tocca lavorare.","Scusa, oggi lavoro un sacco."],"tip":"'Mi tocca' klingt nach einer Pflicht ohne Spaß."},{"sit":"Erzähl, wie dein Morgen normalerweise aussieht: Du isst ein Cornetto und arbeitest dann.","answers":["Di solito mangio un cornetto e poi lavoro.","La mattina mangio un cornetto. Poi lavoro."],"tip":""},{"sit":"Giulia fragt, ob du oft kochst. Du kochst ab und zu.","answers":["Ogni tanto.","Sì, ogni tanto.","A volte, non spesso."],"tip":""},{"sit":"Du triffst Giulia zufällig auf der Straße, hast aber gerade gar keine Zeit.","answers":["Scusa, sono di corsa!","Ciao Giulia! Scusa, sono di corsa!"],"tip":"Mit einem Lächeln und 'Ciao ciao!' bist du dann weg."}]},{"id":8,"title":"Che ore sono?","titleDe":"Wie spät ist es?","goal":"Du kannst die Uhrzeit sagen, über Wochentage sprechen und dich mit Freunden verabreden.","intro":"Wann treffen wir uns? Diese Woche lernst du die Uhrzeit, die Wochentage und alles, was du für eine Verabredung brauchst. Dazu kommen die Verben auf ere und ire, mit denen du noch viel mehr sagen kannst.","culture":"Bei Verabredungen unter Freunden sind Italiener entspannt: Eine Viertelstunde Verspätung ist ganz normal. Im Gespräch zählt man die Stunden meist nur bis zwölf und sagt 'alle otto di sera'. Auf Fahrplänen und Schildern mit Öffnungszeiten zählt man dagegen bis 24: Dort steht 20:00.","vocab":[{"it":"Che ore sono?","de":"Wie spät ist es?","alt":["Che ora è?"],"note":"Antwort: Sono le tre. Aber bei eins: È l'una.","ex":"Scusi, che ore sono?","exDe":"Entschuldigung, wie spät ist es?"},{"it":"l'ora","de":"die Stunde; die Uhrzeit","alt":["ora"],"note":"Feminin. Plural: le ore.","ex":"Ho solo un'ora.","exDe":"Ich habe nur eine Stunde."},{"it":"e mezza","de":"halb (nach der vollen Stunde)","alt":["e mezzo","e trenta"],"note":"Sono le tre e mezza = 3:30 Uhr. Deutsch sagt halb vier!","ex":"Sono le otto e mezza.","exDe":"Es ist halb neun."},{"it":"e un quarto","de":"Viertel nach","alt":["e quindici"],"note":"Sono le due e un quarto = 2:15 Uhr.","ex":"Sono le sette e un quarto.","exDe":"Es ist Viertel nach sieben."},{"it":"meno un quarto","de":"Viertel vor","alt":["meno quindici"],"note":"Sono le sei meno un quarto = 5:45 Uhr.","ex":"Sono le nove meno un quarto.","exDe":"Es ist Viertel vor neun."},{"it":"A che ora?","de":"Um wie viel Uhr?","alt":[],"note":"Antwort mit alle: alle otto. Bei eins: all'una.","ex":"A che ora comincia la lezione?","exDe":"Um wie viel Uhr fängt der Unterricht an?"},{"it":"mezzogiorno","de":"der Mittag (12 Uhr)","alt":[],"note":"Ohne Artikel: È mezzogiorno. a mezzogiorno = um zwölf.","ex":"A mezzogiorno mangio con Giulia.","exDe":"Um zwölf esse ich mit Giulia."},{"it":"mezzanotte","de":"die Mitternacht","alt":[],"note":"Ohne Artikel: È mezzanotte.","ex":"È mezzanotte. Buonanotte!","exDe":"Es ist Mitternacht. Gute Nacht!"},{"it":"oggi","de":"heute","alt":[],"note":"gg klingt wie dsch: OD dschi.","ex":"Che giorno è oggi?","exDe":"Welcher Tag ist heute?"},{"it":"domani","de":"morgen (am nächsten Tag)","alt":[],"note":"Nicht verwechseln: la mattina = der Morgen.","ex":"Domani lavoro tutto il giorno.","exDe":"Morgen arbeite ich den ganzen Tag."},{"it":"stasera","de":"heute Abend","alt":["questa sera"],"note":"Kurz für questa sera.","ex":"Stasera mangiamo insieme?","exDe":"Essen wir heute Abend zusammen?"},{"it":"l'appuntamento","de":"die Verabredung; der Termin","alt":["appuntamento"],"note":"Maskulin. Auch für ein Date.","ex":"Ho un appuntamento alle sei.","exDe":"Ich habe um sechs einen Termin."},{"it":"lunedì","de":"der Montag","alt":["lunedi"],"note":"Wochentage schreibt man klein. il lunedì = montags (jede Woche).","ex":"Lunedì lavoro a casa.","exDe":"Am Montag arbeite ich zu Hause."},{"it":"martedì","de":"der Dienstag","alt":["martedi"],"note":"Betonung am Ende: mar te DÌ.","ex":"Martedì ho tempo.","exDe":"Am Dienstag habe ich Zeit."},{"it":"mercoledì","de":"der Mittwoch","alt":["mercoledi"],"note":"","ex":"Il mercoledì c'è il mercato.","exDe":"Mittwochs ist Markt."},{"it":"giovedì","de":"der Donnerstag","alt":["giovedi"],"note":"","ex":"Ci vediamo giovedì?","exDe":"Sehen wir uns am Donnerstag?"},{"it":"venerdì","de":"der Freitag","alt":["venerdi"],"note":"","ex":"Venerdì sera c'è una festa.","exDe":"Am Freitagabend gibt es eine Party."},{"it":"sabato","de":"der Samstag","alt":[],"note":"Betonung vorne: SA ba to.","ex":"Sabato c'è il concerto di Davide.","exDe":"Am Samstag ist Davides Konzert."},{"it":"domenica","de":"der Sonntag","alt":[],"note":"Feminin: la domenica. Alle anderen Wochentage sind maskulin.","ex":"La domenica mangiamo con la nonna.","exDe":"Sonntags essen wir mit Oma."},{"it":"il fine settimana","de":"das Wochenende","alt":["il weekend","fine settimana","weekend"],"note":"Auch: il weekend. Im Plural unverändert.","ex":"Che bello, è il fine settimana!","exDe":"Wie schön, es ist Wochenende!"},{"it":"prendere","de":"nehmen","alt":[],"note":"prendere un caffè = einen Kaffee trinken.","ex":"Prendiamo un caffè?","exDe":"Trinken wir einen Kaffee?"},{"it":"vedere","de":"sehen","alt":[],"note":"Kennst du schon: ci vediamo = wir sehen uns.","ex":"Vedi Giulia stasera?","exDe":"Siehst du Giulia heute Abend?"},{"it":"capire","de":"verstehen","alt":[],"note":"Mit isc: capisco, capisci, capisce, capiamo, capite, capiscono.","ex":"Scusi, non capisco.","exDe":"Entschuldigung, ich verstehe nicht."},{"it":"finire","de":"enden; beenden","alt":[],"note":"Mit isc: finisco. finire di lavorare = Feierabend machen.","ex":"Finisco di lavorare alle sei.","exDe":"Ich mache um sechs Feierabend."},{"it":"dormire","de":"schlafen","alt":[],"note":"","ex":"Lukas dorme poco.","exDe":"Lukas schläft wenig."},{"it":"scrivere","de":"schreiben","alt":[],"note":"","ex":"Scrivo un messaggio a Giulia.","exDe":"Ich schreibe Giulia eine Nachricht."},{"it":"aprire","de":"öffnen; aufmachen","alt":[],"note":"","ex":"Il museo apre alle dieci.","exDe":"Das Museum öffnet um zehn."},{"it":"chiudere","de":"schließen; zumachen","alt":[],"note":"ch klingt wie k: KIU de re.","ex":"I negozi chiudono alle otto.","exDe":"Die Läden schließen um acht."},{"it":"preferire","de":"lieber mögen; bevorzugen","alt":[],"note":"Mit isc: preferisco, preferisci.","ex":"Preferisci il tè o il caffè?","exDe":"Magst du lieber Tee oder Kaffee?"},{"it":"offrire","de":"anbieten; einladen (bezahlen)","alt":[],"note":"Offro io! = Ich lade dich ein!","ex":"Stasera offro io!","exDe":"Heute Abend lade ich ein!"},{"it":"Hai tempo?","de":"Hast du Zeit?","alt":[],"note":"Höflich (Lei): Ha tempo?","ex":"Hai tempo stasera?","exDe":"Hast du heute Abend Zeit?"},{"it":"D'accordo!","de":"Einverstanden!","alt":["d'accordo"],"note":"","ex":"Alle otto? D'accordo!","exDe":"Um acht? Einverstanden!"},{"it":"purtroppo","de":"leider","alt":[],"note":"","ex":"Purtroppo lunedì lavoro.","exDe":"Leider arbeite ich am Montag."},{"it":"la settimana","de":"die Woche","alt":[],"note":"la settimana prossima = nächste Woche.","ex":"Ci vediamo la settimana prossima!","exDe":"Wir sehen uns nächste Woche!"},{"it":"dopo","de":"danach; nach","alt":[],"note":"A dopo! = Bis später!","ex":"Dopo il lavoro ho tempo.","exDe":"Nach der Arbeit habe ich Zeit."},{"it":"puntuale","de":"pünktlich","alt":[],"note":"Gleich für maskulin und feminin.","ex":"Lukas è sempre puntuale.","exDe":"Lukas ist immer pünktlich."}],"grammar":{"title":"Präsens: Verben auf ere und ire","points":["Verben auf <b>ere</b> funktionieren wie die auf are, nur mit etwas anderen Endungen: <b>o, i, e, iamo, ete, ono</b>. Also: io prendo, tu prendi, lui prende, noi prendiamo, voi prendete, loro prendono.","Verben auf <b>ire</b> sind fast gleich wie die auf ere. Nur bei voi heißt es <b>ite</b>: voi dormite. Gut zu wissen: io, tu und noi enden bei allen regelmäßigen Verben auf <b>o</b>, <b>i</b> und <b>iamo</b>.","Viele Verben auf ire schieben <b>isc</b> ein, nur nicht bei noi und voi: capisco, capisci, capisce, capiamo, capite, capiscono. Genauso gehen <b>finire</b> und <b>preferire</b>. Aussprache: capisco mit sk, capisci mit sch.","Die Uhrzeit: <b>Sono le</b> otto. Nur bei eins, Mittag und Mitternacht sagst du <b>è</b>: È l'una, è mezzogiorno. Um wie viel Uhr? <b>alle</b> otto, <b>all'una</b>, <b>a</b> mezzogiorno."],"table":{"head":["","prendere","dormire","capire"],"rows":[["io","prendo","dormo","capisco"],["tu","prendi","dormi","capisci"],["lui, lei, Lei","prende","dorme","capisce"],["noi","prendiamo","dormiamo","capiamo"],["voi","prendete","dormite","capite"],["loro","prendono","dormono","capiscono"]]},"examples":[{"it":"Che ore sono? È l'una.","de":"Wie spät ist es? Es ist ein Uhr."},{"it":"Prendete un caffè?","de":"Trinkt ihr einen Kaffee?"},{"it":"Il mercato apre alle sette.","de":"Der Markt öffnet um sieben."},{"it":"La lezione finisce alle otto e mezza.","de":"Der Unterricht endet um halb neun."},{"it":"Vedete Davide stasera?","de":"Seht ihr Davide heute Abend?"},{"it":"Preferisco il venerdì sera.","de":"Freitagabend ist mir lieber."}],"drills":[{"type":"choice","q":"Io ___ un caffè, grazie.","de":"Ich nehme einen Kaffee, danke.","options":["prende","prendi","prendo"],"answer":2,"why":"io bekommt die Endung o: prendo."},{"type":"type","q":"Lukas, ___ l'italiano? (capire)","de":"Lukas, verstehst du Italienisch?","answer":"capisci","alt":[],"why":"capire schiebt isc ein: tu capisci."},{"type":"choice","q":"Il sabato noi ___ fino a tardi.","de":"Samstags schlafen wir lange.","options":["dormiamo","dormono","dormite"],"answer":0,"why":"noi bekommt die Endung iamo: dormiamo."},{"type":"type","q":"La farmacia ___ alle nove. (aprire)","de":"Die Apotheke öffnet um neun.","answer":"apre","alt":[],"why":"lei bekommt die Endung e: apre."},{"type":"choice","q":"Il concerto ___ a mezzanotte.","de":"Das Konzert endet um Mitternacht.","options":["finiscono","finisce","finisci"],"answer":1,"why":"Für eine Sache nimmst du die lui Form mit isc: finisce."},{"type":"type","q":"Voi ___ il venerdì o il sabato? (preferire)","de":"Ist euch Freitag oder Samstag lieber?","answer":"preferite","alt":[],"why":"Bei voi kein isc: preferite."},{"type":"choice","q":"Che ore sono? ___ le otto.","de":"Wie spät ist es? Es ist acht Uhr.","options":["È","Ci sono","Sono"],"answer":2,"why":"Ab zwei Uhr sagst du sono le."},{"type":"type","q":"I miei amici ___ un messaggio. (scrivere)","de":"Meine Freunde schreiben eine Nachricht.","answer":"scrivono","alt":[],"why":"loro bekommt bei ere die Endung ono: scrivono."}]},"dialog":{"title":"Ci vediamo sabato?","setting":"Giulia ruft Lukas an und möchte sich mit ihm verabreden.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Giulia","gender":"f"}},"lines":[{"s":"B","it":"Ciao Lukas! Senti, sabato hai tempo?","de":"Hallo Lukas! Sag mal, hast du am Samstag Zeit?"},{"s":"A","it":"La mattina no, purtroppo. Ho lezione. Perché?","de":"Vormittags leider nicht, da hab ich Unterricht. Warum?"},{"s":"B","it":"E la sera? C'è il concerto di Davide!","de":"Und abends? Davide hat ein Konzert!"},{"s":"A","it":"Ma dai! A che ora comincia?","de":"Echt? Wann fängt es an?"},{"s":"B","it":"Alle nove. Prima mangiamo una pizza? Ti va?","de":"Um neun. Essen wir vorher eine Pizza? Hast du Lust?"},{"s":"A","it":"Volentieri! Dove ci vediamo?","de":"Gern! Wo treffen wir uns?"},{"s":"B","it":"In Piazza Maggiore. Facciamo alle sette e mezza?","de":"Auf der Piazza Maggiore. Sagen wir um halb acht?"},{"s":"A","it":"D'accordo! Alle sette e mezza in punto.","de":"Abgemacht! Punkt halb acht."},{"s":"B","it":"In punto? Ma sei sempre così puntuale?","de":"Punkt? Bist du immer so pünktlich?"},{"s":"A","it":"Certo! Sono tedesco!","de":"Klar! Ich bin Deutscher!"},{"s":"B","it":"Bravo! Allora a sabato!","de":"Sehr gut! Dann bis Samstag!"},{"s":"A","it":"A sabato, Giulia. Ciao ciao!","de":"Bis Samstag, Giulia. Tschüss!"}],"questions":[{"q":"Warum hat Lukas am Samstagvormittag keine Zeit?","options":["Er schläft","Er arbeitet","Er hat Unterricht"],"answer":2},{"q":"Um wie viel Uhr treffen sich Lukas und Giulia?","options":["Um halb acht","Um neun","Um halb neun"],"answer":0},{"q":"Was gibt es am Samstagabend?","options":["Ein Fußballspiel","Ein Konzert von Davide","Ein Essen bei Giulias Eltern"],"answer":1}]},"sentences":[{"it":"Che ore sono? Sono le dieci.","de":"Wie spät ist es? Es ist zehn Uhr."},{"it":"Ci vediamo sabato alle otto.","de":"Wir sehen uns am Samstag um acht."},{"it":"Hai tempo domani sera?","de":"Hast du morgen Abend Zeit?"},{"it":"Il bar apre alle sei e mezza.","de":"Die Bar öffnet um halb sieben."},{"it":"Lukas capisce bene l'italiano.","de":"Lukas versteht gut Italienisch."},{"it":"La domenica dormo molto.","de":"Sonntags schlafe ich viel."},{"it":"Il fine settimana non lavoro mai.","de":"Am Wochenende arbeite ich nie."},{"it":"A che ora finisci di lavorare?","de":"Um wie viel Uhr machst du Feierabend?"}],"spoken":[{"it":"Ti va?","book":"Vuoi?","de":"Hast du Lust?","note":"Für Vorschläge unter Freunden: Ti va un caffè? Ti va di uscire? Höflich (Lei): Le va?","ex":"Un caffè dopo il lavoro? Ti va?","exDe":"Ein Kaffee nach der Arbeit? Hast du Lust?","alt":[]},{"it":"Ci sei?","book":"Vieni anche tu?","de":"Bist du dabei?","note":"Für Pläne unter Freunden. Die Antwort: Ci sono! Am Telefon heißt Ci sei? auch: Bist du noch dran?","ex":"Sabato pizza con Davide. Ci sei?","exDe":"Samstag Pizza mit Davide. Bist du dabei?","alt":[]},{"it":"Ci vediamo dopo","book":"A più tardi.","de":"Bis nachher!","note":"Wenn ihr euch am selben Tag noch seht. Noch kürzer: A dopo!","ex":"Ok, ci vediamo dopo! Ciao!","exDe":"Okay, bis nachher! Tschüss!","alt":["A dopo"]},{"it":"A che ora stacchi?","book":"A che ora finisci di lavorare?","de":"Wann hast du Feierabend?","note":"staccare heißt locker Feierabend machen: Stacco alle sei. Überall üblich.","ex":"A che ora stacchi oggi? Alle cinque.","exDe":"Wann hast du heute Feierabend? Um fünf.","alt":[]},{"it":"Facciamo alle otto?","book":"Ci vediamo alle otto?","de":"Sagen wir um acht?","note":"Mit facciamo schlägst du einen Termin vor: Facciamo sabato? Das Verb fare lernst du in Lektion 12.","ex":"Stasera? Facciamo alle nove?","exDe":"Heute Abend? Sagen wir um neun?","alt":[]},{"it":"Verso le otto","book":"Alle otto circa.","de":"gegen acht","note":"verso heißt hier gegen, ungefähr. Bei eins: verso l'una. Praktisch, wenn du es nicht genau weißt.","ex":"Ci vediamo verso le otto?","exDe":"Treffen wir uns gegen acht?","alt":[]},{"it":"in punto","book":"alle otto esatte","de":"Punkt (bei der Uhrzeit)","note":"Steht nach der Uhrzeit: alle otto in punto. Unter Freunden heißt das trotzdem oft zehn Minuten später.","ex":"Il film comincia alle nove in punto.","exDe":"Der Film fängt Punkt neun an.","alt":[]},{"it":"Arrivo!","book":"Vengo subito.","de":"Bin gleich da!","note":"Hörst du überall, auch vom Kellner. Gemeint ist: gleich, nicht unbedingt sofort.","ex":"Dove sei? Arrivo, arrivo!","exDe":"Wo bist du? Bin gleich da!","alt":[]}],"speak":[{"sit":"Du hast Lust auf einen Kaffee mit Giulia. Frag sie, ob sie auch Lust hat.","answers":["Ti va un caffè?","Prendiamo un caffè?","Hai tempo per un caffè?"],"tip":"'Ti va?' passt immer, wenn du etwas vorschlägst."},{"sit":"Ihr plant ein Treffen. Schlag Samstag um halb acht vor.","answers":["Facciamo sabato alle sette e mezza?","Sabato alle sette e mezza?","Ci vediamo sabato alle sette e mezza?"],"tip":""},{"sit":"Eine Frau fragt dich auf der Straße nach der Uhrzeit. Es ist Viertel nach drei.","answers":["Sono le tre e un quarto.","Le tre e un quarto."],"tip":"Im Gespräch lassen Italiener 'sono' oft einfach weg."},{"sit":"Davide lädt dich für Freitagabend zu einer Party ein. Leider arbeitest du.","answers":["Venerdì no, purtroppo lavoro.","Purtroppo venerdì lavoro. Peccato!"],"tip":""},{"sit":"Giulia fragt, wann du heute Feierabend hast. Du bist um sechs fertig.","answers":["Alle sei.","Stacco alle sei.","Finisco di lavorare alle sei."],"tip":""},{"sit":"Du bist auf dem Weg zu einer Verabredung. Giulia schreibt: 'Dove sei?' Sag, dass du gleich da bist.","answers":["Arrivo!","Arrivo, cinque minuti!"],"tip":"Doppelt gesagt klingt es noch dringender: Arrivo, arrivo!"}]},{"id":9,"title":"In città","titleDe":"In der Stadt","goal":"Du kannst nach dem Weg fragen, eine Wegbeschreibung verstehen und sagen, wo etwas ist.","intro":"Wo ist die Apotheke? Wie komme ich zur Piazza? Diese Woche lernst du die wichtigsten Orte in der Stadt und fragst nach dem Weg. Dazu kommen das Verb andare und kleine Wörter wie al, nella und dal.","culture":"Bologna hat fast 40 Kilometer Portici, also überdachte Laubengänge, allein in der Altstadt. Seit 2021 gehören sie zum Welterbe der UNESCO. So kommst du fast überall trocken zu Fuß hin, auch bei Regen. Das Wahrzeichen der Stadt sind die Due Torri, zwei Türme aus dem Mittelalter, einer davon ganz schön schief.","vocab":[{"it":"andare","de":"gehen; fahren","alt":[],"note":"Unregelmäßig: io vado, tu vai, lui va.","ex":"Dove vai, Lukas?","exDe":"Wohin gehst du, Lukas?"},{"it":"la piazza","de":"der Platz","alt":[],"note":"zz klingt wie ts: PIAT tsa.","ex":"La piazza è molto bella.","exDe":"Der Platz ist sehr schön."},{"it":"la via","de":"die Straße (in Adressen)","alt":[],"note":"Steht vor dem Straßennamen: via Rizzoli.","ex":"La banca è in via Rizzoli.","exDe":"Die Bank ist in der Via Rizzoli."},{"it":"la strada","de":"die Straße; der Weg","alt":[],"note":"Plural: le strade.","ex":"La strada è lunga.","exDe":"Der Weg ist lang."},{"it":"il centro","de":"das Zentrum; die Innenstadt","alt":[],"note":"in centro = im Zentrum; ins Zentrum.","ex":"Abito in centro.","exDe":"Ich wohne im Zentrum."},{"it":"la stazione","de":"der Bahnhof","alt":[],"note":"Plural: le stazioni.","ex":"La stazione è lontana?","exDe":"Ist der Bahnhof weit weg?"},{"it":"il museo","de":"das Museum","alt":[],"note":"Betonung: mu SE o.","ex":"Oggi il museo è chiuso.","exDe":"Heute ist das Museum geschlossen."},{"it":"la chiesa","de":"die Kirche","alt":[],"note":"ch klingt wie k: KIE sa.","ex":"La chiesa è molto antica.","exDe":"Die Kirche ist sehr alt."},{"it":"la farmacia","de":"die Apotheke","alt":[],"note":"Betonung auf dem i: far ma TSCHI a.","ex":"La farmacia è aperta?","exDe":"Hat die Apotheke offen?"},{"it":"la banca","de":"die Bank (für Geld)","alt":[],"note":"Plural: le banche. Die Sitzbank heißt la panchina.","ex":"La banca apre alle otto e mezza.","exDe":"Die Bank öffnet um halb neun."},{"it":"Dov'è?","de":"Wo ist ...?","alt":["Dove è?","Dov'e?"],"note":"Kurz für dove è. Für mehrere Dinge: Dove sono?","ex":"Dov'è il museo?","exDe":"Wo ist das Museum?"},{"it":"il negozio","de":"der Laden; das Geschäft","alt":[],"note":"Plural: i negozi.","ex":"Il negozio è accanto alla banca.","exDe":"Der Laden ist neben der Bank."},{"it":"a destra","de":"rechts; nach rechts","alt":[],"note":"","ex":"La farmacia è a destra.","exDe":"Die Apotheke ist rechts."},{"it":"a sinistra","de":"links; nach links","alt":[],"note":"","ex":"Poi giriamo a sinistra.","exDe":"Dann biegen wir links ab."},{"it":"dritto","de":"geradeaus","alt":["diritto","sempre dritto"],"note":"sempre dritto = immer geradeaus.","ex":"Da qui vai sempre dritto.","exDe":"Von hier gehst du immer geradeaus."},{"it":"vicino","de":"in der Nähe; nah","alt":[],"note":"vicino a = in der Nähe von: vicino alla stazione.","ex":"Il bar è qui vicino.","exDe":"Die Bar ist hier in der Nähe."},{"it":"lontano","de":"weit (weg)","alt":[],"note":"feminin: lontana. lontano da = weit weg von: lontano dal centro.","ex":"È lontano da qui?","exDe":"Ist es weit von hier?"},{"it":"accanto a","de":"neben","alt":[],"note":"Mit Artikel: accanto al bar, accanto alla chiesa.","ex":"La banca è accanto al museo.","exDe":"Die Bank ist neben dem Museum."},{"it":"di fronte a","de":"gegenüber (von)","alt":[],"note":"Mit Artikel: di fronte alla stazione.","ex":"Il bar è di fronte alla chiesa.","exDe":"Die Bar ist gegenüber der Kirche."},{"it":"davanti a","de":"vor (Ort)","alt":[],"note":"Mit Artikel: davanti al museo.","ex":"Ci vediamo davanti alla stazione.","exDe":"Wir treffen uns vor dem Bahnhof."},{"it":"dietro","de":"hinter","alt":[],"note":"Mit Artikel: dietro la chiesa oder dietro alla chiesa.","ex":"Il parco è dietro il museo.","exDe":"Der Park ist hinter dem Museum."},{"it":"qui","de":"hier","alt":["qua"],"note":"Auch: qua.","ex":"Abito qui vicino.","exDe":"Ich wohne hier in der Nähe."},{"it":"girare","de":"abbiegen","alt":[],"note":"girare a destra = rechts abbiegen.","ex":"Giro a destra o a sinistra?","exDe":"Biege ich rechts oder links ab?"},{"it":"attraversare","de":"überqueren","alt":[],"note":"","ex":"Attraversiamo la piazza.","exDe":"Wir überqueren den Platz."},{"it":"il supermercato","de":"der Supermarkt","alt":[],"note":"","ex":"C'è un supermercato qui vicino?","exDe":"Gibt es hier in der Nähe einen Supermarkt?"},{"it":"l'ospedale","de":"das Krankenhaus","alt":["ospedale"],"note":"Maskulin. Plural: gli ospedali.","ex":"L'ospedale è lontano dal centro.","exDe":"Das Krankenhaus ist weit vom Zentrum entfernt."},{"it":"la posta","de":"die Post","alt":["l'ufficio postale"],"note":"Auch: l'ufficio postale.","ex":"Vado alla posta.","exDe":"Ich gehe zur Post."},{"it":"il parco","de":"der Park","alt":[],"note":"Plural: i parchi (mit h).","ex":"Andiamo al parco?","exDe":"Gehen wir in den Park?"},{"it":"la torre","de":"der Turm","alt":[],"note":"Plural: le torri. Le Due Torri sind das Wahrzeichen von Bologna.","ex":"La torre è molto alta.","exDe":"Der Turm ist sehr hoch."},{"it":"il portico","de":"der Laubengang; die Arkade","alt":[],"note":"Plural: i portici. Typisch für Bologna.","ex":"Camminiamo sotto i portici.","exDe":"Wir laufen unter den Arkaden."},{"it":"l'angolo","de":"die Ecke","alt":["angolo"],"note":"Maskulin. all'angolo = an der Ecke.","ex":"C'è una banca all'angolo.","exDe":"An der Ecke ist eine Bank."},{"it":"il semaforo","de":"die Ampel","alt":[],"note":"Betonung: se MA fo ro.","ex":"Al semaforo giriamo a destra.","exDe":"An der Ampel biegen wir rechts ab."},{"it":"a piedi","de":"zu Fuß","alt":[],"note":"","ex":"Andiamo a piedi?","exDe":"Gehen wir zu Fuß?"},{"it":"fino a","de":"bis (zu)","alt":[],"note":"Mit Artikel: fino al semaforo, fino alla piazza.","ex":"Andiamo fino alla stazione.","exDe":"Wir gehen bis zum Bahnhof."},{"it":"la cartina","de":"der Stadtplan","alt":["la mappa"],"note":"Auch: la mappa.","ex":"Hai una cartina della città?","exDe":"Hast du einen Stadtplan?"},{"it":"Non sono di qui.","de":"Ich bin nicht von hier.","alt":["Non sono di qua."],"note":"Praktisch, wenn du selbst den Weg nicht kennst.","ex":"Scusi, non sono di qui.","exDe":"Entschuldigung, ich bin nicht von hier."}],"grammar":{"title":"andare und Präpositionen mit Artikel","points":["<b>andare</b> ist unregelmäßig: io <b>vado</b>, tu <b>vai</b>, lui <b>va</b>, noi andiamo, voi andate, loro <b>vanno</b>. Italienisch unterscheidet nicht zwischen gehen und fahren: Vado a Milano heißt auch ich fahre nach Mailand.","Wohin? Bei Städten nimmst du <b>a</b>: vado a Firenze. Bei vielen Orten ohne Artikel <b>in</b>: in centro, in piazza, in farmacia, in banca. Zu einer Person gehst du mit <b>da</b>: vado da Giulia.","Braucht der Ort einen Artikel, verschmelzen <b>a</b>, <b>in</b>, <b>da</b> und <b>di</b> mit ihm zu einem Wort: a + il = <b>al</b>, a + la = <b>alla</b>, di + la = <b>della</b>. Mit da geht es genauso: dal, dalla. Also: vado al museo, alla stazione.","Auch bei Ortsangaben verschmilzt die Präposition mit dem Artikel: vicino <b>alla</b> banca, accanto <b>al</b> bar, di fronte <b>alla</b> chiesa, lontano <b>dal</b> centro."],"table":{"head":["Artikel","a","in","di"],"rows":[["il","al","nel","del"],["lo","allo","nello","dello"],["l'","all'","nell'","dell'"],["la","alla","nella","della"],["i","ai","nei","dei"],["gli","agli","negli","degli"],["le","alle","nelle","delle"]]},"examples":[{"it":"Vado al museo con Giulia.","de":"Ich gehe mit Giulia ins Museum."},{"it":"La farmacia è vicino alla stazione.","de":"Die Apotheke ist in der Nähe des Bahnhofs."},{"it":"Andiamo in centro a piedi?","de":"Gehen wir zu Fuß ins Zentrum?"},{"it":"Stasera vado da Davide.","de":"Heute Abend gehe ich zu Davide."},{"it":"Domani Matteo va a Milano.","de":"Morgen fährt Matteo nach Mailand."},{"it":"Piazza Maggiore è nel centro di Bologna.","de":"Die Piazza Maggiore liegt im Zentrum von Bologna."}],"drills":[{"type":"choice","q":"Io ___ in centro.","de":"Ich gehe ins Zentrum.","options":["va","vado","vai"],"answer":1,"why":"andare ist unregelmäßig: io vado."},{"type":"type","q":"Rosa e Franco ___ al mercato. (andare)","de":"Rosa und Franco gehen auf den Markt.","answer":"vanno","alt":[],"why":"loro: vanno."},{"type":"choice","q":"Vado ___ stazione.","de":"Ich gehe zum Bahnhof.","options":["al","allo","alla"],"answer":2,"why":"stazione ist feminin: a + la = alla."},{"type":"type","q":"Piazza Maggiore è il centro ___ città.","de":"Die Piazza Maggiore ist das Zentrum der Stadt.","answer":"della","alt":[],"why":"città ist feminin: di + la = della."},{"type":"choice","q":"Stasera andiamo ___ Davide.","de":"Heute Abend gehen wir zu Davide.","options":["da","a","in"],"answer":0,"why":"Zu einer Person gehst du mit da."},{"type":"type","q":"La farmacia è accanto ___ supermercato.","de":"Die Apotheke ist neben dem Supermarkt.","answer":"al","alt":[],"why":"il supermercato: a + il = al."},{"type":"choice","q":"Il museo è lontano ___ centro?","de":"Ist das Museum weit vom Zentrum entfernt?","options":["del","dal","nel"],"answer":1,"why":"lontano da, mit il wird daraus dal."},{"type":"type","q":"Voi ___ al parco? (andare)","de":"Geht ihr in den Park?","answer":"andate","alt":[],"why":"Bei voi ist andare regelmäßig: andate."}]},"dialog":{"title":"Scusi, dov'è Piazza Maggiore?","setting":"Lukas ist in der Nähe des Bahnhofs und sucht den Weg zur Piazza Maggiore. Er fragt eine Passantin.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Passantin","gender":"f"}},"lines":[{"s":"A","it":"Scusi, signora, per Piazza Maggiore?","de":"Entschuldigung, wie komme ich zur Piazza Maggiore?"},{"s":"B","it":"Piazza Maggiore? È in centro, vicino alle Due Torri.","de":"Zur Piazza Maggiore? Die ist im Zentrum, bei den zwei Türmen."},{"s":"A","it":"È lontano? Quanto ci vuole a piedi?","de":"Ist es weit? Wie lange braucht man zu Fuß?"},{"s":"B","it":"Ma no, ci vogliono quindici minuti.","de":"Ach was, das sind fünfzehn Minuten."},{"s":"A","it":"Perfetto. E vado a destra o a sinistra?","de":"Perfekt. Und muss ich nach rechts oder nach links?"},{"s":"B","it":"Guardi, è facile: sempre dritto per via dell'Indipendenza.","de":"Also, das ist einfach: immer geradeaus durch die Via dell'Indipendenza."},{"s":"A","it":"Un attimo... sempre dritto. E poi?","de":"Moment ... immer geradeaus. Und dann?"},{"s":"B","it":"Poi attraversa via Rizzoli ed ecco la piazza.","de":"Dann überqueren Sie die Via Rizzoli und schon sind Sie da."},{"s":"A","it":"Capito! Senta, c'è anche una farmacia lì vicino?","de":"Alles klar! Sagen Sie, gibt es da in der Nähe auch eine Apotheke?"},{"s":"B","it":"Sì, accanto alla banca, sotto il portico.","de":"Ja, neben der Bank, unter dem Laubengang."},{"s":"A","it":"Grazie mille, signora! Gentilissima!","de":"Vielen Dank! Sehr nett von Ihnen!"},{"s":"B","it":"Si figuri! Buona giornata!","de":"Gern geschehen! Schönen Tag noch!"}],"questions":[{"q":"Wohin möchte Lukas?","options":["Zum Bahnhof","Zur Piazza Maggiore","Zum Museum"],"answer":1},{"q":"Wie lange braucht Lukas zu Fuß?","options":["Fünf Minuten","Eine halbe Stunde","Fünfzehn Minuten"],"answer":2},{"q":"Wo ist die Apotheke?","options":["Neben der Bank","Gegenüber der Kirche","Am Bahnhof"],"answer":0}]},"sentences":[{"it":"Scusi, dov'è la stazione?","de":"Entschuldigung, wo ist der Bahnhof?"},{"it":"Vado in centro a piedi.","de":"Ich gehe zu Fuß ins Zentrum."},{"it":"La farmacia è accanto alla banca.","de":"Die Apotheke ist neben der Bank."},{"it":"Al semaforo gira a sinistra.","de":"An der Ampel biegen Sie links ab."},{"it":"Il museo è di fronte alla chiesa.","de":"Das Museum ist gegenüber der Kirche."},{"it":"Domani andiamo al museo insieme.","de":"Morgen gehen wir zusammen ins Museum."},{"it":"Il supermercato è lontano da qui?","de":"Ist der Supermarkt weit von hier?"},{"it":"Purtroppo non sono di qui.","de":"Leider bin ich nicht von hier."}],"spoken":[{"it":"dalle parti di","book":"vicino a","de":"in der Gegend von","note":"Sehr häufig, wenn man ungefähr sagt, wo etwas ist. Mit Artikel: dalle parti del centro, dalle parti della stazione.","ex":"Abito dalle parti della stazione.","exDe":"Ich wohne in der Gegend vom Bahnhof.","alt":[]},{"it":"Scusi, per la stazione?","book":"Scusi, come arrivo alla stazione?","de":"Entschuldigung, wie komme ich zum Bahnhof?","note":"Kurz und typisch: per und das Ziel reichen. Geht mit jedem Ort: Per il centro?","ex":"Scusi, per il centro? Sempre dritto.","exDe":"Entschuldigung, wie komme ich ins Zentrum? Immer geradeaus.","alt":[]},{"it":"È a due passi.","book":"È molto vicino.","de":"Das ist ganz in der Nähe.","note":"Wörtlich: zwei Schritte entfernt. Sagen Italiener gern, auch wenn es zehn Minuten sind.","ex":"Il museo? È a due passi da qui.","exDe":"Das Museum? Nur ein Katzensprung von hier.","alt":["È a due passi"]},{"it":"la prima a destra","book":"la prima strada a destra","de":"die erste (Straße) rechts","note":"strada lässt man einfach weg. Genauso: la seconda a sinistra.","ex":"Giro alla prima a destra?","exDe":"Biege ich die erste rechts ab?","alt":[]},{"it":"Quanto ci vuole?","book":"Quanto tempo ci vuole?","de":"Wie lange braucht man?","note":"Italiener lassen tempo oft weg. Die Antwort: Ci vuole un'ora oder Ci vogliono dieci minuti.","ex":"Quanto ci vuole a piedi? Dieci minuti.","exDe":"Wie lange braucht man zu Fuß? Zehn Minuten.","alt":[]},{"it":"Guardi","book":"","de":"also (höflich, wörtlich: schauen Sie)","note":"Damit beginnen Italiener gern eine Erklärung. Zu Fremden guardi, zu Freunden guarda.","ex":"Guardi, è facile: sempre dritto.","exDe":"Also, das ist ganz einfach: immer geradeaus.","alt":[]},{"it":"Capito!","book":"Ho capito.","de":"Alles klar!; Verstanden!","note":"Die Kurzform ohne ho. Mit fragendem Ton: Capito? = Alles klar?","ex":"Dritto e poi a destra. Capito!","exDe":"Geradeaus und dann rechts. Alles klar!","alt":[]},{"it":"in fondo alla strada","book":"alla fine della strada","de":"am Ende der Straße","note":"in fondo heißt ganz hinten, am Ende. In fondo a destra (hinten rechts) hörst du oft, wenn du nach der Toilette fragst.","ex":"La farmacia è in fondo alla strada.","exDe":"Die Apotheke ist am Ende der Straße.","alt":[]}],"speak":[{"sit":"Du bist am Bahnhof und willst zur Piazza Maggiore. Frag eine Passantin.","answers":["Scusi, per Piazza Maggiore?","Scusi, dov'è Piazza Maggiore?","Scusi, come arrivo a Piazza Maggiore?"],"tip":"Kurz mit 'per' klingt am natürlichsten."},{"sit":"Ein Tourist fragt dich nach dem Weg, aber du kennst dich selbst nicht aus.","answers":["Scusi, non sono di qui.","Purtroppo non sono di qui."],"tip":""},{"sit":"Erklär einer Touristin den Weg: immer geradeaus, dann an der Ampel rechts.","answers":["Sempre dritto e al semaforo a destra.","Guardi, va sempre dritto e al semaforo gira a destra."],"tip":"Für Wegbeschreibungen reicht das Präsens."},{"sit":"Frag, ob es hier in der Nähe eine Apotheke gibt.","answers":["Scusi, c'è una farmacia qui vicino?","C'è una farmacia qui vicino?"],"tip":""},{"sit":"Du willst wissen, wie lange man zu Fuß zum Bahnhof braucht.","answers":["Quanto ci vuole a piedi?","Quanto ci vuole a piedi fino alla stazione?","La stazione è lontana a piedi?"],"tip":""},{"sit":"Giulia fragt, wo ihr euch trefft. Schlag vor: vor dem Museum.","answers":["Davanti al museo.","Ci vediamo davanti al museo?"],"tip":""}]},{"id":10,"title":"Al ristorante","titleDe":"Im Restaurant","goal":"Du kannst im Restaurant bestellen, nach Empfehlungen fragen und die Rechnung verlangen.","intro":"Essen ist in Italien ein kleines Fest! Diese Woche lernst du, einen Tisch zu reservieren, die Speisekarte zu verstehen und wie ein Profi zu bestellen. Dazu kommen drei Verben, die du ständig brauchst: wollen, können und müssen.","culture":"In Italien isst man in Gängen: antipasto, primo (Pasta, Risotto oder Suppe), secondo (Fleisch oder Fisch) mit contorno und am Ende dolce und caffè. Niemand muss alles bestellen, ein primo mit contorno ist völlig normal. Auf der Rechnung steht oft der coperto, ein kleiner Betrag für Brot und Gedeck. Und Spaghetti Bolognese gibt es in Bologna traditionell nicht: Hier isst man tagliatelle al ragù.","vocab":[{"it":"il cameriere","de":"der Kellner","alt":["cameriere"],"note":"Feminin: la cameriera. Du rufst ihn mit: Scusi!","ex":"Il cameriere è molto gentile.","exDe":"Der Kellner ist sehr nett."},{"it":"il menù","de":"die Speisekarte","alt":["il menu"],"note":"Man schreibt auch menu ohne Akzent. Plural unverändert: i menù.","ex":"Avete il menù anche in tedesco?","exDe":"Haben Sie die Speisekarte auch auf Deutsch?"},{"it":"il tavolo","de":"der Tisch","alt":["tavolo"],"note":"","ex":"Il nostro tavolo è vicino alla finestra.","exDe":"Unser Tisch ist am Fenster."},{"it":"volere","de":"wollen","alt":[],"note":"Unregelmäßig: io voglio, tu vuoi.","ex":"Voglio assaggiare tutto!","exDe":"Ich will alles probieren!"},{"it":"potere","de":"können; dürfen","alt":[],"note":"Unregelmäßig: io posso, tu puoi.","ex":"Posso pagare con la carta?","exDe":"Kann ich mit Karte zahlen?"},{"it":"dovere","de":"müssen","alt":[],"note":"Unregelmäßig: io devo, tu devi.","ex":"Scusa, devo andare.","exDe":"Entschuldige, ich muss gehen."},{"it":"Avete un tavolo per due?","de":"Haben Sie einen Tisch für zwei?","alt":[],"note":"Avete (ihr) meint hier das ganze Restaurant.","ex":"Buonasera! Avete un tavolo per due?","exDe":"Guten Abend! Haben Sie einen Tisch für zwei?"},{"it":"l'antipasto","de":"die Vorspeise","alt":["antipasto"],"note":"Maskulin. Plural: gli antipasti.","ex":"Un antipasto per due, per favore.","exDe":"Eine Vorspeise für zwei, bitte."},{"it":"il primo","de":"der erste Gang (Pasta, Risotto, Suppe)","alt":["primo"],"note":"Kurz für il primo piatto.","ex":"Come primo prendo le tagliatelle.","exDe":"Als ersten Gang nehme ich die Tagliatelle."},{"it":"il secondo","de":"der Hauptgang (Fleisch oder Fisch)","alt":["secondo"],"note":"Kurz für il secondo piatto. Die Beilage bestellt man extra.","ex":"Come secondo vorrei la cotoletta.","exDe":"Als Hauptgang hätte ich gern das Schnitzel."},{"it":"il contorno","de":"die Beilage","alt":["contorno"],"note":"Zum Beispiel Salat, Gemüse oder Pommes.","ex":"Che contorni avete?","exDe":"Welche Beilagen haben Sie?"},{"it":"il dolce","de":"der Nachtisch","alt":["dolce"],"note":"Als Adjektiv heißt dolce süß.","ex":"Come dolce prendiamo il tiramisù.","exDe":"Als Nachtisch nehmen wir Tiramisu."},{"it":"Cosa prendete?","de":"Was nehmt ihr?","alt":["Che cosa prendete?"],"note":"Zu einer Person höflich: Cosa prende?","ex":"Ragazzi, cosa prendete?","exDe":"Leute, was nehmt ihr?"},{"it":"Da bere?","de":"Und zu trinken?","alt":["E da bere?"],"note":"So fragt der Kellner nach den Getränken.","ex":"E da bere? Un'acqua, grazie.","exDe":"Und zu trinken? Ein Wasser, danke."},{"it":"Buon appetito!","de":"Guten Appetit!","alt":[],"note":"Antwort: Grazie, altrettanto! (Danke, gleichfalls!)","ex":"Buon appetito a tutti!","exDe":"Guten Appetit euch allen!"},{"it":"Possiamo avere il conto?","de":"Können wir die Rechnung haben?","alt":[],"note":"In Italien bringt der Kellner die Rechnung erst, wenn du danach fragst.","ex":"Scusi, possiamo avere il conto?","exDe":"Entschuldigung, können wir die Rechnung haben?"},{"it":"consigliare","de":"empfehlen","alt":[],"note":"Sehr nützlich: Cosa mi consiglia? = Was empfehlen Sie mir?","ex":"Mi può consigliare un buon vino?","exDe":"Können Sie mir einen guten Wein empfehlen?"},{"it":"il piatto del giorno","de":"das Tagesgericht","alt":[],"note":"Steht oft auf einer Tafel und nicht auf der Speisekarte.","ex":"Qual è il piatto del giorno?","exDe":"Was ist das Tagesgericht?"},{"it":"le tagliatelle","de":"die Tagliatelle (Bandnudeln)","alt":["tagliatelle"],"note":"Typisch für Bologna. Immer im Plural.","ex":"Le tagliatelle della nonna sono buonissime.","exDe":"Omas Tagliatelle sind super lecker."},{"it":"il ragù","de":"die Fleischsoße (Ragù)","alt":["il ragu"],"note":"Das Original aus Bologna kocht stundenlang.","ex":"Le tagliatelle al ragù sono tipiche di Bologna.","exDe":"Tagliatelle mit Ragù sind typisch für Bologna."},{"it":"i tortellini","de":"die Tortellini (gefüllte Nudeln)","alt":["tortellini"],"note":"Klassisch in Bologna: tortellini in brodo, also in Brühe.","ex":"A Natale mangiamo i tortellini in brodo.","exDe":"Zu Weihnachten essen wir Tortellini in Brühe."},{"it":"le lasagne","de":"die Lasagne","alt":["la lasagna","lasagne"],"note":"In Bologna mit grünen Nudelplatten. Meist im Plural.","ex":"Le lasagne di Rosa sono famose.","exDe":"Rosas Lasagne ist berühmt."},{"it":"la cotoletta","de":"das Schnitzel (paniert)","alt":["cotoletta"],"note":"Cotoletta alla bolognese: mit Schinken und Parmesan überbacken.","ex":"Prendo la cotoletta con le patatine.","exDe":"Ich nehme das Schnitzel mit Pommes."},{"it":"il tiramisù","de":"das Tiramisu","alt":["il tiramisu","tiramisù"],"note":"Wörtlich: zieh mich hoch. Mit Kaffee und Mascarpone.","ex":"Il tiramisù qui è buonissimo!","exDe":"Das Tiramisu hier ist super lecker!"},{"it":"prenotare","de":"reservieren; buchen","alt":[],"note":"","ex":"Vorrei prenotare un tavolo per stasera.","exDe":"Ich möchte für heute Abend einen Tisch reservieren."},{"it":"libero","de":"frei","alt":[],"note":"Feminin: libera.","ex":"Scusi, è libero?","exDe":"Entschuldigung, ist hier frei?"},{"it":"occupato","de":"besetzt","alt":[],"note":"Feminin: occupata.","ex":"Purtroppo il tavolo è occupato.","exDe":"Leider ist der Tisch besetzt."},{"it":"portare","de":"bringen; tragen","alt":[],"note":"","ex":"Ci porta ancora un po' di pane?","exDe":"Bringen Sie uns noch etwas Brot?"},{"it":"assaggiare","de":"probieren (Essen)","alt":[],"note":"gg vor i klingt wie dsch: as sad dscha re.","ex":"Vuoi assaggiare le mie tagliatelle?","exDe":"Willst du meine Tagliatelle probieren?"},{"it":"scegliere","de":"wählen; aussuchen","alt":[],"note":"Unregelmäßig: io scelgo, tu scegli. gli klingt wie lj.","ex":"Scegli tu il vino?","exDe":"Suchst du den Wein aus?"},{"it":"vegetariano","de":"vegetarisch","alt":[],"note":"Feminin: vegetariana.","ex":"Avete un piatto vegetariano?","exDe":"Haben Sie ein vegetarisches Gericht?"},{"it":"buonissimo","de":"sehr lecker","alt":[],"note":"Von buono (gut). Feminin: buonissima.","ex":"Mmh, è buonissimo!","exDe":"Mmh, das ist super lecker!"},{"it":"pieno","de":"satt; voll","alt":[],"note":"Sono pieno = ich bin satt. Feminin: piena.","ex":"Basta, grazie, sono pieno!","exDe":"Genug, danke, ich bin satt!"},{"it":"il coperto","de":"das Gedeck (Brot und Service)","alt":["coperto"],"note":"Steht oft extra auf der Rechnung, pro Person.","ex":"Il coperto costa due euro.","exDe":"Das Gedeck kostet zwei Euro."},{"it":"la mancia","de":"das Trinkgeld","alt":["mancia"],"note":"In Italien kein Muss. Man rundet ein wenig auf.","ex":"Lasciamo una piccola mancia?","exDe":"Lassen wir ein kleines Trinkgeld da?"},{"it":"il vino della casa","de":"der Hauswein","alt":["vino della casa"],"note":"Oft gut und günstig, gern auch in der Karaffe.","ex":"Un quarto di vino della casa, per favore.","exDe":"Einen Viertelliter Hauswein, bitte."}],"grammar":{"title":"volere, potere, dovere","points":["Mit <b>volere</b> (wollen), <b>potere</b> (können, dürfen) und <b>dovere</b> (müssen) sagst du, was du willst, kannst oder musst. Danach folgt einfach ein Verb in der Grundform: <b>Posso pagare?</b> = Kann ich zahlen?","Alle drei sind unregelmäßig, deshalb lernst du die Formen am besten auswendig. Gut zu merken: Die noi Form endet immer auf <b>iamo</b>: vogliamo, possiamo, dobbiamo.","<b>Voglio</b> klingt zu Fremden schnell fordernd. Im Restaurant sagst du besser <b>vorrei</b> (ich hätte gern) oder fragst mit <b>Posso ...?</b> und <b>Può ...?</b> (Lei).","Die Verneinung <b>non</b> steht vor dem Modalverb: <b>Non posso bere vino.</b> <b>Volere</b> geht auch ohne zweites Verb: <b>Vuoi un caffè?</b>"],"table":{"head":["","volere","potere","dovere"],"rows":[["io","voglio","posso","devo"],["tu","vuoi","puoi","devi"],["lui / lei / Lei","vuole","può","deve"],["noi","vogliamo","possiamo","dobbiamo"],["voi","volete","potete","dovete"],["loro","vogliono","possono","devono"]]},"examples":[{"it":"Voglio assaggiare le tagliatelle.","de":"Ich will die Tagliatelle probieren."},{"it":"Possiamo avere il menù, per favore?","de":"Können wir bitte die Speisekarte haben?"},{"it":"Devo prenotare un tavolo?","de":"Muss ich einen Tisch reservieren?"},{"it":"Volete un dolce?","de":"Wollt ihr einen Nachtisch?"},{"it":"Scusi, può portare il conto?","de":"Entschuldigung, können Sie die Rechnung bringen?"},{"it":"Stasera non posso bere vino.","de":"Heute Abend kann ich keinen Wein trinken."}],"drills":[{"type":"choice","q":"Io ___ prenotare un tavolo per stasera.","de":"Ich will für heute Abend einen Tisch reservieren.","options":["vuole","voglio","vogliamo"],"answer":1,"why":"io Form von volere: voglio."},{"type":"type","q":"Scusi, ___ portare il menù?","de":"Entschuldigung, können Sie die Speisekarte bringen?","answer":"può","alt":["puo"],"why":"Lei Form von potere: può, mit Akzent."},{"type":"choice","q":"Noi ___ pagare anche il coperto.","de":"Wir müssen auch das Gedeck bezahlen.","options":["dobbiamo","dovete","devono"],"answer":0,"why":"noi Form von dovere: dobbiamo."},{"type":"type","q":"Tu ___ un dolce?","de":"Willst du einen Nachtisch?","answer":"vuoi","alt":[],"why":"tu Form von volere: vuoi."},{"type":"choice","q":"I bambini non ___ bere il vino.","de":"Die Kinder dürfen keinen Wein trinken.","options":["potete","può","possono"],"answer":2,"why":"loro Form von potere: possono."},{"type":"type","q":"Scusa, io ___ andare a casa.","de":"Entschuldige, ich muss nach Hause gehen.","answer":"devo","alt":[],"why":"io Form von dovere: devo."},{"type":"choice","q":"Voi ___ assaggiare il tiramisù?","de":"Wollt ihr das Tiramisu probieren?","options":["vogliamo","volete","vuoi"],"answer":1,"why":"voi Form von volere: volete."},{"type":"type","q":"Scusi, ___ avere il conto?","de":"Entschuldigung, können wir die Rechnung haben?","answer":"possiamo","alt":[],"why":"noi Form von potere: possiamo."}]},"dialog":{"title":"In trattoria","setting":"Lukas und Giulia essen abends in einer Trattoria in Bologna. Am Ende kommt der Kellner noch einmal an den Tisch.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Giulia","gender":"f"},"C":{"name":"Cameriere","gender":"m"}},"lines":[{"s":"C","it":"Buonasera! In due?","de":"Guten Abend! Zu zweit?"},{"s":"A","it":"Sì. C'è un tavolo libero?","de":"Ja. Haben Sie einen Tisch frei?"},{"s":"C","it":"Certo, prego. Ecco il menù.","de":"Klar, bitte schön. Hier die Karte."},{"s":"B","it":"Lukas, qui devi assaggiare i tortellini in brodo!","de":"Lukas, hier musst du die Tortellini in Brühe probieren!"},{"s":"A","it":"Va bene! E come secondo, cosa mi consiglia?","de":"Okay! Und als Hauptgang, was empfehlen Sie mir?"},{"s":"C","it":"La cotoletta alla bolognese. È la nostra specialità!","de":"Das Schnitzel nach Bologneser Art. Das ist unsere Spezialität!"},{"s":"A","it":"Perfetto! Allora tortellini e cotoletta.","de":"Perfekt! Dann Tortellini und Schnitzel."},{"s":"B","it":"Per me tagliatelle al ragù e un contorno di verdure.","de":"Für mich Tagliatelle mit Ragù und Gemüse als Beilage."},{"s":"C","it":"Benissimo. E da bere?","de":"Sehr gut. Und zu trinken?"},{"s":"B","it":"Vino della casa e un'acqua liscia, grazie.","de":"Hauswein und ein stilles Wasser, danke."},{"s":"C","it":"Allora, un dolce? Un caffè?","de":"So, noch einen Nachtisch? Einen Kaffee?"},{"s":"A","it":"No, grazie, sono pieno! Ci fa il conto?","de":"Nein danke, ich bin satt! Machen Sie uns die Rechnung?"}],"questions":[{"q":"Was soll Lukas unbedingt probieren?","options":["Tortellini in Brühe","Lasagne","Tiramisu"],"answer":0},{"q":"Was empfiehlt der Kellner als Hauptgang?","options":["Fisch","Gemüse","Das Schnitzel nach Bologneser Art"],"answer":2},{"q":"Warum möchte Lukas keinen Nachtisch?","options":["Er hat keine Zeit","Er ist satt","Er mag kein Tiramisu"],"answer":1}]},"sentences":[{"it":"Avete un tavolo libero per due?","de":"Haben Sie einen freien Tisch für zwei?"},{"it":"Vorrei prenotare un tavolo per stasera.","de":"Ich möchte für heute Abend einen Tisch reservieren."},{"it":"Mi può consigliare un buon vino rosso?","de":"Können Sie mir einen guten Rotwein empfehlen?"},{"it":"Per me le tagliatelle al ragù.","de":"Für mich die Tagliatelle mit Ragù."},{"it":"Non posso mangiare carne.","de":"Ich kann kein Fleisch essen."},{"it":"Dobbiamo pagare anche il coperto?","de":"Müssen wir auch das Gedeck bezahlen?"},{"it":"Possiamo avere il conto, per favore?","de":"Können wir bitte die Rechnung haben?"},{"it":"Il piatto del giorno è buonissimo.","de":"Das Tagesgericht ist super lecker."}],"spoken":[{"it":"In quanti siete?","book":"Quante persone siete?","de":"Wie viele seid ihr?","note":"Das fragt der Kellner gleich an der Tür. Die Antwort: Siamo in due, in tre, in quattro ...","ex":"In quanti siete? Siamo in quattro.","exDe":"Wie viele seid ihr? Wir sind zu viert.","alt":[]},{"it":"Liscia o gassata?","book":"Naturale o frizzante?","de":"Still oder mit Kohlensäure?","note":"So fragt der Kellner nach dem Wasser. Auf der Karte steht oft naturale und frizzante, gesagt wird meist liscia und gassata.","ex":"Acqua liscia o gassata? Liscia, grazie.","exDe":"Wasser still oder mit Kohlensäure? Still, danke.","alt":[]},{"it":"Per me lo stesso.","book":"Anche io prendo questo.","de":"Für mich das Gleiche.","note":"Wenn du dasselbe bestellst wie die Person vor dir. Passt im Restaurant und an der Bar.","ex":"Prendo le lasagne. E tu? Per me lo stesso!","exDe":"Ich nehme die Lasagne. Und du? Für mich das Gleiche!","alt":["Per me lo stesso"]},{"it":"Cosa c'è di buono?","book":"Che cosa mi consiglia?","de":"Was gibt's heute Gutes?","note":"Ganz typisch in der Trattoria. Oft zählt der Kellner dann auf, was es heute frisch gibt.","ex":"Buonasera! Cosa c'è di buono oggi?","exDe":"Guten Abend! Was gibt's heute Gutes?","alt":["Che c'è di buono?"]},{"it":"Ci fa il conto?","book":"Possiamo avere il conto?","de":"Machen Sie uns die Rechnung?","note":"So fragen Italiener im Restaurant am häufigsten. Bist du allein: Mi fa il conto?","ex":"Scusi, ci fa il conto, per favore?","exDe":"Entschuldigung, machen Sie uns bitte die Rechnung?","alt":["Mi fa il conto?"]},{"it":"Facciamo alla romana?","book":"Dividiamo il conto in parti uguali?","de":"Teilen wir die Rechnung gleichmäßig auf?","note":"Alla romana heißt: Alle zahlen den gleichen Anteil, egal was sie gegessen haben. Unter Freunden ganz normal.","ex":"Siamo in tre. Facciamo alla romana?","exDe":"Wir sind zu dritt. Teilen wir durch drei?","alt":[]},{"it":"Ci sta","book":"È una buona idea.","de":"passt; geht klar","note":"Locker, eher jung, aber überall verstanden: für etwas, das gerade gut passt. Nicht verwechseln mit Ci sto! = Ich bin dabei!","ex":"Un tiramisù alla fine? Ci sta!","exDe":"Zum Schluss ein Tiramisu? Geht immer!","alt":[]},{"it":"Qui si mangia bene.","book":"Il cibo qui è buono.","de":"Hier isst man gut.","note":"Das größte Lob für ein Lokal. Noch stärker: Qui si mangia benissimo!","ex":"Qui si mangia bene e non è caro.","exDe":"Hier isst man gut und es ist nicht teuer.","alt":["Qui si mangia benissimo."]}],"speak":[{"sit":"Du kommst mit Giulia in eine Trattoria. Frag nach einem freien Tisch für zwei.","answers":["Buonasera, avete un tavolo per due?","Buonasera, siamo in due. C'è un tavolo libero?"],"tip":""},{"sit":"Der Kellner fragt, was du nimmst. Bestell als ersten Gang Tagliatelle mit Ragù.","answers":["Per me le tagliatelle al ragù.","Come primo le tagliatelle al ragù, per favore.","Vorrei le tagliatelle al ragù."],"tip":"'Per me ...' ist die einfachste Art zu bestellen."},{"sit":"Du kannst dich nicht entscheiden. Frag den Kellner, was er dir empfiehlt.","answers":["Cosa mi consiglia?","Scusi, cosa ci consiglia?"],"tip":""},{"sit":"Der Kellner fragt nach dem Wasser. Du möchtest stilles Wasser.","answers":["Liscia, grazie.","Un'acqua liscia, per favore.","Naturale, grazie."],"tip":""},{"sit":"Der Kellner bietet dir einen Nachtisch an, aber du bist satt.","answers":["No, grazie, sono pieno.","Basta così, grazie. Sono pieno!"],"tip":"Als Frau sagst du: sono piena."},{"sit":"Ihr seid fertig und du möchtest die Rechnung.","answers":["Ci fa il conto, per favore?","Il conto, per favore.","Scusi, possiamo avere il conto?"],"tip":"Du bleibst einfach sitzen: Der Kellner bringt die Rechnung an den Tisch."}]},{"id":11,"title":"Mi piace!","titleDe":"Das gefällt mir!","goal":"Du kannst über Hobbys sprechen und sagen, was dir gefällt und was nicht.","intro":"Diese Woche geht es um alles, was Spaß macht: Sport, Musik, Filme und Freizeit. Mit dem Verb piacere sagst du, was dir gefällt und was nicht. So kannst du endlich richtig mitreden!","culture":"Fußball ist in Italien fast eine Religion. Jede Stadt hat ihre squadra und die tifosi bleiben ihr ein Leben lang treu. In Neapel verehrt man Diego Maradona bis heute wie einen Heiligen. Willst du mit Italienern ins Gespräch kommen, frag einfach: 'Per che squadra tifi?' (Für welche Mannschaft bist du?)","vocab":[{"it":"mi piace","de":"ich mag; mir gefällt (eine Sache)","alt":[],"note":"Mit Verb: Mi piace ballare = Ich tanze gern.","ex":"Mi piace molto Bologna.","exDe":"Bologna gefällt mir sehr."},{"it":"mi piacciono","de":"ich mag (mehrere Sachen)","alt":[],"note":"Für den Plural. Mit zwei c geschrieben.","ex":"Mi piacciono i film italiani.","exDe":"Ich mag italienische Filme."},{"it":"Ti piace?","de":"Magst du das?; Gefällt es dir?","alt":[],"note":"Höflich (Lei): Le piace?","ex":"Ti piace il jazz?","exDe":"Magst du Jazz?"},{"it":"anche a me","de":"mir auch","alt":[],"note":"Antwort auf mi piace.","ex":"Mi piace il mare. Anche a me!","exDe":"Ich mag das Meer. Ich auch!"},{"it":"neanche a me","de":"mir auch nicht","alt":["nemmeno a me","neppure a me"],"note":"Antwort auf non mi piace.","ex":"Non mi piace il golf. Neanche a me.","exDe":"Ich mag Golf nicht. Ich auch nicht."},{"it":"il tempo libero","de":"die Freizeit","alt":["tempo libero"],"note":"","ex":"Nel tempo libero leggo molto.","exDe":"In meiner Freizeit lese ich viel."},{"it":"Cosa fai nel tempo libero?","de":"Was machst du in deiner Freizeit?","alt":["Che cosa fai nel tempo libero?"],"note":"fai kommt von fare (machen). Das Verb lernst du in Lektion 12.","ex":"Davide, cosa fai nel tempo libero?","exDe":"Davide, was machst du in deiner Freizeit?"},{"it":"l'hobby","de":"das Hobby","alt":["hobby"],"note":"Maskulin. Plural unverändert: gli hobby. Das h ist stumm.","ex":"Il mio hobby è la musica.","exDe":"Mein Hobby ist die Musik."},{"it":"lo sport","de":"der Sport","alt":["sport"],"note":"Plural unverändert: gli sport.","ex":"Lo sport è importante per me.","exDe":"Sport ist mir wichtig."},{"it":"il calcio","de":"der Fußball (Sport)","alt":["calcio"],"note":"Der Ball selbst heißt il pallone.","ex":"A Davide piace molto il calcio.","exDe":"Davide mag Fußball sehr."},{"it":"la partita","de":"das Spiel (Match)","alt":["partita"],"note":"Für Sport und Karten. Ein Spiel zum Spielen heißt il gioco.","ex":"Stasera guardiamo la partita insieme?","exDe":"Schauen wir heute Abend zusammen das Spiel?"},{"it":"nuotare","de":"schwimmen","alt":[],"note":"","ex":"Nuoto in piscina il martedì.","exDe":"Dienstags schwimme ich im Schwimmbad."},{"it":"ballare","de":"tanzen","alt":[],"note":"","ex":"Giulia balla molto bene.","exDe":"Giulia tanzt sehr gut."},{"it":"cantare","de":"singen","alt":[],"note":"","ex":"Davide canta sempre sotto la doccia.","exDe":"Davide singt immer unter der Dusche."},{"it":"suonare","de":"spielen (Instrument)","alt":[],"note":"Für Spiele und Sport nimmst du giocare.","ex":"Davide suona la chitarra.","exDe":"Davide spielt Gitarre."},{"it":"la chitarra","de":"die Gitarre","alt":["chitarra"],"note":"ch klingt wie k: ki tar ra.","ex":"La chitarra di Davide è vecchia.","exDe":"Davides Gitarre ist alt."},{"it":"il pianoforte","de":"das Klavier","alt":["il piano"],"note":"Kurz auch: il piano.","ex":"Matteo suona il pianoforte.","exDe":"Matteo spielt Klavier."},{"it":"la squadra","de":"die Mannschaft","alt":["squadra"],"note":"","ex":"La mia squadra è il Bayern.","exDe":"Meine Mannschaft ist der FC Bayern."},{"it":"il tifoso","de":"der Fan (Sport)","alt":["tifoso"],"note":"Feminin: la tifosa. Plural: i tifosi.","ex":"Davide è un tifoso del Napoli.","exDe":"Davide ist ein Fan vom SSC Neapel."},{"it":"la palestra","de":"das Fitnessstudio","alt":["palestra"],"note":"","ex":"Vado in palestra due volte alla settimana.","exDe":"Ich gehe zweimal pro Woche ins Fitnessstudio."},{"it":"sciare","de":"Ski fahren","alt":[],"note":"sci klingt wie schi: schi a re.","ex":"In inverno sciamo in montagna.","exDe":"Im Winter fahren wir in den Bergen Ski."},{"it":"il videogioco","de":"das Videospiel","alt":["videogioco"],"note":"Plural: i videogiochi.","ex":"Matteo gioca ai videogiochi ogni sera.","exDe":"Matteo spielt jeden Abend Videospiele."},{"it":"la serie TV","de":"die Serie (im Fernsehen)","alt":["la serie tv","la serie"],"note":"Plural unverändert: le serie TV.","ex":"Che serie TV guardi?","exDe":"Welche Serie schaust du?"},{"it":"preferito","de":"Lieblings; bevorzugt","alt":[],"note":"Steht nach dem Nomen: il mio film preferito = mein Lieblingsfilm. Feminin: preferita.","ex":"Qual è il tuo sport preferito?","exDe":"Was ist dein Lieblingssport?"},{"it":"a me no","de":"mir nicht","alt":[],"note":"Wenn dir etwas nicht gefällt, das anderen gefällt.","ex":"A Giulia piace il jazz, a me no.","exDe":"Giulia mag Jazz, ich nicht."},{"it":"a me sì","de":"mir schon","alt":["a me si"],"note":"Wenn dir etwas gefällt, das anderen nicht gefällt.","ex":"Non ti piace il calcio? A me sì!","exDe":"Du magst keinen Fußball? Ich schon!"},{"it":"per niente","de":"überhaupt nicht","alt":[],"note":"Immer mit non: Non mi piace per niente.","ex":"Non mi piace per niente.","exDe":"Das mag ich überhaupt nicht."},{"it":"adorare","de":"total gern mögen; lieben","alt":[],"note":"Stärker als piacere.","ex":"Adoro la musica italiana.","exDe":"Ich liebe italienische Musik."},{"it":"odiare","de":"hassen","alt":[],"note":"Aussprache: o dja re. Io odio.","ex":"Odio correre!","exDe":"Ich hasse Joggen!"},{"it":"rilassante","de":"entspannend","alt":[],"note":"Gleiche Form für maskulin und feminin.","ex":"Leggere è molto rilassante.","exDe":"Lesen ist sehr entspannend."},{"it":"noioso","de":"langweilig","alt":[],"note":"Feminin: noiosa.","ex":"Il film è un po' noioso.","exDe":"Der Film ist ein bisschen langweilig."},{"it":"lo strumento","de":"das Instrument","alt":["strumento"],"note":"Lo, weil es mit s plus Konsonant beginnt. Plural: gli strumenti.","ex":"Suoni uno strumento?","exDe":"Spielst du ein Instrument?"},{"it":"il gruppo","de":"die Gruppe; die Band","alt":["gruppo"],"note":"","ex":"Davide suona in un gruppo rock.","exDe":"Davide spielt in einer Rockband."},{"it":"la passeggiata","de":"der Spaziergang","alt":["passeggiata"],"note":"fare una passeggiata = spazieren gehen.","ex":"Una passeggiata in centro? Volentieri!","exDe":"Ein Spaziergang in die Stadt? Gern!"},{"it":"la pallavolo","de":"der Volleyball","alt":["pallavolo"],"note":"Feminin, obwohl es auf o endet.","ex":"Giulia gioca a pallavolo il giovedì.","exDe":"Giulia spielt donnerstags Volleyball."},{"it":"le carte","de":"die Spielkarten","alt":["carte"],"note":"giocare a carte = Karten spielen.","ex":"La nonna gioca a carte con le amiche.","exDe":"Oma spielt mit ihren Freundinnen Karten."}],"grammar":{"title":"piacere: mi piace, mi piacciono","points":["Italienisch sagt nicht 'ich mag', sondern 'mir gefällt': <b>Mi piace la musica.</b> Wörtlich: Mir gefällt die Musik. Das Verb richtet sich also nach der Sache, die gefällt.","Eine Sache oder ein Verb: <b>piace</b>. Mehrere Sachen: <b>piacciono</b> (Mi piacciono i film italiani). Mit Verb übersetzt du am besten mit gern: <b>Mi piace ballare</b> = Ich tanze gern.","Wem gefällt es? <b>mi</b> (mir), <b>ti</b> (dir), <b>gli</b> (ihm), <b>le</b> (ihr), <b>Le</b> (Ihnen), <b>ci</b> (uns), <b>vi</b> (euch), <b>gli</b> (ihnen). Mit einem Namen nimmst du <b>a</b>: <b>A Davide piace</b> il calcio. Verneint: <b>Non mi piace.</b>","So reagierst du: Auf mi piace antwortest du <b>Anche a me!</b> (mir auch) oder <b>A me no.</b> Auf non mi piace antwortest du <b>Neanche a me!</b> (mir auch nicht) oder <b>A me sì.</b>"],"table":{"head":["wem?","eine Sache","mehrere Sachen"],"rows":[["mir","mi piace","mi piacciono"],["dir","ti piace","ti piacciono"],["ihm / ihr","gli piace / le piace","gli piacciono / le piacciono"],["Ihnen","Le piace","Le piacciono"],["uns","ci piace","ci piacciono"],["euch","vi piace","vi piacciono"],["ihnen","gli piace","gli piacciono"]]},"examples":[{"it":"Mi piace la musica italiana.","de":"Ich mag italienische Musik."},{"it":"Ti piacciono i film di Fellini?","de":"Magst du die Filme von Fellini?"},{"it":"A Davide piacciono la musica e il calcio.","de":"Davide mag Musik und Fußball."},{"it":"Non mi piace correre.","de":"Ich laufe nicht gern."},{"it":"Le piace Bologna, signora?","de":"Gefällt Ihnen Bologna?"},{"it":"Mi piace ballare. Anche a me!","de":"Ich tanze gern. Ich auch!"}],"drills":[{"type":"choice","q":"Mi ___ i film italiani.","de":"Ich mag italienische Filme.","options":["piace","piacciono","piacciamo"],"answer":1,"why":"i film ist Plural, also piacciono."},{"type":"type","q":"Ti ___ il calcio?","de":"Magst du Fußball?","answer":"piace","alt":[],"why":"il calcio ist eine einzelne Sache, also piace."},{"type":"choice","q":"A Giulia piace leggere? Sì, ___ piace molto.","de":"Liest Giulia gern? Ja, sie liest sehr gern.","options":["le","gli","ti"],"answer":0,"why":"Für eine Frau (ihr) nimmst du le."},{"type":"choice","q":"Matteo adora lo sport: ___ piace il tennis.","de":"Matteo liebt Sport: Er mag Tennis.","options":["le","mi","gli"],"answer":2,"why":"Für einen Mann (ihm) nimmst du gli."},{"type":"type","q":"A Davide ___ le canzoni napoletane.","de":"Davide mag neapolitanische Lieder.","answer":"piacciono","alt":[],"why":"le canzoni ist Plural, also piacciono."},{"type":"choice","q":"Mi piace il mare. ___","de":"Ich mag das Meer. Ich auch!","options":["Neanche a me!","A me sì!","Anche a me!"],"answer":2,"why":"Zustimmung zu mi piace: anche a me."},{"type":"choice","q":"Non mi piace il golf. ___ a me.","de":"Ich mag Golf nicht. Ich auch nicht.","options":["Anche","Neanche","Per"],"answer":1,"why":"Zustimmung zu non mi piace: neanche a me."},{"type":"type","q":"Ci ___ ballare la salsa.","de":"Wir tanzen gern Salsa.","answer":"piace","alt":[],"why":"Mit einem Verb im Infinitiv steht immer piace."}]},"dialog":{"title":"Il tempo libero","setting":"Lukas und Davide sitzen abends in einer Bar in Bologna und sprechen über ihre Freizeit.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Davide","gender":"m"}},"lines":[{"s":"B","it":"E tu, Lukas? Nel tempo libero che fai?","de":"Und du, Lukas? Was machst du so in deiner Freizeit?"},{"s":"A","it":"Mah, mi piace un sacco leggere. E nuoto spesso.","de":"Hm, ich lese wahnsinnig gern. Und ich schwimme oft."},{"s":"B","it":"Leggere? Non fa per me. Io adoro la musica!","de":"Lesen? Nichts für mich. Ich liebe Musik!"},{"s":"A","it":"Anche a me piace la musica. Suoni qualcosa?","de":"Musik mag ich auch. Spielst du was?"},{"s":"B","it":"Sì, la chitarra, in un gruppo. E canto, ma malissimo!","de":"Ja, Gitarre, in einer Band. Und ich singe, aber grottenschlecht!"},{"s":"A","it":"E lo sport? Ti piace?","de":"Und Sport? Magst du das?"},{"s":"B","it":"Il calcio mi piace da morire! Sono tifoso del Napoli.","de":"Fußball liebe ich über alles! Ich bin Fan vom SSC Neapel."},{"s":"A","it":"Io guardo sempre le partite del Bayern.","de":"Ich schaue immer die Spiele vom FC Bayern."},{"s":"B","it":"Il Bayern? Ma dai! Non mi piace per niente!","de":"Bayern? Ach nee! Die mag ich überhaupt nicht!"},{"s":"A","it":"Mercoledì c'è Napoli contro Bayern. Guardiamo la partita insieme?","de":"Am Mittwoch spielt Neapel gegen Bayern. Schauen wir das Spiel zusammen?"},{"s":"B","it":"Ci sta! E dopo andiamo a ballare, che ne dici?","de":"Klar! Und danach gehen wir tanzen, was meinst du?"},{"s":"A","it":"Ballare? Eh no, sono negato!","de":"Tanzen? Oh nein, da bin ich total unbegabt!"}],"questions":[{"q":"Was macht Lukas gern?","options":["Kochen und tanzen","Lesen und schwimmen","Singen und Gitarre spielen"],"answer":1},{"q":"Welches Instrument spielt Davide?","options":["Gitarre","Klavier","Schlagzeug"],"answer":0},{"q":"Was hält Davide vom FC Bayern?","options":["Er ist ein großer Fan","Er schaut jedes Spiel","Er mag ihn überhaupt nicht"],"answer":2}]},"sentences":[{"it":"Mi piace molto la musica italiana.","de":"Ich mag italienische Musik sehr."},{"it":"Ti piacciono i film italiani?","de":"Magst du italienische Filme?"},{"it":"Nel tempo libero vado in palestra.","de":"In meiner Freizeit gehe ich ins Fitnessstudio."},{"it":"Davide suona la chitarra e canta.","de":"Davide spielt Gitarre und singt."},{"it":"Non mi piace per niente il golf.","de":"Ich mag Golf überhaupt nicht."},{"it":"Qual è la tua squadra preferita?","de":"Was ist deine Lieblingsmannschaft?"},{"it":"A Giulia piace ballare, a me no.","de":"Giulia tanzt gern, ich nicht."},{"it":"Mi piace il calcio. Anche a me!","de":"Ich mag Fußball. Ich auch!"}],"spoken":[{"it":"Che ne dici?","book":"Cosa pensi?","de":"Was meinst du?; Was hältst du davon?","note":"Für Vorschläge: erst die Idee, dann che ne dici? Höflich (Lei): Che ne dice?","ex":"Stasera cinema, che ne dici?","exDe":"Heute Abend Kino, was meinst du?","alt":["Che ne pensi?"]},{"it":"Come mai?","book":"Perché?","de":"Wieso denn?","note":"Klingt neugieriger und freundlicher als perché. Überall üblich.","ex":"Non ti piace il calcio? Come mai?","exDe":"Du magst keinen Fußball? Wieso denn?","alt":[]},{"it":"da morire","book":"moltissimo","de":"wahnsinnig; über alles","note":"Verstärkt Gefühle: Mi piace da morire = Ich liebe es total. Locker, aber überall üblich.","ex":"Ballare? Mi piace da morire!","exDe":"Tanzen? Das liebe ich total!","alt":[]},{"it":"Non fa per me.","book":"Non mi piace.","de":"Das ist nichts für mich.","note":"Klingt freundlicher als non mi piace, weil es um dich geht und nicht um die Sache.","ex":"Il golf? Non fa per me.","exDe":"Golf? Das ist nichts für mich.","alt":["Non fa per me"]},{"it":"Sono negato","book":"Non sono bravo.","de":"Ich bin total unbegabt.","note":"Mit per: sono negato per lo sport. Als Frau: sono negata. Meist mit Humor gesagt.","ex":"Cantare? Sono negato!","exDe":"Singen? Da bin ich total unbegabt!","alt":["Sono negata"]},{"it":"Per chi tifi?","book":"Qual è la tua squadra preferita?","de":"Für wen bist du (im Fußball)?","note":"tifare heißt Fan sein. Unter Fußballfans die erste Frage. Vereine sind maskulin: il Napoli, il Bologna.","ex":"Per chi tifi? Per il Bologna!","exDe":"Für wen bist du? Für Bologna!","alt":["Per che squadra tifi?"]},{"it":"Non mi va","book":"Non voglio.","de":"Ich hab keine Lust.","note":"Das Gegenstück zu Ti va? Klingt viel freundlicher als non voglio.","ex":"Correre? Oggi non mi va.","exDe":"Joggen? Heute hab ich keine Lust.","alt":[]},{"it":"Forza Napoli!","book":"","de":"Auf geht's, Neapel!","note":"So feuert man jede Mannschaft an: Forza Bologna! Forza allein heißt auch: Los, komm schon!","ex":"Gol! Forza Napoli!","exDe":"Tor! Auf geht's, Neapel!","alt":[]}],"speak":[{"sit":"Davide fragt, was du in deiner Freizeit machst. Du liest gern und gehst ins Fitnessstudio.","answers":["Leggo e vado in palestra.","Mi piace leggere e vado in palestra.","Nel tempo libero leggo un sacco e vado in palestra."],"tip":""},{"sit":"Giulia sagt: 'Mi piace il jazz.' Du magst Jazz auch.","answers":["Anche a me!","Anche a me, un sacco!"],"tip":"Nicht 'anche io': Bei piacere heißt es 'anche a me'."},{"sit":"Ein Freund schlägt vor, Golf zu spielen. Sag freundlich, dass das nichts für dich ist.","answers":["Il golf? Non fa per me.","No, grazie, il golf non fa per me."],"tip":""},{"sit":"Schlag Davide vor, am Samstag zusammen das Spiel zu schauen. Frag, was er davon hält.","answers":["Sabato guardiamo la partita insieme, che ne dici?","Guardiamo la partita sabato? Che ne dici?","Ti va di guardare la partita sabato?"],"tip":""},{"sit":"Giulia will mit dir tanzen gehen, aber du kannst überhaupt nicht tanzen.","answers":["Ballare? Sono negato!","Mah, per il ballo sono negato."],"tip":"Als Frau: sono negata."},{"sit":"Davide aus Neapel sagt, dass er keine Pizza mag. Frag erstaunt, wieso.","answers":["Davvero? Come mai?","Come mai?","Ma come mai?"],"tip":""}]},{"id":12,"title":"In viaggio","titleDe":"Unterwegs","goal":"Du kannst Fahrkarten kaufen und dich mit Zug, Bus und Flugzeug zurechtfinden.","intro":"Jetzt geht es auf Reisen! Diese Woche lernst du alles für Bahnhof, Flughafen und Bus: Fahrkarten kaufen, nach dem Gleis fragen und Verspätungen verstehen. Dazu kommen vier wichtige unregelmäßige Verben.","culture":"Regionalzüge (regionali) sind in Italien günstig und fahren fast überall hin. Eine Papierfahrkarte für den Regionalzug musst du vor der Fahrt am Automaten auf dem Bahnsteig entwerten, sonst droht eine Strafe. In schnellen Zügen wie dem Frecciarossa hast du immer einen reservierten Platz. Und Achtung: Bei einem sciopero, also einem Streik, fallen oft viele Züge aus.","vocab":[{"it":"il treno","de":"der Zug","alt":["treno"],"note":"","ex":"Prendo il treno delle dieci.","exDe":"Ich nehme den Zug um zehn."},{"it":"il biglietto","de":"die Fahrkarte; das Ticket","alt":["biglietto"],"note":"Auch die Eintrittskarte: il biglietto del museo.","ex":"Un biglietto per Firenze, per favore.","exDe":"Eine Fahrkarte nach Florenz, bitte."},{"it":"il binario","de":"das Gleis","alt":["binario"],"note":"","ex":"Il treno parte dal binario 5.","exDe":"Der Zug fährt von Gleis 5 ab."},{"it":"la valigia","de":"der Koffer","alt":["valigia"],"note":"Plural: le valigie.","ex":"La mia valigia è molto pesante.","exDe":"Mein Koffer ist sehr schwer."},{"it":"fare","de":"machen; tun","alt":[],"note":"Unregelmäßig: io faccio, tu fai.","ex":"Cosa fai stasera?","exDe":"Was machst du heute Abend?"},{"it":"venire","de":"kommen","alt":[],"note":"Unregelmäßig: io vengo, tu vieni.","ex":"Vieni anche tu a Firenze?","exDe":"Kommst du auch mit nach Florenz?"},{"it":"uscire","de":"ausgehen; hinausgehen","alt":[],"note":"Unregelmäßig: io esco, tu esci.","ex":"Stasera esco con gli amici.","exDe":"Heute Abend gehe ich mit Freunden aus."},{"it":"sapere","de":"wissen; können (gelernt)","alt":[],"note":"Unregelmäßig: io so, tu sai.","ex":"Sai a che ora parte il treno?","exDe":"Weißt du, wann der Zug abfährt?"},{"it":"Non lo so.","de":"Ich weiß es nicht.","alt":["Non so."],"note":"lo heißt hier es. Mehr dazu in Lektion 13.","ex":"Scusi, non lo so.","exDe":"Entschuldigung, das weiß ich nicht."},{"it":"andata e ritorno","de":"hin und zurück","alt":[],"note":"l'andata = die Hinfahrt, il ritorno = die Rückfahrt.","ex":"Un biglietto andata e ritorno, per favore.","exDe":"Eine Fahrkarte hin und zurück, bitte."},{"it":"l'autobus","de":"der Bus","alt":["autobus","il bus"],"note":"Maskulin. Plural unverändert: gli autobus.","ex":"L'autobus per il centro è in ritardo.","exDe":"Der Bus ins Zentrum hat Verspätung."},{"it":"la biglietteria","de":"der Fahrkartenschalter","alt":["biglietteria"],"note":"Fahrkarten gibt es auch am Automaten.","ex":"La biglietteria è vicino al binario 1.","exDe":"Der Fahrkartenschalter ist in der Nähe von Gleis 1."},{"it":"il ritardo","de":"die Verspätung","alt":["ritardo"],"note":"in ritardo = verspätet; zu spät.","ex":"Il treno ha venti minuti di ritardo.","exDe":"Der Zug hat zwanzig Minuten Verspätung."},{"it":"in orario","de":"pünktlich","alt":[],"note":"","ex":"Oggi il treno è in orario.","exDe":"Heute ist der Zug pünktlich."},{"it":"la partenza","de":"die Abfahrt; der Abflug","alt":["partenza"],"note":"Auf der Anzeigetafel: partenze.","ex":"La partenza è alle otto.","exDe":"Die Abfahrt ist um acht."},{"it":"l'arrivo","de":"die Ankunft","alt":["arrivo"],"note":"Maskulin. Auf der Anzeigetafel: arrivi.","ex":"L'arrivo a Firenze è alle undici.","exDe":"Die Ankunft in Florenz ist um elf."},{"it":"il posto","de":"der Platz; der Sitzplatz","alt":["posto"],"note":"","ex":"Scusi, è libero il posto?","exDe":"Entschuldigung, ist der Platz frei?"},{"it":"il bagaglio","de":"das Gepäck","alt":["bagaglio"],"note":"Plural: i bagagli (die Gepäckstücke).","ex":"Il mio bagaglio è nel taxi.","exDe":"Mein Gepäck ist im Taxi."},{"it":"l'aeroporto","de":"der Flughafen","alt":["aeroporto"],"note":"Maskulin. Aussprache: a e ro por to.","ex":"Come vado all'aeroporto?","exDe":"Wie komme ich zum Flughafen?"},{"it":"l'aereo","de":"das Flugzeug","alt":["aereo"],"note":"Maskulin. Plural: gli aerei. in aereo = mit dem Flugzeug.","ex":"Lukas torna a Monaco in aereo.","exDe":"Lukas fliegt zurück nach München."},{"it":"il volo","de":"der Flug","alt":["volo"],"note":"","ex":"Il volo per Monaco è alle sei.","exDe":"Der Flug nach München ist um sechs."},{"it":"la fermata","de":"die Haltestelle","alt":["fermata"],"note":"","ex":"Dov'è la fermata dell'autobus?","exDe":"Wo ist die Bushaltestelle?"},{"it":"il taxi","de":"das Taxi","alt":["taxi"],"note":"Plural unverändert: i taxi.","ex":"Prendiamo un taxi per la stazione?","exDe":"Nehmen wir ein Taxi zum Bahnhof?"},{"it":"la macchina","de":"das Auto","alt":["macchina","l'auto"],"note":"Auch: l'auto (feminin). in macchina = mit dem Auto.","ex":"Matteo va a Milano in macchina.","exDe":"Matteo fährt mit dem Auto nach Mailand."},{"it":"il viaggio","de":"die Reise; die Fahrt","alt":["viaggio"],"note":"Plural: i viaggi. fare un viaggio = eine Reise machen.","ex":"Il viaggio dura due ore.","exDe":"Die Fahrt dauert zwei Stunden."},{"it":"Buon viaggio!","de":"Gute Reise!","alt":[],"note":"","ex":"Ciao Lukas, buon viaggio!","exDe":"Tschüss Lukas, gute Reise!"},{"it":"la metropolitana","de":"die Metro","alt":["la metro"],"note":"Kurz: la metro. Gibt es zum Beispiel in Milano und Roma.","ex":"A Milano prendo sempre la metropolitana.","exDe":"In Mailand nehme ich immer die Metro."},{"it":"la bicicletta","de":"das Fahrrad","alt":["la bici"],"note":"Kurz: la bici. in bicicletta = mit dem Rad.","ex":"A Bologna vado in bicicletta.","exDe":"In Bologna fahre ich Rad."},{"it":"cambiare","de":"umsteigen; wechseln","alt":[],"note":"cambiare treno = umsteigen.","ex":"Devo cambiare a Bologna?","exDe":"Muss ich in Bologna umsteigen?"},{"it":"convalidare","de":"entwerten (Fahrkarte)","alt":[],"note":"Bei Papierfahrkarten für Regionalzüge Pflicht.","ex":"Devo convalidare il biglietto?","exDe":"Muss ich die Fahrkarte entwerten?"},{"it":"diretto","de":"direkt; ohne Umsteigen","alt":[],"note":"Feminin: diretta.","ex":"C'è un treno diretto per Roma?","exDe":"Gibt es einen direkten Zug nach Rom?"},{"it":"la coincidenza","de":"der Anschluss (Zug)","alt":["coincidenza"],"note":"Aussprache: ko in tschi den tsa. Heißt auch der Zufall.","ex":"La coincidenza per Pisa è alle tre.","exDe":"Der Anschluss nach Pisa ist um drei."},{"it":"lo sciopero","de":"der Streik","alt":["sciopero"],"note":"Aussprache: scho pe ro. Lo, weil es mit s plus Konsonant beginnt.","ex":"Domani c'è uno sciopero dei treni.","exDe":"Morgen streikt die Bahn."},{"it":"Da quale binario parte?","de":"Von welchem Gleis fährt er ab?","alt":["Da che binario parte?"],"note":"","ex":"Scusi, da quale binario parte il treno?","exDe":"Entschuldigung, von welchem Gleis fährt der Zug ab?"},{"it":"Quanto dura il viaggio?","de":"Wie lange dauert die Fahrt?","alt":[],"note":"durare = dauern.","ex":"Quanto dura il viaggio fino a Firenze?","exDe":"Wie lange dauert die Fahrt bis Florenz?"},{"it":"solo andata","de":"nur Hinfahrt; einfach","alt":[],"note":"","ex":"Solo andata, per favore.","exDe":"Nur Hinfahrt, bitte."}],"grammar":{"title":"fare, venire, uscire, sapere","points":["Vier sehr wichtige Verben sind unregelmäßig: <b>fare</b> (machen), <b>venire</b> (kommen), <b>uscire</b> (ausgehen) und <b>sapere</b> (wissen). Du brauchst sie ständig, das Auswendiglernen lohnt sich also.","<b>fare</b> steckt in vielen festen Ausdrücken: <b>fare il biglietto</b> (eine Fahrkarte kaufen), <b>fare un viaggio</b> (eine Reise machen), <b>fare una passeggiata</b> (spazieren gehen).","Bei <b>uscire</b> wird aus dem u in vier Formen ein e: <b>esco, esci, esce, escono</b>. Nur noi und voi behalten das u: usciamo, uscite. Mit <b>venire</b> sagst du auch, woher du kommst: <b>Vengo da Monaco.</b>","<b>sapere</b>: so, sai, sa, sappiamo, sapete, sanno. Es heißt wissen, aber auch etwas können, das man gelernt hat: <b>So nuotare.</b> (Ich kann schwimmen.) Ganz wichtig: <b>Non lo so.</b> (Ich weiß es nicht.)"],"table":{"head":["","fare","venire","uscire"],"rows":[["io","faccio","vengo","esco"],["tu","fai","vieni","esci"],["lui / lei / Lei","fa","viene","esce"],["noi","facciamo","veniamo","usciamo"],["voi","fate","venite","uscite"],["loro","fanno","vengono","escono"]]},"examples":[{"it":"Faccio il biglietto per Firenze.","de":"Ich kaufe die Fahrkarte nach Florenz."},{"it":"Giulia viene alla stazione con me.","de":"Giulia kommt mit mir zum Bahnhof."},{"it":"Stasera usciamo con Davide.","de":"Heute Abend gehen wir mit Davide aus."},{"it":"Sa se il treno è in ritardo?","de":"Wissen Sie, ob der Zug Verspätung hat?"},{"it":"Da dove venite?","de":"Woher kommt ihr?"},{"it":"Che cosa fai domani?","de":"Was machst du morgen?"}],"drills":[{"type":"choice","q":"Io ___ il biglietto alla biglietteria.","de":"Ich kaufe die Fahrkarte am Schalter.","options":["fa","faccio","facciamo"],"answer":1,"why":"io Form von fare: faccio."},{"type":"type","q":"Tu ___ alla stazione con me?","de":"Kommst du mit mir zum Bahnhof?","answer":"vieni","alt":[],"why":"tu Form von venire: vieni."},{"type":"choice","q":"Scusi, ___ a che ora parte il treno?","de":"Entschuldigung, wissen Sie, wann der Zug abfährt?","options":["sa","so","sai"],"answer":0,"why":"Höflich (Lei) heißt die Form von sapere: sa."},{"type":"type","q":"Stasera io ___ con Giulia e Davide.","de":"Heute Abend gehe ich mit Giulia und Davide aus.","answer":"esco","alt":[],"why":"io Form von uscire: esco, mit e."},{"type":"choice","q":"Matteo e Giulia ___ da Bologna.","de":"Matteo und Giulia kommen aus Bologna.","options":["viene","veniamo","vengono"],"answer":2,"why":"loro Form von venire: vengono."},{"type":"type","q":"Noi ___ un viaggio in Italia.","de":"Wir machen eine Reise nach Italien.","answer":"facciamo","alt":[],"why":"noi Form von fare: facciamo."},{"type":"choice","q":"Voi ___ stasera?","de":"Geht ihr heute Abend aus?","options":["escono","uscite","usciamo"],"answer":1,"why":"voi Form von uscire: uscite, mit u."},{"type":"type","q":"Non lo ___, scusi.","de":"Ich weiß es nicht, Entschuldigung.","answer":"so","alt":[],"why":"io Form von sapere: so."}]},"dialog":{"title":"Alla biglietteria","setting":"Lukas steht im Hauptbahnhof von Bologna am Fahrkartenschalter. Er möchte nach Firenze fahren.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Impiegata","gender":"f"}},"lines":[{"s":"B","it":"Buongiorno! Mi dica.","de":"Guten Tag! Was kann ich für Sie tun?"},{"s":"A","it":"Buongiorno. Un biglietto per Firenze, per favore.","de":"Guten Tag. Eine Fahrkarte nach Florenz, bitte."},{"s":"B","it":"Solo andata o andata e ritorno?","de":"Nur hin oder hin und zurück?"},{"s":"A","it":"Solo andata. Sa se c'è un treno diretto?","de":"Nur hin. Wissen Sie, ob es einen direkten Zug gibt?"},{"s":"B","it":"Sì, c'è il regionale delle dieci e venti.","de":"Ja, um zehn Uhr zwanzig fährt ein Regionalzug."},{"s":"A","it":"Perfetto! E da che binario parte?","de":"Perfekt! Und von welchem Gleis fährt er?"},{"s":"B","it":"Ancora non lo so. C'è il tabellone, lì a sinistra.","de":"Das weiß ich noch nicht. Da links ist die Anzeigetafel."},{"s":"A","it":"Va bene. Ed è in orario?","de":"Gut. Und ist er pünktlich?"},{"s":"B","it":"Per ora sì, niente ritardi. Sono dieci euro.","de":"Im Moment ja, keine Verspätung. Das macht zehn Euro."},{"s":"A","it":"Ecco a Lei. Devo convalidare il biglietto?","de":"Bitte schön. Muss ich die Fahrkarte entwerten?"},{"s":"B","it":"Sì, prima di salire sul treno. Buon viaggio!","de":"Ja, bevor Sie einsteigen. Gute Reise!"},{"s":"A","it":"Grazie mille, arrivederci!","de":"Vielen Dank, auf Wiedersehen!"}],"questions":[{"q":"Wohin fährt Lukas?","options":["Nach Mailand","Nach Rom","Nach Florenz"],"answer":2},{"q":"Welche Fahrkarte kauft Lukas?","options":["Hin und zurück","Nur Hinfahrt","Erste Klasse"],"answer":1},{"q":"Was muss Lukas vor dem Einsteigen machen?","options":["Die Fahrkarte entwerten","Den Pass zeigen","Einen Platz reservieren"],"answer":0}]},"sentences":[{"it":"Vorrei un biglietto per Firenze, per favore.","de":"Ich hätte gern eine Fahrkarte nach Florenz, bitte."},{"it":"Da quale binario parte il treno?","de":"Von welchem Gleis fährt der Zug ab?"},{"it":"Il treno per Roma è in ritardo.","de":"Der Zug nach Rom hat Verspätung."},{"it":"Sa se c'è un autobus per l'aeroporto?","de":"Wissen Sie, ob es einen Bus zum Flughafen gibt?"},{"it":"Stasera esco con Giulia e Davide.","de":"Heute Abend gehe ich mit Giulia und Davide aus."},{"it":"Vieni anche tu alla stazione?","de":"Kommst du auch mit zum Bahnhof?"},{"it":"Facciamo un viaggio in Italia.","de":"Wir machen eine Reise nach Italien."},{"it":"Devo cambiare treno a Bologna?","de":"Muss ich in Bologna umsteigen?"}],"spoken":[{"it":"Quanto manca?","book":"Quanto tempo ancora?","de":"Wie lange noch?","note":"Die Frage, die Kinder auf jeder Autofahrt stellen. Auch: Quanto manca a Firenze?","ex":"Quanto manca? Dieci minuti.","exDe":"Wie lange noch? Zehn Minuten.","alt":[]},{"it":"Ce la facciamo?","book":"Arriviamo in tempo?","de":"Schaffen wir das?","note":"Von farcela = es schaffen. Die Antwort: Sì, ce la facciamo! Ich schaffe es nicht: Non ce la faccio.","ex":"Il treno parte alle dieci. Ce la facciamo?","exDe":"Der Zug fährt um zehn. Schaffen wir das?","alt":[]},{"it":"Scende alla prossima?","book":"Lei scende alla prossima fermata?","de":"Steigen Sie an der nächsten aus?","note":"Fragst du im vollen Bus, wenn du zur Tür willst. Unter Freunden: Scendi alla prossima?","ex":"Scusi, scende alla prossima? No, prego.","exDe":"Entschuldigung, steigen Sie an der nächsten aus? Nein, gehen Sie ruhig vor.","alt":[]},{"it":"Vengo anch'io!","book":"Anche io vengo.","de":"Ich komme auch mit!","note":"Ganz alltäglich. Berühmt ist das Lied 'Vengo anch'io? No, tu no!' von Enzo Jannacci.","ex":"Andate a Firenze? Vengo anch'io!","exDe":"Ihr fahrt nach Florenz? Ich komm mit!","alt":["Vengo anche io!"]},{"it":"Faccio un salto","book":"Vado un momento.","de":"Ich spring kurz hin.","note":"Für einen kurzen Abstecher: faccio un salto in farmacia, faccio un salto da Giulia.","ex":"Faccio un salto in biglietteria e torno.","exDe":"Ich spring kurz zum Schalter und bin gleich zurück.","alt":[]},{"it":"pieno zeppo","book":"molto pieno","de":"rappelvoll","note":"Locker und überall üblich, für Züge, Busse und Strände. Feminin: piena zeppa.","ex":"Il treno è pieno zeppo!","exDe":"Der Zug ist rappelvoll!","alt":["piena zeppa"]},{"it":"Ci siamo!","book":"Siamo arrivati.","de":"Wir sind da!","note":"Wenn ihr ankommt oder etwas endlich so weit ist. Die Antwort auf Quanto manca?","ex":"Ecco Firenze! Ci siamo!","exDe":"Da ist Florenz! Wir sind da!","alt":[]},{"it":"Si parte!","book":"Partiamo!","de":"Los geht's!","note":"Ruft man, wenn die Reise endlich losgeht, egal ob mit Zug, Auto oder Fahrrad.","ex":"Valigia pronta? Allora si parte!","exDe":"Koffer gepackt? Dann los geht's!","alt":[]}],"speak":[{"sit":"Du stehst am Schalter und brauchst eine Fahrkarte nach Florenz, nur Hinfahrt.","answers":["Un biglietto per Firenze, solo andata.","Solo andata per Firenze, per favore.","Vorrei un biglietto per Firenze, solo andata."],"tip":""},{"sit":"Frag am Bahnhof, von welchem Gleis der Zug nach Rom abfährt.","answers":["Da quale binario parte il treno per Roma?","Scusi, il treno per Roma da che binario parte?"],"tip":"'Da che binario' hörst du genauso oft wie 'da quale binario'."},{"sit":"Im vollen Zug siehst du einen leeren Platz. Frag, ob er frei ist.","answers":["Scusi, è libero?","Scusi, è libero il posto?"],"tip":""},{"sit":"Du sitzt im Bus und musst zur Tür. Frag die Frau vor dir, ob sie an der nächsten Haltestelle aussteigt.","answers":["Scusi, scende alla prossima?","Scende alla prossima fermata?"],"tip":""},{"sit":"Giulia und Davide fahren am Sonntag ans Meer. Sag, dass du mitkommst.","answers":["Vengo anch'io!","Vengo anch'io al mare!"],"tip":""},{"sit":"Du sitzt mit Giulia im Zug nach Florenz. Frag sie, wie lange es noch dauert.","answers":["Quanto manca?","Quanto manca a Firenze?"],"tip":"Wenn ihr ankommt, sagt Giulia bestimmt: 'Ci siamo!'"}]},{"id":13,"title":"In albergo","titleDe":"Im Hotel","goal":"Du kannst im Hotel einchecken, Fragen zum Zimmer stellen und Probleme melden.","intro":"Diese Woche checkst du in einem Hotel in Firenze ein. Du lernst, nach dem Zimmer zu fragen, Probleme zu melden und höflich um Hilfe zu bitten. Mit den Objektpronomen klingt dein Italienisch gleich viel natürlicher.","culture":"In vielen Orten Italiens zahlst du im Hotel eine tassa di soggiorno, eine Kurtaxe pro Person und Nacht. In Städten wie Firenze oder Roma sind das schnell einige Euro, die oft direkt im Hotel bezahlt werden. Beim Einchecken zeigst du immer einen Ausweis, das ist Pflicht. Eine camera matrimoniale hat ein großes Bett, eine camera doppia oft zwei einzelne Betten.","vocab":[{"it":"l'albergo","de":"das Hotel","alt":["albergo","l'hotel"],"note":"Maskulin. Plural: gli alberghi. Man sagt auch l'hotel.","ex":"L'albergo è vicino al Duomo.","exDe":"Das Hotel ist in der Nähe vom Dom."},{"it":"la camera","de":"das Zimmer (im Hotel)","alt":["camera"],"note":"Plural: le camere.","ex":"La camera è al terzo piano.","exDe":"Das Zimmer ist im dritten Stock."},{"it":"la chiave","de":"der Schlüssel","alt":["chiave"],"note":"Feminin! Plural: le chiavi.","ex":"Ecco la chiave della camera.","exDe":"Hier ist der Zimmerschlüssel."},{"it":"il letto","de":"das Bett","alt":["letto"],"note":"","ex":"Il letto è molto comodo.","exDe":"Das Bett ist sehr bequem."},{"it":"il bagno","de":"das Bad; die Toilette","alt":["bagno"],"note":"Dov'è il bagno? = Wo ist die Toilette?","ex":"La camera ha un bagno privato.","exDe":"Das Zimmer hat ein eigenes Bad."},{"it":"la prenotazione","de":"die Reservierung; die Buchung","alt":["prenotazione"],"note":"Von prenotare (reservieren).","ex":"La prenotazione è per tre notti.","exDe":"Die Reservierung ist für drei Nächte."},{"it":"Ho una prenotazione.","de":"Ich habe reserviert.","alt":["Ho prenotato."],"note":"Wörtlich: Ich habe eine Reservierung.","ex":"Buonasera, ho una prenotazione.","exDe":"Guten Abend, ich habe reserviert."},{"it":"la camera singola","de":"das Einzelzimmer","alt":["camera singola"],"note":"","ex":"Vorrei una camera singola per stanotte.","exDe":"Ich hätte gern ein Einzelzimmer für heute Nacht."},{"it":"la camera doppia","de":"das Doppelzimmer (oft zwei Betten)","alt":["camera doppia"],"note":"Oft mit zwei Betten. Mit einem großen Bett: matrimoniale.","ex":"Avete una camera doppia per due notti?","exDe":"Haben Sie ein Doppelzimmer für zwei Nächte?"},{"it":"la reception","de":"die Rezeption","alt":["reception"],"note":"Aussprache wie im Englischen.","ex":"La reception è aperta tutta la notte.","exDe":"Die Rezeption ist die ganze Nacht geöffnet."},{"it":"non funziona","de":"es funktioniert nicht; es geht nicht","alt":[],"note":"Von funzionare (funktionieren).","ex":"La doccia non funziona.","exDe":"Die Dusche funktioniert nicht."},{"it":"C'è un problema.","de":"Es gibt ein Problem.","alt":[],"note":"problema ist maskulin, obwohl es auf a endet: il problema, i problemi.","ex":"Scusi, c'è un problema in camera.","exDe":"Entschuldigung, es gibt ein Problem im Zimmer."},{"it":"l'aria condizionata","de":"die Klimaanlage","alt":["aria condizionata"],"note":"Feminin.","ex":"L'aria condizionata è troppo forte.","exDe":"Die Klimaanlage ist zu stark."},{"it":"il wifi","de":"das WLAN","alt":["wifi","il wi fi","il wi-fi"],"note":"Aussprache: uai fai.","ex":"Qual è la password del wifi?","exDe":"Wie lautet das Passwort fürs WLAN?"},{"it":"il passaporto","de":"der Reisepass","alt":["passaporto"],"note":"","ex":"Il passaporto, per favore.","exDe":"Ihren Pass, bitte."},{"it":"il documento","de":"der Ausweis","alt":["documento"],"note":"Kurz für documento d'identità.","ex":"Posso vedere un documento?","exDe":"Kann ich einen Ausweis sehen?"},{"it":"incluso","de":"inbegriffen; inklusive","alt":[],"note":"Feminin: inclusa.","ex":"La colazione è inclusa?","exDe":"Ist das Frühstück inbegriffen?"},{"it":"A che ora è la colazione?","de":"Wann gibt es Frühstück?","alt":["A che ora c'è la colazione?"],"note":"","ex":"Scusi, a che ora è la colazione domani?","exDe":"Entschuldigung, wann gibt es morgen Frühstück?"},{"it":"il piano","de":"das Stockwerk; die Etage","alt":["piano"],"note":"il piano terra = das Erdgeschoss. Piano heißt auch langsam: piano piano!","ex":"La mia camera è al primo piano.","exDe":"Mein Zimmer ist im ersten Stock."},{"it":"l'ascensore","de":"der Aufzug","alt":["ascensore"],"note":"Maskulin.","ex":"L'ascensore non funziona, purtroppo.","exDe":"Der Aufzug funktioniert leider nicht."},{"it":"la doccia","de":"die Dusche","alt":["doccia"],"note":"cc vor i klingt wie tsch: dot tscha.","ex":"La doccia è molto piccola.","exDe":"Die Dusche ist sehr klein."},{"it":"l'asciugamano","de":"das Handtuch","alt":["asciugamano"],"note":"Maskulin. Plural: gli asciugamani.","ex":"Posso avere un altro asciugamano?","exDe":"Kann ich noch ein Handtuch haben?"},{"it":"il cuscino","de":"das Kopfkissen","alt":["cuscino"],"note":"","ex":"Il cuscino è troppo duro.","exDe":"Das Kopfkissen ist zu hart."},{"it":"la camera matrimoniale","de":"das Zimmer mit Doppelbett","alt":["camera matrimoniale"],"note":"Mit einem großen Bett für zwei.","ex":"Avete ancora una camera matrimoniale?","exDe":"Haben Sie noch ein Zimmer mit Doppelbett?"},{"it":"rotto","de":"kaputt","alt":[],"note":"Feminin: rotta.","ex":"La lampada è rotta.","exDe":"Die Lampe ist kaputt."},{"it":"sporco","de":"schmutzig","alt":[],"note":"Feminin: sporca. Plural: sporchi, sporche.","ex":"Gli asciugamani sono sporchi.","exDe":"Die Handtücher sind schmutzig."},{"it":"pulito","de":"sauber","alt":[],"note":"Feminin: pulita.","ex":"La camera è pulita e grande.","exDe":"Das Zimmer ist sauber und groß."},{"it":"rumoroso","de":"laut (voller Lärm)","alt":[],"note":"Feminin: rumorosa.","ex":"La camera è troppo rumorosa.","exDe":"Das Zimmer ist zu laut."},{"it":"silenzioso","de":"ruhig; leise","alt":[],"note":"Feminin: silenziosa.","ex":"Avete una camera silenziosa?","exDe":"Haben Sie ein ruhiges Zimmer?"},{"it":"controllare","de":"prüfen; nachsehen","alt":[],"note":"","ex":"Lo controllo subito.","exDe":"Ich sehe sofort nach."},{"it":"aiutare","de":"helfen","alt":[],"note":"Mit direktem Objekt: La posso aiutare? = Kann ich Ihnen helfen?","ex":"Mi può aiutare, per favore?","exDe":"Können Sie mir bitte helfen?"},{"it":"lasciare","de":"lassen; dalassen","alt":[],"note":"","ex":"Posso lasciare qui la valigia?","exDe":"Kann ich den Koffer hier lassen?"},{"it":"chiamare","de":"rufen; anrufen","alt":[],"note":"","ex":"Ti chiamo stasera, Giulia!","exDe":"Ich rufe dich heute Abend an, Giulia!"},{"it":"subito","de":"sofort","alt":[],"note":"","ex":"Vengo subito!","exDe":"Ich komme sofort!"},{"it":"Mi dispiace.","de":"Es tut mir leid.","alt":[],"note":"","ex":"Mi dispiace, l'albergo è pieno.","exDe":"Es tut mir leid, das Hotel ist voll."},{"it":"Nessun problema!","de":"Kein Problem!","alt":["Non c'è problema!"],"note":"","ex":"Grazie mille! Nessun problema!","exDe":"Vielen Dank! Kein Problem!"}],"grammar":{"title":"Objektpronomen: lo, la, li, le","points":["Damit du ein Nomen nicht wiederholen musst, ersetzt du es durch ein kurzes Pronomen: <b>Prendo la chiave.</b> wird zu <b>La prendo.</b> Es richtet sich nach dem italienischen Wort: la chiave ist feminin, also <b>la</b>, auch wenn es im Deutschen 'den' heißt.","Das Pronomen steht <b>vor dem Verb</b>, bei Verneinung zwischen non und Verb: <b>Non lo so.</b> Mit Modalverb darf es auch hinten am Infinitiv hängen, der dann sein e verliert: <b>La posso aiutare?</b> = <b>Posso aiutarla?</b>","<b>lo</b> steht für Maskulines, <b>la</b> für Feminines, im Plural <b>li</b> und <b>le</b>. Für gemischte Gruppen nimmst du <b>li</b>. Vor einem Vokal werden lo und la oft zu <b>l'</b>: <b>L'aspetto qui.</b>","Mit großem <b>La</b> sprichst du jemanden höflich an: <b>La chiamo domani.</b> (Ich rufe Sie morgen an.) Achtung: <b>aiutare</b> (helfen) und <b>aspettare</b> (warten auf) haben im Italienischen ein direktes Objekt."],"table":{"head":["Deutsch","Pronomen","Beispiel"],"rows":[["mich","mi","Mi chiami stasera?"],["dich","ti","Ti aspetto qui."],["ihn, es","lo","Lo prendo."],["sie, es; Sie","la / La","La chiamo domani."],["uns","ci","Ci aiuta?"],["euch","vi","Vi chiamo stasera."],["sie (Plural, m)","li","Li porto subito."],["sie (Plural, f)","le","Le lascio qui."]]},"examples":[{"it":"La chiave? La prendo io.","de":"Der Schlüssel? Den nehme ich."},{"it":"Il wifi non funziona. Lo controllo subito.","de":"Das WLAN funktioniert nicht. Ich prüfe es sofort."},{"it":"Le valigie? Le lascio alla reception.","de":"Die Koffer? Die lasse ich an der Rezeption."},{"it":"Signora, La posso aiutare?","de":"Kann ich Ihnen helfen?"},{"it":"Giulia, ti chiamo stasera!","de":"Giulia, ich rufe dich heute Abend an!"},{"it":"Gli asciugamani? Li porto subito.","de":"Die Handtücher? Die bringe ich sofort."}],"drills":[{"type":"choice","q":"La chiave? ___ prendo io.","de":"Der Schlüssel? Den nehme ich.","options":["Lo","La","Li"],"answer":1,"why":"la chiave ist feminin, also la."},{"type":"type","q":"Il wifi non funziona? Adesso ___ controllo.","de":"Das WLAN funktioniert nicht? Ich prüfe es jetzt.","answer":"lo","alt":[],"why":"il wifi ist maskulin Singular, also lo."},{"type":"choice","q":"Gli asciugamani? ___ porto subito in camera.","de":"Die Handtücher? Die bringe ich sofort aufs Zimmer.","options":["Le","Lo","Li"],"answer":2,"why":"gli asciugamani ist maskulin Plural, also li."},{"type":"type","q":"Le valigie? Io ___ lascio qui.","de":"Die Koffer? Die lasse ich hier.","answer":"le","alt":[],"why":"le valigie ist feminin Plural, also le."},{"type":"choice","q":"Giulia, ___ chiamo stasera!","de":"Giulia, ich rufe dich heute Abend an!","options":["ti","mi","ci"],"answer":0,"why":"dich heißt ti."},{"type":"type","q":"Signora, ___ posso aiutare?","de":"Kann ich Ihnen helfen?","answer":"La","alt":["la"],"why":"Höflich (Lei) heißt das Pronomen La. aiutare hat ein direktes Objekt."},{"type":"choice","q":"Lukas e Giulia? ___ aspetto alla stazione.","de":"Lukas und Giulia? Ich warte am Bahnhof auf sie.","options":["Le","Li","Lo"],"answer":1,"why":"Für eine gemischte Gruppe nimmst du li."},{"type":"type","q":"Davide, mi senti? Sì, ___ sento bene!","de":"Davide, hörst du mich? Ja, ich höre dich gut!","answer":"ti","alt":[],"why":"dich heißt ti."}]},"dialog":{"title":"Arrivo in albergo","setting":"Lukas kommt abends in einem kleinen Hotel in Firenze an. Später ruft er aus seinem Zimmer die Rezeption an.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Receptionist","gender":"f"}},"lines":[{"s":"B","it":"Buonasera, benvenuto! Ha una prenotazione?","de":"Guten Abend, willkommen! Haben Sie reserviert?"},{"s":"A","it":"Sì, una singola per tre notti.","de":"Ja, ein Einzelzimmer für drei Nächte."},{"s":"B","it":"Perfetto. Un documento, per cortesia.","de":"Perfekt. Ihren Ausweis, bitte."},{"s":"A","it":"Ecco il passaporto. La colazione è inclusa, no?","de":"Hier, mein Pass. Frühstück ist inklusive, oder?"},{"s":"B","it":"Sì, certo. Ecco la chiave: la 24, al secondo piano.","de":"Ja, klar. Hier ist der Schlüssel: die 24, im zweiten Stock."},{"s":"A","it":"Grazie! E c'è il wifi?","de":"Danke! Und gibt's WLAN?"},{"s":"B","it":"Sì, è gratis. La password è in camera.","de":"Ja, kostenlos. Das Passwort liegt im Zimmer."},{"s":"A","it":"Pronto, reception? Scusi il disturbo, c'è un problema in camera.","de":"Hallo, Rezeption? Entschuldigen Sie die Störung, in meinem Zimmer stimmt was nicht."},{"s":"B","it":"Mi dica, che cosa non va?","de":"Ja bitte, was ist denn los?"},{"s":"A","it":"L'aria condizionata è rotta. E ho caldissimo!","de":"Die Klimaanlage ist kaputt. Und mir ist total heiß!"},{"s":"B","it":"Mi dispiace! Un tecnico la controlla subito. Intanto vuole un ventilatore?","de":"Oh, das tut mir leid! Ein Techniker schaut sie sich sofort an. Möchten Sie bis dahin einen Ventilator?"},{"s":"A","it":"Sì, gentilissima! Vengo io a prenderlo.","de":"Ja, sehr freundlich! Ich hol ihn mir selbst."}],"questions":[{"q":"Wie viele Nächte bleibt Lukas im Hotel?","options":["Zwei","Drei","Vier"],"answer":1},{"q":"Was funktioniert im Zimmer nicht?","options":["Das WLAN","Die Dusche","Die Klimaanlage"],"answer":2},{"q":"Was holt Lukas an der Rezeption?","options":["Einen Ventilator","Ein Handtuch","Einen zweiten Schlüssel"],"answer":0}]},"sentences":[{"it":"Ho una prenotazione per due notti.","de":"Ich habe eine Reservierung für zwei Nächte."},{"it":"La colazione è inclusa nel prezzo?","de":"Ist das Frühstück im Preis inbegriffen?"},{"it":"L'aria condizionata in camera non funziona.","de":"Die Klimaanlage im Zimmer funktioniert nicht."},{"it":"Scusi, mi può aiutare con la valigia?","de":"Entschuldigung, können Sie mir mit dem Koffer helfen?"},{"it":"La chiave? La lascio alla reception.","de":"Der Schlüssel? Den lasse ich an der Rezeption."},{"it":"Vorrei una camera doppia con bagno.","de":"Ich hätte gern ein Doppelzimmer mit Bad."},{"it":"Gli asciugamani sono sporchi. Li potete cambiare?","de":"Die Handtücher sind schmutzig. Können Sie sie wechseln?"},{"it":"Giulia, ti chiamo stasera dall'albergo.","de":"Giulia, ich rufe dich heute Abend aus dem Hotel an."}],"spoken":[{"it":"Fa niente.","book":"Non importa.","de":"Macht nichts.","note":"Die übliche Antwort, wenn sich jemand bei dir entschuldigt. Passt überall, auch im Hotel.","ex":"Mi dispiace, la camera non è ancora pronta. Fa niente!","exDe":"Tut mir leid, das Zimmer ist noch nicht fertig. Macht nichts!","alt":["Non fa niente."]},{"it":"Meno male che ...","book":"Per fortuna ...","de":"Zum Glück ...","note":"Zeigt Erleichterung und ist sehr häufig. Oft hörst du es auch allein als Ausruf: Meno male!","ex":"Meno male che c'è l'ascensore!","exDe":"Zum Glück gibt's einen Aufzug!","alt":["Meno male!"]},{"it":"Non va.","book":"Non funziona.","de":"Geht nicht! (bei Geräten)","note":"Im Alltag sagt man bei kaputten Sachen oft einfach non va statt non funziona. Non va più = geht nicht mehr.","ex":"Scusi, il wifi in camera non va.","exDe":"Entschuldigung, das WLAN im Zimmer geht nicht.","alt":[]},{"it":"Ci penso io.","book":"Lo faccio io.","de":"Ich kümmere mich darum.","note":"Hörst du oft, wenn jemand ein Problem für dich löst. Im Hotel genauso wie unter Freunden.","ex":"La valigia? Ci penso io!","exDe":"Der Koffer? Darum kümmere ich mich!","alt":[]},{"it":"Mi può dare una mano?","book":"Mi può aiutare?","de":"Können Sie mir kurz helfen?","note":"Wörtlich: Können Sie mir eine Hand geben? Zu Freunden sagst du: Mi dai una mano?","ex":"Scusi, mi può dare una mano con la valigia?","exDe":"Entschuldigung, können Sie mir mit dem Koffer helfen?","alt":["Mi dà una mano?","Mi dai una mano?"]},{"it":"Scusi il disturbo.","book":"Mi scusi per il disturbo.","de":"Entschuldigen Sie die Störung.","note":"Höflich, wenn du anrufst oder jemanden unterbrichst. Zu Freunden: Scusa il disturbo.","ex":"Pronto, reception? Scusi il disturbo.","exDe":"Hallo, Rezeption? Entschuldigen Sie die Störung.","alt":["Scusi se disturbo."]},{"it":"Ecco fatto!","book":"","de":"So, fertig!","note":"Sagt man, wenn etwas erledigt oder repariert ist. Sehr häufig, überall.","ex":"Ecco fatto, adesso l'aria condizionata funziona!","exDe":"So, fertig, jetzt geht die Klimaanlage!","alt":[]},{"it":"Gentilissimo!","book":"Lei è molto gentile.","de":"Sehr freundlich von Ihnen!","note":"Typische Reaktion, wenn dir jemand hilft, vor allem im Hotel oder im Laden. Zu einer Frau: Gentilissima!","ex":"Ecco un altro cuscino. Gentilissima, grazie!","exDe":"Hier ist noch ein Kissen. Sehr freundlich, danke!","alt":["Gentilissima!"]}],"speak":[{"sit":"Du kommst abends an der Rezeption an. Sag, dass du ein Zimmer für zwei Nächte reserviert hast.","answers":["Buonasera, ho una prenotazione per due notti.","Salve, ho prenotato una camera per due notti."],"tip":"Mit 'a nome' sagst du, auf welchen Namen die Reservierung läuft: a nome Müller."},{"sit":"In deinem Zimmer geht die Dusche nicht. Ruf an der Rezeption an und sag Bescheid.","answers":["Pronto? Scusi, la doccia non funziona.","Scusi il disturbo, la doccia in camera non va.","Buonasera, c'è un problema: la doccia non funziona."],"tip":"Am Telefon meldest du dich auf Italienisch mit 'Pronto?'."},{"sit":"Die Rezeptionistin entschuldigt sich, weil dein Zimmer noch nicht fertig ist. Sag ihr freundlich, dass das nichts macht.","answers":["Fa niente!","Non fa niente, non c'è problema.","Nessun problema, aspetto qui."],"tip":""},{"sit":"Du möchtest wissen, ob das Frühstück inklusive ist und wann es Frühstück gibt.","answers":["La colazione è inclusa? A che ora è?","Scusi, la colazione è inclusa? E a che ora c'è?"],"tip":""},{"sit":"In deinem Bad liegt nur ein Handtuch. Bitte an der Rezeption um ein zweites.","answers":["Scusi, posso avere un altro asciugamano?","Mi può portare un altro asciugamano, per favore?"],"tip":"'Un altro' heißt hier 'noch ein'."},{"sit":"Ein Mitarbeiter will deinen Koffer aufs Zimmer bringen. Sag ihm, dass du ihn selbst trägst.","answers":["Grazie, la porto io.","No, grazie, ci penso io.","Grazie, non si preoccupi, la porto io."],"tip":"la valigia ist feminin, also: la porto io."}]},{"id":14,"title":"Che tempo fa?","titleDe":"Wetter und Jahreszeiten","goal":"Du kannst über das Wetter sprechen, Monate und Jahreszeiten nennen und sagen, was gerade passiert.","intro":"Über das Wetter reden ist überall der perfekte Gesprächsanfang. Diese Woche lernst du die Monate, die Jahreszeiten und alles, was du für den Wetterbericht brauchst. Außerdem kannst du bald sagen, was du gerade machst.","culture":"Im August machen viele Italiener Urlaub, vor allem rund um Ferragosto am 15. August. Dann sind die Strände voll und in Städten wie Bologna haben viele Bars und Läden geschlossen. Im Winter liegt über der Poebene rund um Bologna dagegen oft dichter Nebel, die berühmte 'nebbia'.","vocab":[{"it":"Che tempo fa?","de":"Wie ist das Wetter?","alt":[],"note":"Wörtlich: Welches Wetter macht es?","ex":"Che tempo fa a Bologna?","exDe":"Wie ist das Wetter in Bologna?"},{"it":"il tempo","de":"das Wetter; die Zeit","alt":[],"note":"Bedeutet auch die Zeit: Non ho tempo = ich habe keine Zeit.","ex":"Oggi il tempo è bellissimo.","exDe":"Heute ist das Wetter wunderschön."},{"it":"fa bel tempo","de":"das Wetter ist schön","alt":[],"note":"Vor tempo wird bello zu bel.","ex":"Domani fa bel tempo?","exDe":"Wird morgen schönes Wetter?"},{"it":"fa brutto tempo","de":"das Wetter ist schlecht","alt":["fa cattivo tempo"],"note":"Auch: fa cattivo tempo.","ex":"Oggi fa brutto tempo.","exDe":"Heute ist das Wetter schlecht."},{"it":"fa caldo","de":"es ist warm; es ist heiß","alt":[],"note":"Für eine Person sagst du ho caldo = mir ist warm.","ex":"Oggi fa caldo, andiamo al mare?","exDe":"Heute ist es heiß, fahren wir ans Meer?"},{"it":"fa freddo","de":"es ist kalt","alt":[],"note":"Für eine Person sagst du ho freddo = mir ist kalt.","ex":"Fa freddo, sto a casa.","exDe":"Es ist kalt, ich bleibe zu Hause."},{"it":"il sole","de":"die Sonne","alt":[],"note":"Maskulin! C'è il sole = die Sonne scheint.","ex":"Oggi c'è il sole.","exDe":"Heute scheint die Sonne."},{"it":"piovere","de":"regnen","alt":[],"note":"Ohne Subjekt: piove = es regnet.","ex":"A Londra piove spesso.","exDe":"In London regnet es oft."},{"it":"la pioggia","de":"der Regen","alt":[],"note":"","ex":"Non mi piace la pioggia.","exDe":"Ich mag den Regen nicht."},{"it":"l'ombrello","de":"der Regenschirm","alt":["ombrello"],"note":"Maskulin. Plural: gli ombrelli.","ex":"Piove! Hai un ombrello?","exDe":"Es regnet! Hast du einen Regenschirm?"},{"it":"il vento","de":"der Wind","alt":[],"note":"C'è vento = es ist windig.","ex":"Al mare c'è molto vento.","exDe":"Am Meer ist es sehr windig."},{"it":"nuvoloso","de":"bewölkt","alt":[],"note":"feminin: nuvolosa. Von la nuvola = die Wolke.","ex":"Oggi è nuvoloso, ma non piove.","exDe":"Heute ist es bewölkt, aber es regnet nicht."},{"it":"gennaio","de":"der Januar","alt":[],"note":"Monate schreibt man klein und meist ohne Artikel. Datum: il primo gennaio, il due gennaio.","ex":"Il primo gennaio è festa.","exDe":"Am 1. Januar ist Feiertag."},{"it":"febbraio","de":"der Februar","alt":[],"note":"","ex":"A febbraio fa ancora freddo.","exDe":"Im Februar ist es noch kalt."},{"it":"marzo","de":"der März","alt":[],"note":"","ex":"A marzo arriva la primavera.","exDe":"Im März kommt der Frühling."},{"it":"aprile","de":"der April","alt":[],"note":"Vor a wird a oft zu ad: ad aprile.","ex":"Ad aprile piove spesso.","exDe":"Im April regnet es oft."},{"it":"maggio","de":"der Mai","alt":[],"note":"","ex":"Il mio compleanno è a maggio.","exDe":"Mein Geburtstag ist im Mai."},{"it":"giugno","de":"der Juni","alt":[],"note":"","ex":"A giugno finisce la scuola.","exDe":"Im Juni ist die Schule zu Ende."},{"it":"luglio","de":"der Juli","alt":[],"note":"","ex":"A luglio fa molto caldo.","exDe":"Im Juli ist es sehr heiß."},{"it":"agosto","de":"der August","alt":[],"note":"Am 15. August ist Ferragosto, ein großer Feiertag.","ex":"Ad agosto sono tutti in vacanza.","exDe":"Im August sind alle im Urlaub."},{"it":"settembre","de":"der September","alt":[],"note":"","ex":"A settembre torno a Monaco.","exDe":"Im September fahre ich zurück nach München."},{"it":"ottobre","de":"der Oktober","alt":[],"note":"","ex":"A ottobre comincia l'università.","exDe":"Im Oktober fängt die Uni an."},{"it":"novembre","de":"der November","alt":[],"note":"","ex":"A novembre c'è spesso la nebbia.","exDe":"Im November gibt es oft Nebel."},{"it":"dicembre","de":"der Dezember","alt":[],"note":"","ex":"A dicembre c'è Natale.","exDe":"Im Dezember ist Weihnachten."},{"it":"la primavera","de":"der Frühling","alt":[],"note":"In primavera = im Frühling.","ex":"In primavera Bologna è bellissima.","exDe":"Im Frühling ist Bologna wunderschön."},{"it":"l'estate","de":"der Sommer","alt":["estate"],"note":"Feminin! In estate oder d'estate = im Sommer.","ex":"L'estate a Bologna è caldissima.","exDe":"Der Sommer in Bologna ist total heiß."},{"it":"l'autunno","de":"der Herbst","alt":["autunno"],"note":"Maskulin. In autunno = im Herbst.","ex":"In autunno i colori sono bellissimi.","exDe":"Im Herbst sind die Farben wunderschön."},{"it":"l'inverno","de":"der Winter","alt":["inverno"],"note":"Maskulin. In inverno oder d'inverno = im Winter.","ex":"In inverno vado a sciare.","exDe":"Im Winter gehe ich Ski fahren."},{"it":"la stagione","de":"die Jahreszeit; die Saison","alt":[],"note":"Plural: le stagioni.","ex":"Qual è la tua stagione preferita?","exDe":"Was ist deine Lieblingsjahreszeit?"},{"it":"nevicare","de":"schneien","alt":[],"note":"Ohne Subjekt: nevica = es schneit.","ex":"In montagna sta nevicando.","exDe":"In den Bergen schneit es gerade."},{"it":"la neve","de":"der Schnee","alt":[],"note":"","ex":"Ai bambini piace la neve.","exDe":"Kinder mögen Schnee."},{"it":"il temporale","de":"das Gewitter","alt":[],"note":"","ex":"Attenzione, arriva un temporale!","exDe":"Achtung, ein Gewitter kommt!"},{"it":"la nebbia","de":"der Nebel","alt":[],"note":"Typisch für die Poebene im Winter.","ex":"C'è nebbia e non vedo niente.","exDe":"Es ist neblig und ich sehe nichts."},{"it":"fa fresco","de":"es ist kühl","alt":[],"note":"Angenehm kühl, nicht richtig kalt.","ex":"La sera fa fresco.","exDe":"Abends ist es kühl."},{"it":"il grado","de":"der Grad (Temperatur)","alt":[],"note":"Plural: i gradi. Ci sono 30 gradi = es hat 30 Grad.","ex":"Oggi ci sono trenta gradi!","exDe":"Heute hat es dreißig Grad!"},{"it":"le previsioni del tempo","de":"die Wettervorhersage","alt":["le previsioni"],"note":"Oft nur kurz: le previsioni.","ex":"Secondo le previsioni domani piove.","exDe":"Laut Wettervorhersage regnet es morgen."}],"grammar":{"title":"stare und stare + Gerundio","points":["<b>stare</b> kennst du schon aus <b>Come stai?</b> Es bedeutet sich befinden oder bleiben: <b>Sto bene.</b> <b>Oggi sto a casa.</b> Die Formen sind unregelmäßig, schau dir die Tabelle gut an.","Was <b>gerade jetzt</b> passiert, sagst du mit <b>stare + Gerundio</b>: <b>Sto mangiando.</b> = Ich esse gerade. Das ist wie im Englischen I am eating. Für Gewohnheiten bleibt das normale Präsens: <b>Mangio sempre alle otto.</b>","So bildest du das Gerundio: Verben auf <b>are</b> bekommen <b>ando</b> (parlare → parlando). Verben auf <b>ere</b> und <b>ire</b> bekommen <b>endo</b> (leggere → leggendo, dormire → dormendo). Das Gerundio ist für alle Personen gleich.","Nur wenige Ausnahmen: <b>fare → facendo</b>, <b>bere → bevendo</b>, <b>dire → dicendo</b>. Beim Wetter gibt es kein Subjekt: <b>Piove.</b> = Es regnet. <b>Sta piovendo.</b> = Es regnet gerade. Für die Temperatur nimmst du <b>fare</b>: <b>Fa caldo.</b>"],"table":{"head":["Person","stare","stare + Gerundio"],"rows":[["io","sto","sto parlando"],["tu","stai","stai leggendo"],["lui / lei / Lei","sta","sta dormendo"],["noi","stiamo","stiamo mangiando"],["voi","state","state facendo"],["loro","stanno","stanno partendo"]]},"examples":[{"it":"Che cosa stai facendo?","de":"Was machst du gerade?"},{"it":"Sto guardando un film.","de":"Ich schaue gerade einen Film."},{"it":"Giulia sta lavorando in ufficio.","de":"Giulia arbeitet gerade im Büro."},{"it":"Fuori sta piovendo.","de":"Draußen regnet es gerade."},{"it":"I bambini stanno dormendo.","de":"Die Kinder schlafen gerade."}],"drills":[{"type":"choice","q":"Io ___ bene, grazie.","de":"Mir geht es gut, danke.","options":["sto","stai","sta"],"answer":0,"why":"stare, 1. Person: io sto."},{"type":"type","q":"Giulia sta ___ un libro. (leggere)","de":"Giulia liest gerade ein Buch.","answer":"leggendo","alt":[],"why":"Verben auf ere bekommen endo: leggendo."},{"type":"choice","q":"Noi ___ guardando un film.","de":"Wir schauen gerade einen Film.","options":["stanno","stiamo","state"],"answer":1,"why":"noi → stiamo."},{"type":"type","q":"Che cosa stai ___? (fare)","de":"Was machst du gerade?","answer":"facendo","alt":[],"why":"fare ist unregelmäßig: facendo."},{"type":"choice","q":"Fuori sta ___.","de":"Draußen regnet es gerade.","options":["piove","pioggia","piovendo"],"answer":2,"why":"Nach stare kommt das Gerundio: sta piovendo."},{"type":"type","q":"Lukas e Davide ___ giocando a calcio.","de":"Lukas und Davide spielen gerade Fußball.","answer":"stanno","alt":[],"why":"Lukas e Davide = loro → stanno."},{"type":"choice","q":"A Napoli d'estate ___ molto caldo.","de":"In Napoli ist es im Sommer sehr heiß.","options":["sta","fa","va"],"answer":1,"why":"Für Wetter und Temperatur nimmst du fare: fa caldo."},{"type":"type","q":"Lukas sta ___ un caffè. (bere)","de":"Lukas trinkt gerade einen Kaffee.","answer":"bevendo","alt":[],"why":"bere ist unregelmäßig: bevendo."}]},"dialog":{"title":"Andiamo al mare?","setting":"Lukas ist in Firenze. Giulia ruft ihn aus Bologna an. Sie will mit ihm ans Meer fahren, aber wie wird das Wetter?","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Giulia","gender":"f"}},"lines":[{"s":"B","it":"Pronto, Lukas? Ciao! Che stai facendo?","de":"Hallo, Lukas? Hi! Was machst du gerade?"},{"s":"A","it":"Ciao Giulia! Niente, sto bevendo un caffè in piazza.","de":"Hi Giulia! Nichts Besonderes, ich trink grad einen Kaffee auf der Piazza."},{"s":"B","it":"Che bello! E lì che tempo fa?","de":"Wie schön! Und wie ist das Wetter bei dir?"},{"s":"A","it":"C'è il sole e ci sono trenta gradi. Che caldo!","de":"Die Sonne scheint und es hat dreißig Grad. Ist das heiß!"},{"s":"B","it":"Beato te! Qui a Bologna sta diluviando.","de":"Du Glücklicher! Hier in Bologna schüttet es."},{"s":"A","it":"Oh no! E sabato? Andiamo al mare?","de":"Oh nein! Und Samstag? Fahren wir ans Meer?"},{"s":"B","it":"Dipende dal tempo. Secondo le previsioni c'è un temporale.","de":"Kommt aufs Wetter an. Laut Wetterbericht gibt's ein Gewitter."},{"s":"A","it":"Uffa! E domenica?","de":"Och nee! Und am Sonntag?"},{"s":"B","it":"Domenica sì: c'è il sole e fa caldo.","de":"Sonntag schon: Da scheint die Sonne und es ist warm."},{"s":"A","it":"Perfetto, allora domenica! Porto anche l'ombrello, non si sa mai.","de":"Perfekt, dann Sonntag! Ich nehm auch den Schirm mit, man weiß ja nie."},{"s":"B","it":"L'ombrello al mare? Sei proprio tedesco!","de":"Einen Regenschirm am Meer? Du bist echt typisch deutsch!"}],"questions":[{"q":"Was macht Lukas gerade?","options":["Er trinkt einen Kaffee","Er isst ein Eis","Er schläft"],"answer":0},{"q":"Wie ist das Wetter in Bologna?","options":["Die Sonne scheint","Es regnet","Es schneit"],"answer":1},{"q":"Wann fahren die beiden ans Meer?","options":["Am Samstag","Heute","Am Sonntag"],"answer":2}]},"sentences":[{"it":"Che tempo fa oggi a Bologna?","de":"Wie ist das Wetter heute in Bologna?"},{"it":"Oggi fa bel tempo e c'è il sole.","de":"Heute ist schönes Wetter und die Sonne scheint."},{"it":"Sta piovendo, prendo l'ombrello.","de":"Es regnet gerade, ich nehme den Regenschirm."},{"it":"A gennaio fa molto freddo.","de":"Im Januar ist es sehr kalt."},{"it":"Domani fa freddo e nevica.","de":"Morgen ist es kalt und es schneit."},{"it":"Giulia sta parlando al telefono.","de":"Giulia telefoniert gerade."},{"it":"In estate andiamo spesso al mare.","de":"Im Sommer fahren wir oft ans Meer."},{"it":"Ragazzi, che state facendo?","de":"Leute, was macht ihr gerade?"}],"spoken":[{"it":"Che caldo!","book":"Fa molto caldo.","de":"Ist das heiß!","note":"Der typische Seufzer im italienischen Sommer, mit allen und überall. Genauso oft: Che caldo che fa!","ex":"Che caldo! Andiamo a prendere un gelato?","exDe":"Ist das heiß! Holen wir uns ein Eis?","alt":["Che caldo che fa!"]},{"it":"Che freddo!","book":"Fa molto freddo.","de":"Ist das kalt!","note":"Genauso beliebt wie Che caldo! und der perfekte Gesprächsanfang an der Bushaltestelle.","ex":"Che freddo! Prendiamo una cioccolata calda?","exDe":"Ist das kalt! Trinken wir eine heiße Schokolade?","alt":["Che freddo che fa!"]},{"it":"Che afa!","book":"Fa molto caldo ed è umido.","de":"Ist das schwül!","note":"l'afa ist die drückende, feuchte Hitze, typisch für Bologna und die Poebene im Juli.","ex":"Che afa oggi! Non si respira.","exDe":"Ist das schwül heute! Man kriegt kaum Luft.","alt":[]},{"it":"Sta diluviando!","book":"Piove molto.","de":"Es schüttet!","note":"Von diluviare, wie bei der Sintflut. Bei richtig starkem Regen sagen das alle.","ex":"Non esco, sta diluviando!","exDe":"Ich geh nicht raus, es schüttet!","alt":["Diluvia!"]},{"it":"Che tempaccio!","book":"Fa brutto tempo.","de":"So ein Mistwetter!","note":"Die Endung accio macht ein Wort negativ: tempo wird zu tempaccio. Locker, aber nicht unhöflich.","ex":"Che tempaccio! Oggi sto a casa.","exDe":"So ein Mistwetter! Heute bleib ich zu Hause.","alt":[]},{"it":"Si sta bene.","book":"Il tempo è piacevole.","de":"Es ist angenehm.","note":"Sagt man, wenn Wetter oder Ort einfach angenehm sind. Gerne mit proprio: Si sta proprio bene!","ex":"Non fa troppo caldo, si sta bene.","exDe":"Es ist nicht zu heiß, richtig angenehm.","alt":[]},{"it":"Non si sa mai.","book":"","de":"Man weiß ja nie.","note":"Perfekt, wenn du zur Sicherheit etwas mitnimmst. Überall üblich.","ex":"Prendo l'ombrello, non si sa mai.","exDe":"Ich nehme den Schirm mit, man weiß ja nie.","alt":[]},{"it":"Dipende.","book":"","de":"Kommt drauf an.","note":"Sehr häufig, oft mit dal oder dalla: dipende dal tempo. Passt überall.","ex":"Andiamo al mare? Dipende dal tempo.","exDe":"Fahren wir ans Meer? Kommt aufs Wetter an.","alt":[]}],"speak":[{"sit":"Giulia ruft an und fragt, wie das Wetter in Firenze ist. Die Sonne scheint und es ist heiß.","answers":["C'è il sole e fa caldo.","Bel tempo, c'è il sole. Che caldo!","C'è il sole e ci sono trenta gradi!"],"tip":""},{"sit":"Ein Freund ruft an und fragt, was du gerade machst. Du kochst gerade.","answers":["Sto cucinando.","Niente, sto cucinando. E tu?"],"tip":"Mit stare + Gerundio sagst du, was du gerade tust."},{"sit":"Du wartest mit einer Fremden an der Bushaltestelle. Es ist eiskalt. Sag etwas übers Wetter, um ins Gespräch zu kommen.","answers":["Che freddo oggi!","Che freddo, eh?","Fa proprio freddo oggi, eh?"],"tip":"Ein kurzes 'eh?' am Ende lädt zum Antworten ein."},{"sit":"Giulia will morgen ans Meer. Sag ihr, dass es laut Wettervorhersage regnet.","answers":["Secondo le previsioni domani piove.","Guarda, domani piove. Andiamo un altro giorno?"],"tip":""},{"sit":"Freunde fragen, ob ihr am Samstag einen Ausflug macht. Sag, dass es aufs Wetter ankommt.","answers":["Dipende dal tempo.","Mah, dipende dal tempo. Vediamo!"],"tip":"'Vediamo' heißt: Mal sehen."},{"sit":"Jemand fragt dich nach deiner Lieblingsjahreszeit. Du magst den Herbst am liebsten, weil es dann nicht so heiß ist.","answers":["L'autunno, perché non fa troppo caldo.","Preferisco l'autunno: non fa troppo caldo.","La mia stagione preferita è l'autunno."],"tip":""}]},{"id":15,"title":"Ieri","titleDe":"Gestern","goal":"Du kannst erzählen, was du gestern oder letzte Woche gemacht hast.","intro":"Endlich kannst du erzählen! Diese Woche lernst du das passato prossimo, die wichtigste Vergangenheitsform im gesprochenen Italienisch. Damit berichtest du, was du gestern gemacht, gesehen und gegessen hast.","culture":"Für die Uffizien in Firenze reservierst du die Tickets am besten vorher online, sonst stehst du oft stundenlang in der Schlange. In vielen staatlichen Museen Italiens ist der Eintritt am ersten Sonntag im Monat kostenlos. Dann ist allerdings auch besonders viel los.","vocab":[{"it":"ieri","de":"gestern","alt":[],"note":"","ex":"Ieri ho lavorato tanto.","exDe":"Gestern habe ich viel gearbeitet."},{"it":"ieri sera","de":"gestern Abend","alt":[],"note":"","ex":"Ieri sera abbiamo mangiato una pizza.","exDe":"Gestern Abend haben wir Pizza gegessen."},{"it":"l'altro ieri","de":"vorgestern","alt":["l'altroieri","altro ieri","altroieri"],"note":"Auch zusammengeschrieben: l'altroieri.","ex":"L'altro ieri ho visto Davide.","exDe":"Vorgestern habe ich Davide gesehen."},{"it":"fa","de":"vor (zeitlich)","alt":[],"note":"Steht hinter der Zeitangabe: due giorni fa = vor zwei Tagen.","ex":"Ho comprato il biglietto due giorni fa.","exDe":"Ich habe die Fahrkarte vor zwei Tagen gekauft."},{"it":"la settimana scorsa","de":"letzte Woche","alt":["la scorsa settimana"],"note":"","ex":"La settimana scorsa ho preso il treno.","exDe":"Letzte Woche habe ich den Zug genommen."},{"it":"il mese scorso","de":"letzten Monat","alt":["lo scorso mese"],"note":"scorso = vergangen, letzter. feminin: scorsa.","ex":"Il mese scorso ho cominciato un corso d'italiano.","exDe":"Letzten Monat habe ich einen Italienischkurs angefangen."},{"it":"l'anno scorso","de":"letztes Jahr","alt":["anno scorso","lo scorso anno"],"note":"","ex":"L'anno scorso abbiamo comprato una macchina.","exDe":"Letztes Jahr haben wir ein Auto gekauft."},{"it":"già","de":"schon; bereits","alt":["gia"],"note":"Steht meist zwischen avere und Partizip: ho già mangiato.","ex":"Hai già mangiato?","exDe":"Hast du schon gegessen?"},{"it":"non ancora","de":"noch nicht","alt":[],"note":"Im Satz: non ho ancora visto = ich habe noch nicht gesehen.","ex":"Non ho ancora visto il Duomo.","exDe":"Ich habe den Dom noch nicht gesehen."},{"it":"appena","de":"gerade eben; soeben","alt":[],"note":"Ho appena mangiato = ich habe gerade gegessen.","ex":"Ho appena finito di lavorare.","exDe":"Ich habe gerade eben mit der Arbeit aufgehört."},{"it":"Che cosa hai fatto?","de":"Was hast du gemacht?","alt":["Cosa hai fatto?","Che hai fatto?"],"note":"Zu mehreren Personen: Che cosa avete fatto?","ex":"Che cosa hai fatto ieri sera?","exDe":"Was hast du gestern Abend gemacht?"},{"it":"tutto il giorno","de":"den ganzen Tag","alt":[],"note":"Genauso: tutta la sera, tutto l'anno.","ex":"Ieri ho dormito tutto il giorno.","exDe":"Gestern habe ich den ganzen Tag geschlafen."},{"it":"passare","de":"verbringen (Zeit)","alt":[],"note":"Ho passato una bella giornata = ich hatte einen schönen Tag.","ex":"Abbiamo passato una serata fantastica.","exDe":"Wir haben einen fantastischen Abend verbracht."},{"it":"visitare","de":"besichtigen","alt":[],"note":"Für Orte und Sehenswürdigkeiten.","ex":"Che cosa avete visitato?","exDe":"Was habt ihr besichtigt?"},{"it":"chiedere","de":"fragen; bitten um","alt":[],"note":"Partizip: chiesto.","ex":"Ho chiesto la strada a un signore.","exDe":"Ich habe einen Herrn nach dem Weg gefragt."},{"it":"perdere","de":"verlieren; verpassen","alt":[],"note":"Partizip: perso.","ex":"Ho perso il treno!","exDe":"Ich habe den Zug verpasst!"},{"it":"dimenticare","de":"vergessen","alt":[],"note":"","ex":"Ho dimenticato l'ombrello.","exDe":"Ich habe den Regenschirm vergessen."},{"it":"trovare","de":"finden","alt":[],"note":"","ex":"Non ho trovato la chiave.","exDe":"Ich habe den Schlüssel nicht gefunden."},{"it":"decidere","de":"entscheiden; beschließen","alt":[],"note":"Partizip: deciso.","ex":"Abbiamo deciso di andare a Pisa.","exDe":"Wir haben beschlossen, nach Pisa zu fahren."},{"it":"spendere","de":"ausgeben (Geld)","alt":[],"note":"Partizip: speso.","ex":"Quanto hai speso?","exDe":"Wie viel hast du ausgegeben?"},{"it":"rispondere","de":"antworten","alt":[],"note":"Partizip: risposto.","ex":"Giulia non ha risposto.","exDe":"Giulia hat nicht geantwortet."},{"it":"mettere","de":"legen; stellen; tun","alt":[],"note":"Partizip: messo.","ex":"Dove hai messo il biglietto?","exDe":"Wo hast du die Fahrkarte hingelegt?"},{"it":"ricevere","de":"bekommen; erhalten","alt":[],"note":"Partizip regelmäßig: ricevuto.","ex":"Ho ricevuto un messaggio da Davide.","exDe":"Ich habe eine Nachricht von Davide bekommen."},{"it":"fotografare","de":"fotografieren","alt":[],"note":"","ex":"Ho fotografato il Ponte Vecchio.","exDe":"Ich habe den Ponte Vecchio fotografiert."},{"it":"fare la fila","de":"Schlange stehen","alt":["fare la coda"],"note":"la fila = die Schlange (von Menschen).","ex":"Abbiamo fatto la fila per un'ora.","exDe":"Wir haben eine Stunde lang Schlange gestanden."},{"it":"la cartolina","de":"die Postkarte","alt":[],"note":"","ex":"Ho scritto una cartolina alla nonna.","exDe":"Ich habe der Oma eine Postkarte geschrieben."},{"it":"il portafoglio","de":"der Geldbeutel","alt":[],"note":"Plural: i portafogli.","ex":"Hai il portafoglio?","exDe":"Hast du den Geldbeutel dabei?"},{"it":"il panorama","de":"die Aussicht; das Panorama","alt":[],"note":"Maskulin, obwohl es auf a endet. Plural: i panorami.","ex":"Da qui il panorama è bellissimo.","exDe":"Von hier ist die Aussicht wunderschön."},{"it":"il tramonto","de":"der Sonnenuntergang","alt":[],"note":"","ex":"Abbiamo visto un tramonto bellissimo.","exDe":"Wir haben einen wunderschönen Sonnenuntergang gesehen."},{"it":"la cupola","de":"die Kuppel","alt":[],"note":"Die Kuppel des Doms in Firenze ist von Brunelleschi.","ex":"Ho visto la cupola del Duomo.","exDe":"Ich habe die Kuppel des Doms gesehen."},{"it":"per la prima volta","de":"zum ersten Mal","alt":[],"note":"la volta = das Mal. Due volte = zweimal.","ex":"Ho mangiato la ribollita per la prima volta.","exDe":"Ich habe zum ersten Mal Ribollita gegessen."},{"it":"finalmente","de":"endlich","alt":[],"note":"","ex":"Finalmente ho visto il David!","exDe":"Endlich habe ich den David gesehen!"},{"it":"Non ho capito.","de":"Ich habe nicht verstanden.","alt":[],"note":"Sehr nützlich, wenn jemand zu schnell spricht.","ex":"Scusi, non ho capito.","exDe":"Entschuldigung, ich habe nicht verstanden."},{"it":"Ho avuto fortuna.","de":"Ich hatte Glück.","alt":[],"note":"la fortuna = das Glück.","ex":"Ho trovato il portafoglio, ho avuto fortuna!","exDe":"Ich habe den Geldbeutel gefunden, ich hatte Glück!"},{"it":"l'ingresso","de":"der Eingang; der Eintritt","alt":["ingresso"],"note":"Maskulin. Ingresso libero = Eintritt frei.","ex":"L'ingresso è gratis.","exDe":"Der Eintritt ist kostenlos."},{"it":"la guida","de":"der Reiseführer; der Fremdenführer","alt":[],"note":"Kann ein Buch oder eine Person sein.","ex":"Abbiamo comprato una guida di Firenze.","exDe":"Wir haben einen Reiseführer über Firenze gekauft."}],"grammar":{"title":"Das passato prossimo mit avere","points":["Für Dinge, die du gestern oder letzte Woche gemacht hast, nimmst du das <b>passato prossimo</b>. Es funktioniert fast wie das deutsche Perfekt: eine Form von <b>avere</b> + Partizip. <b>Ho mangiato</b> = ich habe gegessen.","Das Partizip ist meist regelmäßig: Aus <b>are</b> wird <b>ato</b> (mangiare → mangiato), aus <b>ere</b> wird <b>uto</b> (ricevere → ricevuto), aus <b>ire</b> wird <b>ito</b> (dormire → dormito).","Viele häufige Verben haben ein unregelmäßiges Partizip. Lern sie am besten auswendig: <b>fatto</b> (fare), <b>visto</b> (vedere), <b>preso</b> (prendere), <b>detto</b> (dire), <b>letto</b> (leggere), <b>scritto</b> (scrivere), <b>aperto</b> (aprire), <b>chiuso</b> (chiudere), <b>perso</b> (perdere).","Anders als im Deutschen steht das Partizip direkt hinter avere, nicht am Satzende: <b>Ho visto il Duomo.</b> <b>non</b> steht vor avere, <b>già</b> und <b>ancora</b> stehen dazwischen: <b>Non ho ancora mangiato.</b>"],"table":{"head":["Person","parlare","ricevere","dormire"],"rows":[["io","ho parlato","ho ricevuto","ho dormito"],["tu","hai parlato","hai ricevuto","hai dormito"],["lui / lei / Lei","ha parlato","ha ricevuto","ha dormito"],["noi","abbiamo parlato","abbiamo ricevuto","abbiamo dormito"],["voi","avete parlato","avete ricevuto","avete dormito"],["loro","hanno parlato","hanno ricevuto","hanno dormito"]]},"examples":[{"it":"Ieri sera abbiamo visto un bel film.","de":"Gestern Abend haben wir einen schönen Film gesehen."},{"it":"Giulia ha letto il giornale.","de":"Giulia hat die Zeitung gelesen."},{"it":"Hai già fatto colazione?","de":"Hast du schon gefrühstückt?"},{"it":"Non ho ancora preso il biglietto.","de":"Ich habe die Fahrkarte noch nicht gekauft."},{"it":"Il museo ha chiuso alle sette.","de":"Das Museum hat um sieben geschlossen."},{"it":"Che cosa avete fatto la settimana scorsa?","de":"Was habt ihr letzte Woche gemacht?"}],"drills":[{"type":"choice","q":"Lukas ___ visitato gli Uffizi.","de":"Lukas hat die Uffizien besichtigt.","options":["hanno","ha","abbiamo"],"answer":1,"why":"Lukas = lui → ha."},{"type":"type","q":"Hai ___ il Ponte Vecchio? (vedere)","de":"Hast du den Ponte Vecchio gesehen?","answer":"visto","alt":["veduto"],"why":"vedere hat ein unregelmäßiges Partizip: visto."},{"type":"choice","q":"Giulia ha ___ un libro.","de":"Giulia hat ein Buch gelesen.","options":["leggiuto","leggito","letto"],"answer":2,"why":"leggere ist unregelmäßig: letto."},{"type":"type","q":"Noi ___ preso il treno delle otto.","de":"Wir haben den Zug um acht genommen.","answer":"abbiamo","alt":[],"why":"noi → abbiamo."},{"type":"choice","q":"E voi, che cosa ___ fatto ieri?","de":"Und ihr, was habt ihr gestern gemacht?","options":["avete","hanno","abbiamo"],"answer":0,"why":"voi → avete."},{"type":"type","q":"Hai ___ la mia cartolina? (ricevere)","de":"Hast du meine Postkarte bekommen?","answer":"ricevuto","alt":[],"why":"Verben auf ere: Partizip auf uto."},{"type":"choice","q":"Ieri abbiamo ___ tutto il giorno.","de":"Gestern sind wir den ganzen Tag gelaufen.","options":["camminuto","camminato","camminito"],"answer":1,"why":"Verben auf are: Partizip auf ato. Achtung: camminare nimmt avere."},{"type":"type","q":"Ho ___ il portafoglio! (perdere)","de":"Ich habe den Geldbeutel verloren!","answer":"perso","alt":["perduto"],"why":"perdere hat das Partizip perso (seltener perduto)."}]},"dialog":{"title":"Una giornata a Firenze","setting":"Giulia ruft Lukas an. Er erzählt ihr, was er gestern in Firenze gemacht hat.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Giulia","gender":"f"}},"lines":[{"s":"B","it":"Ciao Lukas! Allora, che hai fatto ieri?","de":"Hi Lukas! Und, was hast du gestern gemacht?"},{"s":"A","it":"Praticamente ho fatto la fila agli Uffizi per due ore!","de":"Im Grunde hab ich zwei Stunden vor den Uffizien angestanden!"},{"s":"B","it":"Due ore? Ma non hai prenotato?","de":"Zwei Stunden? Hast du denn nicht reserviert?"},{"s":"A","it":"No... Però ho visto quadri bellissimi. Ne vale la pena!","de":"Nein ... Aber ich hab wunderschöne Bilder gesehen. Das lohnt sich!"},{"s":"B","it":"E il Duomo? Hai già visto la cupola?","de":"Und der Dom? Hast du die Kuppel schon gesehen?"},{"s":"A","it":"Non ancora. Ma ieri sera ho fotografato il tramonto.","de":"Noch nicht. Aber gestern Abend hab ich den Sonnenuntergang fotografiert."},{"s":"B","it":"Dal Piazzale Michelangelo? Che spettacolo!","de":"Vom Piazzale Michelangelo? Ein Traum!"},{"s":"A","it":"Sì! Poi a cena ho mangiato una fiorentina.","de":"Ja! Und zum Abendessen gab's ein Florentiner Steak."},{"s":"B","it":"Buonissima! E quanto hai speso?","de":"Superlecker! Und wie viel hast du ausgegeben?"},{"s":"A","it":"Troppo! E poi... ho perso il portafoglio.","de":"Zu viel! Und dann ... hab ich meinen Geldbeutel verloren."},{"s":"B","it":"Accidenti! E adesso?","de":"Mist! Und jetzt?"},{"s":"A","it":"Tranquilla, ho avuto fortuna: il cameriere ha trovato tutto.","de":"Keine Sorge, ich hatte Glück: Der Kellner hat alles gefunden."}],"questions":[{"q":"Wie lange hat Lukas vor den Uffizien gewartet?","options":["Eine Stunde","Zwei Stunden","Drei Stunden"],"answer":1},{"q":"Was hat Lukas noch nicht gesehen?","options":["Die Kuppel vom Dom","Den Sonnenuntergang","Die Uffizien"],"answer":0},{"q":"Wer hat den Geldbeutel gefunden?","options":["Giulia","Ein Polizist","Der Kellner"],"answer":2}]},"sentences":[{"it":"Ieri ho visitato un museo bellissimo.","de":"Gestern habe ich ein wunderschönes Museum besichtigt."},{"it":"Che cosa hai fatto la settimana scorsa?","de":"Was hast du letzte Woche gemacht?"},{"it":"Non abbiamo ancora mangiato.","de":"Wir haben noch nicht gegessen."},{"it":"Due giorni fa ho perso il treno.","de":"Vor zwei Tagen habe ich den Zug verpasst."},{"it":"Giulia ha già comprato i biglietti.","de":"Giulia hat die Fahrkarten schon gekauft."},{"it":"Ieri sera ho scritto a Giulia.","de":"Gestern Abend habe ich Giulia geschrieben."},{"it":"Hai letto il messaggio di Davide?","de":"Hast du Davides Nachricht gelesen?"},{"it":"Abbiamo passato una bella giornata.","de":"Wir haben einen schönen Tag verbracht."}],"spoken":[{"it":"Praticamente","book":"","de":"im Grunde; also quasi","note":"Beliebtes Füllwort beim Erzählen, oft ganz am Anfang. Es bedeutet oft nicht viel, gibt dir aber Zeit zum Nachdenken.","ex":"Praticamente ho camminato tutto il giorno.","exDe":"Im Grunde bin ich den ganzen Tag gelaufen.","alt":[]},{"it":"E poi?","book":"E dopo che cosa hai fatto?","de":"Und dann?","note":"Damit zeigst du, dass du zuhörst und mehr wissen willst. Unter Freunden hörst du das ständig.","ex":"Abbiamo visto il Duomo. E poi?","exDe":"Wir haben den Dom gesehen. Und dann?","alt":[]},{"it":"Ne vale la pena.","book":"","de":"Es lohnt sich.","note":"Für Museen, Ausflüge oder teure Dinge. Gegenteil: Non ne vale la pena.","ex":"Due ore di fila? Sì, ma ne vale la pena!","exDe":"Zwei Stunden Schlange? Ja, aber es lohnt sich!","alt":["Vale la pena."]},{"it":"Che spettacolo!","book":"È molto bello.","de":"Was für ein Anblick!","note":"Für alles, was dich begeistert: ein Panorama, ein Sonnenuntergang, sogar ein gutes Essen.","ex":"Hai visto il tramonto? Che spettacolo!","exDe":"Hast du den Sonnenuntergang gesehen? Ein Traum!","alt":[]},{"it":"Per un pelo!","book":"All'ultimo momento.","de":"Ganz knapp!","note":"Wörtlich: um ein Haar. Sehr häufig, wenn etwas gerade noch geklappt hat.","ex":"Ho preso il treno per un pelo!","exDe":"Ich hab den Zug ganz knapp noch erwischt!","alt":[]},{"it":"Sono distrutto.","book":"Sono molto stanco.","de":"Ich bin total fertig.","note":"Nach einem langen Tag. Als Frau sagst du: Sono distrutta.","ex":"Ho camminato tutto il giorno, sono distrutto!","exDe":"Ich bin den ganzen Tag gelaufen, ich bin total fertig!","alt":["Sono distrutta."]},{"it":"Accidenti!","book":"","de":"Mist!; Verflixt!","note":"Harmloser Ausruf, wenn etwas schiefgeht. Passt überall, auch vor der Oma.","ex":"Accidenti, ho dimenticato l'ombrello!","exDe":"Mist, ich hab den Schirm vergessen!","alt":[]},{"it":"Ho fatto tardi.","book":"","de":"Es ist spät geworden.","note":"Ieri sera ho fatto tardi = gestern war ich lange unterwegs. Auch als Entschuldigung: Scusa, ho fatto tardi! = Sorry, ich bin spät dran!","ex":"Ieri sera ho fatto tardi con Davide.","exDe":"Gestern Abend ist es mit Davide spät geworden.","alt":[]}],"speak":[{"sit":"Giulia fragt, was du gestern gemacht hast. Du hast die Uffizien besichtigt und danach eine Pizza gegessen.","answers":["Ho visitato gli Uffizi e poi ho mangiato una pizza.","Allora, ho visto gli Uffizi e poi ho mangiato una pizza."],"tip":"Mit 'e poi' reihst du deine Erlebnisse aneinander."},{"sit":"Ein Freund fragt, ob du den Dom schon gesehen hast. Hast du noch nicht.","answers":["No, non ancora.","Non l'ho ancora visto.","No, non ho ancora visto il Duomo."],"tip":"Ganz kurz und natürlich: 'Non ancora.'"},{"sit":"Du erzählst Giulia, dass du gestern Abend deinen Geldbeutel verloren hast.","answers":["Ieri sera ho perso il portafoglio.","Accidenti, ieri sera ho perso il portafoglio!"],"tip":""},{"sit":"Ein Freund überlegt, ob er für die Uffizien zwei Stunden anstehen soll. Sag ihm, dass es sich lohnt.","answers":["Sì, ne vale la pena!","Sì, dai, vale la pena!"],"tip":""},{"sit":"Giulia erzählt von ihrem Tag und macht plötzlich eine Pause. Zeig, dass du mehr hören willst.","answers":["E poi?","E poi? Che cosa hai fatto?"],"tip":""},{"sit":"Du triffst Giulia morgens und bist total müde. Erklär, dass es gestern Abend spät geworden ist.","answers":["Ieri sera ho fatto tardi.","Sono distrutto, ieri sera ho fatto tardi."],"tip":"Als Frau sagst du: sono distrutta."}]},{"id":16,"title":"Il fine settimana","titleDe":"Das Wochenende","goal":"Du kannst erzählen, wohin du gefahren bist und was du am Wochenende erlebt hast.","intro":"Letzte Woche hast du das passato prossimo mit avere gelernt. Jetzt kommt die zweite Hälfte: Bei Verben wie gehen, fahren, ankommen und bleiben nimmst du essere. Damit erzählst du von Ausflügen und Reisen.","culture":"Der Gardasee ist der größte See Italiens und liegt zwischen Lombardei, Venetien und Trentino. Sehr beliebt ist Sirmione mit seiner Wasserburg und den Thermen. Einen kurzen Ausflug ins Grüne nennen Italiener übrigens 'gita fuori porta', also einen Ausflug vor die Tore der Stadt.","vocab":[{"it":"partire","de":"abfahren; losfahren","alt":[],"note":"Passato mit essere: sono partito / partita.","ex":"Siamo partiti presto.","exDe":"Wir sind früh losgefahren."},{"it":"arrivare","de":"ankommen","alt":[],"note":"","ex":"Giulia è arrivata in ritardo.","exDe":"Giulia ist zu spät angekommen."},{"it":"tornare","de":"zurückkommen; zurückfahren","alt":[],"note":"","ex":"Quando sei tornato?","exDe":"Wann bist du zurückgekommen?"},{"it":"restare","de":"bleiben","alt":["rimanere"],"note":"Gleiche Bedeutung: rimanere (sono rimasto).","ex":"Sono restata a casa.","exDe":"Ich bin zu Hause geblieben."},{"it":"salire","de":"einsteigen; hinaufgehen","alt":[],"note":"Unregelmäßig: io salgo, loro salgono.","ex":"Siamo saliti sul treno.","exDe":"Wir sind in den Zug eingestiegen."},{"it":"scendere","de":"aussteigen; hinuntergehen","alt":[],"note":"Partizip: sceso.","ex":"Sono sceso a Verona.","exDe":"Ich bin in Verona ausgestiegen."},{"it":"entrare","de":"hineingehen; eintreten","alt":[],"note":"","ex":"Siamo entrati nel castello.","exDe":"Wir sind in die Burg hineingegangen."},{"it":"succedere","de":"passieren","alt":[],"note":"Partizip: successo.","ex":"È successo ieri sera.","exDe":"Es ist gestern Abend passiert."},{"it":"la gita","de":"der Ausflug","alt":[],"note":"","ex":"La gita al lago è stata bellissima.","exDe":"Der Ausflug an den See war wunderschön."},{"it":"il lago","de":"der See","alt":[],"note":"Plural: i laghi. Il lago di Garda = der Gardasee.","ex":"Siamo andati al lago di Garda.","exDe":"Wir sind an den Gardasee gefahren."},{"it":"Com'è andata?","de":"Wie war's? (Wie ist es gelaufen?)","alt":["Come è andata?"],"note":"Feste Wendung, immer feminin: andata.","ex":"Allora, com'è andata la gita?","exDe":"Und, wie war der Ausflug?"},{"it":"È stato bellissimo.","de":"Es war wunderschön.","alt":[],"note":"stato ist das Partizip von essere und stare.","ex":"Grazie, è stato bellissimo!","exDe":"Danke, es war wunderschön!"},{"it":"Dove sei stato?","de":"Wo warst du?","alt":["Dove sei stata?"],"note":"Zu einer Frau: Dove sei stata?","ex":"Dove sei stato sabato?","exDe":"Wo warst du am Samstag?"},{"it":"Ti è piaciuto?","de":"Hat es dir gefallen?","alt":["Ti è piaciuta?"],"note":"piacere bildet das passato mit essere: mi è piaciuto / piaciuta.","ex":"Ti è piaciuto il lago?","exDe":"Hat dir der See gefallen?"},{"it":"Che cosa avete fatto di bello?","de":"Was habt ihr Schönes gemacht?","alt":["Cosa avete fatto di bello?"],"note":"Zu einer Person: Che cosa hai fatto di bello?","ex":"Ciao ragazzi! Che cosa avete fatto di bello?","exDe":"Hallo Leute! Was habt ihr Schönes gemacht?"},{"it":"Cos'è successo?","de":"Was ist passiert?","alt":["Che cosa è successo?","Cosa è successo?","Che è successo?"],"note":"","ex":"Lukas, cos'è successo?","exDe":"Lukas, was ist passiert?"},{"it":"nascere","de":"geboren werden","alt":[],"note":"Passato mit essere, Partizip: nato. Sono nato a Monaco.","ex":"Davide è nato a Napoli.","exDe":"Davide ist in Napoli geboren."},{"it":"cadere","de":"hinfallen; fallen","alt":[],"note":"Passato mit essere: sono caduto.","ex":"Lukas è caduto in acqua!","exDe":"Lukas ist ins Wasser gefallen!"},{"it":"il castello","de":"die Burg; das Schloss","alt":[],"note":"","ex":"Il castello di Sirmione è sull'acqua.","exDe":"Die Burg von Sirmione steht im Wasser."},{"it":"la barca","de":"das Boot","alt":[],"note":"Plural: le barche. In barca = im Boot; mit dem Boot.","ex":"Siamo andati in barca sul lago.","exDe":"Wir sind mit dem Boot auf den See gefahren."},{"it":"il battello","de":"das Schiff (auf dem See)","alt":[],"note":"Auf den großen Seen fahren battelli wie Linienbusse.","ex":"Abbiamo preso il battello per Malcesine.","exDe":"Wir haben das Schiff nach Malcesine genommen."},{"it":"la riva","de":"das Ufer","alt":[],"note":"","ex":"Abbiamo mangiato sulla riva del lago.","exDe":"Wir haben am Seeufer gegessen."},{"it":"la funivia","de":"die Seilbahn","alt":[],"note":"","ex":"Siamo saliti con la funivia.","exDe":"Wir sind mit der Seilbahn hinaufgefahren."},{"it":"la vista","de":"der Blick; die Aussicht","alt":[],"note":"","ex":"Dal castello c'è una vista fantastica.","exDe":"Von der Burg hat man einen fantastischen Blick."},{"it":"fare un giro","de":"eine Runde drehen","alt":[],"note":"Fare un giro in centro = durch die Stadt bummeln.","ex":"Abbiamo fatto un giro in barca.","exDe":"Wir haben eine Runde mit dem Boot gedreht."},{"it":"fare il bagno","de":"baden (im Meer, im See)","alt":[],"note":"Auch: ein Bad nehmen.","ex":"Ieri ho fatto il bagno nel lago.","exDe":"Gestern habe ich im See gebadet."},{"it":"le terme","de":"die Thermen; das Thermalbad","alt":[],"note":"Immer Plural.","ex":"A Sirmione siamo andati alle terme.","exDe":"In Sirmione sind wir in die Therme gegangen."},{"it":"il sentiero","de":"der Wanderweg; der Pfad","alt":[],"note":"","ex":"Siamo scesi a piedi per il sentiero.","exDe":"Wir sind zu Fuß über den Wanderweg hinuntergegangen."},{"it":"diventare","de":"werden","alt":[],"note":"Passato mit essere: è diventato / diventata.","ex":"Il cielo è diventato nero.","exDe":"Der Himmel ist schwarz geworden."},{"it":"il borgo","de":"das Städtchen; der kleine Ort","alt":[],"note":"Meist ein alter, historischer Ort. Plural: i borghi.","ex":"Malcesine è un borgo bellissimo.","exDe":"Malcesine ist ein wunderschönes Städtchen."},{"it":"il porto","de":"der Hafen","alt":[],"note":"","ex":"Il battello parte dal porto.","exDe":"Das Schiff fährt am Hafen ab."},{"it":"la coda","de":"der Stau; die Schlange","alt":[],"note":"In coda = im Stau.","ex":"Al ritorno siamo stati due ore in coda.","exDe":"Auf dem Rückweg standen wir zwei Stunden im Stau."},{"it":"affollato","de":"überfüllt; voller Leute","alt":[],"note":"feminin: affollata.","ex":"Il sabato Sirmione è molto affollata.","exDe":"Samstags ist Sirmione total überfüllt."},{"it":"stupendo","de":"wunderbar; herrlich","alt":[],"note":"feminin: stupenda.","ex":"Che giornata stupenda!","exDe":"Was für ein herrlicher Tag!"},{"it":"da solo","de":"allein","alt":[],"note":"feminin: da sola.","ex":"Lukas è partito da solo.","exDe":"Lukas ist allein losgefahren."},{"it":"il giorno dopo","de":"am nächsten Tag","alt":[],"note":"","ex":"Il giorno dopo siamo tornati a casa.","exDe":"Am nächsten Tag sind wir nach Hause gefahren."}],"grammar":{"title":"Das passato prossimo mit essere","points":["Manche Verben bilden das passato prossimo mit <b>essere</b>. Das sind vor allem Verben der Bewegung: <b>andare, venire, partire, arrivare, tornare, uscire, entrare</b>. Wie im Deutschen: ich <b>bin</b> gefahren = <b>sono andato</b>.","Auch <b>restare</b>, <b>succedere</b>, <b>piacere</b> und <b>essere</b> selbst nehmen essere: <b>sono stato</b> = ich bin gewesen, <b>mi è piaciuto</b> = es hat mir gefallen.","Mit essere passt sich das Partizip an wie ein Adjektiv: Lukas è <b>andato</b>, Giulia è <b>andata</b>, Lukas e Davide sono <b>andati</b>, Giulia e Rosa sono <b>andate</b>. Bei gemischten Gruppen nimmst du die Endung <b>i</b>.","Mit avere bleibt das Partizip meist gleich: Giulia <b>ha mangiato</b>. Nur nach lo, la, li, le passt es sich an: <b>La pizza? L'ho mangiata.</b> Merkregel: Bewegung von A nach B oder Veränderung braucht meist essere, etwas tun braucht avere."],"table":{"head":["Person","maskulin","feminin"],"rows":[["io","sono andato","sono andata"],["tu","sei andato","sei andata"],["lui / lei","è andato","è andata"],["noi","siamo andati","siamo andate"],["voi","siete andati","siete andate"],["loro","sono andati","sono andate"]]},"examples":[{"it":"Sabato siamo andati al lago di Garda.","de":"Am Samstag sind wir an den Gardasee gefahren."},{"it":"Giulia è partita alle otto.","de":"Giulia ist um acht losgefahren."},{"it":"Davide è arrivato tardi, come sempre.","de":"Davide ist wie immer spät angekommen."},{"it":"Rosa e Giulia sono tornate domenica sera.","de":"Rosa und Giulia sind am Sonntagabend zurückgekommen."},{"it":"Mi è piaciuta molto la gita.","de":"Der Ausflug hat mir sehr gefallen."},{"it":"Dove siete stati ieri?","de":"Wo wart ihr gestern?"}],"drills":[{"type":"choice","q":"Giulia ___ andata al lago.","de":"Giulia ist an den See gefahren.","options":["ha","è","sono"],"answer":1,"why":"andare bildet das passato mit essere: è andata."},{"type":"type","q":"Lukas è ___ alle nove. (partire)","de":"Lukas ist um neun losgefahren.","answer":"partito","alt":[],"why":"Lukas ist maskulin: partito."},{"type":"choice","q":"Giulia e Rosa sono ___ ieri sera.","de":"Giulia und Rosa sind gestern Abend zurückgekommen.","options":["tornati","tornata","tornate"],"answer":2,"why":"Zwei Frauen: Endung e."},{"type":"type","q":"Noi ___ arrivati a Sirmione alle dieci.","de":"Wir sind um zehn in Sirmione angekommen.","answer":"siamo","alt":[],"why":"arrivare nimmt essere: noi siamo."},{"type":"choice","q":"Lukas e Giulia sono ___ a casa.","de":"Lukas und Giulia sind zu Hause geblieben.","options":["restati","restate","restato"],"answer":0,"why":"Gemischte Gruppe: Endung i."},{"type":"type","q":"Davide, dove sei ___ ieri? (essere)","de":"Davide, wo warst du gestern?","answer":"stato","alt":[],"why":"essere hat das Partizip stato."},{"type":"choice","q":"Domenica ___ mangiato sulla riva del lago.","de":"Am Sonntag haben wir am Seeufer gegessen.","options":["sono","siamo","abbiamo"],"answer":2,"why":"mangiare ist keine Bewegung, also avere."},{"type":"type","q":"Ti è ___ la gita? (piacere)","de":"Hat dir der Ausflug gefallen?","answer":"piaciuta","alt":[],"why":"la gita ist feminin: piaciuta."}]},"dialog":{"title":"Al lago di Garda","setting":"Lukas und Giulia waren am Wochenende am Gardasee. Davide war bei seiner Familie in Napoli. Am Montag telefonieren die drei per Video.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Giulia","gender":"f"},"C":{"name":"Davide","gender":"m"}},"lines":[{"s":"C","it":"Allora, ragazzi, com'è andata al lago?","de":"Na, Leute, wie war's am See?"},{"s":"B","it":"Benissimo! Siamo partiti sabato mattina prestissimo.","de":"Super! Wir sind am Samstag in aller Frühe losgefahren."},{"s":"A","it":"E alle dieci siamo arrivati a Sirmione.","de":"Und um zehn waren wir schon in Sirmione."},{"s":"C","it":"Che invidia! E che avete fatto di bello?","de":"Ich bin ja so neidisch! Und was habt ihr Schönes gemacht?"},{"s":"B","it":"Abbiamo visto il castello e poi siamo andati alle terme.","de":"Wir haben uns die Burg angeschaut und sind dann in die Therme gegangen."},{"s":"A","it":"Domenica siamo saliti sul Monte Baldo con la funivia.","de":"Am Sonntag sind wir mit der Seilbahn auf den Monte Baldo gefahren."},{"s":"C","it":"E la vista? Ti è piaciuta?","de":"Und die Aussicht? Hat sie dir gefallen?"},{"s":"A","it":"Tantissimo! Siamo stati benissimo.","de":"Total! Wir hatten eine super Zeit."},{"s":"B","it":"Sì, ma sai cos'è successo in barca? Lukas è caduto in acqua!","de":"Ja, aber weißt du, was im Boot passiert ist? Lukas ist ins Wasser gefallen!"},{"s":"C","it":"Ma dai! Che ridere! E come hai fatto?","de":"Echt jetzt? Zum Totlachen! Wie hast du das denn geschafft?"},{"s":"A","it":"Boh! Però almeno ho fatto il bagno!","de":"Keine Ahnung! Aber immerhin war ich baden!"},{"s":"C","it":"Io invece sono restato a Napoli con mia nonna. Insomma...","de":"Und ich bin bei meiner Oma in Napoli geblieben. Na ja ..."}],"questions":[{"q":"Wann sind Lukas und Giulia losgefahren?","options":["Am Freitagabend","Am Samstagmorgen","Am Sonntagmorgen"],"answer":1},{"q":"Wie sind sie auf den Monte Baldo gekommen?","options":["Mit der Seilbahn","Zu Fuß","Mit dem Auto"],"answer":0},{"q":"Was ist Lukas passiert?","options":["Er hat sein Handy verloren","Er hat den Zug verpasst","Er ist ins Wasser gefallen"],"answer":2}]},"sentences":[{"it":"Sabato siamo andati al lago.","de":"Am Samstag sind wir an den See gefahren."},{"it":"Giulia è partita alle sette.","de":"Giulia ist um sieben losgefahren."},{"it":"A che ora sei arrivato a casa?","de":"Um wie viel Uhr bist du nach Hause gekommen?"},{"it":"Siamo restati al lago tutto il giorno.","de":"Wir sind den ganzen Tag am See geblieben."},{"it":"Domenica sera siamo tornati a Bologna.","de":"Am Sonntagabend sind wir nach Bologna zurückgefahren."},{"it":"La gita mi è piaciuta molto.","de":"Der Ausflug hat mir sehr gefallen."},{"it":"Dove siete stati il fine settimana scorso?","de":"Wo wart ihr letztes Wochenende?"},{"it":"Le ragazze sono scese dal treno.","de":"Die Mädchen sind aus dem Zug ausgestiegen."}],"spoken":[{"it":"Insomma","book":"","de":"kurz gesagt; na ja, geht so","note":"Am Ende einer Geschichte fasst du damit zusammen. Allein und gedehnt (Insomma ...) heißt es: so lala, nicht so toll.","ex":"Insomma, è stato un fine settimana stupendo!","exDe":"Kurz gesagt: Es war ein herrliches Wochenende!","alt":[]},{"it":"Mi è andata bene.","book":"Ho avuto fortuna.","de":"Da hatte ich Glück.","note":"Feste Wendung, immer mit andata. Gegenteil: Mi è andata male.","ex":"Ho preso l'ultimo battello. Mi è andata bene!","exDe":"Ich hab das letzte Schiff erwischt. Da hatte ich Glück!","alt":[]},{"it":"Come al solito","book":"Come sempre","de":"wie immer (typisch!)","note":"Oft mit einem Augenzwinkern, wenn jemand immer dasselbe macht.","ex":"Davide è arrivato tardi, come al solito.","exDe":"Davide ist zu spät gekommen, wie immer.","alt":[]},{"it":"Che ridere!","book":"È molto divertente.","de":"Zum Totlachen!","note":"Wenn etwas richtig komisch war. Unter Freunden sehr häufig.","ex":"Lukas è caduto in acqua. Che ridere!","exDe":"Lukas ist ins Wasser gefallen. Zum Totlachen!","alt":[]},{"it":"Che invidia!","book":"","de":"Da werd ich neidisch!","note":"Freundlich gemeint, wenn jemand von etwas Schönem erzählt. Gerne auch: Beati voi!","ex":"Siete stati al lago? Che invidia!","exDe":"Ihr wart am See? Da werd ich ja neidisch!","alt":[]},{"it":"una gita fuori porta","book":"una breve gita","de":"ein kurzer Ausflug ins Grüne","note":"Ein Tagesausflug raus aus der Stadt, typisch am Wochenende. Wörtlich: ein Ausflug vor das Stadttor.","ex":"Domenica facciamo una gita fuori porta?","exDe":"Machen wir am Sonntag einen Ausflug ins Grüne?","alt":["la gita fuori porta"]},{"it":"Siamo stati benissimo.","book":"Abbiamo passato un bel fine settimana.","de":"Wir hatten eine super Zeit.","note":"So sagen Italiener, dass es schön war. Für dich allein: Sono stato benissimo (als Frau: stata).","ex":"Grazie di tutto, siamo stati benissimo!","exDe":"Danke für alles, wir hatten eine super Zeit!","alt":["Sono stato benissimo.","Sono stata benissimo."]},{"it":"Mannaggia!","book":"","de":"So ein Mist!","note":"Typisch für Mittelitalien und den Süden, wird aber überall verstanden. Ganz harmlos, auch Omas sagen das.","ex":"Mannaggia, ho perso il battello!","exDe":"So ein Mist, ich hab das Schiff verpasst!","alt":[]}],"speak":[{"sit":"Ein Kollege fragt, was du am Wochenende gemacht hast. Du bist an den Gardasee gefahren.","answers":["Sono andato al lago di Garda.","Sono stato sul Garda con Giulia."],"tip":"Als Frau sagst du: sono andata, sono stata."},{"sit":"Giulia kommt von einem Ausflug zurück. Frag sie, wie es war.","answers":["Com'è andata?","Allora, com'è andata la gita?","Ti è piaciuta la gita?"],"tip":""},{"sit":"Erzähl, dass ihr am Samstag früh losgefahren und um zehn angekommen seid.","answers":["Siamo partiti sabato presto e siamo arrivati alle dieci.","Sabato mattina siamo partiti presto e alle dieci siamo arrivati."],"tip":""},{"sit":"Davide erzählt, dass er eine Woche am Meer war. Reagier ein bisschen neidisch.","answers":["Che invidia!","Beato te! Che invidia!"],"tip":"'Beato te!' heißt: Du Glücklicher!"},{"sit":"Du warst mit Giulia bei Freunden auf dem Land. Bedank dich beim Abschied und sag, dass ihr eine tolle Zeit hattet.","answers":["Grazie di tutto, siamo stati benissimo!","Grazie! È stato bellissimo."],"tip":"Italiener sagen 'siamo stati benissimo', nicht 'abbiamo avuto un bel tempo'."},{"sit":"Jemand fragt, was du am Sonntag gemacht hast. Du warst den ganzen Tag zu Hause.","answers":["Sono restato a casa tutto il giorno.","Niente di speciale, sono rimasto a casa."],"tip":"Statt restare hörst du genauso oft rimanere: sono rimasto."}]},{"id":17,"title":"Facciamo shopping","titleDe":"Shoppen gehen","goal":"Du kannst Kleidung kaufen, nach Größe und Farbe fragen und Dinge miteinander vergleichen.","intro":"Italien ist das Land der Mode! Diese Woche lernst du Kleidung, Farben und alles, was du im Geschäft brauchst. Außerdem kannst du bald sagen, was dir besser gefällt und was weniger kostet.","culture":"Bei Damenmode sind italienische Größen anders: Eine deutsche 38 entspricht in Italien meist einer 44. Herrengrößen und Schuhgrößen sind fast gleich. Die 'saldi', der große Schlussverkauf, beginnen Anfang Januar und Anfang Juli. Dann gibt es oft 30 bis 50 Prozent Rabatt.","vocab":[{"it":"la giacca","de":"die Jacke; das Sakko","alt":[],"note":"Plural: le giacche.","ex":"Questa giacca è molto bella.","exDe":"Diese Jacke ist sehr schön."},{"it":"la maglietta","de":"das Shirt (kurze Ärmel)","alt":[],"note":"","ex":"Ho comprato una maglietta bianca.","exDe":"Ich habe ein weißes Shirt gekauft."},{"it":"la camicia","de":"das Hemd; die Bluse","alt":[],"note":"Plural: le camicie.","ex":"Lukas porta una camicia azzurra.","exDe":"Lukas trägt ein hellblaues Hemd."},{"it":"i pantaloni","de":"die Hose","alt":[],"note":"Im Italienischen immer Plural.","ex":"Questi pantaloni sono troppo lunghi.","exDe":"Diese Hose ist zu lang."},{"it":"il vestito","de":"das Kleid; der Anzug","alt":[],"note":"","ex":"Giulia ha un vestito elegante.","exDe":"Giulia hat ein elegantes Kleid."},{"it":"la gonna","de":"der Rock","alt":[],"note":"","ex":"La gonna nera costa poco.","exDe":"Der schwarze Rock kostet wenig."},{"it":"le scarpe","de":"die Schuhe","alt":[],"note":"Singular: la scarpa.","ex":"Queste scarpe sono comode.","exDe":"Diese Schuhe sind bequem."},{"it":"il maglione","de":"der Pullover","alt":[],"note":"","ex":"Questo maglione è caldo.","exDe":"Dieser Pullover ist warm."},{"it":"il cappotto","de":"der Mantel","alt":[],"note":"","ex":"Fa freddo, prendo il cappotto.","exDe":"Es ist kalt, ich nehme den Mantel."},{"it":"la taglia","de":"die Größe (Kleidung)","alt":[],"note":"Bei Schuhen sagt man il numero.","ex":"Avete una taglia più grande?","exDe":"Haben Sie eine größere Größe?"},{"it":"provare","de":"anprobieren; probieren","alt":[],"note":"Posso provare? = Darf ich anprobieren?","ex":"Posso provare questa giacca?","exDe":"Kann ich diese Jacke anprobieren?"},{"it":"il camerino","de":"die Umkleidekabine","alt":[],"note":"","ex":"Il camerino è lì a destra.","exDe":"Die Umkleidekabine ist da rechts."},{"it":"rosso","de":"rot","alt":[],"note":"feminin: rossa.","ex":"Mi piace il vestito rosso.","exDe":"Mir gefällt das rote Kleid."},{"it":"blu","de":"blau (dunkelblau)","alt":[],"note":"Unveränderlich: la giacca blu, i pantaloni blu.","ex":"La giacca blu è elegante.","exDe":"Die blaue Jacke ist elegant."},{"it":"verde","de":"grün","alt":[],"note":"feminin auch verde. Plural: verdi.","ex":"Mi piacciono le scarpe verdi.","exDe":"Mir gefallen die grünen Schuhe."},{"it":"giallo","de":"gelb","alt":[],"note":"feminin: gialla.","ex":"Il giallo ti sta benissimo!","exDe":"Gelb steht dir super!"},{"it":"nero","de":"schwarz","alt":[],"note":"feminin: nera.","ex":"Il nero sta bene con tutto.","exDe":"Schwarz passt zu allem."},{"it":"bianco","de":"weiß","alt":[],"note":"feminin: bianca. Plural: bianchi, bianche.","ex":"Vorrei una camicia bianca.","exDe":"Ich hätte gern ein weißes Hemd."},{"it":"grigio","de":"grau","alt":[],"note":"feminin: grigia. Plural: grigi, grigie.","ex":"Oggi il cielo è grigio.","exDe":"Heute ist der Himmel grau."},{"it":"marrone","de":"braun","alt":[],"note":"feminin auch marrone. Plural: marroni.","ex":"Porto le scarpe marroni.","exDe":"Ich trage die braunen Schuhe."},{"it":"rosa","de":"rosa","alt":[],"note":"Unveränderlich: le magliette rosa.","ex":"Giulia ha una maglietta rosa.","exDe":"Giulia hat ein rosa Shirt."},{"it":"azzurro","de":"hellblau; himmelblau","alt":[],"note":"feminin: azzurra. Die italienische Nationalmannschaft heißt gli Azzurri.","ex":"Quella camicia azzurra ti sta bene.","exDe":"Das hellblaue Hemd da steht dir gut."},{"it":"arancione","de":"orange","alt":[],"note":"Plural: arancioni.","ex":"Davide porta una sciarpa arancione.","exDe":"Davide trägt einen orangefarbenen Schal."},{"it":"viola","de":"lila; violett","alt":[],"note":"Unveränderlich: i pantaloni viola. Die Farbe der Fiorentina, des Fußballklubs von Firenze.","ex":"La maglietta viola costa dieci euro.","exDe":"Das lila Shirt kostet zehn Euro."},{"it":"Mi sta bene?","de":"Steht mir das?","alt":[],"note":"Ti sta bene = es steht dir gut.","ex":"Questa giacca mi sta bene?","exDe":"Steht mir diese Jacke?"},{"it":"Che taglia porta?","de":"Welche Größe tragen Sie?","alt":["Che taglia porti?"],"note":"Zu Freunden: Che taglia porti?","ex":"Buongiorno! Che taglia porta?","exDe":"Guten Tag! Welche Größe tragen Sie?"},{"it":"Lo prendo.","de":"Ich nehme es.","alt":["La prendo."],"note":"Bei femininen Dingen: la prendo (la giacca).","ex":"Perfetto, lo prendo!","exDe":"Perfekt, ich nehme ihn!"},{"it":"lo sconto","de":"der Rabatt","alt":[],"note":"","ex":"C'è uno sconto del venti per cento.","exDe":"Es gibt zwanzig Prozent Rabatt."},{"it":"i saldi","de":"der Schlussverkauf","alt":[],"note":"Immer Plural.","ex":"A gennaio ci sono i saldi.","exDe":"Im Januar ist Schlussverkauf."},{"it":"di pelle","de":"aus Leder","alt":[],"note":"la pelle = das Leder; auch die Haut.","ex":"Questa giacca è di pelle.","exDe":"Diese Jacke ist aus Leder."},{"it":"stretto","de":"eng","alt":[],"note":"feminin: stretta.","ex":"Questi pantaloni sono stretti.","exDe":"Diese Hose ist eng."},{"it":"largo","de":"weit","alt":[],"note":"feminin: larga. Achtung: largo heißt nicht lang!","ex":"La giacca è un po' larga.","exDe":"Die Jacke ist ein bisschen weit."},{"it":"la sciarpa","de":"der Schal","alt":[],"note":"","ex":"Mi piace questa sciarpa.","exDe":"Mir gefällt dieser Schal."},{"it":"il cappello","de":"der Hut","alt":[],"note":"","ex":"Al mare porto il cappello.","exDe":"Am Meer trage ich einen Hut."},{"it":"la borsa","de":"die Tasche; die Handtasche","alt":[],"note":"Plural: le borse.","ex":"Questa borsa costa troppo.","exDe":"Diese Tasche kostet zu viel."},{"it":"la commessa","de":"die Verkäuferin","alt":[],"note":"Maskulin: il commesso.","ex":"La commessa è molto gentile.","exDe":"Die Verkäuferin ist sehr nett."}],"grammar":{"title":"questo, quello und Vergleiche","points":["<b>questo</b> zeigt auf etwas in deiner Nähe (dieser hier), <b>quello</b> auf etwas weiter weg (der da). questo hat die normalen Endungen: <b>questo, questa, questi, queste</b>. Vor Vokal oft kurz: <b>quest'estate</b>.","<b>quello</b> vor einem Nomen verhält sich wie der bestimmte Artikel: il → <b>quel</b>, lo → <b>quello</b>, l' → <b>quell'</b>, la → <b>quella</b>, i → <b>quei</b>, gli → <b>quegli</b>, le → <b>quelle</b>. Ohne Nomen: quello, quella, quelli, quelle.","Vergleichen: <b>più</b> ... <b>di</b> = mehr ... als, <b>meno</b> ... <b>di</b> = weniger ... als. di verbindet sich mit dem Artikel: La giacca è <b>più</b> cara <b>del</b> cappotto. Vor Namen steht nur <b>di</b>: Firenze è più piccola <b>di</b> Milano.","Gleich viel: <b>come</b> = so ... wie. Lukas è alto <b>come</b> Davide. Merkregel: Im Deutschen sagst du als, im Italienischen <b>di</b>."],"table":{"head":["Artikel","quello","Beispiel"],"rows":[["il","quel","quel cappotto"],["lo","quello","quello zaino"],["l'","quell'","quell'ombrello"],["la","quella","quella gonna"],["i","quei","quei pantaloni"],["gli","quegli","quegli occhiali"],["le","quelle","quelle scarpe"]]},"examples":[{"it":"Questa giacca è bellissima.","de":"Diese Jacke ist wunderschön."},{"it":"Quel cappotto costa troppo.","de":"Der Mantel da kostet zu viel."},{"it":"La giacca nera è più cara della giacca blu.","de":"Die schwarze Jacke ist teurer als die blaue."},{"it":"Questa maglietta costa meno di quella.","de":"Dieses Shirt kostet weniger als das da."},{"it":"Lukas è alto come Davide.","de":"Lukas ist so groß wie Davide."},{"it":"Firenze è più piccola di Milano.","de":"Firenze ist kleiner als Milano."}],"drills":[{"type":"choice","q":"___ scarpe sono molto belle.","de":"Diese Schuhe sind sehr schön.","options":["Questo","Queste","Questi"],"answer":1,"why":"scarpe ist feminin Plural: queste."},{"type":"type","q":"Ti piace ___ cappotto? (quello)","de":"Gefällt dir der Mantel da?","answer":"quel","alt":[],"why":"il cappotto → quel cappotto."},{"type":"choice","q":"Mi piacciono ___ pantaloni.","de":"Mir gefällt die Hose da.","options":["quegli","quelli","quei"],"answer":2,"why":"i pantaloni → quei pantaloni."},{"type":"type","q":"La giacca rossa è più cara ___ giacca verde.","de":"Die rote Jacke ist teurer als die grüne.","answer":"della","alt":[],"why":"di + la = della."},{"type":"choice","q":"Le scarpe nere costano ___ delle scarpe marroni.","de":"Die schwarzen Schuhe kosten weniger als die braunen.","options":["meno","come","di"],"answer":0,"why":"weniger ... als = meno ... di."},{"type":"type","q":"Il vestito rosso è bello ___ il vestito blu.","de":"Das rote Kleid ist so schön wie das blaue.","answer":"come","alt":["quanto"],"why":"so ... wie = come."},{"type":"choice","q":"Mi piace ___ ombrello giallo.","de":"Mir gefällt der gelbe Regenschirm da.","options":["quel","quello","quell'"],"answer":2,"why":"l'ombrello → quell'ombrello."},{"type":"type","q":"Quale gonna preferisci? ___ o quella?","de":"Welchen Rock magst du lieber? Diesen hier oder den da?","answer":"questa","alt":[],"why":"la gonna ist feminin: questa."}]},"dialog":{"title":"Una giacca di pelle","setting":"Giulia besucht Lukas in Firenze. In einem Lederwarengeschäft sucht er mit ihr eine Jacke.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Giulia","gender":"f"},"C":{"name":"Commessa","gender":"f"}},"lines":[{"s":"C","it":"Buongiorno! Cercate qualcosa?","de":"Guten Tag! Suchen Sie etwas?"},{"s":"A","it":"Sì, una giacca di pelle. Porto la 50.","de":"Ja, eine Lederjacke. Ich hab Größe 50."},{"s":"B","it":"Guarda quella marrone, Lukas. Ti piace?","de":"Schau mal die braune da, Lukas. Gefällt sie dir?"},{"s":"A","it":"Mah, non mi convince. Questa nera è più elegante.","de":"Hm, die überzeugt mich nicht. Die schwarze hier ist eleganter."},{"s":"C","it":"La vuole provare? Il camerino è lì in fondo.","de":"Möchten Sie sie anprobieren? Die Kabine ist dahinten."},{"s":"A","it":"Allora, Giulia? Come mi sta?","de":"Und, Giulia? Wie steht sie mir?"},{"s":"B","it":"Ti sta benissimo! Però è un po' stretta, no?","de":"Steht dir super! Aber sie ist ein bisschen eng, oder?"},{"s":"C","it":"Non c'è problema, ecco la 52. È più larga di quella.","de":"Kein Problem, hier ist die 52. Die ist weiter als die andere."},{"s":"A","it":"Ah, questa sì! Quanto costa?","de":"Ah, die ist es! Was kostet sie?"},{"s":"C","it":"180 euro, ma oggi c'è il venti per cento di sconto.","de":"180 Euro, aber heute gibt's zwanzig Prozent Rabatt."},{"s":"B","it":"Quindi sono solo 144 euro. Che affare!","de":"Dann sind es nur 144 Euro. Ein echtes Schnäppchen!"},{"s":"A","it":"Perfetto, la prendo!","de":"Perfekt, ich nehm sie!"}],"questions":[{"q":"Was für eine Jacke sucht Lukas?","options":["Eine Lederjacke","Eine Regenjacke","Eine Jeansjacke"],"answer":0},{"q":"Warum probiert Lukas eine zweite Jacke an?","options":["Die erste ist zu teuer","Die erste ist ein bisschen eng","Die erste gefällt Giulia nicht"],"answer":1},{"q":"Wie viel zahlt Lukas?","options":["180 Euro","120 Euro","144 Euro"],"answer":2}]},"sentences":[{"it":"Dov'è il camerino, per favore?","de":"Wo ist die Umkleidekabine, bitte?"},{"it":"Questa maglietta è più bella di quella.","de":"Dieses Shirt ist schöner als das da."},{"it":"Quel vestito rosso è bellissimo.","de":"Das rote Kleid da ist wunderschön."},{"it":"Avete questa giacca in blu?","de":"Haben Sie diese Jacke in Blau?"},{"it":"Le scarpe costano meno dei pantaloni.","de":"Die Schuhe kosten weniger als die Hose."},{"it":"Questa camicia non mi sta bene.","de":"Dieses Hemd steht mir nicht."},{"it":"Giulia è elegante come sua madre.","de":"Giulia ist so elegant wie ihre Mutter."},{"it":"Vorrei una taglia più piccola, per favore.","de":"Ich hätte gern eine kleinere Größe, bitte."}],"spoken":[{"it":"Costa un occhio della testa.","book":"È molto caro.","de":"Das kostet ein Vermögen.","note":"Wörtlich: Es kostet ein Auge vom Kopf. Locker und bildhaft, überall verstanden.","ex":"Quella borsa? Costa un occhio della testa!","exDe":"Die Tasche da? Die kostet ein Vermögen!","alt":["Costa un occhio."]},{"it":"Non c'è problema.","book":"Sì, è possibile.","de":"Klar, kein Problem.","note":"Genauso häufig wie Nessun problema. Im Laden hörst du es ständig, wenn du etwas anprobieren oder umtauschen willst.","ex":"Posso provare la 48? Certo, non c'è problema!","exDe":"Kann ich die 48 anprobieren? Klar, kein Problem!","alt":["Nessun problema."]},{"it":"Do solo un'occhiata.","book":"Guardo solamente.","de":"Ich schau mich nur um.","note":"Die Standardantwort, wenn dich im Laden jemand anspricht und du nur schauen willst. Mit einem grazie klingt es freundlich.","ex":"Posso aiutarla? No, grazie, do solo un'occhiata.","exDe":"Kann ich Ihnen helfen? Nein danke, ich schau mich nur um.","alt":["Sto solo guardando."]},{"it":"Che affare!","book":"È molto economico.","de":"Was für ein Schnäppchen!","note":"Wenn du etwas richtig günstig bekommst. Bei den saldi hörst du es oft.","ex":"Cinquanta per cento di sconto? Che affare!","exDe":"Fünfzig Prozent Rabatt? Was für ein Schnäppchen!","alt":[]},{"it":"Ti sta a pennello!","book":"Ti sta molto bene.","de":"Das sitzt wie angegossen!","note":"Wörtlich: wie mit dem Pinsel gemalt. Höflich zu Fremden: Le sta a pennello!","ex":"Questa giacca ti sta a pennello!","exDe":"Die Jacke sitzt bei dir wie angegossen!","alt":["Le sta a pennello!"]},{"it":"Mi fa uno sconticino?","book":"Posso avere uno sconto?","de":"Geht da noch was am Preis?","note":"sconticino ist die Verkleinerung von sconto und klingt charmant. Auf dem Markt ganz normal, in Boutiquen eher selten.","ex":"Prendo due magliette. Mi fa uno sconticino?","exDe":"Ich nehme zwei Shirts. Geht da noch was am Preis?","alt":["Mi fa uno sconto?"]},{"it":"Va di moda.","book":"È di moda.","de":"Das ist gerade angesagt.","note":"Für alles, was gerade in ist. Gegenteil: Non va più di moda.","ex":"Quest'anno va di moda il verde.","exDe":"Dieses Jahr ist Grün angesagt.","alt":[]},{"it":"Non mi convince.","book":"Non mi piace molto.","de":"Das überzeugt mich nicht.","note":"Ehrlich, aber höflich: So sagst du, dass dir etwas nicht richtig gefällt. Im Laden und unter Freunden.","ex":"Questo colore non mi convince.","exDe":"Die Farbe überzeugt mich nicht.","alt":[]}],"speak":[{"sit":"Eine Verkäuferin fragt, ob sie dir helfen kann. Du willst dich nur umschauen.","answers":["No, grazie, do solo un'occhiata.","Grazie, sto solo guardando."],"tip":"Mit einem Lächeln und 'grazie' ist das ganz normal."},{"sit":"Du hast eine schöne Jacke gefunden. Frag, ob du sie anprobieren kannst und wo die Umkleide ist.","answers":["Posso provarla? Dov'è il camerino?","La posso provare? Dov'è il camerino?","Posso provare questa giacca? Dov'è il camerino?"],"tip":"la giacca ist feminin, also: provarla."},{"sit":"Die Hose ist dir zu eng. Frag nach einer größeren Größe.","answers":["Sono un po' stretti. Avete una taglia più grande?","Mi stanno stretti. Avete la taglia sopra?"],"tip":"i pantaloni sind Plural, also stretti. Im Laden hörst du oft 'la taglia sopra'."},{"sit":"Giulia probiert ein Kleid an. Sag ihr, dass es ihr super steht und schöner ist als das rote.","answers":["Ti sta benissimo! È più bello di quello rosso.","Ti sta a pennello! Questo è più bello di quello rosso."],"tip":""},{"sit":"Ein Mantel kostet 400 Euro. Sag Giulia, dass er viel zu teuer ist.","answers":["È troppo caro!","Quattrocento euro? Costa un occhio della testa!"],"tip":""},{"sit":"Du kaufst auf dem Markt zwei Schals. Frag charmant nach einem kleinen Rabatt.","answers":["Mi fa uno sconticino?","Prendo queste due sciarpe. Mi fa uno sconto?"],"tip":"Auf Märkten ist Handeln normal, in Boutiquen eher nicht."}]},{"id":18,"title":"Come ti senti?","titleDe":"Wie fühlst du dich?","goal":"Du kannst sagen, was dir wehtut, in der Apotheke um Hilfe bitten und deinen Tagesablauf beschreiben.","intro":"Krank im Urlaub ist ärgerlich, aber mit den richtigen Wörtern bekommst du schnell Hilfe. Diese Woche lernst du den Körper, typische Beschwerden und was du in der Apotheke sagst. Dazu kommen reflexive Verben wie aufstehen und sich ausruhen.","culture":"Italienische Apotheken erkennst du am grünen Kreuz. Die Apotheker beraten dich gern und bei leichten Beschwerden brauchst du oft gar keinen Arzt. Nachts und am Sonntag hat immer eine 'farmacia di turno' offen. Welche das ist, steht meist an der Tür jeder Apotheke.","vocab":[{"it":"Come ti senti?","de":"Wie fühlst du dich?","alt":[],"note":"Höflich: Come si sente?","ex":"Ciao Lukas, come ti senti oggi?","exDe":"Hallo Lukas, wie fühlst du dich heute?"},{"it":"sentirsi","de":"sich fühlen","alt":[],"note":"mi sento, ti senti, si sente ...","ex":"Non mi sento bene.","exDe":"Ich fühle mich nicht gut."},{"it":"mi fa male","de":"es tut mir weh","alt":[],"note":"Bei mehreren Dingen: mi fanno male i piedi.","ex":"Mi fa male la testa.","exDe":"Mir tut der Kopf weh."},{"it":"la testa","de":"der Kopf","alt":[],"note":"","ex":"Mi gira la testa.","exDe":"Mir ist schwindelig."},{"it":"la gola","de":"der Hals (innen); die Kehle","alt":[],"note":"","ex":"Bevo un tè caldo per la gola.","exDe":"Ich trinke einen heißen Tee für den Hals."},{"it":"la pancia","de":"der Bauch","alt":[],"note":"","ex":"Ho mangiato troppo, mi fa male la pancia.","exDe":"Ich habe zu viel gegessen, mir tut der Bauch weh."},{"it":"il mal di testa","de":"die Kopfschmerzen","alt":["mal di testa"],"note":"Ohne Artikel: ho mal di testa.","ex":"Ho mal di testa da stamattina.","exDe":"Ich habe seit heute Morgen Kopfschmerzen."},{"it":"il mal di gola","de":"die Halsschmerzen","alt":["mal di gola"],"note":"Ohne Artikel: ho mal di gola.","ex":"Hai mal di gola?","exDe":"Hast du Halsschmerzen?"},{"it":"il raffreddore","de":"die Erkältung; der Schnupfen","alt":[],"note":"Ho il raffreddore = ich bin erkältet.","ex":"Lukas ha il raffreddore.","exDe":"Lukas ist erkältet."},{"it":"la febbre","de":"das Fieber","alt":[],"note":"","ex":"Ho la febbre a trentotto.","exDe":"Ich habe achtunddreißig Fieber."},{"it":"la tosse","de":"der Husten","alt":[],"note":"","ex":"Ho la tosse da tre giorni.","exDe":"Ich habe seit drei Tagen Husten."},{"it":"il medico","de":"der Arzt; die Ärztin","alt":["il dottore"],"note":"Anrede: dottore oder dottoressa. Plural: i medici.","ex":"Devi andare dal medico.","exDe":"Du musst zum Arzt gehen."},{"it":"il braccio","de":"der Arm","alt":[],"note":"Unregelmäßiger Plural: le braccia.","ex":"Matteo ha il braccio rotto.","exDe":"Matteo hat einen gebrochenen Arm."},{"it":"la mano","de":"die Hand","alt":[],"note":"Feminin, obwohl es auf o endet. Plural: le mani.","ex":"Mi lavo le mani.","exDe":"Ich wasche mir die Hände."},{"it":"la gamba","de":"das Bein","alt":[],"note":"","ex":"Mi fanno male le gambe.","exDe":"Mir tun die Beine weh."},{"it":"il piede","de":"der Fuß","alt":[],"note":"Plural: i piedi. A piedi = zu Fuß.","ex":"Andiamo a piedi?","exDe":"Gehen wir zu Fuß?"},{"it":"la schiena","de":"der Rücken","alt":[],"note":"sch klingt hier wie sk: skie na.","ex":"Ho mal di schiena.","exDe":"Ich habe Rückenschmerzen."},{"it":"lo stomaco","de":"der Magen","alt":[],"note":"Plural: gli stomaci.","ex":"Non mangio, ho mal di stomaco.","exDe":"Ich esse nichts, ich habe Magenschmerzen."},{"it":"il naso","de":"die Nase","alt":[],"note":"","ex":"Ho il naso chiuso.","exDe":"Meine Nase ist zu."},{"it":"la bocca","de":"der Mund","alt":[],"note":"Plural: le bocche.","ex":"Ho la bocca secca.","exDe":"Ich habe einen trockenen Mund."},{"it":"l'orecchio","de":"das Ohr","alt":["orecchio"],"note":"Maskulin. Plural meist: le orecchie.","ex":"Non sento bene da un orecchio.","exDe":"Ich höre auf einem Ohr schlecht."},{"it":"gli occhi","de":"die Augen","alt":["occhi"],"note":"Singular: l'occhio (maskulin).","ex":"Mi bruciano gli occhi.","exDe":"Mir brennen die Augen."},{"it":"i capelli","de":"die Haare (auf dem Kopf)","alt":[],"note":"Singular: il capello.","ex":"Mi lavo i capelli la sera.","exDe":"Ich wasche mir abends die Haare."},{"it":"il dente","de":"der Zahn","alt":[],"note":"Plural: i denti. Il dentista = der Zahnarzt.","ex":"Ho mal di denti.","exDe":"Ich habe Zahnschmerzen."},{"it":"svegliarsi","de":"aufwachen","alt":[],"note":"mi sveglio, ti svegli, si sveglia ...","ex":"Mi sveglio alle sette.","exDe":"Ich wache um sieben auf."},{"it":"alzarsi","de":"aufstehen","alt":[],"note":"mi alzo, ti alzi, si alza ...","ex":"Giulia si alza presto.","exDe":"Giulia steht früh auf."},{"it":"riposarsi","de":"sich ausruhen","alt":[],"note":"","ex":"Oggi devi riposarti.","exDe":"Heute musst du dich ausruhen."},{"it":"lavarsi","de":"sich waschen","alt":[],"note":"","ex":"Mi lavo i denti e vado a letto.","exDe":"Ich putze mir die Zähne und gehe ins Bett."},{"it":"vestirsi","de":"sich anziehen","alt":[],"note":"mi vesto, ti vesti, si veste ...","ex":"Mi vesto e vado al lavoro.","exDe":"Ich ziehe mich an und gehe zur Arbeit."},{"it":"addormentarsi","de":"einschlafen","alt":[],"note":"","ex":"La sera mi addormento subito.","exDe":"Abends schlafe ich sofort ein."},{"it":"la medicina","de":"das Medikament; die Medizin","alt":[],"note":"","ex":"Prendo la medicina dopo cena.","exDe":"Ich nehme das Medikament nach dem Abendessen."},{"it":"la compressa","de":"die Tablette","alt":["la pastiglia"],"note":"Auch: la pastiglia.","ex":"Una compressa al giorno.","exDe":"Eine Tablette pro Tag."},{"it":"lo sciroppo","de":"der Hustensaft; der Sirup","alt":[],"note":"","ex":"Hai preso lo sciroppo per la tosse?","exDe":"Hast du den Hustensaft genommen?"},{"it":"l'influenza","de":"die Grippe","alt":["influenza"],"note":"Feminin.","ex":"Matteo ha l'influenza.","exDe":"Matteo hat die Grippe."},{"it":"Buona guarigione!","de":"Gute Besserung!","alt":[],"note":"","ex":"Ciao Lukas, buona guarigione!","exDe":"Tschüss Lukas, gute Besserung!"},{"it":"il cerotto","de":"das Pflaster","alt":[],"note":"","ex":"Hai un cerotto?","exDe":"Hast du ein Pflaster?"}],"grammar":{"title":"Reflexive Verben","points":["Manche Verben haben ein kleines Pronomen, das auf die Person selbst zurückzeigt, wie sich im Deutschen. Im Infinitiv hängt es als <b>si</b> am Ende: <b>lavarsi</b> = sich waschen. Im Italienischen sind mehr Verben reflexiv als im Deutschen: <b>alzarsi</b> = aufstehen.","Beim Konjugieren fällt <b>si</b> am Ende weg und das passende Pronomen steht vor dem Verb: <b>mi, ti, si, ci, vi, si</b>. Das Verb konjugierst du ganz normal: <b>mi alzo, ti alzi, si alza</b>. Du kennst das schon von <b>mi chiamo</b>.","<b>non</b> steht vor dem Pronomen: <b>Non mi sento bene.</b> Nach dovere oder volere hängt das Pronomen meist am Infinitiv, immer passend zur Person: <b>Devo riposarmi.</b> <b>Devi riposarti.</b> Auch möglich: <b>Mi devo riposare.</b>","Für Schmerzen gibt es zwei Wege: <b>Ho mal di testa.</b> oder <b>Mi fa male la testa.</b> Bei mehreren Dingen heißt es <b>fanno</b>: <b>Mi fanno male i piedi.</b>"],"table":{"head":["Person","alzarsi","sentirsi"],"rows":[["io","mi alzo","mi sento"],["tu","ti alzi","ti senti"],["lui / lei / Lei","si alza","si sente"],["noi","ci alziamo","ci sentiamo"],["voi","vi alzate","vi sentite"],["loro","si alzano","si sentono"]]},"examples":[{"it":"Mi sveglio alle sette e mi alzo subito.","de":"Ich wache um sieben auf und stehe sofort auf."},{"it":"Giulia si veste in cinque minuti.","de":"Giulia zieht sich in fünf Minuten an."},{"it":"Come ti senti oggi?","de":"Wie fühlst du dich heute?"},{"it":"La domenica ci riposiamo.","de":"Sonntags ruhen wir uns aus."},{"it":"Non mi sento bene, ho la febbre.","de":"Ich fühle mich nicht gut, ich habe Fieber."},{"it":"Devi riposarti un po'.","de":"Du musst dich ein bisschen ausruhen."}],"drills":[{"type":"choice","q":"Io ___ alzo alle sette.","de":"Ich stehe um sieben auf.","options":["ti","mi","si"],"answer":1,"why":"io → mi."},{"type":"type","q":"Come ___ senti, Lukas?","de":"Wie fühlst du dich, Lukas?","answer":"ti","alt":[],"why":"tu → ti."},{"type":"choice","q":"Giulia e Matteo ___ svegliano tardi.","de":"Giulia und Matteo wachen spät auf.","options":["si","ci","vi"],"answer":0,"why":"loro → si."},{"type":"type","q":"Noi ___ riposiamo un po'.","de":"Wir ruhen uns ein bisschen aus.","answer":"ci","alt":[],"why":"noi → ci."},{"type":"choice","q":"Io oggi non ___ bene.","de":"Heute fühle ich mich nicht gut.","options":["si sente","ti senti","mi sento"],"answer":2,"why":"io → mi sento."},{"type":"type","q":"Lukas si ___ alle otto. (alzarsi)","de":"Lukas steht um acht auf.","answer":"alza","alt":[],"why":"lui → si alza."},{"type":"choice","q":"Devo ___ un po'.","de":"Ich muss mich ein bisschen ausruhen.","options":["riposarmi","riposarsi","riposarti"],"answer":0,"why":"Das Pronomen passt zur Person: io → riposarmi."},{"type":"type","q":"A che ora vi ___? (svegliarsi)","de":"Um wie viel Uhr wacht ihr auf?","answer":"svegliate","alt":[],"why":"voi → vi svegliate."}]},"dialog":{"title":"In farmacia","setting":"Lukas ist wieder in Bologna bei Giulias Familie. Er ist erkältet und geht in eine Apotheke.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Farmacista","gender":"f"}},"lines":[{"s":"B","it":"Buongiorno! Mi dica.","de":"Guten Tag! Was darf's sein?"},{"s":"A","it":"Buongiorno. Eh, non mi sento bene, ho il raffreddore.","de":"Guten Tag. Tja, mir geht's nicht gut, ich bin erkältet."},{"s":"B","it":"Ah, mi dispiace. Ha anche la febbre?","de":"Oh, das tut mir leid. Haben Sie auch Fieber?"},{"s":"A","it":"Penso di sì, un pochino. E mi fa male la gola.","de":"Ich glaub schon, ein bisschen. Und der Hals tut mir weh."},{"s":"B","it":"E la tosse?","de":"Und Husten?"},{"s":"A","it":"Sì, soprattutto di notte. Non ho chiuso occhio!","de":"Ja, vor allem nachts. Ich hab kein Auge zugemacht!"},{"s":"B","it":"Allora, per la tosse c'è questo sciroppo. Due volte al giorno.","de":"Also, gegen den Husten gibt's diesen Sirup. Zweimal am Tag."},{"s":"A","it":"Perfetto. E per la febbre?","de":"Gut. Und gegen das Fieber?"},{"s":"B","it":"Queste compresse, una ogni otto ore. E deve riposarsi, mi raccomando!","de":"Diese Tabletten, eine alle acht Stunden. Und ruhen Sie sich unbedingt aus!"},{"s":"A","it":"Va bene, promesso. Quant'è?","de":"Mach ich, versprochen. Was macht das?"},{"s":"B","it":"Dodici e cinquanta. Ecco a Lei, e buona guarigione!","de":"Zwölf fünfzig. Bitte schön. Und gute Besserung!"},{"s":"A","it":"Grazie mille, arrivederci!","de":"Vielen Dank, auf Wiedersehen!"}],"questions":[{"q":"Was hat Lukas?","options":["Bauchschmerzen","Eine Erkältung mit Fieber","Rückenschmerzen"],"answer":1},{"q":"Was bekommt Lukas gegen den Husten?","options":["Einen Sirup","Tabletten","Ein Pflaster"],"answer":0},{"q":"Was soll Lukas außerdem tun?","options":["Viel Sport machen","Sofort zum Arzt gehen","Sich ausruhen"],"answer":2}]},"sentences":[{"it":"Oggi non mi sento tanto bene.","de":"Heute geht's mir nicht so gut."},{"it":"Mi fanno male i piedi.","de":"Mir tun die Füße weh."},{"it":"Ho la febbre e la tosse.","de":"Ich habe Fieber und Husten."},{"it":"La mattina mi alzo alle sette.","de":"Morgens stehe ich um sieben auf."},{"it":"Giulia si riposa dopo il lavoro.","de":"Giulia ruht sich nach der Arbeit aus."},{"it":"Devo andare in farmacia.","de":"Ich muss in die Apotheke gehen."},{"it":"A che ora ti svegli?","de":"Um wie viel Uhr wachst du auf?"},{"it":"Ho mal di gola da ieri.","de":"Ich habe seit gestern Halsschmerzen."}],"spoken":[{"it":"Cos'hai?","book":"Che cosa hai?","de":"Was ist los mit dir?","note":"Im Alltag kürzt man che cosa einfach ab. Genauso häufig: Che hai?","ex":"Cos'hai, Lukas? Non ti senti bene?","exDe":"Was ist los, Lukas? Geht's dir nicht gut?","alt":["Che hai?","Che cos'hai?"]},{"it":"Sto da cani.","book":"Sto molto male.","de":"Mir geht's hundsmiserabel.","note":"Locker, unter Freunden und in der Familie. Wörtlich etwa: Mir geht's wie den Hunden.","ex":"Come ti senti oggi? Sto da cani!","exDe":"Wie fühlst du dich heute? Hundsmiserabel!","alt":[]},{"it":"Riguardati!","book":"Abbi cura di te.","de":"Schon dich!; Pass auf dich auf!","note":"Sagt man zu jemandem, der krank ist oder gerade wieder gesund wird. Von riguardarsi = sich schonen.","ex":"Hai ancora la febbre? Riguardati, eh!","exDe":"Hast du immer noch Fieber? Schon dich, ja?","alt":[]},{"it":"Ho preso freddo.","book":"Ho il raffreddore.","de":"Ich hab mich erkältet.","note":"So erklären Italiener fast jede Erkältung. Vor Zugluft, il colpo d'aria, haben viele großen Respekt.","ex":"Ieri al lago ho preso freddo.","exDe":"Gestern am See hab ich mich erkältet.","alt":[]},{"it":"Non ho chiuso occhio.","book":"Non ho dormito.","de":"Ich hab kein Auge zugemacht.","note":"Locker und überall üblich nach einer schlechten Nacht.","ex":"Con questa tosse non ho chiuso occhio.","exDe":"Mit diesem Husten hab ich kein Auge zugemacht.","alt":[]},{"it":"Niente di grave.","book":"Non è una cosa grave.","de":"Nichts Schlimmes.","note":"Damit beruhigst du andere, beim Arzt oder unter Freunden. Als Frage: Niente di grave?","ex":"È solo un raffreddore, niente di grave.","exDe":"Ist nur eine Erkältung, nichts Schlimmes.","alt":[]},{"it":"Salute!","book":"","de":"Gesundheit! (beim Niesen)","note":"Darauf antwortet man einfach: Grazie! Beim Anstoßen sagt man übrigens auch Salute!","ex":"Etciù! Salute, Lukas! Grazie!","exDe":"Hatschi! Gesundheit, Lukas! Danke!","alt":[]},{"it":"Mi raccomando!","book":"È importante!","de":"Denk dran!; Ganz wichtig!","note":"Sagen Mütter, Omas und Apotheker ständig, wenn ihnen etwas wichtig ist. Steht oft am Satzende.","ex":"Devi riposarti, mi raccomando!","exDe":"Du musst dich ausruhen, denk dran!","alt":[]}],"speak":[{"sit":"Du bist in der Apotheke. Sag, dass du Halsschmerzen und Husten hast.","answers":["Ho mal di gola e la tosse.","Mi fa male la gola e ho la tosse."],"tip":"Für Schmerzen gehen beide Wege: ho mal di ... oder mi fa male ..."},{"sit":"Giulia fragt, wie du dich heute fühlst. Dir geht es richtig schlecht.","answers":["Non mi sento bene.","Sto malissimo.","Sto da cani!"],"tip":"'Sto da cani' sagst du nur zu Freunden."},{"sit":"Der Arzt fragt, seit wann du Fieber hast. Du hast es seit gestern.","answers":["Da ieri.","Ho la febbre da ieri."],"tip":"Seit heißt hier da: da ieri, da tre giorni."},{"sit":"Davide niest neben dir.","answers":["Salute!","Salute! Hai il raffreddore?"],"tip":""},{"sit":"Erzähl, wann du morgens aufwachst und wann du aufstehst.","answers":["Mi sveglio alle sette e mi alzo subito.","Di solito mi sveglio alle sette e mi alzo alle sette e mezza."],"tip":"Das kleine Pronomen steht vor dem Verb: mi sveglio, mi alzo."},{"sit":"Giulia sieht krank aus. Frag sie, was los ist. Sag ihr dann, dass sie sich ausruhen muss.","answers":["Cos'hai? Devi riposarti.","Che hai? Ti devi riposare un po'."],"tip":""}]},{"id":19,"title":"A casa","titleDe":"Zu Hause","goal":"Du kannst eine Wohnung beschreiben, dich als Gast richtig verhalten und andere zu etwas auffordern.","intro":"Diese Woche bist du bei Giulias Familie zum Abendessen eingeladen. Du lernst Räume, Möbel und alles für den gedeckten Tisch. Dazu kommt der Imperativ, denn als Gast hörst du ständig: Komm! Setz dich! Nimm noch!","culture":"Wenn du in Italien zum Essen eingeladen bist, bringst du am besten etwas mit: Gebäck aus der Pasticceria, eine Flasche Wein oder Blumen. Das Essen hat oft mehrere Gänge, also iss beim Primo nicht zu viel! Mit einem Stück Brot die Soße vom Teller wischen heißt 'fare la scarpetta'. In eleganten Restaurants gilt das als unfein, in der Familie freut sich die Köchin meistens darüber.","vocab":[{"it":"l'appartamento","de":"die Wohnung","alt":["appartamento"],"note":"Maskulin. Plural: gli appartamenti.","ex":"Il mio appartamento è piccolo ma bello.","exDe":"Meine Wohnung ist klein, aber schön."},{"it":"la cucina","de":"die Küche","alt":[],"note":"Auch die Kochkunst: la cucina italiana.","ex":"La nonna è in cucina.","exDe":"Oma ist in der Küche."},{"it":"il soggiorno","de":"das Wohnzimmer","alt":["il salotto"],"note":"Auch: il salotto.","ex":"Ci sediamo in soggiorno?","exDe":"Setzen wir uns ins Wohnzimmer?"},{"it":"la camera da letto","de":"das Schlafzimmer","alt":[],"note":"Wörtlich: Zimmer zum Schlafen. Oft kurz: la camera.","ex":"La camera da letto è a destra.","exDe":"Das Schlafzimmer ist rechts."},{"it":"il balcone","de":"der Balkon","alt":[],"note":"","ex":"Mangiamo sul balcone stasera?","exDe":"Essen wir heute Abend auf dem Balkon?"},{"it":"il giardino","de":"der Garten","alt":[],"note":"","ex":"I bambini giocano in giardino.","exDe":"Die Kinder spielen im Garten."},{"it":"la sedia","de":"der Stuhl","alt":[],"note":"Plural: le sedie.","ex":"Prendi una sedia e siediti!","exDe":"Nimm einen Stuhl und setz dich!"},{"it":"il divano","de":"das Sofa","alt":[],"note":"","ex":"Stasera dormo sul divano.","exDe":"Heute Nacht schlafe ich auf dem Sofa."},{"it":"l'armadio","de":"der Schrank","alt":["armadio"],"note":"Maskulin. Vor allem der Kleiderschrank.","ex":"I vestiti sono nell'armadio.","exDe":"Die Kleider sind im Schrank."},{"it":"la finestra","de":"das Fenster","alt":[],"note":"","ex":"Apri la finestra, per favore!","exDe":"Mach bitte das Fenster auf!"},{"it":"la porta","de":"die Tür","alt":[],"note":"","ex":"Chiudi la porta, fa freddo!","exDe":"Mach die Tür zu, es ist kalt!"},{"it":"il frigorifero","de":"der Kühlschrank","alt":["il frigo"],"note":"Kurz: il frigo.","ex":"Il latte è nel frigorifero.","exDe":"Die Milch ist im Kühlschrank."},{"it":"la tavola","de":"der Tisch (zum Essen)","alt":[],"note":"Il tavolo ist das Möbelstück. La tavola ist der Tisch, an dem man isst: a tavola!","ex":"La tavola è già apparecchiata.","exDe":"Der Tisch ist schon gedeckt."},{"it":"apparecchiare","de":"den Tisch decken","alt":["apparecchiare la tavola"],"note":"Meist: apparecchiare la tavola.","ex":"Matteo, apparecchia tu, per favore!","exDe":"Matteo, deck du bitte den Tisch!"},{"it":"il piatto","de":"der Teller","alt":[],"note":"Auch: das Gericht. Plural: i piatti.","ex":"Metti i piatti in tavola!","exDe":"Stell die Teller auf den Tisch!"},{"it":"la forchetta","de":"die Gabel","alt":[],"note":"","ex":"Scusa, manca una forchetta.","exDe":"Entschuldige, es fehlt eine Gabel."},{"it":"il coltello","de":"das Messer","alt":[],"note":"","ex":"Questo coltello non taglia.","exDe":"Dieses Messer schneidet nicht."},{"it":"il cucchiaio","de":"der Löffel","alt":[],"note":"Aussprache: kuk kja io. Il cucchiaino = der Teelöffel.","ex":"Prendi un cucchiaio per il tiramisù!","exDe":"Nimm einen Löffel für das Tiramisu!"},{"it":"il tovagliolo","de":"die Serviette","alt":[],"note":"gli klingt wie lj: to va ljo lo.","ex":"Metti un tovagliolo accanto al piatto.","exDe":"Leg eine Serviette neben den Teller."},{"it":"l'ospite","de":"der Gast","alt":["ospite"],"note":"Maskulin und feminin: l'ospite. Plural: gli ospiti.","ex":"Stasera abbiamo un ospite tedesco.","exDe":"Heute Abend haben wir einen deutschen Gast."},{"it":"Accomodati!","de":"Komm rein! (zum Gast)","alt":[],"note":"Heißt auch: Nimm Platz! Mach es dir bequem! Höflich: Si accomodi!","ex":"Ciao Lukas, accomodati!","exDe":"Hallo Lukas, komm rein!"},{"it":"Siediti!","de":"Setz dich!","alt":[],"note":"Von sedersi (io mi siedo). Höflich: Si sieda!","ex":"Siediti pure, Lukas!","exDe":"Setz dich ruhig, Lukas!"},{"it":"A tavola!","de":"Zu Tisch!; Essen ist fertig!","alt":[],"note":"So ruft man alle zum Essen.","ex":"Ragazzi, a tavola! È pronto!","exDe":"Leute, zu Tisch! Das Essen ist fertig!"},{"it":"Serviti pure!","de":"Bedien dich ruhig!","alt":["Serviti!"],"note":"Von servirsi. Pure macht die Aufforderung freundlich.","ex":"C'è tanta pasta, serviti pure!","exDe":"Es gibt viel Pasta, bedien dich ruhig!"},{"it":"Fai come a casa tua!","de":"Fühl dich wie zu Hause!","alt":[],"note":"Höflich: Faccia come a casa Sua!","ex":"Benvenuto! Fai come a casa tua!","exDe":"Willkommen! Fühl dich wie zu Hause!"},{"it":"Mi passi il sale?","de":"Gibst du mir das Salz?","alt":[],"note":"Höflich: Mi passa il sale?","ex":"Giulia, mi passi il sale, per favore?","exDe":"Giulia, gibst du mir bitte das Salz?"},{"it":"Ancora un po'?","de":"Noch ein bisschen?","alt":["Ancora un po"],"note":"po' schreibt man mit Apostroph, nicht mit Akzent.","ex":"Lukas, ancora un po' di pasta?","exDe":"Lukas, noch ein bisschen Pasta?"},{"it":"la tovaglia","de":"die Tischdecke","alt":[],"note":"Nicht verwechseln: il tovagliolo = die Serviette.","ex":"Metti la tovaglia bianca, per favore.","exDe":"Leg bitte die weiße Tischdecke auf."},{"it":"Complimenti!","de":"Kompliment!; Gut gemacht!","alt":[],"note":"Complimenti per la cena! = Kompliment für das Essen!","ex":"Complimenti, nonna! È buonissimo!","exDe":"Kompliment, Oma! Das schmeckt super!"},{"it":"il campanello","de":"die Klingel","alt":[],"note":"Suonare il campanello = klingeln.","ex":"Suona il campanello: è Lukas!","exDe":"Es klingelt: Das ist Lukas!"},{"it":"sparecchiare","de":"den Tisch abräumen","alt":[],"note":"Das Gegenteil von apparecchiare.","ex":"Dopo cena sparecchiamo insieme.","exDe":"Nach dem Abendessen räumen wir zusammen ab."},{"it":"lavare i piatti","de":"Geschirr spülen","alt":[],"note":"Wörtlich: die Teller waschen.","ex":"Stasera lavo io i piatti.","exDe":"Heute Abend spüle ich."},{"it":"mettere in ordine","de":"aufräumen","alt":[],"note":"Passato prossimo: ho messo in ordine.","ex":"Metti in ordine la tua camera!","exDe":"Räum dein Zimmer auf!"},{"it":"comodo","de":"bequem","alt":[],"note":"feminin: comoda.","ex":"Questa sedia non è comoda.","exDe":"Dieser Stuhl ist nicht bequem."},{"it":"accogliente","de":"gemütlich; einladend","alt":[],"note":"Gleich für maskulin und feminin.","ex":"Che casa accogliente!","exDe":"Was für ein gemütliches Haus!"},{"it":"il mobile","de":"das Möbelstück","alt":[],"note":"Plural: i mobili = die Möbel.","ex":"Questi mobili sono della nonna.","exDe":"Diese Möbel gehören Oma."}],"grammar":{"title":"Der Imperativ: Komm! Setz dich!","points":["Mit dem <b>Imperativ</b> forderst du jemanden auf: Komm! Setz dich! Bei <b>tu</b> enden Verben auf <b>are</b> mit a: <b>mangia!</b>, <b>apparecchia!</b> Verben auf <b>ere</b> und <b>ire</b> enden mit i: <b>prendi!</b>, <b>senti!</b>","Bei <b>voi</b> ist der Imperativ gleich wie das Präsens: <b>mangiate!</b>, <b>prendete!</b>, <b>venite!</b> Bei <b>Lei</b> tauschen die Endungen: aus are wird i, aus ere und ire wird a. Deshalb sagst du höflich <b>scusi!</b> und <b>senta!</b>","Verbot mit tu: <b>non</b> + Infinitiv. <b>Non mangiare!</b> = Iss nicht! <b>Non preoccuparti!</b> = Mach dir keine Sorgen! Bei Lei und voi kommt einfach non davor: <b>non si preoccupi!</b>, <b>non mangiate!</b>","Pronomen hängen bei tu und voi hinten an: <b>siediti!</b>, <b>accomodati!</b>, <b>prendilo!</b> Bei Lei stehen sie davor: <b>si accomodi!</b> Merk dir auch die unregelmäßigen Formen <b>vieni!</b> (komm!), <b>fai!</b> (mach!) und <b>vai!</b> (geh!)."],"table":{"head":["","mangiare","prendere","venire"],"rows":[["tu","mangia!","prendi!","vieni!"],["Lei","mangi!","prenda!","venga!"],["voi","mangiate!","prendete!","venite!"],["tu, verneint","non mangiare!","non prendere!","non venire!"]]},"examples":[{"it":"Vieni, Lukas! Accomodati!","de":"Komm, Lukas! Nimm Platz!"},{"it":"Siediti qui, vicino a me.","de":"Setz dich hierher, neben mich."},{"it":"Prendi ancora un po' di pasta!","de":"Nimm noch ein bisschen Pasta!"},{"it":"Signora, si accomodi, prego.","de":"Bitte nehmen Sie Platz."},{"it":"Ragazzi, apparecchiate la tavola!","de":"Leute, deckt den Tisch!"},{"it":"Non preoccuparti, lo faccio io!","de":"Mach dir keine Sorgen, das mache ich!"}],"drills":[{"type":"choice","q":"Lukas, ___ qui, vicino a me!","de":"Lukas, setz dich hierher, neben mich!","options":["si sieda","siediti","sedetevi"],"answer":1,"why":"Lukas ist ein Freund (tu): siediti, das Pronomen hängt hinten an."},{"type":"choice","q":"Signor Bianchi, ___ pure!","de":"Herr Bianchi, nehmen Sie ruhig Platz!","options":["si accomodi","accomodati","accomodatevi"],"answer":0,"why":"Herrn Bianchi siezt du (Lei): si accomodi, das Pronomen steht davor."},{"type":"type","q":"Giulia, ___ (apparecchiare) la tavola, per favore!","de":"Giulia, deck bitte den Tisch!","answer":"apparecchia","alt":[],"why":"apparecchiare endet auf are, die tu Form endet also auf a."},{"type":"type","q":"Ragazzi, ___ (venire) a tavola!","de":"Leute, kommt zu Tisch!","answer":"venite","alt":[],"why":"Bei voi ist der Imperativ wie das Präsens: venite."},{"type":"choice","q":"Lukas, ___ ancora un po' di pasta!","de":"Lukas, nimm noch ein bisschen Pasta!","options":["prenda","prendete","prendi"],"answer":2,"why":"prendere mit tu: Die Endung ist i."},{"type":"type","q":"Lukas, non ___ i piatti, sei nostro ospite!","de":"Lukas, spül nicht das Geschirr, du bist unser Gast!","answer":"lavare","alt":[],"why":"Verbot mit tu: non + Infinitiv."},{"type":"choice","q":"Signora, ___ un altro caffè!","de":"Nehmen Sie noch einen Kaffee!","options":["prenda","prendi","prende"],"answer":0,"why":"Lei Form von prendere: Aus der Endung ere wird a."},{"type":"type","q":"Ti piace il libro? ___ pure!","de":"Gefällt dir das Buch? Nimm es ruhig!","answer":"prendilo","alt":["Prendilo"],"why":"Bei tu hängt das Pronomen hinten an: prendi + lo."}]},"dialog":{"title":"Una cena in famiglia","setting":"Lukas ist bei Giulias Eltern in Bologna zum Abendessen eingeladen. Nonna Lucia hat gekocht.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Rosa","gender":"f"},"C":{"name":"Nonna Lucia","gender":"f"}},"lines":[{"s":"A","it":"Buonasera! Permesso?","de":"Guten Abend! Darf ich reinkommen?"},{"s":"B","it":"Ciao Lukas, vieni, accomodati! Fai come a casa tua.","de":"Hallo Lukas, komm rein! Fühl dich wie zu Hause."},{"s":"A","it":"Grazie! Questi pasticcini sono per Lei, signora.","de":"Danke! Das Gebäck hier ist für Sie."},{"s":"B","it":"Ma non dovevi! Siediti, siediti.","de":"Das wär doch nicht nötig gewesen! Setz dich, setz dich."},{"s":"C","it":"A tavola! Le tagliatelle sono pronte!","de":"Zu Tisch! Die Tagliatelle sind fertig!"},{"s":"A","it":"Che profumino! Ha cucinato tutto Lei, nonna Lucia?","de":"Mmh, wie das duftet! Haben Sie das alles selbst gekocht, Nonna Lucia?"},{"s":"C","it":"Eh sì, caro. Mangia, mangia, sei troppo magro!","de":"Na klar, mein Lieber. Iss, iss, du bist viel zu dünn!"},{"s":"B","it":"Ancora un po'? Serviti pure, non fare complimenti!","de":"Noch ein bisschen? Bedien dich ruhig, zier dich nicht!"},{"s":"A","it":"Buonissime, complimenti! Ma scoppio. Posso aiutare a sparecchiare?","de":"Superlecker, Kompliment! Aber ich platze gleich. Kann ich beim Abräumen helfen?"},{"s":"B","it":"Ma no, lascia, lascia! Sei nostro ospite.","de":"Ach was, lass nur! Du bist unser Gast."},{"s":"C","it":"E adesso il dolce! Non dire di no, eh!","de":"Und jetzt der Nachtisch! Und sag ja nicht nein!"},{"s":"A","it":"Va bene, nonna Lucia. Ma solo un pezzetto!","de":"Na gut, Nonna Lucia. Aber nur ein kleines Stück!"}],"questions":[{"q":"Wer hat das Essen gekocht?","options":["Rosa","Nonna Lucia","Giulia"],"answer":1},{"q":"Wobei möchte Lukas helfen?","options":["Beim Abräumen","Beim Kochen","Beim Tischdecken"],"answer":0},{"q":"Wie viel Nachtisch nimmt Lukas?","options":["Gar keinen","Zwei Stück","Nur ein kleines Stück"],"answer":2}]},"sentences":[{"it":"Vieni, accomodati in soggiorno!","de":"Komm, nimm im Wohnzimmer Platz!"},{"it":"Giulia, apparecchia la tavola, per favore!","de":"Giulia, deck bitte den Tisch!"},{"it":"La cucina è accanto al soggiorno.","de":"Die Küche ist neben dem Wohnzimmer."},{"it":"Prego, signora, si sieda qui!","de":"Bitte, setzen Sie sich hierher!"},{"it":"Mi passi il pane, per favore?","de":"Gibst du mir bitte das Brot?"},{"it":"Ragazzi, venite a tavola, è pronto!","de":"Leute, kommt zu Tisch, das Essen ist fertig!"},{"it":"Non preoccuparti, sparecchio io!","de":"Mach dir keine Sorgen, ich räume ab!"},{"it":"Il divano in soggiorno è molto comodo.","de":"Das Sofa im Wohnzimmer ist sehr bequem."}],"spoken":[{"it":"Permesso?","book":"Posso entrare?","de":"Darf ich reinkommen?","note":"Sagt man beim Betreten einer fremden Wohnung, auch wenn die Tür schon offen ist. Die Antwort: Avanti! oder Prego!","ex":"Permesso? Avanti, Lukas, vieni!","exDe":"Darf ich reinkommen? Herein, Lukas, komm!","alt":[]},{"it":"Ma non dovevi!","book":"Grazie, è molto gentile.","de":"Das wär doch nicht nötig gewesen!","note":"Typische Antwort, wenn ein Gast etwas mitbringt. Dovevi ist eine Vergangenheitsform aus Lektion 22, merk dir den Satz einfach als Ganzes.","ex":"Un regalo per me? Ma non dovevi!","exDe":"Ein Geschenk für mich? Das wär doch nicht nötig gewesen!","alt":["Non dovevi!"]},{"it":"Che profumino!","book":"Che buon odore!","de":"Mmh, das riecht lecker!","note":"Die Endung ino macht es liebevoll. Hört man oft, wenn man in eine Küche kommt.","ex":"Che profumino! Cosa c'è per cena?","exDe":"Mmh, das riecht lecker! Was gibt's zum Abendessen?","alt":[]},{"it":"Non fare complimenti!","book":"Prendi pure!","de":"Zier dich nicht!","note":"Hörst du als Gast ständig. Complimenti heißt hier: sich zieren. Zu jemandem, den man siezt: Non faccia complimenti!","ex":"Prendi ancora, non fare complimenti!","exDe":"Nimm noch was, zier dich nicht!","alt":[]},{"it":"È solo un pensierino.","book":"È un piccolo regalo.","de":"Ist nur eine Kleinigkeit.","note":"Un pensierino ist ein kleines Mitbringsel, wörtlich: ein kleiner Gedanke. So überreichst du bescheiden dein Geschenk.","ex":"Tieni, è solo un pensierino!","exDe":"Hier, ist nur eine Kleinigkeit!","alt":["Solo un pensierino."]},{"it":"Scoppio!","book":"Sono pieno.","de":"Ich platze gleich!","note":"Locker und mit einem Lächeln, wenn du wirklich nichts mehr essen kannst. Bei der Nonna hilft das allerdings selten.","ex":"Ancora pasta? No, grazie, scoppio!","exDe":"Noch Pasta? Nein danke, ich platze gleich!","alt":[]},{"it":"Lascia, lascia!","book":"Non è necessario.","de":"Lass nur, lass!","note":"Sagt der Gastgeber, wenn du beim Abräumen oder Spülen helfen willst. Danach kommt oft: Faccio io!","ex":"Ti aiuto a sparecchiare? Ma no, lascia, lascia!","exDe":"Soll ich beim Abräumen helfen? Ach was, lass nur!","alt":[]},{"it":"Ci mancherebbe!","book":"Prego, non c'è di che.","de":"Das ist doch selbstverständlich!","note":"Herzliche Antwort auf Danke oder Entschuldigung. Passt zu allen, auch wenn man sich siezt.","ex":"Grazie per la cena! Ci mancherebbe!","exDe":"Danke für das Essen! Das ist doch selbstverständlich!","alt":[]}],"speak":[{"sit":"Du kommst bei Giulias Eltern an. Die Wohnungstür steht offen. Was sagst du beim Reingehen?","answers":["Permesso?","Buonasera! Permesso?"],"tip":"Mit 'Permesso?' bist du als Gast sofort sympathisch."},{"sit":"Du gibst Rosa Gebäck aus der Pasticceria. Sag, dass es für sie ist.","answers":["Questi sono per Lei.","Ecco, è solo un pensierino!","Questi pasticcini sono per Lei, signora."],"tip":"Rosa siezt du, also: per Lei."},{"sit":"Beim Essen brauchst du das Salz. Frag Giulia danach.","answers":["Mi passi il sale?","Giulia, mi passi il sale, per favore?"],"tip":""},{"sit":"Nonna Lucia will dir zum dritten Mal Pasta geben. Du kannst wirklich nicht mehr.","answers":["No, grazie, sono pieno.","Grazie, ma basta così. Scoppio!","Buonissima, ma non ce la faccio più!"],"tip":""},{"sit":"Ein Freund besucht dich zu Hause. Bitte ihn herein und sag ihm, dass er sich setzen soll.","answers":["Vieni, accomodati!","Ciao! Entra e siediti!","Vieni, siediti pure! Fai come a casa tua."],"tip":"Bei tu hängt das Pronomen hinten an: siediti, accomodati."},{"sit":"Das Essen ist fertig. Ruf Giulia und Matteo an den Tisch.","answers":["Ragazzi, a tavola!","Giulia, Matteo, venite a tavola!","A tavola, ragazzi, è pronto!"],"tip":"Bei voi ist der Imperativ wie das Präsens: venite!"}]},{"id":20,"title":"Tra amici","titleDe":"Unter Freunden","goal":"Du kannst über Gefühle sprechen, mit Freunden locker plaudern und von deinen Plänen erzählen.","intro":"Diese Woche geht es um Gefühle und um die Zukunft. Du lernst typische Ausrufe, die Italiener unter Freunden ständig benutzen. Mit dem Futuro sprichst du dann über deine Pläne und Träume.","culture":"Vor einer Prüfung oder einem wichtigen Termin wünscht man sich in Italien 'In bocca al lupo!', wörtlich: ins Maul des Wolfes. Die Antwort ist 'Crepi!', also: Er soll krepieren, gemeint ist der Wolf. 'Grazie' sagt man darauf traditionell nicht, das bringt angeblich Unglück. Es ist also ganz ähnlich wie unser 'Toi, toi, toi'.","vocab":[{"it":"felice","de":"glücklich","alt":[],"note":"Gleich für maskulin und feminin.","ex":"Sono felice di vederti!","exDe":"Ich freue mich, dich zu sehen!"},{"it":"triste","de":"traurig","alt":[],"note":"Gleich für maskulin und feminin.","ex":"Perché sei triste oggi?","exDe":"Warum bist du heute traurig?"},{"it":"stanco","de":"müde","alt":[],"note":"feminin: stanca. Plural: stanchi, stanche.","ex":"Stasera sono troppo stanco.","exDe":"Heute Abend bin ich zu müde."},{"it":"contento","de":"zufrieden; froh","alt":[],"note":"feminin: contenta. Contento di = zufrieden mit.","ex":"Sei contento del viaggio?","exDe":"Bist du mit der Reise zufrieden?"},{"it":"arrabbiato","de":"wütend; sauer","alt":[],"note":"feminin: arrabbiata. Arrabbiato con = sauer auf.","ex":"Perché sei arrabbiata con me?","exDe":"Warum bist du sauer auf mich?"},{"it":"preoccupato","de":"besorgt","alt":[],"note":"feminin: preoccupata.","ex":"La mamma è sempre preoccupata.","exDe":"Mama macht sich immer Sorgen."},{"it":"emozionato","de":"aufgeregt (vor Freude); gerührt","alt":[],"note":"feminin: emozionata.","ex":"Domani parto, sono molto emozionato!","exDe":"Morgen reise ich ab, ich bin sehr aufgeregt!"},{"it":"nervoso","de":"nervös; gereizt","alt":[],"note":"feminin: nervosa.","ex":"Prima dell'esame sono sempre nervoso.","exDe":"Vor der Prüfung bin ich immer nervös."},{"it":"annoiato","de":"gelangweilt","alt":[],"note":"feminin: annoiata. Che noia! = Wie langweilig!","ex":"Sei annoiato? Usciamo!","exDe":"Ist dir langweilig? Lass uns ausgehen!"},{"it":"deluso","de":"enttäuscht","alt":[],"note":"feminin: delusa.","ex":"Sono un po' deluso dal film.","exDe":"Ich bin ein bisschen enttäuscht von dem Film."},{"it":"innamorato","de":"verliebt","alt":[],"note":"feminin: innamorata. Innamorato di = verliebt in.","ex":"Matteo è innamorato di una ragazza.","exDe":"Matteo ist in ein Mädchen verliebt."},{"it":"tranquillo","de":"ruhig; entspannt","alt":[],"note":"feminin: tranquilla. Stai tranquillo! = Keine Sorge!","ex":"Stai tranquillo, va tutto bene!","exDe":"Keine Sorge, alles ist gut!"},{"it":"Dai!","de":"Komm schon!; Ach komm!","alt":[],"note":"Sehr häufig unter Freunden: zum Ermutigen oder Überreden.","ex":"Dai, vieni con noi!","exDe":"Komm schon, komm mit uns!"},{"it":"Magari!","de":"Schön wär's!; Das wäre toll!","alt":[],"note":"Drückt einen Wunsch aus. Mitten im Satz auch: vielleicht.","ex":"Vieni in Italia l'anno prossimo? Magari!","exDe":"Kommst du nächstes Jahr nach Italien? Das wäre toll!"},{"it":"Che peccato!","de":"Wie schade!","alt":[],"note":"","ex":"Parti domani? Che peccato!","exDe":"Du fährst morgen? Wie schade!"},{"it":"In bocca al lupo!","de":"Viel Glück! (vor einer Prüfung)","alt":[],"note":"Wörtlich: ins Maul des Wolfes. Die Antwort ist: Crepi!","ex":"Domani hai l'esame? In bocca al lupo!","exDe":"Morgen hast du die Prüfung? Viel Glück!"},{"it":"Meno male!","de":"Zum Glück!; Gott sei Dank!","alt":[],"note":"","ex":"Il treno è in orario? Meno male!","exDe":"Der Zug ist pünktlich? Zum Glück!"},{"it":"Che bello!","de":"Wie schön!","alt":[],"note":"","ex":"Che bello vederti, Davide!","exDe":"Wie schön, dich zu sehen, Davide!"},{"it":"Non vedo l'ora!","de":"Ich kann es kaum erwarten!","alt":[],"note":"Mit di: Non vedo l'ora di partire.","ex":"Andiamo al mare sabato? Non vedo l'ora!","exDe":"Fahren wir am Samstag ans Meer? Ich kann es kaum erwarten!"},{"it":"Mi mancherai!","de":"Du wirst mir fehlen!","alt":[],"note":"Futuro von mancare. Mi manchi = du fehlst mir.","ex":"Ciao Giulia, mi mancherai tanto!","exDe":"Tschüss Giulia, du wirst mir sehr fehlen!"},{"it":"Boh!","de":"Keine Ahnung!","alt":["Boh"],"note":"Sehr umgangssprachlich, oft mit Schulterzucken.","ex":"Dov'è Davide? Boh!","exDe":"Wo ist Davide? Keine Ahnung!"},{"it":"Sul serio?","de":"Im Ernst?","alt":[],"note":"","ex":"Sul serio? Torni a Monaco?","exDe":"Im Ernst? Du fährst zurück nach München?"},{"it":"Pazienza!","de":"Da kann man nichts machen!","alt":[],"note":"Wörtlich: Geduld.","ex":"Piove? Pazienza, restiamo a casa.","exDe":"Es regnet? Da kann man nichts machen, wir bleiben zu Hause."},{"it":"l'anno prossimo","de":"nächstes Jahr","alt":["anno prossimo"],"note":"prossimo = nächster: la settimana prossima. Gegenteil: l'anno scorso.","ex":"L'anno prossimo andrò in Sicilia.","exDe":"Nächstes Jahr fahre ich nach Sizilien."},{"it":"il sogno","de":"der Traum","alt":[],"note":"Plural: i sogni.","ex":"Il mio sogno è vivere in Italia.","exDe":"Mein Traum ist es, in Italien zu leben."},{"it":"sognare","de":"träumen","alt":[],"note":"Sognare di + Infinitiv: Sogno di vivere al mare.","ex":"Stanotte ho sognato la nonna.","exDe":"Heute Nacht habe ich von Oma geträumt."},{"it":"sperare","de":"hoffen","alt":[],"note":"Spero di sì = ich hoffe es.","ex":"Spero di tornare presto.","exDe":"Ich hoffe, bald zurückzukommen."},{"it":"il progetto","de":"der Plan; das Projekt","alt":[],"note":"Plural: i progetti.","ex":"Che progetti hai per l'estate?","exDe":"Welche Pläne hast du für den Sommer?"},{"it":"il futuro","de":"die Zukunft","alt":[],"note":"So heißt auch die Zeitform dieser Lektion.","ex":"Penso spesso al futuro.","exDe":"Ich denke oft an die Zukunft."},{"it":"tra una settimana","de":"in einer Woche","alt":["fra una settimana"],"note":"Tra oder fra + Zeitangabe = in (Zukunft): tra due giorni.","ex":"Tra una settimana sarò a casa.","exDe":"In einer Woche bin ich zu Hause."},{"it":"un giorno","de":"eines Tages","alt":[],"note":"","ex":"Un giorno tornerò in Italia.","exDe":"Eines Tages komme ich wieder nach Italien."},{"it":"il desiderio","de":"der Wunsch","alt":[],"note":"Plural: i desideri.","ex":"Il mio desiderio? Vivere al mare!","exDe":"Mein Wunsch? Am Meer leben!"},{"it":"trasferirsi","de":"umziehen (in eine andere Stadt)","alt":[],"note":"Mit isc: mi trasferisco.","ex":"Mi trasferirò a Bologna.","exDe":"Ich werde nach Bologna ziehen."},{"it":"sposarsi","de":"heiraten","alt":[],"note":"Sposarsi con = jemanden heiraten.","ex":"Mio fratello si sposa a giugno.","exDe":"Mein Bruder heiratet im Juni."},{"it":"l'esame","de":"die Prüfung","alt":["esame"],"note":"Maskulin. Plural: gli esami. Fare un esame = eine Prüfung machen.","ex":"Domani ho un esame di italiano.","exDe":"Morgen habe ich eine Italienischprüfung."},{"it":"promettere","de":"versprechen","alt":[],"note":"Passato prossimo: ho promesso. Promesso! = Versprochen!","ex":"Prometto di tornare l'anno prossimo.","exDe":"Ich verspreche, nächstes Jahr wiederzukommen."}],"grammar":{"title":"Das Futuro: Tornerò!","points":["Mit dem <b>Futuro</b> sprichst du über Pläne, Versprechen und Vermutungen: <b>Tornerò!</b> = Ich komme wieder! Für feste Pläne nimmt man im Alltag oft auch einfach das Präsens: Domani parto.","So bildest du es: Nimm den Infinitiv ohne das letzte e und häng <b>ò, ai, à, emo, ete, anno</b> an. Aus prendere wird <b>prenderò</b>, aus partire <b>partirò</b>. Bei Verben auf <b>are</b> wird das a zu e: Aus parlare wird <b>parlerò</b>.","Wichtige unregelmäßige Formen: essere wird zu <b>sarò</b>, avere zu <b>avrò</b>, fare zu <b>farò</b>, andare zu <b>andrò</b>, venire zu <b>verrò</b>. Die Endungen bleiben gleich: sarò, sarai, sarà, saremo, sarete, saranno.","Achte auf die Akzente: <b>tornerò</b>, <b>tornerà</b>. Die Betonung liegt auf der Endung. Bei <b>care</b> und <b>gare</b> kommt ein h dazu, damit der Klang hart bleibt: pagare wird zu <b>pagherò</b>."],"table":{"head":["","tornare","prendere","essere"],"rows":[["io","tornerò","prenderò","sarò"],["tu","tornerai","prenderai","sarai"],["lui / lei / Lei","tornerà","prenderà","sarà"],["noi","torneremo","prenderemo","saremo"],["voi","tornerete","prenderete","sarete"],["loro","torneranno","prenderanno","saranno"]]},"examples":[{"it":"Quest'estate andrò al mare con Davide.","de":"Diesen Sommer fahre ich mit Davide ans Meer."},{"it":"Che cosa farai dopo l'università?","de":"Was wirst du nach dem Studium machen?"},{"it":"L'anno prossimo verrò di nuovo a Bologna.","de":"Nächstes Jahr komme ich wieder nach Bologna."},{"it":"Un giorno avremo una casa al mare.","de":"Eines Tages werden wir ein Haus am Meer haben."},{"it":"Ci vedremo presto, promesso!","de":"Wir sehen uns bald, versprochen!"},{"it":"Il viaggio sarà bellissimo!","de":"Die Reise wird wunderschön!"}],"drills":[{"type":"choice","q":"Domani io ___ a Venezia con Davide.","de":"Morgen fahre ich mit Davide nach Venedig.","options":["andrò","anderò","andrai"],"answer":0,"why":"andare ist unregelmäßig: io andrò."},{"type":"type","q":"Tra due settimane Lukas ___ (tornare) a Monaco.","de":"In zwei Wochen wird Lukas nach München zurückkehren.","answer":"tornerà","alt":["tornera"],"why":"tornare, lui Form im Futuro: tornerà mit Akzent."},{"type":"choice","q":"Ragazzi, quando ___ a trovarci?","de":"Leute, wann kommt ihr uns besuchen?","options":["venirete","verremo","verrete"],"answer":2,"why":"venire ist unregelmäßig, die voi Form heißt verrete."},{"type":"type","q":"L'anno prossimo io ___ (avere) trent'anni.","de":"Nächstes Jahr werde ich dreißig.","answer":"avrò","alt":["avro"],"why":"avere wird im Futuro zu avrò."},{"type":"choice","q":"Giulia e Matteo ___ a Monaco a dicembre.","de":"Giulia und Matteo kommen im Dezember nach München.","options":["verrà","verranno","venranno"],"answer":1,"why":"Zwei Personen (loro): verranno."},{"type":"type","q":"Quest'estate io ___ (fare) il giro della Sicilia.","de":"Diesen Sommer werde ich eine Rundreise durch Sizilien machen.","answer":"farò","alt":["faro"],"why":"fare wird im Futuro zu farò."},{"type":"choice","q":"Domani ___ una bella giornata.","de":"Morgen wird ein schöner Tag.","options":["sarà","sarò","sarai"],"answer":0,"why":"Subjekt ist una bella giornata, also 3. Person Singular: sarà."},{"type":"type","q":"Ti ___ (chiamare) ogni domenica, promesso!","de":"Ich werde dich jeden Sonntag anrufen, versprochen!","answer":"chiamerò","alt":["chiamero"],"why":"chiamare, io Form: Aus a wird e, also chiamerò."}]},"dialog":{"title":"Progetti per il futuro","setting":"Lukas sitzt mit Giulia und Davide in einer Bar. In ein paar Tagen fliegt er zurück nach München.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Giulia","gender":"f"},"C":{"name":"Davide","gender":"m"}},"lines":[{"s":"C","it":"Allora, Lukas, è vero che sabato parti?","de":"Na, Lukas, stimmt's, dass du am Samstag abreist?"},{"s":"A","it":"Eh sì, purtroppo. Sabato sarò già a Monaco.","de":"Ja, leider. Am Samstag bin ich schon wieder in München."},{"s":"B","it":"Che peccato! Mi mancherai tanto, sai?","de":"Wie schade! Du wirst mir echt fehlen, weißt du?"},{"s":"A","it":"Anche voi! Ma tornerò presto, promesso.","de":"Ihr mir auch! Aber ich komm bald wieder, versprochen."},{"s":"C","it":"Dai, Giulia, non fare quella faccia! Lukas, che progetti hai?","de":"Komm schon, Giulia, mach nicht so ein Gesicht! Lukas, was hast du so vor?"},{"s":"A","it":"A maggio farò l'esame di italiano. Che ansia!","de":"Im Mai mach ich die Italienischprüfung. Ich bin jetzt schon nervös!"},{"s":"C","it":"Tranquillo, ce la farai! In bocca al lupo!","de":"Keine Sorge, du schaffst das! Viel Glück!"},{"s":"A","it":"Crepi! E dopo l'esame andrò in Sicilia.","de":"Crepi! Und nach der Prüfung fahr ich nach Sizilien."},{"s":"B","it":"In Sicilia? Che figata! Veniamo anche noi!","de":"Nach Sizilien? Wie cool! Da kommen wir mit!"},{"s":"A","it":"Magari! Sarà un viaggio fantastico.","de":"Das wär toll! Das wird eine fantastische Reise."},{"s":"C","it":"Perfetto! E stasera festa d'addio a casa mia!","de":"Super! Und heute Abend gibt's eine Abschiedsparty bei mir!"},{"s":"B","it":"Grande! Il dolce lo porto io.","de":"Klasse! Den Nachtisch bring ich mit."}],"questions":[{"q":"Wann fährt Lukas zurück nach München?","options":["Am Samstag","Im Mai","In einem Monat"],"answer":0},{"q":"Was macht Lukas im Mai?","options":["Er zieht nach Italien.","Er macht eine Italienischprüfung.","Er besucht Davide in Neapel."],"answer":1},{"q":"Was ist heute Abend?","options":["Ein Essen bei Giulias Eltern","Ein Konzert in Bologna","Eine Abschiedsparty bei Davide"],"answer":2}]},"sentences":[{"it":"Domani sarò molto stanco.","de":"Morgen werde ich sehr müde sein."},{"it":"Tra una settimana tornerò a Monaco.","de":"In einer Woche fahre ich zurück nach München."},{"it":"Che peccato, mi mancherai tanto!","de":"Wie schade, du wirst mir sehr fehlen!"},{"it":"Un giorno avrò una casa in Toscana.","de":"Eines Tages werde ich ein Haus in der Toskana haben."},{"it":"In bocca al lupo per l'esame!","de":"Viel Glück bei der Prüfung!"},{"it":"Quest'estate andremo tutti in Sicilia.","de":"Diesen Sommer fahren wir alle nach Sizilien."},{"it":"Dai, non essere triste!","de":"Komm schon, sei nicht traurig!"},{"it":"Non vedo l'ora di rivederti!","de":"Ich kann es kaum erwarten, dich wiederzusehen!"}],"spoken":[{"it":"Figurati!","book":"Di niente.","de":"Ach was!; Keine Ursache!","note":"Unter Freunden die typische Antwort auf Danke oder Entschuldigung. Zu jemandem, den du siezt: Si figuri!","ex":"Scusa per ieri sera! Figurati!","exDe":"Sorry wegen gestern Abend! Ach was!","alt":["Ma figurati!"]},{"it":"Che figata!","book":"Che bello!","de":"Wie cool!","note":"Jung und sehr locker, nur unter Freunden. Bei Oma oder im Büro sagst du lieber: Che bello!","ex":"Andiamo tutti in Sicilia? Che figata!","exDe":"Wir fahren alle nach Sizilien? Wie cool!","alt":[]},{"it":"Che palle!","book":"Che noia!","de":"So ein Mist!; Wie ätzend! (umgangssprachlich)","note":"Umgangssprachlich und etwas derb: nur unter guten Freunden, nie bei Fremden, Eltern oder im Büro. Neutraler: Che noia! oder Uffa!","ex":"Sabato devo lavorare. Che palle!","exDe":"Am Samstag muss ich arbeiten. So ein Mist!","alt":[]},{"it":"Che ansia!","book":"Sono molto nervoso.","de":"Ich bin total nervös!","note":"Bei jungen Leuten sehr beliebt, für alles, was nervös macht: Prüfungen, Termine, lange Warteschlangen.","ex":"Domani ho l'esame. Che ansia!","exDe":"Morgen hab ich die Prüfung. Ich bin total nervös!","alt":[]},{"it":"Sono un po' giù.","book":"Sono triste.","de":"Ich bin ein bisschen down.","note":"Giù heißt unten. Klingt weicher als triste und passt überall.","ex":"Cos'hai? Niente, sono solo un po' giù.","exDe":"Was ist los? Nichts, ich bin nur ein bisschen down.","alt":["Sono giù."]},{"it":"Ce la farai!","book":"Riuscirai a farlo.","de":"Du schaffst das!","note":"Zum Mutmachen vor einer Prüfung oder etwas Schwierigem. Das ist das Futuro von farcela (es schaffen): ce la farò, ce la farai ...","ex":"Sei nervoso per l'esame? Dai, ce la farai!","exDe":"Bist du nervös wegen der Prüfung? Komm, du schaffst das!","alt":[]},{"it":"Ti voglio bene.","book":"","de":"Ich hab dich lieb.","note":"Unter Freunden und in der Familie. Ti amo sagst du nur zu deinem Partner oder deiner Partnerin.","ex":"Grazie di tutto, ragazzi. Vi voglio bene!","exDe":"Danke für alles, Leute. Ich hab euch lieb!","alt":[]},{"it":"Ci conto!","book":"Lo spero.","de":"Ich verlass mich drauf!","note":"Wenn dir jemand etwas verspricht. Wörtlich: Ich zähle darauf.","ex":"Tornerò presto, promesso! Ci conto, eh!","exDe":"Ich komme bald wieder, versprochen! Ich verlass mich drauf!","alt":[]}],"speak":[{"sit":"Davide hat morgen eine wichtige Prüfung. Wünsch ihm Glück.","answers":["In bocca al lupo!","In bocca al lupo per l'esame!"],"tip":"Er antwortet 'Crepi!'. Grazie sagt man darauf nicht."},{"sit":"Giulia erzählt, dass ihr nächsten Sommer alle zusammen nach Sizilien fahrt. Reagier begeistert.","answers":["Che bello!","Che figata!","Davvero? Non vedo l'ora!"],"tip":"'Che figata!' nur unter Freunden."},{"sit":"Davide fragt, was du nächsten Sommer machst. Erzähl von einem Plan.","answers":["Andrò al mare.","L'estate prossima farò un viaggio in Sicilia.","Tornerò in Italia!"],"tip":"Für Pläne passt das Futuro: andrò, farò, tornerò."},{"sit":"Giulia ist heute ganz still und wirkt traurig. Frag sie, was los ist.","answers":["Cos'hai?","Che hai? Sei triste?","Tutto bene? Ti vedo un po' giù."],"tip":""},{"sit":"Du verabschiedest dich von Giulia. Sag, dass sie dir fehlen wird und du bald wiederkommst.","answers":["Mi mancherai! Tornerò presto.","Mi mancherai tanto! Ma tornerò presto, promesso."],"tip":""},{"sit":"Davide bedankt sich, weil du ihm beim Umzug geholfen hast. Antworte locker.","answers":["Figurati!","Ma figurati, Davide!","Di niente!"],"tip":""}]},{"id":21,"title":"La cultura italiana","titleDe":"Italienische Kultur","goal":"Du kannst über italienische Feste sprechen, Glückwünsche aussprechen und Freunde zu etwas einladen.","intro":"Weihnachten, Karneval, Ferragosto: Diese Woche lernst du die wichtigsten italienischen Feste und Traditionen kennen. Außerdem sagst du, wem du etwas schenkst oder schickst. Mit 'Ti va di ...?' lädst du Freunde ein.","culture":"Italien hat 20 Regionen und fast jede hat ihren eigenen Dialekt, ihre eigenen Feste und Spezialitäten. Im Sommer und Herbst gibt es überall Sagre, also Dorffeste rund um ein Essen wie Trüffel, Wein oder Tortellini. Seit 1951 gibt es außerdem das Festival di Sanremo, einen großen Liederwettbewerb, der heute meist im Februar im Fernsehen läuft. Halb Italien schaut zu und diskutiert danach über die Lieder.","vocab":[{"it":"la festa","de":"das Fest; die Party","alt":[],"note":"Plural: le feste.","ex":"Sabato c'è una festa a casa di Davide.","exDe":"Am Samstag gibt es eine Party bei Davide."},{"it":"il Natale","de":"Weihnachten","alt":["Natale"],"note":"Meist ohne Artikel: a Natale = an Weihnachten.","ex":"A Natale torno a Monaco.","exDe":"An Weihnachten fahre ich zurück nach München."},{"it":"la Pasqua","de":"Ostern","alt":["Pasqua"],"note":"Typisch ist la colomba, ein Kuchen in Form einer Taube.","ex":"A Pasqua mangiamo la colomba.","exDe":"An Ostern essen wir die Colomba."},{"it":"il Capodanno","de":"Neujahr; Silvester","alt":["Capodanno"],"note":"Der 1. Januar und oft auch die Nacht davor. Man isst Linsen, das soll Geld bringen.","ex":"Cosa fai a Capodanno?","exDe":"Was machst du an Silvester?"},{"it":"il Ferragosto","de":"Ferragosto (Feiertag am 15. August)","alt":["Ferragosto"],"note":"Mariä Himmelfahrt. Viele Italiener machen dann Urlaub.","ex":"A Ferragosto la città è vuota.","exDe":"An Ferragosto ist die Stadt leer."},{"it":"il Carnevale","de":"der Karneval; der Fasching","alt":["Carnevale"],"note":"Am berühmtesten ist der Carnevale di Venezia mit seinen Masken.","ex":"A Carnevale ci sono feste in ogni città.","exDe":"Zum Karneval gibt es in jeder Stadt Feste."},{"it":"la Befana","de":"die Befana (bringt am 6. Januar Geschenke)","alt":["Befana"],"note":"Eine freundliche Hexe auf dem Besen. Sie kommt in der Nacht zum 6. Januar.","ex":"La Befana porta i dolci ai bambini.","exDe":"Die Befana bringt den Kindern Süßigkeiten."},{"it":"il regalo","de":"das Geschenk","alt":[],"note":"Plural: i regali.","ex":"Grazie per il regalo!","exDe":"Danke für das Geschenk!"},{"it":"Auguri!","de":"Herzlichen Glückwunsch!; Alles Gute!","alt":["Tanti auguri!"],"note":"Passt zu Geburtstag, Feiertagen und Hochzeit. Auch: Tanti auguri!","ex":"Auguri, Giulia! Buon compleanno!","exDe":"Alles Gute, Giulia! Herzlichen Glückwunsch zum Geburtstag!"},{"it":"Buon Natale!","de":"Frohe Weihnachten!","alt":[],"note":"","ex":"Buon Natale a tutti!","exDe":"Frohe Weihnachten euch allen!"},{"it":"Buon anno!","de":"Frohes neues Jahr!","alt":["Felice anno nuovo!","Buon anno nuovo!"],"note":"Auch: Felice anno nuovo!","ex":"Mezzanotte! Buon anno a tutti!","exDe":"Mitternacht! Frohes neues Jahr euch allen!"},{"it":"festeggiare","de":"feiern","alt":[],"note":"","ex":"Stasera festeggiamo il compleanno di Matteo.","exDe":"Heute Abend feiern wir Matteos Geburtstag."},{"it":"la tradizione","de":"die Tradition","alt":[],"note":"Plural: le tradizioni.","ex":"È una tradizione molto antica.","exDe":"Das ist eine sehr alte Tradition."},{"it":"il panettone","de":"der Panettone (Weihnachtskuchen aus Mailand)","alt":[],"note":"Mit Rosinen und kandierten Früchten. Der Kuchen aus Verona ohne Früchte heißt pandoro.","ex":"Ti piace il panettone?","exDe":"Magst du Panettone?"},{"it":"i fuochi d'artificio","de":"das Feuerwerk","alt":["fuochi d'artificio"],"note":"Singular: il fuoco d'artificio.","ex":"A mezzanotte guardiamo i fuochi d'artificio.","exDe":"Um Mitternacht schauen wir uns das Feuerwerk an."},{"it":"la maschera","de":"die Maske","alt":[],"note":"Auch die Figuren der Commedia dell'arte, zum Beispiel Arlecchino.","ex":"A Venezia compro una maschera.","exDe":"In Venedig kaufe ich eine Maske."},{"it":"la sagra","de":"das Dorffest (rund um ein Essen)","alt":[],"note":"Zum Beispiel la sagra del tartufo, das Trüffelfest.","ex":"Domenica andiamo alla sagra del vino.","exDe":"Am Sonntag gehen wir zum Weinfest."},{"it":"il presepe","de":"die Weihnachtskrippe","alt":[],"note":"Besonders berühmt sind die Krippen aus Neapel.","ex":"A Napoli il presepe è un'arte.","exDe":"In Neapel ist die Krippe eine Kunst."},{"it":"il cenone","de":"das große Festessen an Feiertagen","alt":[],"note":"Von la cena: ein riesiges Abendessen an Heiligabend oder Silvester.","ex":"Il cenone dura sempre tre ore!","exDe":"Das Festessen dauert immer drei Stunden!"},{"it":"il dialetto","de":"der Dialekt","alt":[],"note":"Plural: i dialetti.","ex":"La nonna parla in dialetto bolognese.","exDe":"Oma spricht Dialekt aus Bologna."},{"it":"la regione","de":"die Region","alt":[],"note":"Italien hat 20 Regionen, zum Beispiel die Toscana.","ex":"Qual è la tua regione preferita?","exDe":"Was ist deine Lieblingsregion?"},{"it":"l'arte","de":"die Kunst","alt":["arte"],"note":"Feminin: l'arte italiana.","ex":"Firenze è la città dell'arte.","exDe":"Florenz ist die Stadt der Kunst."},{"it":"il quadro","de":"das Gemälde; das Bild","alt":[],"note":"Plural: i quadri.","ex":"Questo quadro è di Botticelli.","exDe":"Dieses Gemälde ist von Botticelli."},{"it":"famoso","de":"berühmt","alt":[],"note":"feminin: famosa.","ex":"Sanremo è famosa per il suo festival.","exDe":"Sanremo ist für sein Festival berühmt."},{"it":"Ti va di venire?","de":"Hast du Lust mitzukommen?","alt":[],"note":"Ti va di + Infinitiv = Hast du Lust zu ...? Antwort: Sì, mi va! oder No, non mi va.","ex":"Stasera c'è una festa. Ti va di venire?","exDe":"Heute Abend gibt es eine Party. Hast du Lust mitzukommen?"},{"it":"regalare","de":"schenken","alt":[],"note":"Che cosa le regali? = Was schenkst du ihr?","ex":"Cosa regali a Giulia?","exDe":"Was schenkst du Giulia?"},{"it":"dare","de":"geben","alt":[],"note":"Unregelmäßig: io do, tu dai, lui dà. Imperativ: dammi! = gib mir!","ex":"Mi dai il tuo numero?","exDe":"Gibst du mir deine Nummer?"},{"it":"mandare","de":"schicken","alt":[],"note":"","ex":"Mandami un messaggio stasera!","exDe":"Schick mir heute Abend eine Nachricht!"},{"it":"augurare","de":"wünschen","alt":[],"note":"Ti auguro buon viaggio! = Ich wünsche dir eine gute Reise!","ex":"Ti auguro buona fortuna per l'esame!","exDe":"Ich wünsch dir viel Glück für die Prüfung!"},{"it":"spiegare","de":"erklären","alt":[],"note":"Mit h: tu spieghi, noi spieghiamo.","ex":"Giulia gli spiega la Befana.","exDe":"Giulia erklärt ihm die Befana."},{"it":"prestare","de":"leihen (jemandem etwas)","alt":[],"note":"Mi presti ...? = Leihst du mir ...?","ex":"Mi presti la tua maschera?","exDe":"Leihst du mir deine Maske?"},{"it":"Mi fa piacere.","de":"Das freut mich.","alt":["Mi fa piacere!"],"note":"Auch als Frage: Ti fa piacere? = Freut es dich?","ex":"Vieni anche tu? Mi fa piacere!","exDe":"Kommst du auch? Das freut mich!"},{"it":"Congratulazioni!","de":"Gratuliere! (zu einem Erfolg)","alt":[],"note":"Für Prüfung, neuen Job oder Hochzeit. Zum Geburtstag sagt man Auguri!","ex":"Hai passato l'esame? Congratulazioni!","exDe":"Du hast die Prüfung bestanden? Gratuliere!"},{"it":"il pittore","de":"der Maler","alt":[],"note":"feminin: la pittrice.","ex":"Caravaggio è un pittore molto famoso.","exDe":"Caravaggio ist ein sehr berühmter Maler."},{"it":"la vigilia di Natale","de":"Heiligabend","alt":[],"note":"Am Abend des 24. Dezember isst man in vielen Familien Fisch.","ex":"La vigilia di Natale mangiamo il pesce.","exDe":"An Heiligabend essen wir Fisch."},{"it":"Buone feste!","de":"Frohe Feiertage!","alt":[],"note":"","ex":"Ciao a tutti e buone feste!","exDe":"Tschüss allerseits und frohe Feiertage!"}],"grammar":{"title":"Indirekte Objektpronomen und Ti va di ...?","points":["Indirekte Objektpronomen antworten auf die Frage <b>wem?</b> Du kennst sie schon von piacere: <b>Mi</b> piace = es gefällt mir. Genauso funktionieren dare, regalare, mandare und spiegare: <b>Ti</b> mando una foto = ich schicke dir ein Foto.","Die Formen: <b>mi</b> (mir), <b>ti</b> (dir), <b>gli</b> (ihm), <b>le</b> (ihr), <b>Le</b> (Ihnen), <b>ci</b> (uns), <b>vi</b> (euch), <b>gli</b> (ihnen). Sie stehen vor dem Verb: <b>Gli</b> regalo un libro.","Vorsicht bei <b>la</b> und <b>le</b>: La chiamo = ich rufe sie an (wen?). <b>Le</b> telefono = ich rufe sie an (wörtlich: ich telefoniere ihr, wem?). Steht im Italienischen <b>a</b> vor der Person (telefonare a Rosa), nimmst du das indirekte Pronomen.","<b>Ti va di ...?</b> = Hast du Lust zu ...? Es funktioniert wie piacere: <b>Ti va di</b> uscire? Sì, <b>mi va</b>! Höflich: <b>Le va di</b> ...? Beim Imperativ mit tu hängt das Pronomen hinten an: <b>Scrivimi!</b> <b>Mandami</b> una foto!"],"table":{"head":["","wem? (indirekt)","wen? (direkt)"],"rows":[["io","mi","mi"],["tu","ti","ti"],["lui","gli","lo"],["lei","le","la"],["Lei","Le","La"],["noi","ci","ci"],["voi","vi","vi"],["loro","gli","li / le"]]},"examples":[{"it":"Che cosa regali a Giulia? Le regalo un libro.","de":"Was schenkst du Giulia? Ich schenke ihr ein Buch."},{"it":"Davide, ti va di venire alla sagra?","de":"Davide, hast du Lust, zum Dorffest mitzukommen?"},{"it":"I bambini sono felici: la Befana gli porta i dolci.","de":"Die Kinder freuen sich: Die Befana bringt ihnen Süßigkeiten."},{"it":"Signora, Le auguro buone feste!","de":"Ich wünsche Ihnen frohe Feiertage!"},{"it":"Ragazzi, ci spiegate il Carnevale?","de":"Leute, erklärt ihr uns den Karneval?"},{"it":"Mamma, ti telefono stasera.","de":"Mama, ich rufe dich heute Abend an."}],"drills":[{"type":"choice","q":"Domani è il compleanno di Giulia. ___ regalo una borsa.","de":"Morgen hat Giulia Geburtstag. Ich schenke ihr eine Tasche.","options":["Gli","Le","La"],"answer":1,"why":"a Giulia = a lei, also le (ihr)."},{"type":"choice","q":"Davide ama il calcio. ___ regalo la maglietta del Napoli.","de":"Davide liebt Fußball. Ich schenke ihm das Trikot von Neapel.","options":["Le","Lo","Gli"],"answer":2,"why":"a Davide = a lui, also gli (ihm)."},{"type":"type","q":"Ragazzi, ___ porto un panettone da Milano!","de":"Leute, ich bringe euch einen Panettone aus Mailand mit!","answer":"vi","alt":[],"why":"a voi = vi (euch)."},{"type":"type","q":"Signora, ___ va di venire con noi?","de":"Haben Sie Lust, mit uns zu kommen?","answer":"Le","alt":["le"],"why":"Höflich (Lei): Le va di ...?"},{"type":"choice","q":"Nonna, io e Matteo abbiamo fame. ___ prepari i tortellini?","de":"Oma, Matteo und ich haben Hunger. Machst du uns Tortellini?","options":["Vi","Ci","Gli"],"answer":1,"why":"io e Matteo = noi, also ci (uns)."},{"type":"type","q":"Lukas non capisce la tradizione. Giulia ___ spiega tutto.","de":"Lukas versteht die Tradition nicht. Giulia erklärt ihm alles.","answer":"gli","alt":[],"why":"a Lukas = a lui, also gli (ihm)."},{"type":"choice","q":"Ciao Davide, ___ di uscire stasera?","de":"Hallo Davide, hast du Lust, heute Abend auszugehen?","options":["ti va","ti vai","vai"],"answer":0,"why":"Ti va di + Infinitiv = Hast du Lust zu ...?"},{"type":"type","q":"Mamma, domani ___ telefono da Monaco.","de":"Mama, ich rufe dich morgen aus München an.","answer":"ti","alt":[],"why":"telefonare a qualcuno: a te = ti."}]},"dialog":{"title":"Feste e tradizioni","setting":"Am Abend in einer Osteria erklären Giulia und Davide Lukas die italienischen Feste.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Giulia","gender":"f"},"C":{"name":"Davide","gender":"m"}},"lines":[{"s":"A","it":"Ragazzi, mi spiegate un po' le feste italiane?","de":"Leute, erklärt ihr mir mal die italienischen Feste?"},{"s":"B","it":"Certo! Allora, a Natale mangiamo panettone o pandoro.","de":"Klar! Also, an Weihnachten essen wir Panettone oder Pandoro."},{"s":"C","it":"E noi a Napoli facciamo il presepe. È bellissimo!","de":"Und wir in Neapel bauen die Krippe auf. Das ist wunderschön!"},{"s":"A","it":"E il 6 gennaio arriva la Befana, no?","de":"Und am 6. Januar kommt die Befana, oder?"},{"s":"B","it":"Esatto! Ai bambini buoni porta i dolci, ai cattivi il carbone.","de":"Genau! Den braven Kindern bringt sie Süßigkeiten, den frechen Kohle."},{"s":"C","it":"Ma oggi anche il carbone è di zucchero, eh!","de":"Aber heute ist sogar die Kohle aus Zucker!"},{"s":"A","it":"E a Ferragosto che fate?","de":"Und was macht ihr an Ferragosto?"},{"s":"B","it":"Il 15 agosto? Tutti al mare o in montagna!","de":"Am 15. August? Alle ab ans Meer oder in die Berge!"},{"s":"C","it":"Senti, Lukas, ti va di venire al Carnevale di Venezia?","de":"Hör mal, Lukas, hast du Lust, zum Karneval nach Venedig zu kommen?"},{"s":"A","it":"Ci sto! Le maschere mi piacciono un sacco.","de":"Ich bin dabei! Die Masken find ich total toll."},{"s":"B","it":"Allora ti mandiamo le date. Ti aspettiamo!","de":"Dann schicken wir dir die Termine. Wir freuen uns auf dich!"}],"questions":[{"q":"Was gibt es in Neapel an Weihnachten?","options":["Ein großes Feuerwerk","Die Krippe","Einen Umzug mit Masken"],"answer":1},{"q":"Was bringt die Befana braven Kindern?","options":["Süßigkeiten","Kohle","Spielzeug"],"answer":0},{"q":"Wohin lädt Davide Lukas ein?","options":["Nach Neapel zu Ferragosto","Nach Mailand zu Weihnachten","Nach Venedig zum Karneval"],"answer":2}]},"sentences":[{"it":"Ti va di venire alla festa?","de":"Hast du Lust, zur Party zu kommen?"},{"it":"A Natale gli regalo una sciarpa.","de":"Zu Weihnachten schenke ich ihm einen Schal."},{"it":"Buon Natale e felice anno nuovo!","de":"Frohe Weihnachten und ein gutes neues Jahr!"},{"it":"Mi spieghi questa tradizione, per favore?","de":"Erklärst du mir bitte diese Tradition?"},{"it":"Le mando gli auguri per Pasqua.","de":"Ich schicke ihr Ostergrüße."},{"it":"Ferragosto è il quindici agosto.","de":"Ferragosto ist am fünfzehnten August."},{"it":"Ci mandi una foto da Venezia?","de":"Schickst du uns ein Foto aus Venedig?"},{"it":"Il Carnevale di Venezia è molto famoso.","de":"Der Karneval von Venedig ist sehr berühmt."}],"spoken":[{"it":"Auguroni!","book":"Tanti auguri!","de":"Alles, alles Gute!","note":"Locker und herzlich, unter Freunden und in Nachrichten. Die Endung one macht alles größer.","ex":"Oggi è il tuo compleanno? Auguroni!","exDe":"Du hast heute Geburtstag? Alles, alles Gute!","alt":[]},{"it":"Anche a te!","book":"Altrettanto.","de":"Dir auch!; Gleichfalls!","note":"Die Antwort auf Wünsche wie Buone feste! oder Buon anno! Zu mehreren: Anche a voi! Höflich: Anche a Lei!","ex":"Buon Natale, Lukas! Grazie, anche a te!","exDe":"Frohe Weihnachten, Lukas! Danke, dir auch!","alt":[]},{"it":"Ci sto!","book":"Sì, vengo volentieri.","de":"Ich bin dabei!","note":"Lockere Zusage, wenn Freunde etwas vorschlagen. Die Frage dazu: Ci stai? Nicht verwechseln mit Ci sta! = Passt!","ex":"Domenica andiamo alla sagra. Ci stai? Ci sto!","exDe":"Am Sonntag gehen wir zum Dorffest. Bist du dabei? Bin dabei!","alt":[]},{"it":"Magari un'altra volta!","book":"Forse un'altra volta.","de":"Vielleicht ein andermal!","note":"Neben Magari! (Schön wär's!) heißt magari mitten im Satz auch vielleicht. So sagst du freundlich ab.","ex":"Ti va di venire stasera? Stasera no, magari un'altra volta!","exDe":"Hast du Lust, heute Abend mitzukommen? Heute nicht, vielleicht ein andermal!","alt":[]},{"it":"Facciamo il ponte?","book":"Prendiamo un giorno libero?","de":"Machen wir einen Brückentag?","note":"Fällt ein Feiertag auf einen Donnerstag, nehmen viele auch den Freitag frei. Das heißt fare il ponte, wörtlich: die Brücke machen.","ex":"Giovedì è festa. Facciamo il ponte?","exDe":"Donnerstag ist Feiertag. Machen wir einen Brückentag?","alt":[]},{"it":"Natale con i tuoi, Pasqua con chi vuoi.","book":"","de":"Weihnachten mit der Familie, Ostern mit wem du willst.","note":"Bekanntes Sprichwort. I tuoi sind deine Leute, also die Familie. An Ostern fahren deshalb viele mit Freunden weg.","ex":"Pasqua al mare? Certo: Pasqua con chi vuoi!","exDe":"Ostern am Meer? Klar: Ostern mit wem du willst!","alt":[]},{"it":"Ci vado matto!","book":"Mi piace moltissimo.","de":"Da steh ich total drauf!","note":"Locker, für Essen, Musik und alles, was du liebst. Frauen sagen: Ci vado matta! Mit Nomen: Vado matto per il panettone.","ex":"Ti piace il panettone? Ci vado matto!","exDe":"Magst du Panettone? Da steh ich total drauf!","alt":["Ci vado matta!","Ne vado matto!"]},{"it":"Da noi ...","book":"Nella nostra regione ...","de":"Bei uns ...","note":"Italiener sind stolz auf ihre Stadt und Region. Da noi heißt bei uns, also da, wo ich herkomme. Die Frage zurück: E da voi?","ex":"Da noi a Natale si mangia il pesce.","exDe":"Bei uns isst man an Weihnachten Fisch.","alt":[]}],"speak":[{"sit":"Es ist Heiligabend bei Giulias Familie. Wünsch allen frohe Weihnachten.","answers":["Buon Natale a tutti!","Buon Natale e buone feste a tutti!"],"tip":""},{"sit":"Davide wünscht dir frohe Feiertage. Antworte ihm.","answers":["Grazie, anche a te!","Grazie, buone feste anche a te!"],"tip":""},{"sit":"Lade Giulia ein, am Sonntag mit dir zum Weinfest zu gehen.","answers":["Ti va di venire alla sagra del vino domenica?","Domenica c'è la sagra del vino. Ti va di venire?"],"tip":"Ti va di + Infinitiv ist die lockere Einladung."},{"sit":"Matteo fragt, was du Giulia zum Geburtstag schenkst. Sag: ein Buch.","answers":["Le regalo un libro.","Le regalo un libro di cucina."],"tip":"a Giulia wird zu le."},{"sit":"Ein Freund lädt dich für heute Abend ein, aber du kannst nicht. Sag freundlich ab.","answers":["Stasera non posso, magari un'altra volta!","Mi dispiace, stasera no. Magari un'altra volta?"],"tip":""},{"sit":"Davide fragt, ob du zum Karneval nach Venedig mitkommst. Du bist sofort dabei.","answers":["Ci sto!","Sì, volentieri!","Certo, ci sto!"],"tip":""}]},{"id":22,"title":"Racconti","titleDe":"Geschichten von früher","goal":"Du kannst von früher und von deiner Kindheit erzählen und deine Sätze mit kleinen Verbindungswörtern verknüpfen.","intro":"In der letzten Lektion lernst du erzählen: wie es früher war, was du als Kind gemacht hast und woran du dich erinnerst. Dafür gibt es das Imperfetto. Kleine Wörter wie mentre, quindi und però verbinden deine Sätze zu einer echten Geschichte.","culture":"Bologna hat drei Spitznamen: la dotta (die Gelehrte), weil hier die Universität steht, die als älteste Europas gilt (gegründet 1088). Dazu kommen la grassa (die Fette) wegen der reichen Küche und la rossa (die Rote) wegen der roten Dächer. Typisch sind auch die Portici: Fast 40 Kilometer Laubengänge gibt es allein in der Altstadt. Seit 2021 gehören sie zum Welterbe der UNESCO.","vocab":[{"it":"da bambino","de":"als Kind","alt":["da bambina"],"note":"feminin: da bambina. Plural: da bambini.","ex":"Da bambino ero molto timido.","exDe":"Als Kind war ich sehr schüchtern."},{"it":"da giovane","de":"in jungen Jahren; als ich jung war","alt":[],"note":"Gleich für maskulin und feminin.","ex":"Da giovane la nonna lavorava molto.","exDe":"In jungen Jahren arbeitete Oma viel."},{"it":"l'infanzia","de":"die Kindheit","alt":["infanzia"],"note":"Feminin.","ex":"Ho bei ricordi della mia infanzia.","exDe":"Ich habe schöne Erinnerungen an meine Kindheit."},{"it":"il ricordo","de":"die Erinnerung","alt":[],"note":"Plural: i ricordi.","ex":"È un bel ricordo.","exDe":"Das ist eine schöne Erinnerung."},{"it":"ricordare","de":"sich erinnern (an)","alt":[],"note":"Ohne di: Ricordo la casa = ich erinnere mich an das Haus. Auch möglich: ricordarsi di.","ex":"Ricordo bene la casa dei nonni.","exDe":"Ich erinnere mich gut an das Haus der Großeltern."},{"it":"crescere","de":"aufwachsen; wachsen","alt":[],"note":"Passato prossimo mit essere: sono cresciuto.","ex":"Sono cresciuto a Monaco.","exDe":"Ich bin in München aufgewachsen."},{"it":"la storia","de":"die Geschichte","alt":[],"note":"Auch die Geschichte als Fach: la storia d'Italia.","ex":"Nonna, mi racconti una storia?","exDe":"Oma, erzählst du mir eine Geschichte?"},{"it":"prima","de":"vorher; früher","alt":[],"note":"Prima di + Nomen = vor: prima di cena.","ex":"Prima abitavo a Monaco, adesso a Bologna.","exDe":"Früher wohnte ich in München, jetzt in Bologna."},{"it":"ai miei tempi","de":"zu meiner Zeit","alt":[],"note":"Ein typischer Satzanfang von Großeltern.","ex":"Ai miei tempi i ragazzi ballavano in piazza.","exDe":"Zu meiner Zeit tanzten die jungen Leute auf der Piazza."},{"it":"C'era una volta","de":"Es war einmal","alt":["C'era una volta..."],"note":"So beginnen Märchen.","ex":"C'era una volta una bambina.","exDe":"Es war einmal ein kleines Mädchen."},{"it":"la nostalgia","de":"die Sehnsucht; das Heimweh","alt":[],"note":"Avere nostalgia di = sich sehnen nach.","ex":"A volte la nonna ha nostalgia del passato.","exDe":"Manchmal sehnt sich Oma nach früher."},{"it":"diverso","de":"anders; verschieden","alt":[],"note":"feminin: diversa.","ex":"Siamo fratelli, ma molto diversi.","exDe":"Wir sind Geschwister, aber sehr verschieden."},{"it":"mentre","de":"während","alt":[],"note":"Nach mentre steht oft das Imperfetto.","ex":"Mentre cucinavo, ascoltavo la radio.","exDe":"Während ich kochte, hörte ich Radio."},{"it":"quando","de":"als; wenn","alt":[],"note":"Auch Fragewort: Quando? = Wann?","ex":"Quando pioveva, restavamo a casa.","exDe":"Wenn es regnete, blieben wir zu Hause."},{"it":"perché","de":"weil; warum","alt":["perche"],"note":"Mit Akzent é. Frage und Antwort: Perché? Perché ...","ex":"Resto a casa perché sono stanco.","exDe":"Ich bleibe zu Hause, weil ich müde bin."},{"it":"però","de":"aber; allerdings","alt":["pero"],"note":"Wie ma, kann aber auch mitten im Satz stehen: Io però resto qui.","ex":"Era povero, però era felice.","exDe":"Er war arm, aber glücklich."},{"it":"quindi","de":"deshalb; daher","alt":[],"note":"","ex":"Era tardi, quindi siamo tornati a casa.","exDe":"Es war spät, deshalb sind wir nach Hause gegangen."},{"it":"allora","de":"also; na dann","alt":[],"note":"Beim Erzählen auch: damals.","ex":"Allora, che facciamo stasera?","exDe":"Also, was machen wir heute Abend?"},{"it":"invece","de":"dagegen; stattdessen","alt":[],"note":"Io invece = ich dagegen.","ex":"Io preferisco il mare, Giulia invece la montagna.","exDe":"Ich mag lieber das Meer, Giulia dagegen die Berge."},{"it":"alla fine","de":"am Ende; schließlich","alt":[],"note":"","ex":"Alla fine è andato tutto bene.","exDe":"Am Ende ist alles gut gegangen."},{"it":"all'improvviso","de":"plötzlich","alt":[],"note":"Meist mit dem Passato prossimo: All'improvviso è arrivato Davide.","ex":"All'improvviso ha cominciato a piovere.","exDe":"Plötzlich hat es angefangen zu regnen."},{"it":"comunque","de":"jedenfalls; trotzdem","alt":[],"note":"","ex":"Comunque, ci vediamo domani!","exDe":"Jedenfalls sehen wir uns morgen!"},{"it":"infatti","de":"tatsächlich; genau","alt":[],"note":"Bestätigt das, was man gerade gesagt hat.","ex":"Ero stanco, infatti ho dormito dieci ore.","exDe":"Ich war müde. Tatsächlich habe ich zehn Stunden geschlafen."},{"it":"anzi","de":"im Gegenteil; sogar","alt":[],"note":"","ex":"Non è brutto, anzi, è bellissimo!","exDe":"Es ist nicht hässlich, im Gegenteil, es ist wunderschön!"},{"it":"la vita","de":"das Leben","alt":[],"note":"","ex":"La vita in campagna era dura.","exDe":"Das Leben auf dem Land war hart."},{"it":"la gente","de":"die Leute","alt":[],"note":"Grammatisch Singular: la gente è simpatica.","ex":"La gente qui è molto simpatica.","exDe":"Die Leute hier sind sehr nett."},{"it":"il quartiere","de":"das Stadtviertel","alt":[],"note":"Plural: i quartieri.","ex":"Il mio quartiere era molto tranquillo.","exDe":"Mein Viertel war sehr ruhig."},{"it":"la campagna","de":"das Land (ländliche Gegend)","alt":[],"note":"In campagna = auf dem Land.","ex":"I nonni abitavano in campagna.","exDe":"Die Großeltern wohnten auf dem Land."},{"it":"il contadino","de":"der Bauer","alt":[],"note":"feminin: la contadina.","ex":"Mio nonno era contadino.","exDe":"Mein Großvater war Bauer."},{"it":"povero","de":"arm","alt":[],"note":"feminin: povera.","ex":"Era una famiglia povera.","exDe":"Es war eine arme Familie."},{"it":"ricco","de":"reich","alt":[],"note":"feminin: ricca. Plural: ricchi, ricche.","ex":"Lo zio di Franco era molto ricco.","exDe":"Francos Onkel war sehr reich."},{"it":"la radio","de":"das Radio","alt":[],"note":"Feminin und im Plural unverändert: le radio.","ex":"Il nonno ascoltava sempre la radio.","exDe":"Opa hörte immer Radio."},{"it":"il giocattolo","de":"das Spielzeug","alt":[],"note":"Plural: i giocattoli.","ex":"Avevo pochi giocattoli.","exDe":"Ich hatte wenig Spielzeug."},{"it":"il cortile","de":"der Hof (Innenhof)","alt":[],"note":"","ex":"Giocavamo sempre in cortile.","exDe":"Wir spielten immer im Hof."},{"it":"ogni estate","de":"jeden Sommer","alt":[],"note":"Ogni + Singular: ogni giorno, ogni anno.","ex":"Ogni estate facevamo un viaggio.","exDe":"Jeden Sommer machten wir eine Reise."},{"it":"la favola","de":"das Märchen","alt":["la fiaba"],"note":"Märchen beginnen mit: C'era una volta.","ex":"La nonna mi raccontava sempre una favola.","exDe":"Oma erzählte mir immer ein Märchen."}],"grammar":{"title":"Das Imperfetto: Wie war es früher?","points":["Mit dem <b>Imperfetto</b> beschreibst du, wie etwas früher war: La città <b>era</b> piccola. Außerdem erzählst du damit von Gewohnheiten, also von dem, was man immer oder oft gemacht hat: Da bambino <b>giocavo</b> in cortile.","Die Bildung ist fast immer regelmäßig: Infinitiv ohne <b>re</b>, dann <b>vo, vi, va, vamo, vate, vano</b>. Also parla<b>vo</b>, prende<b>vo</b>, dormi<b>vo</b>. Bei loro liegt die Betonung weit vorne: par<b>la</b>vano.","<b>essere</b> ist unregelmäßig: ero, eri, era, eravamo, eravate, erano. Besonders wichtig sind <b>c'era</b> (es gab, Singular) und <b>c'erano</b> (Plural). Auch fare wird zu <b>facevo</b> und bere zu <b>bevevo</b>.","Merkregel: Das Imperfetto ist der <b>Hintergrund</b> (Wie war es? Was machte man immer?). Das Passato prossimo erzählt ein einzelnes <b>Ereignis</b> (Was ist dann passiert?): Mentre <b>dormivo</b>, <b>è arrivato</b> Davide."],"table":{"head":["","abitare","avere","essere"],"rows":[["io","abitavo","avevo","ero"],["tu","abitavi","avevi","eri"],["lui / lei / Lei","abitava","aveva","era"],["noi","abitavamo","avevamo","eravamo"],["voi","abitavate","avevate","eravate"],["loro","abitavano","avevano","erano"]]},"examples":[{"it":"Ai miei tempi non c'era la televisione.","de":"Zu meiner Zeit gab es kein Fernsehen."},{"it":"La casa era piccola, ma molto accogliente.","de":"Das Haus war klein, aber sehr gemütlich."},{"it":"Ogni domenica facevamo una passeggiata.","de":"Jeden Sonntag machten wir einen Spaziergang."},{"it":"Da ragazzo Franco giocava a calcio.","de":"Als Jugendlicher spielte Franco Fußball."},{"it":"Che cosa facevi da bambino?","de":"Was hast du als Kind gemacht?"},{"it":"Mentre dormivo, è arrivato Davide.","de":"Während ich schlief, ist Davide gekommen."}],"drills":[{"type":"choice","q":"Da bambina Giulia ___ i capelli biondi.","de":"Als Kind hatte Giulia blonde Haare.","options":["avevo","aveva","avevano"],"answer":1,"why":"Giulia = lei: aveva."},{"type":"type","q":"Quando la nonna era piccola, non ___ tante macchine.","de":"Als Oma klein war, gab es nicht so viele Autos.","answer":"c'erano","alt":[],"why":"Es gab mit Plural: c'erano."},{"type":"choice","q":"Ogni estate noi ___ in campagna dai nonni.","de":"Jeden Sommer fuhren wir aufs Land zu den Großeltern.","options":["andavano","andavate","andavamo"],"answer":2,"why":"noi: Endung vamo, also andavamo."},{"type":"type","q":"Mentre io ___ (guardare) la TV, è arrivata Giulia.","de":"Während ich fernsah, kam Giulia.","answer":"guardavo","alt":[],"why":"Was gerade lief, ist der Hintergrund: Imperfetto guardavo."},{"type":"choice","q":"Pioveva, ___ siamo rimasti a casa.","de":"Es regnete, deshalb sind wir zu Hause geblieben.","options":["quindi","invece","mentre"],"answer":0,"why":"quindi = deshalb, es nennt die Folge."},{"type":"type","q":"Da bambini io e Matteo ___ (giocare) sempre in cortile.","de":"Als Kinder spielten Matteo und ich immer im Hof.","answer":"giocavamo","alt":[],"why":"io e Matteo = noi: giocavamo."},{"type":"choice","q":"La nonna ___ sempre le tagliatelle la domenica.","de":"Oma machte sonntags immer Tagliatelle.","options":["fareva","facevo","faceva"],"answer":2,"why":"fare ist unregelmäßig: lei faceva."},{"type":"type","q":"Una volta Bologna ___ molto diversa.","de":"Früher war Bologna ganz anders.","answer":"era","alt":[],"why":"Beschreibung von früher: Imperfetto von essere, era."}]},"dialog":{"title":"Bologna una volta","setting":"Nach dem Essen sitzt Lukas mit Nonna Lucia auf dem Balkon. Sie erzählt von früher.","speakers":{"A":{"name":"Lukas","gender":"m"},"B":{"name":"Nonna Lucia","gender":"f"}},"lines":[{"s":"A","it":"Nonna Lucia, com'era Bologna quando Lei era giovane?","de":"Nonna Lucia, wie war Bologna, als Sie jung waren?"},{"s":"B","it":"Eh, caro mio, era tutta un'altra città! Poche macchine, tante biciclette.","de":"Ach, mein Lieber, das war eine ganz andere Stadt! Wenig Autos, viele Fahrräder."},{"s":"A","it":"E Lei dove abitava?","de":"Und wo haben Sie gewohnt?"},{"s":"B","it":"In centro, in un appartamento piccolo piccolo vicino alle Due Torri.","de":"Im Zentrum, in einer winzigen Wohnung bei den Zwei Türmen."},{"s":"A","it":"E la sera cosa facevate?","de":"Und was habt ihr abends so gemacht?"},{"s":"B","it":"Pensa che non c'era la televisione, quindi ascoltavamo la radio.","de":"Stell dir vor, es gab keinen Fernseher. Also haben wir Radio gehört."},{"s":"A","it":"E da piccola giocava in strada?","de":"Und als Kind haben Sie auf der Straße gespielt?"},{"s":"B","it":"Sì, in cortile, con i miei fratelli. Mica come adesso!","de":"Ja, im Hof, mit meinen Geschwistern. Nicht so wie heute!"},{"s":"A","it":"Ed era una vita difficile?","de":"Und war das Leben schwer?"},{"s":"B","it":"Eravamo poveri, però felici. Ci aiutavamo tutti. Bei tempi!","de":"Wir waren arm, aber glücklich. Alle haben sich geholfen. Das waren noch Zeiten!"},{"s":"A","it":"E adesso? Le piace la Bologna di oggi?","de":"Und heute? Gefällt Ihnen das Bologna von heute?"},{"s":"B","it":"Sì, sì. Però una volta c'erano più osterie e meno turisti!","de":"Ja, schon. Aber früher gab es mehr Wirtshäuser und weniger Touristen!"}],"questions":[{"q":"Wo wohnte Nonna Lucia früher?","options":["Auf dem Land","Im Zentrum, nahe bei den Zwei Türmen","In Mailand"],"answer":1},{"q":"Was machte die Familie abends?","options":["Sie sah fern.","Sie ging ins Kino.","Sie hörte Radio."],"answer":2},{"q":"Wovon gab es früher mehr in Bologna?","options":["Wirtshäuser","Touristen","Autos"],"answer":0}]},"sentences":[{"it":"Da bambino avevo tanti giocattoli.","de":"Als Kind hatte ich viel Spielzeug."},{"it":"Una volta qui c'era un piccolo cinema.","de":"Früher gab es hier ein kleines Kino."},{"it":"Mentre mangiavamo, la nonna raccontava storie.","de":"Während wir aßen, erzählte Oma Geschichten."},{"it":"D'estate andavamo sempre al mare.","de":"Im Sommer fuhren wir immer ans Meer."},{"it":"Alla fine siamo tornati a casa insieme.","de":"Am Ende sind wir zusammen nach Hause gegangen."},{"it":"La vita era dura, però eravamo felici.","de":"Das Leben war hart, aber wir waren glücklich."},{"it":"Io invece preferivo stare a casa.","de":"Ich dagegen blieb lieber zu Hause."},{"it":"Quando ero piccolo, abitavo a Monaco.","de":"Als ich klein war, wohnte ich in München."}],"spoken":[{"it":"Ti ricordi?","book":"Ricordi?","de":"Weißt du noch?","note":"Im Gespräch sagt man meist ti ricordi statt ricordi. Oft mit quando: Ti ricordi quando ...?","ex":"Ti ricordi quando giocavamo in cortile?","exDe":"Weißt du noch, wie wir im Hof gespielt haben?","alt":[]},{"it":"Pensa che ...","book":"Immagina che ...","de":"Stell dir vor, ...","note":"Typischer Einstieg, wenn man etwas Überraschendes erzählt.","ex":"Pensa che non c'era neanche la TV!","exDe":"Stell dir vor, es gab nicht mal einen Fernseher!","alt":[]},{"it":"Bei tempi!","book":"Erano tempi belli.","de":"Das waren noch Zeiten!","note":"Sagt man mit einem Seufzer, wenn man an früher denkt. Junge Leute sagen es gern halb im Spaß.","ex":"Le estati al mare con i nonni... bei tempi!","exDe":"Die Sommer am Meer mit Oma und Opa ... das waren noch Zeiten!","alt":[]},{"it":"Mica come adesso!","book":"Non era come oggi.","de":"Nicht so wie heute!","note":"Typisch, wenn Ältere von früher erzählen. Mica verstärkt ein Nein: Non è mica facile! = Das ist gar nicht so leicht!","ex":"Giocavamo sempre fuori, mica come adesso!","exDe":"Wir haben immer draußen gespielt, nicht so wie heute!","alt":[]},{"it":"tipo","book":"","de":"so etwa; so was wie","note":"Sehr beliebtes Füllwort, vor allem bei jungen Leuten: für ungefähre Angaben oder Beispiele. Nicht zu oft benutzen!","ex":"Quanti anni avevi? Tipo dieci, forse undici.","exDe":"Wie alt warst du? So etwa zehn, vielleicht elf.","alt":[]},{"it":"E niente ...","book":"","de":"Na ja, jedenfalls ...","note":"Typisch beim Erzählen, wenn man zum Ende der Geschichte kommt. Klingt sehr natürlich.","ex":"E niente, alla fine siamo tornati a piedi.","exDe":"Na ja, am Ende sind wir dann zu Fuß zurück.","alt":[]},{"it":"Da piccolo ...","book":"Quando ero bambino ...","de":"Als ich klein war, ...","note":"Im Alltag viel häufiger als da bambino. Frauen sagen: da piccola.","ex":"Da piccolo abitavo in campagna.","exDe":"Als ich klein war, habe ich auf dem Land gewohnt.","alt":["Da piccola ..."]},{"it":"Non mi dire!","book":"Davvero?","de":"Sag bloß!","note":"Überraschte Reaktion, wenn dir jemand etwas Unerwartetes erzählt.","ex":"La nonna ballava il rock? Non mi dire!","exDe":"Oma hat Rock 'n' Roll getanzt? Sag bloß!","alt":[]}],"speak":[{"sit":"Giulia fragt, wo du als Kind gewohnt hast. Antworte: in München.","answers":["Da piccolo abitavo a Monaco.","Da bambino abitavo a Monaco.","Quando ero piccolo, abitavo a Monaco."],"tip":"Für früher nimmst du das Imperfetto: abitavo."},{"sit":"Erzähl, was du als Kind im Sommer immer gemacht hast.","answers":["D'estate andavo sempre al lago.","Ogni estate andavamo al mare con i miei genitori.","Da piccolo giocavo sempre fuori."],"tip":"Gewohnheiten von früher stehen im Imperfetto."},{"sit":"Frag Nonna Lucia höflich, wie Bologna früher war.","answers":["Com'era Bologna una volta?","Com'era Bologna quando Lei era giovane?"],"tip":""},{"sit":"Frag Giulia, was sie als Kind gern gemacht hat.","answers":["Cosa facevi da piccola?","Che cosa ti piaceva fare da bambina?"],"tip":"Giulia ist eine Frau, also: da piccola, da bambina."},{"sit":"Nonna Lucia erzählt, dass sie früher jeden Samstag tanzen gegangen ist. Reagier überrascht.","answers":["Non mi dire!","Davvero? Non mi dire!","Ma davvero?"],"tip":""},{"sit":"Erzähl: Es hat geregnet, deshalb bist du zu Hause geblieben.","answers":["Pioveva, quindi sono rimasto a casa.","Pioveva, allora sono restato a casa."],"tip":"Der Hintergrund (es regnete) steht im Imperfetto, die Folge im Passato prossimo."}]}]};
